@app.get("/api/coste/tarifas")
def leer_tarifas():
    """Tabla de tarifas. Vive en un unico sitio: estudio/tarifas.json."""
    return {"tarifas": COSTE.tarifas(refrescar=True), "ruta": COSTE.RUTA_TARIFAS,
            "usd_por_caracter": COSTE.tarifa_caracter()}


@app.put("/api/coste/tarifas")
def escribir_tarifas(cuerpo: dict = Body(default=None)):
    """Actualiza tarifas.json. Sirve para rellenar el precio por caracter."""
    datos = _cuerpo(cuerpo)
    cambios = datos.get("tarifas") if isinstance(datos.get("tarifas"), dict) else datos
    if not cambios:
        raise ErrorApi(400, "no hay nada que cambiar en las tarifas")
    if "usd_por_caracter" in cambios:
        # atajo comodo: lo unico que se rellena a mano es el precio de Cartesia
        cambios = {"tts": {"usd_por_caracter": cambios["usd_por_caracter"]}}
    try:
        tabla = COSTE.guardar_tarifas(cambios)
    except (TypeError, ValueError, OSError) as fallo:
        raise ErrorApi(400, f"no se han podido guardar las tarifas: {fallo}")
    return {"tarifas": tabla, "usd_por_caracter": COSTE.tarifa_caracter()}


# -------------------------------------------------------- ajustes del CLI
# Los pasos que llaman al CLI de Claude dejan elegir modelo y esfuerzo. Estas
# rutas existen para que esa eleccion sea informada: la lista de opciones sale de
# UN solo sitio (cli_claude), y el tiempo que cuesta cada una sale del historico
# real de todos los proyectos, no de un numero escrito a mano en la interfaz.


@app.get("/api/ajustes-cli")
def ajustes_cli():
    """Catalogo de modelos y esfuerzos, y en que pasos se puede elegir.

    La interfaz ofrecia tres esfuerzos y el backend aceptaba cinco: dos listas
    escritas a mano en sitios distintos se desincronizan solas. Esta es la lista.
    """
    return {
        **CLI_CLAUDE.catalogo(),
        "pasos": list(ESTADISTICAS.PASOS_CON_CLI),
        # Ajuste recomendado de cada fase, con el porque. La interfaz lo ensena
        # y lo usa como valor de partida de sus desplegables, para que elegir
        # otro sea una decision y no un descuido.
        #
        # La union de las dos listas, no solo la de estadisticas: hay fases con
        # ajuste razonado que no llevan historico ('tono', 'voz_descrita'), y
        # dejarlas fuera hacia que su pantalla se anunciara con el defecto
        # general del CLI mientras el backend ejecutaba el de la fase.
        "por_fase": {fase: CLI_CLAUDE.por_defecto_de(fase)
                     for fase in sorted(set(ESTADISTICAS.PASOS_CON_CLI)
                                        | set(CLI_CLAUDE.POR_FASE))},
        "medido": {
            "guion": {"sin_effort_s": 605.8, "con_effort_low_s": 67.0,
                      "nota": "mismo transcript de 9.341 palabras"},
        },
    }


# Cualquier campo de texto de la interfaz se puede rellenar hablando. El audio
# lo graba el navegador y lo transcribe Whisper EN LOCAL (el mismo modelo que
# usa la ingesta cuando un video no trae subtitulos): no sale de esta maquina y
# no cuesta nada por uso, asi que no entra en el medidor de coste.


# ------------------------------------- frames del video como referencia real
# Los fotogramas de la ingesta llevaban ahi desde el principio y solo se miraban.
# Etiquetados con lo que se narraba en su segundo, sirven para que el dibujo de
# una persona o un sitio concreto SE PAREZCA al original en vez de a lo que el
# modelo se imagine.
#
# Etiquetar y proponer son ACCIONES, no pasos del grafo: producen candidatos para
# que una persona decida. Lo que si es parametro (y por tanto invalida assets) es
# la seleccion aprobada, porque cambia las imagenes que se le mandan al generador.


def _frames():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.frames


def _correr_etiquetar_frames(avisar, ctx, ajuste):
    frames = _frames()
    with COSTE.contexto(ctx.proyecto, "ingesta"):
        ficha = frames.etiquetar(ctx.proyecto, modelo=ajuste["modelo"],
                                 esfuerzo=ajuste["esfuerzo"], avisar=avisar,
                                 proyecto_id=ctx.id)
    ctx.bitacora.anotar("frames_etiquetados", "ingesta",
                        {"frames": ficha["total"], "utiles": ficha["utiles"],
                         "ajuste": ajuste})
    return ficha


# ------------------------------------------------- imagenes de estilo
# Las referencias de estilo definen COMO se dibuja. Se pueden sacar de un video
# de YouTube cuyo look guste, que no tiene por que ser el video de referencia
# del proyecto: uno aporta el contenido y el otro el estilo.
#
# Extraer es una ACCION, no un paso del grafo: produce candidatos para que una
# persona elija. Lo que si es parametro (y por tanto invalida assets) es la
# seleccion final, porque cambia las imagenes que se le mandan al generador.


def _estilo():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.estilo


def _correr_extraer_estilo(avisar, ctx, url, maximo):
    estilo = _estilo()
    ficha = estilo.extraer(ctx.proyecto, url, avisar=avisar, maximo=maximo)
    ctx.bitacora.anotar("estilo_extraido", "assets", {
        "url": url, "fotogramas": ficha["total"],
        "utiles": ficha.get("utiles"),
        "propuestos": len(ficha.get("sugeridos") or [])})
    return ficha


# ------------------------------------------------- el tono de las instrucciones
# El gemelo narrativo de las imagenes de estilo: alli se copia COMO SE DIBUJA
# mirando fotogramas, aqui COMO SE CUENTA leyendo las transcripciones de videos
# que ya suenan como quieres. Lo que sale son las instrucciones del guion.

def _tono():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.tono


def _correr_tono(avisar, ctx, urls, ajuste):
    tono = _tono()
    # El idioma sale del BRIEF, que es quien lo fija en el modo editor. Sin
    # esto, un video en ingles recibia unas instrucciones escritas en
    # castellano que ademas le ordenaban redactar en castellano.
    brief = ctx.estado.params("brief") or {}
    ficha = tono.deducir(ctx.proyecto, urls,
                         modelo=(ajuste or {}).get("modelo"),
                         esfuerzo=(ajuste or {}).get("esfuerzo"),
                         avisar=avisar, proyecto_id=ctx.proyecto.id,
                         idioma=_idioma_de_brief(brief))
    # LAS TRANSCRIPCIONES SE QUEDAN PUESTAS, y esto SI escribe params -- al
    # contrario que las instrucciones, que se devuelven para que una persona
    # decida. No es una contradiccion: lo que se decide leyendo es el PARRAFO,
    # que puede estar mejor o peor escrito; las transcripciones son un dato, son
    # de los videos que se acaban de elegir, y dejarlas esperando a un segundo
    # boton es la forma de que nunca lleguen al guion (ver `un-cajon-es-una-promesa`).
    referencias = [f for f in (ficha.get("referencias") or []) if f.get("huella")]
    if referencias:
        ctx.estado.actualizar_params("guion", {"referencias_tono": referencias})
    ctx.bitacora.anotar("tono_deducido", "brief", {
        "videos": len(ficha.get("referencias") or []),
        "palabras": ficha.get("palabras"),
        "referencias_guardadas": len(referencias),
        "avisos": len(ficha.get("avisos") or [])})
    return ficha


@app.put("/api/proyectos/{pid}/estilo/seleccion")
def elegir_estilo(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda las imagenes de estilo elegidas en los params de assets."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    estilo = _estilo()
    _lista_de_textos(datos, "referencias")
    try:
        rutas = estilo.validar_seleccion(datos.get("referencias"))
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    minimo = PASOS_MODULOS.p6_assets.MIN_REFERENCIAS_ESTILO
    tope = PASOS_MODULOS.p6_assets.MAX_REFERENCIAS_ESTILO
    if len(rutas) < minimo:
        raise ErrorApi(400, f"elige al menos {minimo} imágenes de estilo; has "
                            f"mandado {len(rutas)}. Con una o dos, el generador "
                            f"copia esa escena concreta en vez de quedarse con "
                            f"el estilo: hacen falta varias situaciones "
                            f"distintas para que lo único que puedan tener en "
                            f"común sea la forma de dibujar")
    if len(rutas) > tope:
        raise ErrorApi(400, f"como mucho {tope} imágenes de estilo; has mandado "
                            f"{len(rutas)}. A cada escena se le adjuntan además "
                            f"las hojas de reparto y los dos planos anteriores, "
                            f"y pasado ese punto el estilo compite con ellas por "
                            f"la atención del modelo")
    actual = dict((ctx.estado.params("assets") or {}).get("estilo") or {})
    actual["referencias"] = rutas
    # se manda el objeto 'estilo' entero: escribir solo 'referencias' lo
    # sustituiria y se perderia el prompt de estilo
    ctx.estado.actualizar_params("assets", {"estilo": actual})
    ctx.bitacora.anotar("estilo_elegido", "assets", {"imagenes": len(rutas)})
    return {"referencias": rutas, "estado": ctx.estado.estado_de("assets"),
            "aguas_abajo": {h: ctx.estado.unidades_obsoletas(h)
                            for h in descendientes_de("assets")}}


def _correr_guia_estilo(avisar, ctx, rutas, ajuste):
    estilo = _estilo()
    actual = dict((ctx.estado.params("assets") or {}).get("estilo") or {})
    # con el contrato del tipo de imagen del proyecto (Etapa Foto A)
    guia = estilo.generar_guia(ctx.proyecto, rutas,
                               modelo=ajuste["modelo"],
                               esfuerzo=ajuste["esfuerzo"],
                               avisar=avisar, proyecto_id=ctx.id,
                               modo=PASOS_MODULOS.p6_assets.modo_de(actual))
    # La guia es parametro del paso: cambia lo que se le manda al generador, asi
    # que tiene que invalidar assets y lo que cuelga. Es el comportamiento
    # correcto, no un efecto secundario.
    actual["guia"] = guia
    ctx.estado.actualizar_params("assets", {"estilo": actual})
    ctx.bitacora.anotar("guia_estilo", "assets", {
        "fotogramas": len(guia.get("fotogramas") or []),
        "palabras": guia.get("palabras"), "ajuste": ajuste})
    avisar(1.0, f"guia de {guia.get('palabras')} palabras")
    return guia


@app.post("/api/proyectos/{pid}/estilo/guia", status_code=202)
def escribir_guia_estilo(pid: str, cuerpo: dict = Body(default=None)):
    """Escribe la guia de estilo mirando los fotogramas elegidos.

    Es la segunda via del mismo estilo: las imagenes van adjuntas en cada
    llamada, y ademas su descripcion viaja escrita dentro del prompt. Dicho por
    dos caminos, el estilo se mantiene mas estable entre planos.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    estilo = _estilo()
    rutas = _lista_de_textos(datos, "referencias")
    if not rutas:
        rutas = ((ctx.estado.params("assets") or {}).get("estilo") or {}).get("referencias")
    try:
        rutas = estilo.validar_seleccion(rutas)
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    minimo = PASOS_MODULOS.p6_assets.MIN_REFERENCIAS_ESTILO
    if len(rutas) < minimo:
        raise ErrorApi(400, f"elige al menos {minimo} fotogramas antes de pedir "
                            f"la guía: con menos se describe una escena, no un "
                            f"estilo")
    ajuste = _ajuste_cli(datos)
    trabajo_id = ctx.gestor.lanzar("guia_estilo", _correr_guia_estilo,
                                   ctx, rutas, ajuste, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ajuste": ajuste,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


def _catalogo_visual():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.catalogo_visual


def _bloques_del_guion(ctx):
    """Los bloques del guion activo, en orden, con su id y su texto."""
    medios = PASOS_MODULOS.medios
    ruta = medios.salida_de(ctx.proyecto, "guion",
                            claves=("guion",), patrones=(r"guion\.json",))
    documento = medios.leer_json(ruta, {}) if ruta else {}
    bloques = documento.get("bloques_detalle") or documento.get("guion") or []
    limpios = []
    for bloque in bloques:
        if not isinstance(bloque, dict):
            continue
        bid = str(bloque.get("id") or "").strip()
        texto = str(bloque.get("texto") or "").strip()
        if bid and texto:
            limpios.append({"id": bid, "texto": texto,
                            # si el personaje del canal da la cara en este
                            # bloque: lo marca el redactor
                            "personaje": bool(bloque.get("personaje"))})
    return limpios


def _espacio_fijo_guardado(ctx):
    """El espacio fijo del video (params de assets), limpio. -> {} si no hay.

    Vive en assets por la regla de la casa --se guarda en el paso cuya salida
    cambia, y lo que cambia son los sitios de las imagenes-- y entra en su firma
    como cualquier param: cambiarlo en un video hecho deja assets obsoleto.
    """
    crudo = (ctx.estado.params("assets") or {}).get("espacio_fijo")
    try:
        return _catalogo_visual().normalizar_espacio_fijo(crudo)
    except ValueError as fallo:
        raise RuntimeError(f"el espacio fijo guardado no vale: {fallo}")


def _correr_catalogo(avisar, ctx, ajuste, peticion):
    catalogo = _catalogo_visual()
    bloques = _bloques_del_guion(ctx)
    if not bloques:
        raise RuntimeError("no hay guion que leer: genera el guion antes de "
                           "pedir el catalogo visual")
    brief = (ctx.estado.salidas("brief") or {})
    # Cuantos planos van a salir lo decide la duracion de plano, que se elige en
    # la tarjeta de assets y que el catalogo no veia: sin ella, «dos planos por
    # sitio» era una intencion sin aritmetica (ver catalogo.planos_previstos).
    por_defecto = PASOS_MODULOS.p6_assets.PARAMS_POR_DEFECTO
    params = ctx.estado.params("assets") or {}
    min_s = params.get("min_s") or por_defecto["min_s"]
    max_s = params.get("max_s") or por_defecto["max_s"]
    planos = catalogo.planos_previstos(bloques, min_s, max_s)
    # PERO ESA PRESION ES DEL MODELO VIEJO, y en el nuevo hace dano.
    #
    # Pedir un minimo de sitios existia porque en 'por_set' pocos sitios son
    # muchos planos compartiendo sitio, o sea planos que se parecen. En
    # 'por_plano' eso no puede pasar: cada plano trae su caja pase lo que pase.
    # Lo unico que queda del sitio es el RELATO -- la luz, el rotulo que situa, y
    # de quien se toma la continuidad --, y ahi cuantos mas sitios, peor.
    #
    # Con la presion puesta salieron 31 sitios para 48 planos: 1,5 planos por
    # sitio. Y no eran sitios distintos, era el MISMO partido por momentos --
    # 'sala_control_2fa', 'sala_control_sin_mfa', 'sala_control_activacion_mfa';
    # tres sucursales del mismo banco --, que es exactamente lo que el criterio
    # del catalogo prohibe con esas palabras: «un set es un LUGAR, no un plano».
    # Con eso, la referencia de continuidad no se dispara casi nunca (necesita
    # dos planos del mismo sitio) y entra una cabecera de sitio cada plano y
    # medio. O sea que se lleva por delante lo unico que sostenia el
    # reconocimiento del lugar, que ya era la parte fragil de este modo.
    ficha = catalogo.proponer(bloques, brief=brief, ajuste=ajuste,
                              avisar=avisar, proyecto_id=ctx.id,
                              # lo que pide el editor: llegaba hasta aqui y no
                              # se pasaba, asi que el prompt nunca lo veia
                              peticion=peticion,
                              planos=planos, min_s=min_s, max_s=max_s,
                              # los personajes del canal, que entran en el
                              # reparto ya decididos
                              # y como son los personajes en este estilo, para
                              # que el reparto se describa ya convertido
                              regla_personajes=PASOS_MODULOS.p6_assets.regla_de_especie(
                                  params.get("estilo") or {}),
                              # todo el video en un mismo sitio, si el encargo
                              # lo fijo (rama espacio-fijo, 20-10-2026)
                              espacio_fijo=_espacio_fijo_guardado(ctx),
                              # como se cuenta (rama tipo-de-relato): solo un
                              # modo EXPLICITO cambia algo del catalogo
                              relato=PASOS_MODULOS.tipo_relato.resolver(params))
    ctx.bitacora.anotar("catalogo_propuesto", "assets", {
        "personajes": len(ficha.get("reparto") or {}),
        "sets": len(ficha.get("sets") or {}),
        "beats": len(ficha.get("beats") or []),
        "cobertura": ficha.get("cobertura"), "ajuste": ajuste})
    avisar(1.0, f"{len(ficha.get('reparto') or {})} personajes, "
                f"{len(ficha.get('sets') or {})} sitios "
                f"para unos {planos} planos")
    return ficha




@app.post("/api/proyectos/{pid}/catalogo/proponer", status_code=202)
def proponer_catalogo(pid: str, cuerpo: dict = Body(default=None)):
    """Lee el guion ENTERO y propone quien sale, donde y con que tono.

    Proponer no es aprobar: esto no toca los params. Lo que devuelve va a una
    persona, que lo repasa y lo guarda con PUT /catalogo.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    # cada fase trae su ajuste razonado (cli_claude.POR_FASE): el del catalogo
    # es el mismo escalon que el del guion, porque es la misma clase de trabajo
    por_fase = CLI_CLAUDE.por_defecto_de("catalogo_visual")
    ajuste = _ajuste_cli(datos, por_fase["modelo"], por_fase["esfuerzo"])
    trabajo_id = ctx.gestor.lanzar("catalogo_visual", _correr_catalogo, ctx,
                                   ajuste, str(datos.get("peticion") or ""),
                                   paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ajuste": ajuste,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@app.get("/api/proyectos/{pid}/catalogo")
def leer_catalogo(pid: str):
    """El catalogo APROBADO que hay guardado en los params de assets."""
    ctx = contexto(pid)
    guardado = (ctx.estado.params("assets") or {}).get("catalogo") or {}
    return {
        "catalogo": guardado,
        "reparto": guardado.get("reparto") or {},
        "sets": guardado.get("sets") or {},
        "beats": guardado.get("beats") or [],
        "bloques": len(_bloques_del_guion(ctx)) if PASOS_MODULOS else 0,
    }


@app.put("/api/proyectos/{pid}/catalogo")
def guardar_catalogo(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda el catalogo aprobado en los params de assets.

    Es un parametro del paso, asi que guardarlo deja obsoletos los assets y todo
    lo que cuelga. Es lo correcto y no un efecto secundario: con otro reparto o
    con otros sitios, las imagenes son otras.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    catalogo = datos.get("catalogo")
    if not isinstance(catalogo, dict):
        raise ErrorApi(400, "hace falta el objeto 'catalogo'")
    limpio = {
        "reparto": catalogo.get("reparto") or {},
        "sets": catalogo.get("sets") or {},
        "beats": catalogo.get("beats") or [],
    }
    if not limpio["reparto"] and not limpio["sets"]:
        raise ErrorApi(400, "el catálogo llega vacío: sin reparto ni sitios, el "
                            "paso de assets no puede repartir encuadres ni "
                            "mantener a un personaje igual entre planos")
    # Lo que la pantalla no edita se CONSERVA del catalogo guardado: la lista
    # 'reales' (las imagenes de Wikimedia) y la firma del guion las escribe
    # /escenarios. Guardar el catalogo a mano las borraba, y con ellas
    # desaparecian los logos de todos los planos.
    previo = (ctx.estado.params("assets") or {}).get("catalogo") or {}
    for clave in ("reales", "_firma_guion", "relato", "_pedido"):
        if clave in previo and clave not in catalogo:
            limpio[clave] = previo[clave]
    if isinstance(catalogo.get("relato"), dict) and catalogo["relato"]:
        limpio["relato"] = catalogo["relato"]
    ctx.estado.actualizar_params("assets", {"catalogo": limpio})
    ctx.bitacora.anotar("catalogo_guardado", "assets", {
        "personajes": len(limpio["reparto"]), "sets": len(limpio["sets"]),
        "beats": len(limpio["beats"])})
    return {"catalogo": limpio, "estado": ctx.estado.estado_de("assets"),
            "aguas_abajo": {h: ctx.estado.unidades_obsoletas(h)
                            for h in descendientes_de("assets")}}


@app.get("/api/proyectos/{pid}/assets/hechos")
def planos_hechos(pid: str, ligero: int = Query(default=0)):
    """Los planos que hay generados AHORA en la carpeta de trabajo.

    Es lo que permite que la rejilla se llene segun salen --las unidades no se
    sellan hasta que el paso termina, asi que durante toda la tanda no hay otra
    senal-- y, a la vez, que un plano que no se ha generado deje de ensenar la
    imagen de otro que se llamaba igual en el plan anterior.

    Con `ligero=1` cada plano va SIN su `prompt`. No es un ahorro cosmetico:
    el prompt son ~17 KB por plano y en un video de 232 son 3,74 MB de los
    3,88 MB de esta respuesta. Y esta respuesta se pide UNA VEZ POR IMAGEN
    GENERADA mientras corre la tanda, asi que el modo light se estaba bajando
    unos 900 MB por tanda -- para mirar `planos.length` y ordenar por `sello`,
    que es lo unico que usa (refrescarPlanosLight en web/app.js).

    El prompt sigue yendo entero por defecto: la rejilla del editor pinta con el
    el boton de «ver el prompt de esta escena», y ahi si se lee.
    """
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    try:
        hechos = PASOS_MODULOS.p6_assets.planos_hechos(ctx.proyecto)
    except Exception as fallo:  # noqa: BLE001
        raise ErrorApi(500, f"no se ha podido mirar qué planos hay: {fallo}")
    # QUE PLANOS TIENE EL PLAN DE AHORA. La carpeta de trabajo CONSERVA lo de
    # pasadas anteriores --es lo que permite retomar una tanda cortada-- asi que
    # ahi puede haber PNG de planos que el plan de hoy ya no tiene: un corte
    # nuevo deja menos planos, o con otros ids. Quien pregunta necesita poder
    # separar «lo que hay en el disco» de «lo que es de este video», y deducirlo
    # por el nombre del fichero es exactamente lo que esta funcion existe para
    # no hacer.
    if ligero:
        # se rehace el dict en vez de tocar el que devuelve el paso: ese es suyo
        # y sale de su propia lectura, no de una copia que se pueda ensuciar
        hechos = {sid: {k: v for k, v in ficha.items() if k != "prompt"}
                  for sid, ficha in hechos.items()}
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    del_plan = [str(e.get("id")) for e in (plan.get("escenas") or []) if e.get("id")]
    return {"planos": hechos, "total": len(hechos),
            "plan": del_plan,
            "del_plan": len([s for s in del_plan if s in hechos])}


def _moodboard():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.moodboard


def _referencias_de_estilo(ctx):
    estilo = (ctx.estado.params("assets") or {}).get("estilo") or {}
    # reubicar: un proyecto traido de otra maquina guarda rutas de ALLI, y los
    # ficheros estan aqui, en el banco de ahora (ver medios.reubicar)
    rutas = PASOS_MODULOS.medios.reubicar_todas(estilo.get("referencias"))
    return [r for r in rutas if os.path.exists(r)], estilo


@app.get("/api/proyectos/{pid}/moodboard")
def leer_moodboard(pid: str):
    """Las referencias de estilo dibujadas a proposito para este estilo.

    Viven en el banco global y se comparten entre videos: la clave sale de los
    fotogramas elegidos, asi que el segundo video con el mismo estilo no paga.

    Cada eje dice de donde sale su lamina ('banco' si esta aprobada, 'propuesta'
    si esta sin mirar) y con que version, porque rehacer un eje deja la misma
    URL apuntando a otra imagen y sin el sello el navegador ensena la vieja.
    """
    ctx = contexto(pid)
    mod = _moodboard()
    rutas, estilo = _referencias_de_estilo(ctx)
    ficha = mod.ficha_de(rutas)
    clave = ficha.get("clave") or mod.clave_de(rutas)
    hechos = ficha.get("ejes") or {}

    def _eje(eje):
        ruta = hechos.get(eje)
        origen = mod.origen_de(ficha, eje)
        return {
            "eje": eje, "titulo": mod.EJES[eje]["titulo"],
            "hecho": bool(ruta), "origen": origen if ruta else None,
            "aprobado": bool(ruta) and origen == "banco",
            "peticion": (ficha.get("peticiones") or {}).get(eje, ""),
            "url": (f"/api/moodboard/{clave}/{origen}/{eje}.png"
                    f"?v={mod.version_de(ruta)}") if ruta else None,
        }

    return {
        "estado": ficha.get("estado"),
        "clave": clave,
        "referencias": len(rutas),
        "hay_guia": bool((estilo.get("guia") or {}) if isinstance(
            estilo.get("guia"), dict) else estilo.get("guia")),
        "peticiones": ficha.get("peticiones") or {},
        "pendientes": ficha.get("pendientes") or [],
        "coste_usd": ficha.get("coste_usd"),
        "ejes": [_eje(eje) for eje in mod.EJES],
    }


@app.get("/api/moodboard/{clave}/{origen}/{archivo}")
def servir_lamina_moodboard(clave: str, origen: str, archivo: str,
                            peticion: Request, mini: int = Query(default=0)):
    """Sirve una lamina del banco de moodboards, que vive fuera de los proyectos.

    El origen va en la ruta y no se adivina: con un moodboard aprobado y un eje
    recien rehecho existen las dos laminas a la vez, y elegir "la que aparezca
    primero" es como se acaba ensenando la vieja despues de corregir.

    Con `?mini=512` sale la version reducida, que es lo que pide la rejilla:
    esto devolvia el PNG tal cual --1536x1024, `moodboard.TAMANO`-- para pintarlo
    a un tercio de ese tamano, y son seis a la vez. Es exactamente lo que ya
    resolvio la revision de planos, con la misma cache por ruta+mtime+ancho
    (`_miniatura_de`): la lupa sigue teniendo el original, sin `mini`.
    """
    mod = _moodboard()
    try:
        carpeta = mod.carpeta_por_origen(clave, origen)
    except ValueError as fallo:
        raise ErrorApi(404, str(fallo))
    destino = ruta_segura(carpeta, archivo)
    if not os.path.isfile(destino):
        raise ErrorApi(404, f"el moodboard «{clave}» no tiene la lámina "
                            f"{archivo!r} en {origen}")
    if mini:
        reducida = _miniatura_de(destino, mini if mini in ANCHOS_MINI else None)
        if reducida:
            return FileResponse(reducida, media_type="image/jpeg",
                                headers={"Cache-Control": "public, max-age=86400"})
    return servir_fichero(peticion, destino)


@_medido_en("estilo")
@_con_turno
def _correr_moodboard(avisar, ctx, ejes, peticiones, calidad):
    mod = _moodboard()
    rutas, estilo = _referencias_de_estilo(ctx)
    hecho = mod.generar(rutas, estilo, ejes=ejes, peticiones=peticiones,
                        calidad=calidad, avisar=avisar)
    ctx.bitacora.anotar("moodboard_generado", "assets", hecho)
    return hecho


@app.post("/api/proyectos/{pid}/moodboard", status_code=202)
def generar_moodboard(pid: str, cuerpo: dict = Body(default=None)):
    """Dibuja las laminas de estilo. Quedan PROPUESTAS hasta que alguien las mira.

    Con 'ejes' se rehacen solo esos, y con 'peticiones' se les dice que corregir.
    Es lo que hace util el feedback: en la practica unos ejes salen clavados y
    otros derivan, y rehacerlo entero tiraria los buenos.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    mod = _moodboard()
    rutas, estilo = _referencias_de_estilo(ctx)
    if len(rutas) < 3:
        raise ErrorApi(409, "hacen falta al menos 3 fotogramas de estilo elegidos "
                            "antes de dibujar el moodboard: con menos se copia "
                            "una escena, no un estilo")
    guia = estilo.get("guia")
    if not ((guia.get("guia") if isinstance(guia, dict) else guia)):
        raise ErrorApi(409, "antes hace falta la guía escrita del estilo: es lo "
                            "que le dice al generador CÓMO se dibuja, y sin ella "
                            "el moodboard sale de lo que el modelo suponga")
    crudos = datos.get("ejes")
    ejes = [e for e in (crudos or []) if e in mod.EJES] or None
    peticiones = {k: str(v).strip() for k, v in (datos.get("peticiones") or {}).items()
                  if k in mod.EJES and str(v).strip()}
    calidad = str(datos.get("calidad") or "medium")
    trabajo_id = ctx.gestor.lanzar("moodboard", _correr_moodboard, ctx, ejes,
                                   peticiones, calidad, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ejes": ejes or sorted(mod.EJES),
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@app.post("/api/proyectos/{pid}/moodboard/aprobar")
def aprobar_moodboard(pid: str):
    """Mete el moodboard en el banco del canal. Es la decision de una persona.

    Hasta aqui, el paso de assets sigue usando los fotogramas reales: estas
    laminas las dibujo el mismo modelo que luego las imita, y si derivan del
    estilo original esa deriva se hereda en todo. Eso no se ve leyendo codigo, se
    ve mirandolas.
    """
    ctx = contexto(pid)
    rutas, _estilo = _referencias_de_estilo(ctx)
    try:
        hecho = _moodboard().aprobar(rutas)
    except RuntimeError as fallo:
        raise ErrorApi(409, str(fallo))
    ctx.bitacora.anotar("moodboard_aprobado", "assets", hecho)
    # Es la referencia de estilo de todas las imagenes, asi que cambiarla deja
    # obsoleto lo generado: es lo correcto, no un efecto secundario.
    ctx.estado.invalidar_unidades("assets", [])
    return {**hecho, "estado_paso": ctx.estado.estado_de("assets")}






# --------------------------------------------------------------- escenarios
#
# UN CLIC, y por eso el catalogo dejo de ser un paso.
#
# Antes esto eran dos acciones encadenadas y ninguna se explicaba sola: pedir el
# catalogo visual y repasarlo y guardarlo. Ninguna era una decision del usuario:
# el catalogo APROBADO guarda `reparto`, `sets` y `beats`, o sea quien sale,
# donde y que pasa en cada tramo -- todo deducido del guion, que ya estaba
# escrito. No habia nada que decidir ahi que no estuviera decidido antes.
#
# Asi que el catalogo deja de ser un paso visible y pasa a ser lo que siempre
# fue: deducir del guion quien sale y donde ocurre. Se sigue guardando en
# `params.assets.catalogo` porque p6_assets reparte reparto y sitios leyendolo,
# y porque sigue siendo un parametro legitimo del paso: lo que cambia es que ya
# no hay que pedirlo, mirarlo y guardarlo a mano.


def _firma_del_guion(ctx):
    """Huella del TEXTO del guion. Cambia solo si cambia lo que se dice."""
    try:
        bloques = _bloques_del_guion(ctx) if PASOS_MODULOS else []
    except Exception:  # noqa: BLE001
        return ""
    if not bloques:
        return ""
    crudo = "|".join(f'{b["id"]}:{b["texto"]}' for b in bloques)
    return hashlib.sha256(crudo.encode("utf-8")).hexdigest()[:16]




def _correr_escenarios(avisar, ctx, ajuste_catalogo, peticion, rehacer):
    """Deduce del guion quien sale y donde ocurre."""
    guardado = (ctx.estado.params("assets") or {}).get("catalogo") or {}
    hay = bool(guardado.get("sets") or guardado.get("reparto"))

    def _tramo(desde, ancho):
        """Avisador que mapea el progreso de un sub-paso dentro de su tramo.

        Acepta fraccion None a proposito: un sub-paso puede querer mandar solo
        un MENSAJE, sin tener todavia ningun progreso que dar. Haciendole
        aritmetica a ese None reventaba con «'<' not supported between NoneType
        and float».
        """
        def avisa(fraccion=None, mensaje=""):
            if fraccion is None:
                return avisar(desde, mensaje)
            return avisar(desde + ancho * max(0.0, min(1.0, float(fraccion))),
                          mensaje)
        return avisa

    # SOLO se vuelve a deducir si el guion ha cambiado de verdad.
    #
    # El boton dice «construye los escenarios de mi guion», y la primera version
    # entendia eso como «vuelve a leer el guion siempre». Suena igual y no lo es:
    # el CLI NO nombra los sitios igual dos veces. La misma frase salio una vez
    # como «centro_datos» y a la siguiente como «salon_de_fiestas». Y como los
    # sitios se guardan POR NOMBRE, cada pulsacion orfanaba lo que ya estaba y lo
    # volvia a pedir con otro nombre.
    #
    # La firma es el TEXTO de los bloques: si el guion no ha cambiado, los
    # nombres se quedan quietos y lo construido sigue valiendo.
    firma = _firma_del_guion(ctx)
    # CON ESPACIO FIJO, LA FIRMA LO LLEVA: con otro sitio fijo los sitios
    # deducidos ya no valen aunque el guion sea el mismo. Sin el, la firma es
    # la de siempre y ningun catalogo guardado se vuelve a pedir.
    espacio = _espacio_fijo_guardado(ctx)
    if firma and espacio:
        firma += "+" + hashlib.sha256(json.dumps(
            espacio, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()[:8]
    # Y EL TIPO DE RELATO, por lo mismo, y SOLO si es explicito (rama
    # tipo-de-relato): sin el, la firma es la de antes y nada se vuelve a pedir.
    relato = PASOS_MODULOS.tipo_relato.resolver(ctx.estado.params("assets") or {})
    if firma and PASOS_MODULOS.tipo_relato.activo(relato):
        firma += "+relato:" + relato["modo"] + (
            ":" + relato["cambia"] if relato.get("cambia") else "")
    cambio = bool(firma) and guardado.get("_firma_guion") != firma
    # Y tambien se vuelve a leer si el catalogo guardado es de ANTES de que el
    # catalogo supiera deducir algo que ahora deduce. La clave 'reales' se
    # escribe siempre desde el 18-08-2026, aunque salga vacia, asi que su
    # AUSENCIA es la senal de que ese catalogo se dedujo con una version que no
    # la conocia. Sin esto, un proyecto en marcha no vuelve a leer el guion
    # nunca -- porque el guion no ha cambiado -- y se queda sin las cosas reales
    # para siempre: el boton decia «ya estaban deducidos» y tenia razon sobre lo
    # que sabia deducir cuando se dedujeron.
    incompleto = hay and "reales" not in guardado
    if incompleto:
        avisar(0.02, "el catalogo se dedujo antes de que existieran las "
                     "imagenes reales: se vuelve a leer el guion")
    elif rehacer and hay and not cambio:
        avisar(0.02, "el guion no ha cambiado: se conservan los sitios ya deducidos")

    # CON UN PEDIDO ESCRITO se vuelve a leer aunque el guion no haya cambiado
    # (rama tipo-de-relato: «Pedido para el reparto de sitios»). La tanda manda
    # el pedido vacio, asi que para ella todo sigue como estaba.
    pedido = " ".join(str(peticion or "").split())
    if pedido and hay:
        avisar(0.02, "con tu pedido: se vuelve a repartir el reparto y los sitios")
    if (rehacer and cambio) or incompleto or not hay or pedido:
        avisar(0.02, "leyendo el guion para deducir quien sale y donde ocurre")
        ficha = _correr_catalogo(_tramo(0.02, 0.33), ctx, ajuste_catalogo, peticion)
        # Se guarda lo mismo que guardaba el PUT de aprobar: reparto, sitios y
        # beats. Lo demas que propone el catalogo (capitulos, componentes,
        # lugares) ya se descartaba al aprobarlo, asi que aqui tampoco entra --
        # guardarlo ahora seria meter en los params campos que nunca han
        # estado ahi y que p6 no espera encontrar.
        limpio = {"reparto": ficha.get("reparto") or {},
                  "sets": ficha.get("sets") or {},
                  "beats": ficha.get("beats") or [],
                  # Lo que existe de verdad y hay que ENSENAR en vez de
                  # imaginar: de aqui salen las imagenes que se bajan de
                  # Wikimedia Commons (pasos/wikimedia.py). Se quedaba fuera al
                  # guardar, asi que el catalogo lo deducia y se tiraba en la
                  # linea siguiente: la funcion entera no podia funcionar nunca,
                  # y no fallaba -- simplemente no salia ningun logo.
                  "reales": ficha.get("reales") or [],
                  "_firma_guion": firma}
        if ficha.get("relato"):
            # con que tipo de relato se repartio (y, en «un espacio que
            # cambia», sus beats traen `cambio` y `estado`)
            limpio["relato"] = ficha["relato"]
        if pedido:
            # el ultimo pedido con el que se repartio, para enseñarlo
            limpio["_pedido"] = pedido[:400]
        if not limpio["reparto"] and not limpio["sets"]:
            raise RuntimeError(
                "del guion no ha salido ni un personaje ni un sitio. Sin eso no "
                "hay escenarios que construir ni encuadres que repartir: revisa "
                "que el guion tenga texto y vuelve a intentarlo")
        ctx.estado.actualizar_params("assets", {"catalogo": limpio})
        ctx.bitacora.anotar("catalogo_guardado", "assets", {
            "personajes": len(limpio["reparto"]), "sets": len(limpio["sets"]),
            "beats": len(limpio["beats"]), "automatico": True})
    else:
        avisar(0.35, "los sitios ya estaban deducidos del guion")

    avisar(1.0, "reparto y sitios deducidos del guion: el encuadre de cada "
                "plano va en texto, asi que no hay nada mas que construir")
    return {"construidos": [], "fallidos": [], "ya_estaban": True,
            "previsualizados": [],
            "resumen": "reparto y sitios listos"}


@app.post("/api/proyectos/{pid}/escenarios", status_code=202)
def construir_escenarios(pid: str, cuerpo: dict = Body(default=None)):
    """Un clic: deduce del guion quien sale y donde ocurre."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    por_catalogo = CLI_CLAUDE.por_defecto_de("catalogo_visual")
    ajuste_catalogo = _ajuste_cli(datos, por_catalogo["modelo"],
                                  por_catalogo["esfuerzo"])
    trabajo_id = ctx.gestor.lanzar("escenarios", _correr_escenarios, ctx,
                                   ajuste_catalogo,
                                   str(datos.get("peticion") or ""),
                                   bool(datos.get("rehacer")),
                                   paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ajuste": ajuste_catalogo,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


# ------------------------------------------------------------- ESPACIO FIJO
#
# Rama espacio-fijo (20-10-2026). Todo el video en un mismo sitio: se elige al
# crear el video (`_opciones_al_crear`) o se APLICA a uno ya hecho, como una
# correccion. Aplicar es gratis y no dibuja nada:
#
#   1. guarda `assets.espacio_fijo` (y su imagen, en el proyecto) y ajusta el
#      catalogo guardado sin llamar a nadie (`catalogo_visual.ajustar_catalogo`);
#   2. contesta QUE planos cambiarian y lo que costaria rehacerlos.
#
# Las dos cosas son params de assets, asi que mueven la firma GLOBAL del paso y
# todas sus unidades quedan sucias A LA VEZ. Eso es lo que hace que no cueste:
# con todo sucio la tanda no pide ninguna unidad (`_plan_de_ejecucion`) y p6
# conserva cada PNG que exista («una imagen que ya existe se queda»), igual que
# al cambiar la calidad o traer el estilo. Lo que se rehace es lo que se PIDE
# despues con `/espacio_fijo/rehacer`, como unidades sueltas (el patron de
# `/imagenes/calidad`). `_firma_imagen` no se toca: la imagen nueva entra en la
# firma de una imagen solo cuando se adjunta, o sea al rehacer ese plano.

def _espacio_fijo_de_ficha(ctx):
    guardado = (ctx.estado.params("assets") or {}).get("espacio_fijo") or {}
    try:
        espacio = _catalogo_visual().normalizar_espacio_fijo(guardado)
    except ValueError:
        espacio = {}
    if espacio.get("imagen"):
        espacio["imagen_url"] = f"/api/proyectos/{ctx.id}/espacio_fijo/imagen"
    return espacio


@app.get("/api/proyectos/{pid}/espacio_fijo")
def leer_espacio_fijo(pid: str):
    """El espacio fijo guardado del video ({} si no tiene) y los planos que cambiarian."""
    ctx = contexto(pid)
    espacio = _espacio_fijo_de_ficha(ctx)
    return {"espacio_fijo": espacio,
            "cambios": _cambios_del_espacio(ctx) if espacio else None}


@app.get("/api/proyectos/{pid}/espacio_fijo/imagen")
def imagen_del_espacio_fijo(pid: str):
    """La imagen de referencia del espacio fijo de este video."""
    ctx = contexto(pid)
    ruta = PASOS_MODULOS.p6_assets.ruta_imagen_del_espacio(
        ctx.proyecto, ctx.estado.params("assets") or {})
    if not ruta:
        raise ErrorApi(404, "este vídeo no tiene imagen del espacio fijo")
    return FileResponse(ruta, media_type="image/png")


def _cambios_del_espacio(ctx):
    """QUE PLANOS CAMBIARIAN con el espacio fijo guardado, y cuanto cuesta rehacerlos.

    -> {"planos": [{id, sitio, narracion}], "imagenes", "usd_por_imagen",
        "usd_referencia", "usd", "calidad", "hechas"}

    Cambia un plano con imagen cuyo sitio (el que le daria el catalogo de
    ahora) tiene una descripcion que su prompt no lleva, o que es del sitio
    principal y no lleva adjunta la imagen del espacio. Repetir «Aplicar» con lo
    mismo no ofrece nada que rehacer."""
    p6 = PASOS_MODULOS.p6_assets
    params = ctx.estado.params("assets") or {}
    espacio = _catalogo_visual().normalizar_espacio_fijo(params.get("espacio_fijo"))
    plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = [e for e in _escenas_que_pagan(plan) if not e.get("componente")]
    carpetas = _carpetas_de_assets(ctx)
    salida = {"planos": [], "imagenes": 0, "hechas": 0}
    if escenas and carpetas and espacio:
        principal, _ = _catalogo_visual().ids_del_espacio(espacio)
        sets = (params.get("catalogo") or {}).get("sets") or {}
        con_imagen = bool(p6.ruta_imagen_del_espacio(ctx.proyecto, params))
        try:
            previstos = p6.sitios_previstos(ctx.proyecto, params, escenas)
        except Exception:                                   # noqa: BLE001
            previstos = [e.get("set") for e in escenas]
        for escena, sitio in zip(escenas, previstos):
            ficha = None
            for carpeta in carpetas:
                if os.path.exists(os.path.join(carpeta, "escenas", f"{escena['id']}.png")):
                    ficha = PASOS_MODULOS.medios.leer_json(
                        os.path.join(carpeta, "escenas", f"{escena['id']}.json"), {}) or {}
                    break
            if ficha is None:
                continue
            salida["hechas"] += 1
            descripcion = " ".join(str((sets.get(sitio) or {}).get("descripcion") or "").split())
            prompt = " ".join(str(ficha.get("prompt") or "").split())
            falta_desc = bool(descripcion) and descripcion not in prompt
            # NO ES UN CAMBIO (aviso falso del 21-10, prueba de la mampara):
            # - un plano EDITADO desde la imagen base (o la de su estado): el
            #   sitio lo pone esa imagen, no la descripcion;
            # - un plano rehecho con nota: el corrector reescribe el prompt y la
            #   descripcion no queda literal, pero partio del plan de ahora, que
            #   si la lleva.
            # Ofrecia pagar otra vez los planos que el revisor acababa de rehacer.
            editado = any(r.get("papel") == "base" for r in ficha.get("referencias") or [])
            del_plan = descripcion in " ".join(str(escena.get("prompt") or "").split())
            if falta_desc and (editado or (ficha.get("corrector") and del_plan)):
                falta_desc = False
            falta_img = (sitio == principal and con_imagen
                         and not any(r.get("papel") == "espacio"
                                     for r in ficha.get("referencias") or []))
            if falta_desc or falta_img:
                salida["planos"].append({
                    "id": escena["id"], "sitio": sitio,
                    "narracion": " ".join(str(escena.get("narracion") or "").split())[:140]})
    salida["imagenes"] = len(salida["planos"])
    usd = _usd_por_imagen(ctx)
    # LA IMAGEN DEL ESPACIO SE PAGA COMO UNA REFERENCIA MAS (tokens de entrada,
    # ~730 por referencia: `coste.TOKENS_POR_REFERENCIA`). La mediana de lo
    # cobrado no la lleva todavia en un video que nunca la adjunto.
    extra = 0.0
    if espacio.get("imagen"):
        try:
            tarifa = float((COSTE.tarifa_tokens() or {}).get("entrada_imagen") or 0.0)
            extra = round(COSTE.TOKENS_POR_REFERENCIA * tarifa, 4)
        except Exception:                                   # noqa: BLE001
            extra = 0.0
    salida.update({"calidad": str(params.get("calidad") or "low"),
                   "usd_por_imagen": usd, "usd_referencia": extra,
                   "usd": round(salida["imagenes"] * (usd + extra), 2)})
    return salida


@app.post("/api/proyectos/{pid}/espacio_fijo/aplicar")
def aplicar_espacio_fijo(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda el espacio fijo de un video hecho y ajusta su catalogo. No dibuja nada.

    {espacio_fijo: {sitio, descripcion, luz, secundarios, imagen?, imagen_nueva?}}
    `imagen` es la ya guardada (se conserva tal cual); `imagen_nueva`, una
    subida que la sustituye; sin ninguna de las dos, sin imagen. -> el espacio
    guardado, el catalogo y los planos que cambiarian (`cambios`)."""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    crudo = datos.get("espacio_fijo")
    if not isinstance(crudo, dict):
        raise ErrorApi(400, "hace falta el objeto 'espacio_fijo'")
    catalogo_mod = _catalogo_visual()
    nueva = crudo.get("imagen_nueva")
    limpio = {k: v for k, v in crudo.items() if k != "imagen_nueva"}
    try:
        espacio = catalogo_mod.normalizar_espacio_fijo(limpio)
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    if not espacio:
        raise ErrorApi(400, "el espacio fijo necesita la descripción del sitio")
    guardada = ((ctx.estado.params("assets") or {}).get("espacio_fijo") or {}).get("imagen")
    if espacio.get("imagen") and espacio["imagen"] != guardada:
        raise ErrorApi(400, "esa imagen no es la del espacio fijo de este vídeo: súbela otra vez")
    png = _png_del_espacio(nueva) if nueva else None
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo generándose en este vídeo: espera a que "
                                "termine y vuelve a aplicarlo")
        if png:
            espacio["imagen"] = _guardar_png_del_espacio(ctx, png)
        cambios = {"espacio_fijo": espacio}
        guardado = (ctx.estado.params("assets") or {}).get("catalogo") or {}
        avisos = []
        if guardado.get("sets") or guardado.get("beats"):
            ids = [b["id"] for b in _bloques_del_guion(ctx)]
            try:
                catalogo, avisos = catalogo_mod.ajustar_catalogo(guardado, espacio, ids)
            except ValueError as fallo:
                raise ErrorApi(400, str(fallo))
            # la firma de los escenarios lleva el espacio: con ella, «deducir los
            # sitios» no vuelve a leer el guion por este cambio
            firma = _firma_del_guion(ctx)
            if firma:
                catalogo["_firma_guion"] = firma + "+" + hashlib.sha256(json.dumps(
                    espacio, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()[:8]
            cambios["catalogo"] = catalogo
        ctx.estado.actualizar_params("assets", cambios)
    ctx.bitacora.anotar("espacio_fijo_aplicado", "assets", {
        "sitio": espacio.get("sitio"), "imagen": bool(espacio.get("imagen")),
        "catalogo": "catalogo" in cambios})
    return {"espacio_fijo": _espacio_fijo_de_ficha(ctx),
            "catalogo": cambios.get("catalogo"), "avisos": avisos,
            "cambios": _cambios_del_espacio(ctx),
            "estado": ctx.estado.estado_de("assets")}


@app.post("/api/proyectos/{pid}/espacio_fijo/rehacer", status_code=202)
def rehacer_planos_del_espacio(pid: str, cuerpo: dict = Body(default=None)):
    """Rehace SOLO los planos pedidos de los que cambian con el espacio fijo (se paga).

    {planos: ["S004", ...], imagenes: n}: `planos` son los elegidos (todos los
    del sitio, o los marcados) y `imagenes` cuantos ha visto quien confirma. Van
    como unidades PEDIDAS, en un trabajo, con la segunda mitad de cada plano
    largo detras (gratis). Lo que no se pide se conserva."""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    pedidos = datos.get("planos")
    if not isinstance(pedidos, list) or not pedidos:
        raise ErrorApi(400, "hace falta 'planos': la lista de los que rehacer")
    pedidos = [str(x).split(":", 1)[-1].strip() for x in pedidos]
    try:
        vistas = int(datos.get("imagenes"))
    except (TypeError, ValueError):
        raise ErrorApi(400, "hace falta 'imagenes': cuántas se confirmaron")
    if vistas != len(set(pedidos)):
        raise ErrorApi(400, f"se piden {len(set(pedidos))} planos y se confirmaron {vistas}")
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo generándose en este vídeo: espera a que "
                                "termine y vuelve a mirarlo")
        with _COLA_LOCK:
            if _cola_dibujando(ctx):
                raise ErrorApi(409, "se están rehaciendo imágenes con tus notas: "
                                    "espera a que terminen")
            posibles = {p["id"] for p in (_cambios_del_espacio(ctx).get("planos") or [])}
            fuera = sorted(set(pedidos) - posibles)
            if fuera:
                raise ErrorApi(409, "estos planos ya no cambian con el espacio fijo: "
                                    + ", ".join(fuera[:8]) + ". Vuelve a mirarlo.",
                               {"fuera": fuera})
            plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets",
                                                       estado=ctx.estado) or {}
            unidades = _con_sus_continuaciones(
                [f"escena:{sid}" for sid in sorted(set(pedidos))], plan)
            trabajo_id = lanzar_paso(ctx, "assets", unidades,
                                     nombre="espacio_fijo",
                                     evento="espacio_fijo_rehacer",
                                     datos={"planos": len(set(pedidos))})
    return {"trabajo_id": trabajo_id, "unidades": unidades,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}








# ----------------------------------------------------------- TIPO DE RELATO
#
# Rama tipo-de-relato (20-10-2026). COMO se cuenta un video en imagenes
# (`pasos/tipo_relato.py`): documental, un espacio que cambia, recorrido,
# escenario y apoyos, producto o clase. Se elige en el Encargo (opcion
# `tipo_relato` de `_opciones_al_crear`), en la Parrilla («Tipo de relato:») o
# por defecto en el preset de Estilo (`estilo.relato`), y se resuelve con
# `tipo_relato.resolver` (opcion B del dueño: video > estilo > espacio fijo
# implicito > documental).
#
# En un video HECHO funciona como «Aplicar el espacio fijo»: guardar no dibuja
# nada, se enseña que planos cambian y cuanto cuesta, y se rehace lo que se pide
# (todos, marcados o ninguno). Los modos que EDITAN necesitan la imagen base del
# sitio aprobada: subida (gratis) o generada (se paga una imagen, con su coste
# delante), y se aprueba antes de pagar ningun plano.

def _tipo_relato():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.tipo_relato


def _tipo_relato_guardado(ctx):
    try:
        return _tipo_relato().normalizar((ctx.estado.params("assets") or {}).get("tipo_relato"))
    except ValueError:
        return {}


def _ficha_tipo_relato(ctx):
    """Lo que la pantalla necesita del tipo de relato del video."""
    tr = _tipo_relato()
    p6 = PASOS_MODULOS.p6_assets
    params = ctx.estado.params("assets") or {}
    guardado = _tipo_relato_guardado(ctx)
    resuelto = tr.resolver(params)
    try:
        sitio, espacio = p6.espacio_del_relato(ctx.proyecto, params)
    except Exception:                                       # noqa: BLE001
        sitio, espacio = None, {}
    bases = {}
    for sid, ficha in (guardado.get("bases") or {}).items():
        bases[sid] = {"aprobada": ficha.get("aprobada", False),
                      "imagen_url": f"/api/proyectos/{ctx.id}/tipo_relato/base/imagen?sitio={sid}"}
    # UN ESTADO, UNA IMAGEN: los estados que pide el guion y su imagen (si la hay)
    estados = []
    try:
        sitio_e, pedidos = p6.estados_del_relato(ctx.proyecto, params)
    except Exception:                                       # noqa: BLE001
        sitio_e, pedidos = None, {}
    guardados = (((guardado.get("bases") or {}).get(sitio_e) or {}).get("estados") or {}) \
        if sitio_e else {}
    for est, cambio in pedidos.items():
        hecho = guardados.get(est) or {}
        vigente = bool(hecho) and hecho.get("cambio") == cambio
        estados.append({
            "estado": est, "cambio": cambio, "vigente": vigente,
            "aprobada": bool(vigente and hecho.get("aprobada")),
            "imagen_url": (f"/api/proyectos/{ctx.id}/tipo_relato/base/imagen?sitio={sitio_e}"
                           f"&estado={est}") if hecho else None})
    subida = (params.get("espacio_fijo") or {}).get("imagen") \
        if isinstance(params.get("espacio_fijo"), dict) else None
    catalogo = params.get("catalogo") or {}
    # sin NINGUN cambio en ningun tramo, todos los planos serian la base tal cual:
    # falta que Claude diga que cambia (un «antes» sin cambio es normal, todos no)
    sin_cambios = (resuelto["modo"] == "espacio_que_cambia" and tr.activo(resuelto)
                   and bool(catalogo.get("beats"))
                   and not any(b.get("cambio")
                               for b in catalogo.get("beats") or [] if isinstance(b, dict)))
    inicial = str(((catalogo.get("relato") or {}) if isinstance(catalogo.get("relato"), dict)
                   else {}).get("inicial") or "")
    # EN ESPAÑOL Y DÓNDE SE USA (rama estados-en-espanol): solo lectura, de un
    # fichero del proyecto y del plan. No escribe nada (regla 1).
    en_espanol = _relato_en_espanol(ctx, params, sitio_e, pedidos, estados, inicial)
    return {
        "tipo_relato": {k: v for k, v in guardado.items() if k != "bases"},
        "resuelto": dict(resuelto, nombre=tr.nombre(resuelto["modo"], resuelto.get("cambia"))),
        "del_estilo": tr.normalizar_de_estilo((params.get("estilo") or {}).get("relato"))
                      if isinstance(params.get("estilo"), dict) else {},
        "modos": [{"clave": k, "nombre": v} for k, v in tr.MODOS.items()],
        "cambia": [{"clave": k, "nombre": v} for k, v in tr.CAMBIA.items()],
        "edita": tr.edita(resuelto),
        "sitio": sitio, "sitio_nombre": (espacio or {}).get("sitio") or sitio,
        "bases": bases,
        "base_aprobada": bool(sitio and (bases.get(sitio) or {}).get("aprobada")),
        "estados": estados,
        # todo aprobado: la base y la imagen de cada estado
        "listo": bool(sitio and (bases.get(sitio) or {}).get("aprobada"))
                 and all(e["aprobada"] for e in estados),
        "puede_usar_subida": bool(subida and sitio),
        "usd_base": _usd_por_imagen(ctx),
        "calidad": str(params.get("calidad") or "low"),
        "faltan_cambios": sin_cambios,
        # como esta en la base lo que luego cambia (lo escribe Claude al repartir)
        "inicial": inicial,
        "inicial_es": en_espanol["inicial_es"],
        # los planos y bloques de la imagen base (los del «antes»)
        "donde_base": en_espanol["donde_base"],
        "traduccion": en_espanol["traduccion"],
    }


@app.get("/api/proyectos/{pid}/tipo_relato")
def leer_tipo_relato(pid: str, ligero: bool = False):
    """El tipo de relato del video: el guardado, el que rige, las bases y los planos que cambian.

    Con `?ligero=1` no se calculan los planos que cambian (lee la ficha de cada
    imagen): es lo que pide la pantalla cada dos segundos mientras traduce."""
    ctx = contexto(pid)
    ficha = _ficha_tipo_relato(ctx)
    if ligero:
        return ficha
    ficha["cambios"] = _cambios_del_relato(ctx) if _tipo_relato_guardado(ctx) else None
    return ficha


# ------------------------------------------- TIPO DE RELATO · EN ESPAÑOL
#
# Rama estados-en-espanol (22-10-2026, pedido del dueño). Los cambios de cada
# estado y lo que la base ya trae (`inicial`) se escriben en INGLÉS, que es lo
# que se manda a dibujar; aquí se enseñan en español (`pasos/traducciones.py`,
# un fichero del proyecto FUERA de params y de toda firma), con DÓNDE SE USA
# cada imagen (bloques del guion y planos), y se pueden reescribir en español:
# Claude lo pasa al inglés y se guarda en el `cambio` de los tramos de ESE
# estado. Traducir no cambia nada; editar mueve el estado (pierde la
# aprobación y pide otra imagen, que no se dibuja sola).
#
# Las dos cosas llaman a Claude y tardan unos segundos: van en un hilo, como la
# ortografía, y NO como trabajo del vídeo (no bloquean generar ni montar). La
# pantalla vuelve a leer la ficha mientras `traduccion.estado` sea «pensando».

_TRADUCIENDO = {}
_LOCK_TRADUCIENDO = threading.Lock()


def _traducciones():
    return getattr(PASOS_MODULOS, "traducciones", None) or __import__("traducciones")


def _relato_en_espanol(ctx, params, sitio, pedidos, estados, inicial):
    """Pega a cada estado su `cambio_es` y su `donde`, y devuelve lo demás.

    -> {"inicial_es", "donde_base", "traduccion": {estado, tipo, error, faltan}}.
    Nada de esto puede tumbar la ficha: sin plan o sin guion, «dónde» va vacío."""
    textos = [e["cambio"] for e in estados if e.get("cambio")] + ([inicial] if inicial else [])
    try:
        mod = _traducciones()
        traducidos = mod.de(ctx.proyecto.raiz, textos)
    except Exception:                                       # noqa: BLE001
        traducidos = {}
    limpio = lambda t: " ".join(str(t or "").split())        # noqa: E731
    try:
        donde = _donde_se_usa_relato(ctx, params, sitio, pedidos)
    except Exception:                                       # noqa: BLE001
        donde = {}
    for e in estados:
        e["cambio_es"] = traducidos.get(limpio(e.get("cambio")), "")
        e["donde"] = donde.get(e["estado"]) or {"bloques": [], "planos": []}
    with _LOCK_TRADUCIENDO:
        marcha = dict(_TRADUCIENDO.get(ctx.id) or {})
    faltan = sum(1 for t in textos if not traducidos.get(limpio(t)))
    return {"inicial_es": traducidos.get(limpio(inicial), "") if inicial else "",
            "donde_base": donde.get("") or {"bloques": [], "planos": []},
            "traduccion": {"estado": marcha.get("estado") or "listo",
                           "tipo": marcha.get("tipo") or "",
                           "estado_relato": marcha.get("estado_relato") or "",
                           "error": marcha.get("error") or "",
                           "faltan": faltan}}


def _donde_se_usa_relato(ctx, params, sitio, pedidos):
    """{estado: {"bloques": [{id, n, texto}], "planos": [ids]}}; la clave "" es la
    imagen base (los tramos sin cambio, el «antes»).

    Los BLOQUES salen del catálogo (cada tramo dice desde/hasta qué bloque del
    guion), así que se saben aunque no haya imágenes. Los PLANOS salen del plan
    cortado: los que editan la imagen de ese estado (mismo `cambio`) o la base
    (editan y sin cambio). Sin plan, la lista va vacía y la pantalla lo dice."""
    tr = _tipo_relato()
    if not sitio:
        return {}
    catalogo = params.get("catalogo") or {}
    bloques = _bloques_del_guion(ctx)
    posicion = {b["id"].upper(): i for i, b in enumerate(bloques)}
    salida = {}

    def ficha(clave):
        return salida.setdefault(clave, {"bloques": [], "planos": [], "_vistos": set()})

    for beat in catalogo.get("beats") or []:
        if not isinstance(beat, dict) or beat.get("set") not in (None, "", sitio):
            continue
        estado = tr.estado_de(beat)
        if estado and estado not in pedidos:
            continue
        desde = posicion.get(str(beat.get("desde") or "").strip().upper())
        hasta = posicion.get(str(beat.get("hasta") or beat.get("desde") or "").strip().upper())
        if desde is None:
            continue
        hasta = desde if hasta is None or hasta < desde else hasta
        f = ficha(estado)
        for i in range(desde, hasta + 1):
            if i in f["_vistos"]:
                continue
            f["_vistos"].add(i)
            texto = " ".join(bloques[i]["texto"].split())
            f["bloques"].append({"id": bloques[i]["id"], "n": i + 1,
                                 "texto": texto[:110] + ("…" if len(texto) > 110 else "")})
    por_cambio = {" ".join(str(c or "").split()): est for est, c in pedidos.items()}
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    for escena in plan.get("escenas") or []:
        if not escena.get("editar_base") or not escena.get("id"):
            continue
        cambio = " ".join(str(escena.get("cambio") or "").split())
        # POR LA CLAVE DE SU IMAGEN primero («sitio#estado», `_marcar_edicion`):
        # sigue valiendo cuando se acaba de editar el cambio y el plan todavía
        # lleva el texto de antes. Por el texto, solo si no la trae.
        clave = str(escena.get("base_clave") or "")
        if "#" in clave:
            estado = clave.split("#", 1)[1]
            if estado not in pedidos:
                continue
        elif cambio:
            estado = por_cambio.get(cambio)
            if estado is None:
                continue
        else:
            estado = ""
        ficha(estado)["planos"].append(str(escena["id"]))
    for f in salida.values():
        f["bloques"].sort(key=lambda b: b["n"])
        f.pop("_vistos", None)
    return salida


def _textos_del_relato(ctx):
    """Los textos en inglés que se enseñan traducidos: cada cambio y `inicial`."""
    p6 = PASOS_MODULOS.p6_assets
    params = ctx.estado.params("assets") or {}
    try:
        _sitio, pedidos = p6.estados_del_relato(ctx.proyecto, params)
    except Exception:                                       # noqa: BLE001
        pedidos = {}
    catalogo = params.get("catalogo") or {}
    relato = catalogo.get("relato") if isinstance(catalogo.get("relato"), dict) else {}
    textos = [c for c in pedidos.values() if c]
    if (relato or {}).get("inicial"):
        textos.append(relato["inicial"])
    return textos


def _error_para_persona(fallo):
    error = str(fallo)[:600]
    if CLI_CLAUDE.es_pasajero(fallo):
        error = ("La sesión de Claude se estaba renovando y no ha contestado. Vuelve a "
                 f"intentarlo en un minuto; no se ha cambiado nada.\n\n{error}")
    return error


def _lanzar_traduccion(ctx, tipo, correr, estado_relato=""):
    """Corre `correr()` en un hilo y deja su estado en `_TRADUCIENDO[pid]`.
    -> False si ya había una en marcha para este vídeo."""
    with _LOCK_TRADUCIENDO:
        if (_TRADUCIENDO.get(ctx.id) or {}).get("estado") == "pensando":
            return False
        _TRADUCIENDO[ctx.id] = {"estado": "pensando", "tipo": tipo,
                                "estado_relato": estado_relato}

    def hilo():
        try:
            correr()
            ficha = {"estado": "listo", "tipo": tipo, "estado_relato": estado_relato}
        except Exception as fallo:                          # noqa: BLE001
            ficha = {"estado": "error", "tipo": tipo, "estado_relato": estado_relato,
                     "error": _error_para_persona(fallo)}
        with _LOCK_TRADUCIENDO:
            _TRADUCIENDO[ctx.id] = ficha

    threading.Thread(target=hilo, daemon=True, name=f"traducir-{ctx.id}").start()
    return True


@app.post("/api/proyectos/{pid}/tipo_relato/traducir")
def traducir_tipo_relato(pid: str, cuerpo: dict = Body(default=None)):
    """Traduce al español lo que falte (cada cambio y `inicial`). {auto?: bool}

    No cambia ningún param ni ninguna firma: la traducción va a
    `<proyecto>/traducciones.json`. Con `auto` (lo pide la pantalla sola al
    abrir) no se relanza tras un error: así una sesión de Claude caída no se
    reintenta cada vez que se repinta; el botón «Traducir» sí. -> la ficha."""
    ctx = contexto(pid)
    auto = bool(_cuerpo(cuerpo).get("auto"))
    mod = _traducciones()
    faltan = mod.faltan(ctx.proyecto.raiz, _textos_del_relato(ctx))
    with _LOCK_TRADUCIENDO:
        previo = dict(_TRADUCIENDO.get(ctx.id) or {})
    if faltan and not (auto and previo.get("estado") == "error"):
        raiz = ctx.proyecto.raiz

        def correr():
            hechas = mod.al_espanol(faltan, cwd=RAIZ_ESTUDIO)
            mod.guardar(raiz, hechas)
            if not hechas:
                raise mod.ErrorTraduccion("Claude no ha devuelto ninguna traducción; "
                                          "vuelve a pedirla.")
            ctx.bitacora.anotar("tipo_relato_traducido", "assets", {"textos": len(hechas)})

        _lanzar_traduccion(ctx, "traducir", correr)
    return _ficha_tipo_relato(ctx)


@app.post("/api/proyectos/{pid}/tipo_relato/estado/editar")
def editar_estado_relato(pid: str, cuerpo: dict = Body(default=None)):
    """Reescribe en ESPAÑOL el cambio de un estado. {estado, es}

    Claude lo pasa al inglés (en un hilo) y se guarda en el `cambio` de todos
    los tramos de ese estado, con la misma etiqueta: su imagen deja de valer
    (pierde la aprobación y pide otra) y sus planos quedan para rehacer. No se
    dibuja nada. -> la ficha, con `traduccion.estado` «pensando»."""
    tr = _tipo_relato()
    p6 = PASOS_MODULOS.p6_assets
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    estado = str(datos.get("estado") or "").strip()
    es = " ".join(str(datos.get("es") or "").split())
    if not es:
        raise ErrorApi(400, "escribe el cambio en español")
    if len(es) > 1200:
        raise ErrorApi(400, "el cambio es demasiado largo: como mucho 1.200 letras")
    params = ctx.estado.params("assets") or {}
    sitio, pedidos = p6.estados_del_relato(ctx.proyecto, params)
    if not sitio or estado not in pedidos:
        raise ErrorApi(404, f"este vídeo no tiene el estado «{estado}»")
    if not ((params.get("catalogo") or {}).get("beats")):
        raise ErrorApi(409, "los cambios de este vídeo no están guardados en el reparto: "
                            "pulsa antes «Escribir qué cambia en cada tramo»")
    if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
        raise ErrorApi(409, "hay algo generándose en este vídeo: cámbialo cuando termine")
    with _COLA_LOCK:
        if _cola_dibujando(ctx):
            raise ErrorApi(409, "se están rehaciendo imágenes con tus notas: cámbialo "
                                "cuando terminen")
    anterior = pedidos[estado]
    mod = _traducciones()
    raiz = ctx.proyecto.raiz

    def correr():
        ingles = mod.al_ingles(es, anterior=anterior, cwd=RAIZ_ESTUDIO)
        with _cerrojo_de_cadena(ctx.id):
            with _COLA_LOCK:
                dibujando = _cola_dibujando(ctx)
            if dibujando or _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
                raise RuntimeError("se ha empezado a generar algo en este vídeo mientras "
                                   "se traducía: vuelve a guardar el cambio cuando termine")
            catalogo = copy.deepcopy((ctx.estado.params("assets") or {}).get("catalogo") or {})
            tocados = 0
            for beat in catalogo.get("beats") or []:
                if not isinstance(beat, dict) or beat.get("set") not in (None, "", sitio):
                    continue
                if tr.estado_de(beat) != estado:
                    continue
                # comparado COMO LO LEE `estados_del_catalogo` (recortado a su
                # tope): un cambio largo escrito a mano no da un falso «se ha
                # reescrito»
                if tr._texto(beat.get("cambio"), 400) != tr._texto(anterior, 400):
                    raise RuntimeError("los cambios de este estado se han reescrito mientras "
                                       "se traducía: vuelve a abrirlo y guárdalo otra vez")
                beat["cambio"] = ingles
                # la MISMA etiqueta: es lo que mantiene el estado (y su sitio
                # en el mapa de bases) aunque cambie su texto
                beat["estado"] = estado
                tocados += 1
            if not tocados:
                raise RuntimeError(f"el estado «{estado}» ya no está en el reparto")
            if ingles != tr._texto(anterior, 400):
                ctx.estado.actualizar_params("assets", {"catalogo": catalogo})
        mod.guardar(raiz, {ingles: es})
        ctx.bitacora.anotar("tipo_relato_estado_editado", "assets",
                            {"estado": estado, "tramos": tocados})

    if not _lanzar_traduccion(ctx, "editar", correr, estado_relato=estado):
        raise ErrorApi(409, "ya se está traduciendo algo de este vídeo: espera unos segundos")
    return _ficha_tipo_relato(ctx)


def _cambios_del_relato(ctx):
    """QUE PLANOS HECHOS CAMBIARIAN con el tipo de relato que rige, y su coste.

    -> {"planos": [{id, sitio, narracion}], "imagenes", "usd_por_imagen", "usd",
        "calidad", "hechas"}. Cambia un plano hecho del sitio cuando:
      - se edita desde la base y su imagen no salio de editarla;
      - lleva la base como referencia (modos de referencia o planos de detalle)
        y no la lleva;
      - salio de editar una base y ya no se edita (se volvio a otro modo).
    Repetir «Aplicar» con lo mismo no ofrece nada que rehacer."""
    tr = _tipo_relato()
    p6 = PASOS_MODULOS.p6_assets
    params = ctx.estado.params("assets") or {}
    relato = tr.resolver(params)
    plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = [e for e in _escenas_que_pagan(plan) if not e.get("componente")]
    carpetas = _carpetas_de_assets(ctx)
    salida = {"planos": [], "imagenes": 0, "hechas": 0}
    if escenas and carpetas:
        try:
            sitio, _ = p6.espacio_del_relato(ctx.proyecto, params)
        except Exception:                                   # noqa: BLE001
            sitio = None
        bases = tr.bases_aprobadas(params) if tr.activo(relato) else {}
        modo_img = p6.modo_de(params.get("estilo"))
        try:
            previstos = p6.sitios_previstos(ctx.proyecto, params, escenas)
        except Exception:                                   # noqa: BLE001
            previstos = [e.get("set") for e in escenas]
        for escena, previsto in zip(escenas, previstos):
            ficha = None
            for carpeta in carpetas:
                if os.path.exists(os.path.join(carpeta, "escenas", f"{escena['id']}.png")):
                    ficha = PASOS_MODULOS.medios.leer_json(
                        os.path.join(carpeta, "escenas", f"{escena['id']}.json"), {}) or {}
                    break
            if ficha is None:
                continue
            salida["hechas"] += 1
            papeles = {r.get("papel") for r in ficha.get("referencias") or []
                       if isinstance(r, dict)}
            familia = (PASOS_MODULOS.encuadres.por_id_de(modo_img).get(escena.get("carta") or "")
                       or {}).get("familia", "")
            editaria = tr.plano_se_edita(dict(escena, set=previsto), relato, sitio, familia)
            cambia = False
            if editaria:
                cambia = "base" not in papeles
            elif "base" in papeles:
                cambia = True
            elif tr.activo(relato) and previsto in bases and "espacio" not in papeles:
                cambia = True
            if cambia:
                salida["planos"].append({
                    "id": escena["id"], "sitio": previsto,
                    "narracion": " ".join(str(escena.get("narracion") or "").split())[:140]})
    salida["imagenes"] = len(salida["planos"])
    usd = _usd_por_imagen(ctx)
    salida.update({"calidad": str(params.get("calidad") or "low"),
                   "usd_por_imagen": usd, "usd": round(salida["imagenes"] * usd, 2)})
    return salida


@app.post("/api/proyectos/{pid}/tipo_relato/aplicar")
def aplicar_tipo_relato(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda el tipo de relato de un video (hecho o no). No dibuja nada.

    {tipo_relato: {modo, cambia?}} o {tipo_relato: null} para volver a lo que
    diga el estilo. En un video con catalogo, un modo de UN solo sitio ajusta
    los sitios sin llamar a nadie (`catalogo_visual.ajustar_catalogo`). -> la
    ficha y los planos que cambiarian (`cambios`)."""
    tr = _tipo_relato()
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    crudo = datos.get("tipo_relato")
    if crudo is not None and not isinstance(crudo, dict):
        raise ErrorApi(400, "'tipo_relato' tiene que ser un objeto {modo, cambia} o null")
    try:
        pedido = tr.normalizar({k: v for k, v in (crudo or {}).items()
                                if k in ("modo", "cambia")}) if crudo else {}
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    catalogo_mod = _catalogo_visual()
    avisos = []
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo generándose en este vídeo: espera a que "
                                "termine y vuelve a aplicarlo")
        actual = dict(ctx.estado.params("assets") or {})
        previo = _tipo_relato_guardado(ctx)
        provisional = {k: v for k, v in (pedido or {}).items()}
        if previo.get("bases"):
            provisional["bases"] = previo["bases"]
        params = dict(actual, tipo_relato=provisional or None)
        relato = tr.resolver(params)
        guardado = params.get("catalogo") or {}
        cambios_params = {}
        if tr.activo(relato) and (guardado.get("sets") or guardado.get("beats")):
            espacio = _espacio_fijo_guardado(ctx) or catalogo_mod.espacio_del_catalogo(guardado)
            if espacio:
                ids = [b["id"] for b in _bloques_del_guion(ctx)]
                try:
                    catalogo, avisos = catalogo_mod.ajustar_catalogo(guardado, espacio, ids)
                except ValueError as fallo:
                    raise ErrorApi(400, str(fallo))
                previo = guardado.get("relato") if isinstance(guardado.get("relato"), dict) else {}
                mismo = (previo.get("modo"), previo.get("cambia")) == (relato["modo"],
                                                                       relato.get("cambia"))
                catalogo["relato"] = {k: v for k, v in (("modo", relato["modo"]),
                                                        ("cambia", relato.get("cambia")),
                                                        ("inicial", previo.get("inicial")
                                                         if mismo else "")) if v}
                if relato["modo"] != "espacio_que_cambia":
                    for beat in catalogo.get("beats") or []:
                        beat.pop("cambio", None)
                        beat.pop("estado", None)
                firma = _firma_del_guion(ctx)
                if firma:
                    if _espacio_fijo_guardado(ctx):
                        firma += "+" + hashlib.sha256(json.dumps(
                            _espacio_fijo_guardado(ctx), sort_keys=True,
                            ensure_ascii=False).encode("utf-8")).hexdigest()[:8]
                    firma += "+relato:" + relato["modo"] + (
                        ":" + relato["cambia"] if relato.get("cambia") else "")
                    catalogo["_firma_guion"] = firma
                cambios_params["catalogo"] = catalogo
        # el modo y el catalogo, en UNA escritura: si el ajuste falla (400) no
        # queda guardado un modo sin su catalogo
        final = tr.normalizar(provisional) if provisional else {}
        if final or previo:
            cambios_params["tipo_relato"] = final or None
        if cambios_params:
            ctx.estado.actualizar_params("assets", cambios_params)
    ctx.bitacora.anotar("tipo_relato_aplicado", "assets", {
        "modo": (pedido or {}).get("modo"), "cambia": (pedido or {}).get("cambia")})
    ficha = _ficha_tipo_relato(ctx)
    ficha.update({"avisos": avisos, "cambios": _cambios_del_relato(ctx),
                  "estado": ctx.estado.estado_de("assets")})
    return ficha


@_medido_en("assets", "cambios_relato")
def _correr_cambios_relato(avisar, ctx, ajuste):
    """Claude escribe QUE CAMBIA en cada tramo de un catalogo ya guardado."""
    tr = _tipo_relato()
    params = ctx.estado.params("assets") or {}
    relato = tr.resolver(params)
    leido = params.get("catalogo") or {}
    catalogo, avisos = _catalogo_visual().proponer_cambios(
        _bloques_del_guion(ctx), leido, relato, ajuste=ajuste,
        avisar=avisar, proyecto_id=ctx.id, cwd=ctx.proyecto.raiz)
    with _cerrojo_de_cadena(ctx.id):
        # si el catalogo cambio mientras Claude leia, no se pisa lo nuevo
        if ((ctx.estado.params("assets") or {}).get("catalogo") or {}) != leido:
            raise RuntimeError("el reparto y los sitios cambiaron mientras se escribían "
                               "los cambios: vuelve a pedirlos")
        ctx.estado.actualizar_params("assets", {"catalogo": catalogo})
    ctx.bitacora.anotar("tipo_relato_cambios", "assets",
                        {"tramos": len(catalogo.get("beats") or [])})
    avisar(1.0, "cambios por tramo escritos")
    return {"tramos": len(catalogo.get("beats") or []), "avisos": avisos}


@app.post("/api/proyectos/{pid}/tipo_relato/cambios", status_code=202)
def escribir_cambios_relato(pid: str, cuerpo: dict = Body(default=None)):
    """En «un espacio que cambia», Claude escribe el cambio de cada tramo (solo texto)."""
    tr = _tipo_relato()
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    relato = tr.resolver(ctx.estado.params("assets") or {})
    if relato["modo"] != "espacio_que_cambia" or not tr.activo(relato):
        raise ErrorApi(400, "solo «Un espacio que cambia» lleva cambios por tramo")
    por_fase = CLI_CLAUDE.por_defecto_de("catalogo_visual")
    ajuste = _ajuste_cli(datos, por_fase["modelo"], por_fase["esfuerzo"])
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo en marcha en este vídeo: espera a que termine")
        trabajo_id = ctx.gestor.lanzar("tipo_relato_cambios", _correr_cambios_relato, ctx,
                                       ajuste, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@_medido_en("assets", "base")
@_con_turno
def _correr_base(avisar, ctx, rehacer):
    """Genera (y paga) la imagen base del sitio. No la aprueba."""
    p6 = PASOS_MODULOS.p6_assets
    avisar(0.1, "dibujando la imagen base del sitio (se paga una imagen)")
    hecho = p6.generar_imagen_base(ctx.proyecto, ctx.estado.params("assets") or {},
                                   rehacer=rehacer)
    tr = _tipo_relato()
    with _cerrojo_de_cadena(ctx.id):
        guardado = _tipo_relato_guardado(ctx)
        bases = dict(guardado.get("bases") or {})
        bases[hecho["sitio"]] = {"imagen": hecho["imagen"], "aprobada": False}
        guardado["bases"] = bases
        ctx.estado.actualizar_params("assets", {"tipo_relato": tr.normalizar(guardado)})
    ctx.bitacora.anotar("tipo_relato_base", "assets", {
        "sitio": hecho["sitio"], "coste": hecho.get("coste"), "origen": hecho.get("origen")})
    avisar(1.0, "imagen base lista: mírala y apruébala")
    return hecho


@_medido_en("assets", "base")
@_con_turno
def _correr_estado(avisar, ctx, estado, rehacer):
    """Genera (y paga) la imagen de un estado: la base, cambiada una vez. No la aprueba."""
    p6 = PASOS_MODULOS.p6_assets
    avisar(0.1, f"dibujando el estado «{estado}» sobre la imagen base (se paga una imagen)")
    hecho = p6.generar_imagen_estado(ctx.proyecto, ctx.estado.params("assets") or {},
                                     estado, rehacer=rehacer)
    tr = _tipo_relato()
    with _cerrojo_de_cadena(ctx.id):
        guardado = _tipo_relato_guardado(ctx)
        bases = dict(guardado.get("bases") or {})
        ficha = dict(bases.get(hecho["sitio"]) or {})
        if not ficha:
            raise RuntimeError("la imagen base del sitio ha desaparecido mientras se dibujaba")
        estados = dict(ficha.get("estados") or {})
        estados[estado] = {"imagen": hecho["imagen"], "aprobada": False,
                           "cambio": hecho["cambio"]}
        ficha["estados"] = estados
        bases[hecho["sitio"]] = ficha
        guardado["bases"] = bases
        ctx.estado.actualizar_params("assets", {"tipo_relato": tr.normalizar(guardado)})
    ctx.bitacora.anotar("tipo_relato_estado", "assets", {
        "sitio": hecho["sitio"], "estado": estado, "coste": hecho.get("coste"),
        "origen": hecho.get("origen")})
    avisar(1.0, f"estado «{estado}» listo: míralo y apruébalo")
    return hecho


@app.post("/api/proyectos/{pid}/tipo_relato/base/generar", status_code=202)
def generar_base_relato(pid: str, cuerpo: dict = Body(default=None)):
    """Genera la imagen base del sitio, o con {estado} la de ese estado (SE PAGA una
    imagen). {usd: lo que se vio, estado?, otra?}"""
    tr = _tipo_relato()
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    params = ctx.estado.params("assets") or {}
    if not tr.edita(tr.resolver(params)):
        raise ErrorApi(400, "la imagen base que se edita es de «Un espacio que cambia» y "
                            "«Producto»: elige antes uno de los dos")
    try:
        visto = float(datos.get("usd"))
    except (TypeError, ValueError):
        raise ErrorApi(400, "hace falta 'usd': el coste que se ha enseñado antes de pagar")
    ahora = _usd_por_imagen(ctx)
    if ahora and abs(visto - ahora) > max(0.01, ahora * 0.25):
        raise ErrorApi(409, f"el precio ha cambiado (≈ {ahora:.3f} $): vuelve a mirarlo")
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo generándose en este vídeo: las imágenes "
                                "se generan de una tanda en una")
        estado = str(datos.get("estado") or "").strip()
        if estado:
            sitio_e, pedidos = PASOS_MODULOS.p6_assets.estados_del_relato(ctx.proyecto, params)
            if estado not in pedidos:
                raise ErrorApi(404, f"el estado «{estado}» no está en los cambios de este vídeo")
            if not tr.bases_aprobadas(params).get(sitio_e):
                raise ErrorApi(409, "aprueba antes la imagen base: cada estado se dibuja "
                                    "editándola")
            trabajo_id = ctx.gestor.lanzar("tipo_relato_estado", _correr_estado, ctx, estado,
                                           bool(datos.get("otra")), paso="assets")
        else:
            trabajo_id = ctx.gestor.lanzar("tipo_relato_base", _correr_base, ctx,
                                           bool(datos.get("otra")), paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@app.post("/api/proyectos/{pid}/tipo_relato/base/usar_subida")
def usar_subida_como_base(pid: str):
    """La imagen subida del espacio fijo pasa a ser la base, aprobada (gratis)."""
    tr = _tipo_relato()
    ctx = contexto(pid)
    params = ctx.estado.params("assets") or {}
    subida = (params.get("espacio_fijo") or {}).get("imagen") \
        if isinstance(params.get("espacio_fijo"), dict) else None
    sitio, _ = PASOS_MODULOS.p6_assets.espacio_del_relato(ctx.proyecto, params)
    if not subida or not sitio:
        raise ErrorApi(400, "este vídeo no tiene imagen subida del espacio fijo")
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo en marcha en este vídeo: espera a que termine")
        guardado = _tipo_relato_guardado(ctx)
        bases = dict(guardado.get("bases") or {})
        bases[sitio] = {"imagen": subida, "aprobada": True}
        guardado["bases"] = bases
        ctx.estado.actualizar_params("assets", {"tipo_relato": tr.normalizar(guardado)})
    ctx.bitacora.anotar("tipo_relato_base", "assets", {"sitio": sitio, "subida": True})
    ficha = _ficha_tipo_relato(ctx)
    ficha["cambios"] = _cambios_del_relato(ctx)
    return ficha


@app.post("/api/proyectos/{pid}/tipo_relato/base/aprobar")
def aprobar_base_relato(pid: str, cuerpo: dict = Body(default=None)):
    """{sitio?, estado?, aprobada: true|false}: aprueba (o retira) la imagen base del
    sitio, o con `estado` la de ese estado."""
    tr = _tipo_relato()
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    aprobada = datos.get("aprobada", True)
    if not isinstance(aprobada, bool):
        raise ErrorApi(400, "'aprobada' tiene que ser true o false")
    sitio = str(datos.get("sitio") or "") or PASOS_MODULOS.p6_assets.espacio_del_relato(
        ctx.proyecto, ctx.estado.params("assets") or {})[0]
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo en marcha en este vídeo: espera a que termine")
        guardado = _tipo_relato_guardado(ctx)
        bases = dict(guardado.get("bases") or {})
        if sitio not in bases:
            raise ErrorApi(404, "ese sitio no tiene imagen base: genérala o usa la subida")
        estado = str(datos.get("estado") or "").strip()
        if estado:
            estados = dict(bases[sitio].get("estados") or {})
            if estado not in estados:
                raise ErrorApi(404, f"el estado «{estado}» no tiene imagen: genérala antes")
            estados[estado] = dict(estados[estado], aprobada=aprobada)
            bases[sitio] = dict(bases[sitio], estados=estados)
        else:
            bases[sitio] = dict(bases[sitio], aprobada=aprobada)
        guardado["bases"] = bases
        ctx.estado.actualizar_params("assets", {"tipo_relato": tr.normalizar(guardado)})
    ctx.bitacora.anotar("tipo_relato_base_aprobada", "assets",
                        {"sitio": sitio, "estado": estado, "aprobada": aprobada})
    ficha = _ficha_tipo_relato(ctx)
    ficha["cambios"] = _cambios_del_relato(ctx)
    return ficha


@app.get("/api/proyectos/{pid}/tipo_relato/base/imagen")
def imagen_base_relato(pid: str, sitio: str = Query(default=""),
                       estado: str = Query(default="")):
    """La imagen base (aprobada o no) de un sitio del video, o la de un estado."""
    ctx = contexto(pid)
    bases = _tipo_relato_guardado(ctx).get("bases") or {}
    ficha = bases.get(sitio) or (next(iter(bases.values())) if bases and not sitio else None)
    if not ficha:
        raise ErrorApi(404, "ese sitio no tiene imagen base")
    if isinstance(estado, str) and estado:      # llamada directa: Query() no es un str
        ficha = (ficha.get("estados") or {}).get(estado)
        if not ficha:
            raise ErrorApi(404, "ese estado no tiene imagen")
    try:
        ruta = ctx.proyecto.ruta(*str(ficha["imagen"]).split("/"))
    except ValueError:
        raise ErrorApi(404, "imagen base fuera del proyecto")
    if not os.path.exists(ruta):
        raise ErrorApi(404, "la imagen base ya no está en el disco")
    return FileResponse(ruta, media_type="image/png")


@app.post("/api/proyectos/{pid}/tipo_relato/rehacer", status_code=202)
def rehacer_planos_del_relato(pid: str, cuerpo: dict = Body(default=None)):
    """Rehace SOLO los planos pedidos de los que cambian con el tipo de relato (se paga).

    {planos: [...], imagenes: n}, como `/espacio_fijo/rehacer`."""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    pedidos = datos.get("planos")
    if not isinstance(pedidos, list) or not pedidos:
        raise ErrorApi(400, "hace falta 'planos': la lista de los que rehacer")
    pedidos = [str(x).split(":", 1)[-1].strip() for x in pedidos]
    try:
        vistas = int(datos.get("imagenes"))
    except (TypeError, ValueError):
        raise ErrorApi(400, "hace falta 'imagenes': cuántas se confirmaron")
    if vistas != len(set(pedidos)):
        raise ErrorApi(400, f"se piden {len(set(pedidos))} planos y se confirmaron {vistas}")
    ficha = _ficha_tipo_relato(ctx)
    if ficha["edita"] and not ficha["listo"]:
        raise ErrorApi(409, "falta aprobar la imagen base del sitio (y la de cada estado) "
                            "antes de rehacer planos")
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo generándose en este vídeo: espera a que "
                                "termine y vuelve a mirarlo")
        with _COLA_LOCK:
            if _cola_dibujando(ctx):
                raise ErrorApi(409, "se están rehaciendo imágenes con tus notas: "
                                    "espera a que terminen")
            posibles = {p["id"] for p in (_cambios_del_relato(ctx).get("planos") or [])}
            fuera = sorted(set(pedidos) - posibles)
            if fuera:
                raise ErrorApi(409, "estos planos ya no cambian con el tipo de relato: "
                                    + ", ".join(fuera[:8]) + ". Vuelve a mirarlo.",
                               {"fuera": fuera})
            plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets",
                                                       estado=ctx.estado) or {}
            unidades = _con_sus_continuaciones(
                [f"escena:{sid}" for sid in sorted(set(pedidos))], plan)
            trabajo_id = lanzar_paso(ctx, "assets", unidades,
                                     nombre="tipo_relato",
                                     evento="tipo_relato_rehacer",
                                     datos={"planos": len(set(pedidos))})
    return {"trabajo_id": trabajo_id, "unidades": unidades,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


def _tipo_relato_pedido(opciones):
    """El `tipo_relato` de las opciones del encargo, limpio. -> {} o {modo, cambia?}"""
    if not isinstance(opciones, dict) or opciones.get("tipo_relato") in (None, "", {}):
        return {}
    crudo = opciones["tipo_relato"]
    if not isinstance(crudo, dict):
        raise ErrorApi(400, "tipo_relato: tiene que ser un objeto {modo, cambia}")
    try:
        return _tipo_relato().normalizar({k: v for k, v in crudo.items()
                                          if k in ("modo", "cambia")})
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))


# ------------------------------------------------------------ GUION VISUAL
#
# Rama guion-visual (22-10-2026). «Qué dibujan las imágenes»: lo que dice la
# voz (como siempre, sin guardar nada) o lo que dice el guion. Con el guion,
# cada linea del guion visual es un plano; sale de las lineas «Visual:» de la
# Parrilla o de un borrador de Claude, y una persona lo aprueba antes de pagar
# ninguna imagen. Ver pasos/guion_visual.py.

def _guion_visual():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.guion_visual


def _ruta_comprobacion_gv(ctx):
    return ctx.proyecto.ruta("guion_visual_comprobacion.json")


def _fijo_del_video(ctx):
    """(espacio, reparto, estados) que el guion visual no puede contradecir."""
    params = ctx.estado.params("assets") or {}
    p6 = PASOS_MODULOS.p6_assets
    try:
        sitio, espacio = p6.espacio_del_relato(ctx.proyecto, params)
    except Exception:                                       # noqa: BLE001
        sitio, espacio = None, {}
    reparto = ((params.get("catalogo") or {}).get("reparto") or {})
    try:
        _s, estados = p6.estados_del_relato(ctx.proyecto, params)
    except Exception:                                       # noqa: BLE001
        estados = {}
    return espacio or {}, reparto, estados or {}


def _ficha_guion_visual(ctx):
    gv = _guion_visual()
    params = ctx.estado.params("assets") or {}
    try:
        guardado = gv.normalizar(params.get("guion_visual"))
    except ValueError:
        guardado = {}
    # sin las marcas de la voz (<break .../>): son de la locucion, no de lo que se lee
    bloques = [{"id": str(b.get("id")),
                "texto": re.sub(r"\s+", " ", re.sub(r"<[^>]*>", " ", str(b.get("texto") or ""))).strip()}
               for b in _bloques_del_guion(ctx)]
    propuesta, avisos = [], []
    if not guardado.get("planos") and guardado.get("visuales"):
        # las lineas «Visual:» de la Parrilla, casadas con el guion de ahora;
        # no se guardan hasta que alguien las mira y guarda (regla 1)
        propuesta, avisos = gv.casar(guardado["visuales"], bloques)
    # las de la Parrilla que casan limpias valen como aprobadas (guion-visual-2)
    _planos_ef, origen_ef = gv.efectivo(params, bloques)
    auto = origen_ef == "parrilla"
    espacio, reparto, estados = _fijo_del_video(ctx)
    fuera = gv.fuera_de_la_voz(guardado.get("planos"), [b["id"] for b in bloques])
    comprobacion = PASOS_MODULOS.medios.leer_json(_ruta_comprobacion_gv(ctx), {}) or {}
    if comprobacion.get("huella") != gv.huella(guardado.get("planos")):
        comprobacion = {}
    estilo = params.get("estilo") if isinstance(params.get("estilo"), dict) else {}
    return {"modo": gv.modo_de(params),
            "del_video": params.get("imagenes") or "",
            "del_estilo": estilo.get("imagenes") or "",
            "modos": [{"clave": k, "nombre": v} for k, v in gv.MODOS.items()],
            "guion_visual": guardado, "propuesta": propuesta, "avisos": avisos,
            "bloques": bloques, "estados": sorted(estados), "reparto": sorted(reparto),
            "comprobacion": comprobacion.get("avisos"),
            # bloques del guion visual que ya no estan en el guion: no vale hasta revisarlo
            "fuera_de_la_voz": fuera,
            # «parrilla»: las lineas de la Parrilla, aprobadas solas
            "aprobado_solo": auto,
            "aprobado": (bool(guardado.get("aprobado")) or auto) and not fuera}


@app.get("/api/proyectos/{pid}/guion_visual")
def leer_guion_visual(pid: str):
    """Qué dibujan las imágenes de un vídeo, su guion visual y lo que hay que revisar."""
    return _ficha_guion_visual(contexto(pid))


@app.put("/api/proyectos/{pid}/guion_visual/modo")
def guardar_modo_guion_visual(pid: str, cuerpo: dict = Body(default=None)):
    """{imagenes: "guion" | "voz" | null}: qué dibujan las imágenes de ESTE vídeo.

    null vuelve a lo que diga el estilo (y quita la clave). No dibuja nada: los
    planos hechos cambian de firma y se ofrecen para rehacer como siempre."""
    gv = _guion_visual()
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    if "imagenes" not in datos:
        raise ErrorApi(400, "manda {imagenes: guion | voz | null}")
    crudo = datos.get("imagenes")
    if crudo not in (None, "") and gv._llano(crudo).strip() == "voz":
        # «la voz» explicita solo hace falta para mandar sobre un estilo que
        # diga «guion»; si no, es lo de siempre y no se escribe nada (regla 1)
        estilo = (ctx.estado.params("assets") or {}).get("estilo")
        valor = "voz" if (estilo if isinstance(estilo, dict) else {}).get("imagenes") == "guion" else ""
    else:
        try:
            valor = gv.normalizar_modo(crudo)
        except ValueError as fallo:
            raise ErrorApi(400, str(fallo))
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo en marcha en este vídeo: espera a que termine")
        params = ctx.estado.params("assets") or {}
        if (params.get("imagenes") or "") != (valor or ""):
            if valor:
                ctx.estado.actualizar_params("assets", {"imagenes": valor})
            else:
                ctx.estado.set_params("assets", {k: v for k, v in params.items()
                                                 if k != "imagenes"})
    ctx.bitacora.anotar("guion_visual_modo", "assets", {"imagenes": valor or "estilo"})
    return _ficha_guion_visual(ctx)


@app.put("/api/proyectos/{pid}/guion_visual")
def guardar_guion_visual(pid: str, cuerpo: dict = Body(default=None)):
    """{planos: [{bloque, visual, camara?, estado?, personajes?}]}: el guion visual
    escrito o corregido a mano. Guardarlo lo deja SIN aprobar."""
    gv = _guion_visual()
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    planos = datos.get("planos")
    if not isinstance(planos, list):
        raise ErrorApi(400, "manda {planos: [...]}")
    validos = {str(b.get("id")).upper() for b in _bloques_del_guion(ctx)}
    if not validos:
        raise ErrorApi(409, "todavía no hay guion: genéralo antes de escribir el guion visual")
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo en marcha en este vídeo: espera a que termine")
        params = ctx.estado.params("assets") or {}
        try:
            antes = gv.normalizar(params.get("guion_visual"))
            nuevo = gv.normalizar({"origen": datos.get("origen") or antes.get("origen") or "manual",
                                   "planos": planos, "aprobado": False,
                                   "visuales": antes.get("visuales") or []}, validos)
        except ValueError as fallo:
            raise ErrorApi(400, str(fallo))
        ctx.estado.actualizar_params("assets", {"guion_visual": nuevo})
    ctx.bitacora.anotar("guion_visual_guardado", "assets", {"planos": len(nuevo["planos"])})
    return _ficha_guion_visual(ctx)


@_medido_en("assets", "guion_visual")
def _correr_proponer_gv(avisar, ctx, ajuste):
    """Claude escribe el borrador del guion visual (solo texto)."""
    gv = _guion_visual()
    espacio, reparto, estados = _fijo_del_video(ctx)
    planos, avisos = gv.proponer(_bloques_del_guion(ctx), espacio=espacio, reparto=reparto,
                                 estados=estados, ajuste=ajuste, avisar=avisar,
                                 proyecto_id=ctx.id, cwd=ctx.proyecto.raiz)
    with _cerrojo_de_cadena(ctx.id):
        params = ctx.estado.params("assets") or {}
        try:
            antes = gv.normalizar(params.get("guion_visual"))
        except ValueError:
            antes = {}
        nuevo = gv.normalizar({"origen": "claude", "planos": planos, "aprobado": False,
                               "visuales": antes.get("visuales") or []})
        ctx.estado.actualizar_params("assets", {"guion_visual": nuevo})
    ctx.bitacora.anotar("guion_visual_propuesto", "assets", {"planos": len(planos)})
    avisar(1.0, "guion visual escrito: revísalo y apruébalo")
    return {"planos": len(planos), "avisos": avisos}


@app.post("/api/proyectos/{pid}/guion_visual/proponer", status_code=202)
def proponer_guion_visual(pid: str, cuerpo: dict = Body(default=None)):
    """Claude escribe el guion visual leyendo el guion entero (solo texto, no se
    paga ninguna imagen). Sustituye al que hubiera, sin aprobar."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    if not _bloques_del_guion(ctx):
        raise ErrorApi(409, "todavía no hay guion: genéralo antes")
    por_fase = CLI_CLAUDE.por_defecto_de("catalogo_visual")
    ajuste = _ajuste_cli(datos, por_fase["modelo"], por_fase["esfuerzo"])
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo en marcha en este vídeo: espera a que termine")
        trabajo_id = ctx.gestor.lanzar("guion_visual_proponer", _correr_proponer_gv, ctx,
                                       ajuste, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@_medido_en("assets", "guion_visual")
def _correr_comprobar_gv(avisar, ctx, planos):
    """Cruza el guion visual con lo fijo (solo texto) y lo deja apuntado."""
    gv = _guion_visual()
    espacio, reparto, estados = _fijo_del_video(ctx)
    avisar(0.1, "comprobando el guion visual contra el sitio, el reparto y los estados")
    avisos = gv.comprobar(planos, espacio=espacio, reparto=reparto, estados=estados,
                          cwd=ctx.proyecto.raiz, proyecto_id=ctx.id)
    PASOS_MODULOS.medios.escribir_json(_ruta_comprobacion_gv(ctx),
                                       {"huella": gv.huella(planos), "avisos": avisos})
    avisar(1.0, f"{len(avisos)} plano(s) contradicen lo fijo" if avisos
           else "nada contradice lo fijo")
    return {"avisos": avisos}


@app.post("/api/proyectos/{pid}/guion_visual/aprobar")
def aprobar_guion_visual(pid: str, cuerpo: dict = Body(default=None)):
    """{aprobado: true|false}. Aprobar lanza también la comprobación contra lo
    fijo (solo texto): sus avisos salen en la ficha, no bloquean."""
    gv = _guion_visual()
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    aprobado = datos.get("aprobado", True)
    if not isinstance(aprobado, bool):
        raise ErrorApi(400, "'aprobado' tiene que ser true o false")
    trabajo_id = None
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo en marcha en este vídeo: espera a que termine")
        params = ctx.estado.params("assets") or {}
        try:
            guardado = gv.normalizar(params.get("guion_visual"))
        except ValueError as fallo:
            raise ErrorApi(400, str(fallo))
        if aprobado and not guardado.get("planos"):
            raise ErrorApi(409, "no hay guion visual que aprobar: escríbelo, guárdalo o pídeselo a Claude")
        if guardado and bool(guardado.get("aprobado")) != aprobado:
            ctx.estado.actualizar_params("assets", {"guion_visual": dict(guardado, aprobado=aprobado)})
        if aprobado and _asistente_listo()[0]:
            trabajo_id = ctx.gestor.lanzar("guion_visual_comprobar", _correr_comprobar_gv, ctx,
                                           guardado["planos"], paso="assets")
    if trabajo_id:
        _registrar_trabajo(trabajo_id, ctx.id)
    ctx.bitacora.anotar("guion_visual_aprobado", "assets", {"aprobado": aprobado})
    ficha = _ficha_guion_visual(ctx)
    ficha["trabajo_id"] = trabajo_id
    return ficha


@app.get("/api/presets-light/{preset_id}/imagenes")
def leer_imagenes_estilo(preset_id: str):
    """Qué dibujan por defecto las imágenes de los vídeos de un estilo."""
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "esto no es un preset de canal")
    estilo = (ficha.get("datos") or {}).get("estilo") or {}
    gv = _guion_visual()
    return {"imagenes": estilo.get("imagenes") or "",
            "modos": [{"clave": k, "nombre": v} for k, v in gv.MODOS.items()]}


@app.put("/api/presets-light/{preset_id}/imagenes")
def guardar_imagenes_estilo(preset_id: str, cuerpo: dict = Body(default=None)):
    """{imagenes: "guion" | null}: el defecto de los vídeos NUEVOS de este estilo.
    No toca ningún vídeo hecho (llega con «Traer el estilo», con su aviso)."""
    presets = _presets()
    gv = _guion_visual()
    datos = _cuerpo(cuerpo)
    if "imagenes" not in datos:
        raise ErrorApi(400, "manda {imagenes: guion | null}")
    try:
        valor = gv.normalizar_modo(datos.get("imagenes"))
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    with presets.lock_de(presets.FICHERO):
        ficha = _preset_o_400(lambda p: p.leer(preset_id))
        if ficha.get("tipo") != "canal":
            raise ErrorApi(400, "esto no es un preset de canal")
        contenido = copy.deepcopy(ficha.get("datos") or {})
        estilo = dict(contenido.get("estilo") or {})
        if (estilo.get("imagenes") or "") == valor:
            return {"imagenes": valor, "cambiado": False}
        if valor and not estilo.get("referencias"):
            raise ErrorApi(400, "este estilo todavía no tiene su estilo gráfico (las "
                                "láminas): genéralo antes")
        if valor:
            estilo["imagenes"] = valor
        else:
            estilo.pop("imagenes", None)
        if estilo:
            contenido["estilo"] = estilo
        else:
            contenido.pop("estilo", None)
        try:
            presets.guardar("canal", ficha.get("nombre") or "", contenido,
                            nota=ficha.get("nota") or "",
                            miniatura=ficha.get("miniatura") or "", pid=preset_id)
        except presets.ErrorPreset as fallo:
            raise ErrorApi(400, str(fallo))
    anotar_global("imagenes_estilo", {"preset": preset_id, "imagenes": valor or "voz"})
    return {"imagenes": valor, "cambiado": True}


# --------------------------------------------------------------- conservacion
#
# Un cambio en una etapa anterior ya no arrasa lo de despues. Se analiza que se
# puede mantener, se mantiene, y se marca solo lo que es imposible conservar.
#
# El analisis va en dos tiempos a proposito:
#
#   GET  mira el guion y los planos y contesta al instante y gratis. Es lo que
#        se pinta nada mas entrar: cuantos bloques han cambiado y de que manera.
#   POST pregunta al CLI por los planos dudosos -- los que narran algo distinto
#        sin cambiar de asunto- y devuelve el plan definitivo.
#
# Aplicarlo es una tercera accion, y tambien a proposito: conservar es aceptar
# material viejo para entradas nuevas, y eso no puede pasar sin que alguien lo
# haya visto.

def _conservar():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.conservar


def _ficha_conservacion(ficha):
    """Lo que la interfaz necesita, sin los textos completos de cada bloque."""
    bloques = {}
    for bid, b in (ficha.get("bloques") or {}).items():
        bloques[bid] = {k: b.get(k) for k in
                        ("estado", "parecido", "solape", "palabras",
                         "palabras_nuevas")}
        bloques[bid]["antes"] = (b.get("antes") or "")[:400]
        bloques[bid]["despues"] = (b.get("despues") or "")[:400]
    return {**{k: v for k, v in ficha.items() if k not in ("bloques", "dudosos")},
            "bloques": bloques,
            "dudosos": [{"id": d["id"], "bloque": d["bloque"]}
                        for d in (ficha.get("dudosos") or [])]}


@app.get("/api/proyectos/{pid}/conservacion")
def leer_conservacion(pid: str):
    """Que se puede mantener del video, sin llamar a nadie y sin gastar."""
    ctx = contexto(pid)
    ficha = _conservar().plan_del_proyecto(ctx.proyecto, ctx.estado,
                                           preguntar=False)
    return _ficha_conservacion(ficha)


def _correr_conservacion(avisar, ctx, ajuste):
    mod = _conservar()
    ficha = mod.plan_del_proyecto(ctx.proyecto, ctx.estado, ajuste=ajuste,
                                  avisar=avisar, proyecto_id=ctx.id,
                                  cwd=ctx.proyecto.raiz, preguntar=True)
    if not ficha.get("posible"):
        raise RuntimeError(ficha.get("por_que_no") or
                           "no hay material anterior con el que comparar")
    ctx.bitacora.anotar("conservacion_analizada", "assets", {
        "conservar": len(ficha.get("conservar") or []),
        "rehacer": len(ficha.get("rehacer") or []),
        "bloques": ficha.get("resumen_bloques"), "ajuste": ajuste})
    avisar(1.0, ficha.get("resumen") or "análisis listo")
    return _ficha_conservacion(ficha)


@app.post("/api/proyectos/{pid}/conservacion/analizar", status_code=202)
def analizar_conservacion(pid: str, cuerpo: dict = Body(default=None)):
    """Pregunta por los planos dudosos y devuelve el plan definitivo."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    por_fase = CLI_CLAUDE.por_defecto_de("conservacion")
    ajuste = _ajuste_cli(datos, por_fase["modelo"], por_fase["esfuerzo"])
    trabajo_id = ctx.gestor.lanzar("conservacion", _correr_conservacion, ctx,
                                   ajuste, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ajuste": ajuste,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@app.post("/api/proyectos/{pid}/conservacion/aplicar")
def aplicar_conservacion(pid: str, cuerpo: dict = Body(default=None)):
    """Conserva lo que se puede conservar y marca el resto para rehacer.

    Se aplica el plan que la persona ha visto, no uno recalculado por dentro:
    aplicar algo distinto de lo que estaba en pantalla es la peor forma posible
    de que esto se gane la confianza de nadie.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    plan = datos.get("plan") if isinstance(datos.get("plan"), dict) else None
    if not plan or not plan.get("pasos"):
        raise ErrorApi(400, "hace falta el plan de conservación que se ha "
                            "revisado (el que devuelve /conservacion/analizar)")
    hecho = _conservar().aplicar(
        ctx.estado, plan, motivo=str(datos.get("motivo") or "")
        or "cambio en el guion analizado plano a plano", quien="persona")
    ctx.bitacora.anotar("conservacion_aplicada", "assets", {
        "conservar": len(plan.get("conservar") or []),
        "rehacer": len(plan.get("rehacer") or []),
        "pasos": {p: len((r or {}).get("conservadas") or [])
                  for p, r in hecho.items()}})
    return {"aplicado": hecho,
            "pasos": {p["id"]: {"estado": ctx.estado.estado_de(p["id"]),
                                "unidades_obsoletas": ctx.estado.unidades_obsoletas(p["id"])}
                      for p in PASOS}}










@app.get("/api/proyectos/{pid}/callouts/diseno")
def leer_diseno(pid: str):
    """Sets de diseno, el elegido y el que sugiere la guia de estilo del video."""
    ctx = contexto(pid)
    p7 = PASOS_MODULOS.p7_callouts if PASOS_MODULOS else None
    if p7 is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    guia = ((ctx.estado.params("assets") or {}).get("estilo") or {}).get("guia")
    sugerido, porque = p7.diseno_sugerido(guia)
    elegido, _ = p7.diseno_de(ctx.estado.params("callouts") or {}, guia)
    return {
        "sets": [{"id": k, **v} for k, v in p7.SETS_DISENO.items()],
        "elegido": elegido,
        "sugerido": sugerido,
        "por_que": porque,
        # con los papeles fijados a mano dentro: lo puesto a mano manda y
        # solo se deriva lo que nadie ha tocado
        "paleta": p7.paleta_de_guia(
            guia, {**p7.PARAMS_POR_DEFECTO["paleta"],
                   **(ctx.estado.params("callouts") or {}).get("paleta", {})}),
        "fijados": ((ctx.estado.params("callouts") or {}).get("paleta") or {}).get("fijados") or {},
        # Y el tamano del subtitulo, que es lo unico que queda por elegir del
        # grafismo. Vive en los params de callouts, o sea que cambiarlo no deja
        # obsoleta ni una imagen: solo las capas, que son gratis.
        "subtitulo_tam": (ctx.estado.params("callouts") or {}).get(
            "subtitulo_tam") or "normal",
        "subtitulo_tamanos": sorted(p7.SUB_TAMANOS),
    }




@app.get("/api/proyectos/{pid}/callouts/vista")
def dibujar_capa(pid: str, plano: str = Query(...),
                 capa: str = Query(default="fija")):
    """La capa de ESE plano, dibujada ahora con el código de p7.

    Es lo que hace que el repaso del montaje enseñe los subtítulos ANTES de
    montar las capas: sin esto la única forma de verlos era ejecutar el paso
    entero, o sea después de haber pagado los planos. La misma llamada que
    dibuja el vídeo (`p7.capa_de_escena`), como en `/cartelas/vista`.

    SON DOS CAPAS Y HAY QUE PEDIR CUÁL (PENDIENTE 38):

      capa=fija    la que NO escala, en píxeles del cuadro de salida. Aquí vive
                   el subtítulo, y es la de por defecto porque es la única que
                   este paso dibuja hoy para un plano normal.
      capa=movil   la que va dentro del zoom, en píxeles del lienzo de
                   generación. En un plano normal sale vacía; la llevan la
                   cabecera de capítulo y la cartela, que tienen su propia ruta.

    Y ESTABA ROTA, de antes de esto: llamaba a `capa_de_escena` con la firma
    vieja —la ruta del PNG y el directorio de assets, más un `evitar=` que ya no
    existe—, que es la de cuando esta función buscaba un hueco limpio en la
    imagen para colocar un rótulo. Desde que los rótulos se retiraron
    la firma es otra, así que cada llamada moría en el `except`
    y devolvía un 500: en el repaso del plan no se veía ni un subtítulo, y el
    aviso de «ningún plano lleva subtítulo» culpaba a las marcas de voz.
    """
    ctx = contexto(pid)
    p7 = PASOS_MODULOS.p7_callouts if PASOS_MODULOS else None
    if p7 is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escena = next((e for e in (plan.get("escenas") or [])
                   if e.get("id") == plano), None)
    if escena is None:
        raise ErrorApi(404, f"no hay ningún plano '{plano}' en el plan")
    # el grafismo DECIDIDO manda sobre lo que dedujo p6, igual que en el vídeo:
    # la pantalla no puede enseñar una cosa y el render otra
    params = dict(ctx.estado.params("callouts") or {})
    params.setdefault("estilo", plan.get("estilo") or {})
    try:
        salida = p7.salida_de(plan)
        movil, fija, _ = p7.capa_de_escena(
            escena, p7._con_defectos(params),
            aspecto=float(salida[0]) / float(salida[1]),
            lienzo=p7.lienzo_de(plan), salida=salida)
    except Exception as fallo:  # noqa: BLE001
        raise ErrorApi(500, f"no se ha podido dibujar la capa de {plano}: {fallo}")
    svg = movil if str(capa).strip().lower() == "movil" else fija
    return Response(content=svg, media_type="image/svg+xml")


@app.put("/api/proyectos/{pid}/callouts/plan")
def guardar_plan_callouts(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda el GRAFISMO del video en los params de callouts.

    Ya no guarda ningun plan de rotulos: se retiraron enteros el 22-08
    . Lo que queda es lo que describe el VIDEO -- el set de
    dibujo, la paleta y el tamano del subtitulo -- y por eso va suelto y no por
    unidad. Merece llamarse /callouts/grafismo; la ruta se conserva porque la
    pantalla vieja la sigue usando y renombrarla no arregla nada.

    El plan va al bloque `unidades` y NO a un param suelto: describe UN plano.
    Suelto entraba en la firma global del paso, y guardar el rotulo de S013
    dejaba obsoletos los cuarenta y nueve y el render.
    El set de diseno, la paleta y el tamano del subtitulo van SUELTOS, y a proposito:
    describen el video entero.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    cambios = {}
    hecho = []
    p7 = PASOS_MODULOS.p7_callouts
    if datos.get("subtitulo_tam"):
        # el tamano del subtitulo, que es lo unico que queda por elegir del
        # grafismo. Vive en los params de callouts: cambiarlo no deja obsoleta
        # ni una imagen, solo las capas, que son gratis.
        nombre = str(datos["subtitulo_tam"]).strip().lower()
        if nombre not in p7.SUB_TAMANOS:
            raise ErrorApi(400, f"tamaño de subtítulo desconocido: {nombre}. "
                                f"Los tamaños son: {', '.join(sorted(p7.SUB_TAMANOS))}")
        cambios["subtitulo_tam"] = nombre
        hecho.append("subtitulo_tam")
    if datos.get("diseno"):
        if not isinstance(datos["diseno"], str) or datos["diseno"] not in p7.SETS_DISENO:
            raise ErrorApi(400, f"set de diseño desconocido: {datos['diseno']}. "
                                f"Los sets son: {', '.join(p7.SETS_DISENO)}")
        cambios["diseno"] = datos["diseno"]
    if "arquetipos" in datos:
        # LOS ARQUETIPOS YA NO SE ELIGEN (R8 del analisis del 13-10-2026): se
        # retiraron con `p7.vigentes()`, y esta rama era un 500 con cualquier
        # valor. La pantalla no los manda; quien los mande se entera con un 400.
        raise ErrorApi(400, "los arquetipos ya no se eligen: el grafismo se "
                            "decide solo con el diseño y la paleta")
    if isinstance(datos.get("paleta"), dict):
        # Los colores elegidos a mano viajan en 'fijados' DENTRO de la paleta,
        # no sueltos: paleta_de_guia necesita distinguir "esto lo puso alguien"
        # de "esto se derivo", o al volver a derivar se los lleva por delante.
        crudos = datos["paleta"].get("fijados") or {}
        if not isinstance(crudos, dict):      # R7: un numero aqui era un 500
            raise ErrorApi(400, "'paleta.fijados' tiene que ser un objeto papel → color")
        fijados = {papel: str(color) for papel, color in crudos.items()
                   if papel in p7.PARAMS_POR_DEFECTO["paleta"] and color}
        actual = dict((ctx.estado.params("callouts") or {}).get("paleta")
                      or p7.PARAMS_POR_DEFECTO["paleta"])
        actual["fijados"] = fijados
        cambios["paleta"] = actual
    if not cambios and not hecho:
        raise ErrorApi(400, "hace falta 'diseno', 'paleta' o 'subtitulo_tam'")
    if cambios:
        ctx.estado.actualizar_params("callouts", cambios)
    hecho.extend(cambios)
    ctx.bitacora.anotar("grafismo_guardado", "callouts", {
        "diseno": cambios.get("diseno"),
        "subtitulo_tam": cambios.get("subtitulo_tam")})
    return {"guardado": hecho, "estado": ctx.estado.estado_de("callouts"),
            "aguas_abajo": {h: ctx.estado.unidades_obsoletas(h)
                            for h in descendientes_de("callouts")}}


# ----------------------------------------------------------------- cartelas
# Un plano de texto sobre negro en vez de una imagen (pasos/cartelas.py).
#
# Vive en ASSETS y no en Rotulos aunque sea grafismo, y el motivo es el dinero:
# una cartela cambia el PLAN -- ese plano deja de generar imagen --, asi que
# tiene que estar decidida ANTES de generar. Decidirla en Rotulos, que va
# despues, seria pagar una imagen para tirarla.

def _cartelas():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.cartelas


def _paleta_del_video(ctx):
    """La paleta derivada de la guia de estilo, que es de donde salen los colores
    de los rotulos, de las cartelas y del acento de las transiciones."""
    p7 = PASOS_MODULOS.p7_callouts
    guia = ((ctx.estado.params("assets") or {}).get("estilo") or {}).get("guia")
    return p7.paleta_de_guia(
        guia, {**p7.PARAMS_POR_DEFECTO["paleta"],
               **(ctx.estado.params("callouts") or {}).get("paleta", {})})


def _grafismo(ctx):
    """El grafismo del video: la paleta y el set de diseno, de rotulos.

    UN video tiene UN grafismo. El mismo set decide como se envuelve un rotulo
    sobre la imagen y como se escribe una cartela, y la misma paleta tine los
    dos y ademas el acento de las transiciones. Vive en los params de ROTULOS
    porque cambiarlo no cuesta imagenes: rehace capas y render, nada mas.
    """
    p7 = PASOS_MODULOS.p7_callouts
    params = ctx.estado.params("callouts") or {}
    _, diseno = p7.diseno_de({**p7.PARAMS_POR_DEFECTO, **params})
    return _paleta_del_video(ctx), diseno


def _migrar_cartelas(ctx):
    """Mueve el plan de cartelas del param suelto viejo a los ajustes por unidad.

    Nacio como `plan_cartelas`, un param global de assets, y era un error caro:
    todo lo que no es el bloque `unidades` entra en la firma GLOBAL del paso,
    asi que guardar el plan dejaba obsoletos los cuarenta y nueve planos y todos
    los assets. Se veia como «rehago el personaje y sigue saliendo obsoleto».

    Se migra al abrir la pantalla, una vez, y se borra la clave vieja. Borrarla
    mueve la firma una ultima vez -- lo que ya estaba obsoleto sigue estandolo --
    y a partir de ahi cambiar una cartela solo ensucia SU plano.
    """
    params = ctx.estado.params("assets") or {}
    viejo = params.get("plan_cartelas")
    if not isinstance(viejo, dict):
        return False
    nuevos = copy.deepcopy(params)
    nuevos.pop("plan_cartelas", None)
    bloque = nuevos.get("unidades")
    bloque = dict(bloque) if isinstance(bloque, dict) else {}
    for sid, ficha in viejo.items():
        if not isinstance(ficha, dict) or not ficha.get("plantilla"):
            continue
        uid = f"escena:{sid}"
        actual = bloque.get(uid)
        actual = dict(actual) if isinstance(actual, dict) else {}
        # el fondo explicito: las de antes de que existieran los dos son negras
        actual.setdefault("cartela", {**ficha, "fondo": _cartelas().fondo_de(ficha)})
        bloque[uid] = actual
    nuevos["unidades"] = bloque
    ctx.estado.set_params("assets", nuevos)
    return True


def _motor_del_plan(ctx):
    """Con qué versión del motor se cortó el plan activo, y qué se ha perdido.

    Devuelve `None` cuando no hay plan todavía: ahí no hay nada que comparar.
    """
    if PASOS_MODULOS is None:
        return None
    p6 = PASOS_MODULOS.p6_assets
    plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    if not plan.get("escenas"):
        return None
    # sin `motor` es un plan de antes de que esto existiera: viejo por defecto
    tenia = int(plan.get("motor") or 1)
    ahora = int(p6.MOTOR_PLAN)
    return {
        "plan": tenia,
        "ahora": ahora,
        "al_dia": tenia >= ahora,
        # QUÉ se ha perdido, no un número: «tienes la 3 y hay la 5» no dice si
        # importa. Lo que importa es qué reglas no lleva este vídeo.
        "cambios": [texto for version, texto in sorted(p6.MOTOR_CAMBIOS.items())
                    if tenia < version <= ahora],
    }


def _plan_de_cartelas(ctx):
    """Las cartelas guardadas, POR UNIDAD: {"S013": {...}}.

    Van en `unidades` y no en un param global porque todo lo que no es ese
    bloque entra en la firma GLOBAL del paso: con el plan suelto, guardar una
    cartela dejaba obsoletos los cuarenta y nueve planos.
    """
    bloque = (ctx.estado.params("assets") or {}).get("unidades") or {}
    plan = {}
    for uid, datos in bloque.items():
        ficha = (datos or {}).get("cartela") if isinstance(datos, dict) else None
        if isinstance(ficha, dict) and ficha.get("plantilla"):
            plan[str(uid).split(":", 1)[-1]] = ficha
    return plan


@app.get("/api/proyectos/{pid}/cartelas")
def leer_cartelas(pid: str):
    """Las plantillas de cartela con su muestra dibujada, y el plan guardado."""
    ctx = contexto(pid)
    cartelas = _cartelas()
    migrado = _migrar_cartelas(ctx)
    activas = (ctx.estado.params("callouts") or {}).get("plantillas_cartela") or []
    paleta, diseno = _grafismo(ctx)
    return {
        "plantillas": [{**ficha,
                        "activa": (not activas) or ficha["id"] in set(activas)}
                       for ficha in cartelas.catalogo_plantillas(paleta, diseno)],
        "todas": not activas,
        "plan": _plan_de_cartelas(ctx),
        "migrado": migrado,
        "iconos": sorted(cartelas.ICONOS),
        "fondos": list(cartelas.FONDOS),
        "separacion_minima": cartelas.SEPARACION_MINIMA,
        "fraccion_maxima": cartelas.FRACCION_MAXIMA,
        # CUÁNTAS PALABRAS CABEN EN CADA PLANO, con la MISMA cuenta que después
        # decide si la cartela cabe (`palabras_que_caben`). Va al lado del cajón
        # mientras se escribe: el aviso del informe llega al planificar, y para
        # entonces ya se ha escrito el texto largo (PENDIENTE §15).
        "caben": {e["id"]: cartelas.palabras_que_caben(e.get("duracion"))
                  for e in ((PASOS_MODULOS.p6_assets.plan_actual(
                      ctx.proyecto, "assets", estado=ctx.estado) or {}).get("escenas") or [])
                  if e.get("id")},
        "palabras_maximas": cartelas.palabras_maximas(ctx.estado.params("assets")),
    }


@app.get("/api/proyectos/{pid}/cartelas/vista")
def dibujar_cartela(pid: str, plano: str = Query(...), animada: int = 0):
    """El SVG de la cartela de ESE plano, dibujado ahora con el grafismo de ahora.

    La rejilla de planos lo pide en vez de leer un PNG, y no es un capricho: una
    cartela no deja fichero (ver p6_assets), y si lo dejara habria que rehacerlo
    cada vez que alguien tocara un color. Asi la rejilla ensena exactamente lo
    que va a dibujar p7, porque es la MISMA llamada.
    """
    ctx = contexto(pid)
    cartelas = _cartelas()
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escena = next((e for e in (plan.get("escenas") or [])
                   if e.get("id") == plano), None)
    if escena is None:
        raise ErrorApi(404, f"no hay ningún plano '{plano}' en el plan")
    # MANDA LA DECISION GUARDADA, no la copia que dejo la ultima tanda.
    #
    # `escena["cartela"]` es una FOTO: p6 estampa en plan.json lo que habia
    # decidido cuando corrio (`_marcar_cartelas`). Leerla primero hacia que esta
    # vista ensenara la cartela vieja despues de volver a decidir o de editar el
    # texto a mano -- se escribia otra frase y el dibujo no cambiaba--, que es
    # justo lo que esta llamada existe para que no pase (ver 27.2). La decision
    # esta en params y es lo que dibujara p7 en cuanto se regenere ese plano.
    #
    # Y sin red de reserva: si la decision dice que este plano ya NO es cartela,
    # dibujar la de la foto seria seguir ensenando algo que alguien ha quitado.
    decidido = _plan_de_cartelas(ctx)
    ficha = decidido.get(plano)
    # UNA CONTINUACION NO ES UNA DECISION, ES UNA CONSECUENCIA.
    #
    # Cuando una cartela no cabe en su plano, el PLAN marca los de al lado como
    # su segunda mitad (`cartela.sigue_a`). Eso no esta en params y no tiene por
    # que estarlo: no lo decide nadie, lo deduce la planificacion. Pero la
    # pantalla lo pedia aqui y se llevaba un 404, asi que en la rejilla ese plano
    # salia como «sin imagen» -- y el video iba a enseñar la cartela puesta. Una
    # pantalla que dice una cosa y un video que hace otra es justo lo que esta
    # llamada existe para evitar.
    #
    # Se dibuja la ficha del HOGAR y se lee de params, no del plan: si la persona
    # cambia el texto o quita la cartela, la continuacion cambia o desaparece con
    # ella. La decision sigue mandando; lo unico que sale del plan es a QUIEN
    # sigue este plano.
    sigue_a = str(((escena.get("cartela") or {}) if isinstance(
        escena.get("cartela"), dict) else {}).get("sigue_a") or "")
    if not ficha and sigue_a:
        ficha = decidido.get(sigue_a)
    if not ficha:
        raise ErrorApi(404, f"el plano '{plano}' no lleva cartela")
    paleta, diseno = _grafismo(ctx)
    duracion = float(escena.get("duracion") or 4.0)
    debajo = ""
    if cartelas.fondo_de(ficha) == "imagen":
        # la cartela va ENCIMA del plano: se mete su imagen debajo del velo,
        # servida por la misma ruta que usa la rejilla
        png = os.path.join(ctx.proyecto.ruta_paso("assets"), "escenas",
                           f"{plano}.png")
        url = url_de(ctx.id, png, ctx.proyecto.raiz) if os.path.exists(png) else None
        if url:
            ancho, alto = PASOS_MODULOS.p7_callouts.lienzo_de(plan)
            debajo = (f'<image href="{url}" x="0" y="0" width="{ancho}" '
                      f'height="{alto}" preserveAspectRatio="xMidYMid slice"/>')
    # ANIMADA para el repaso del montaje, quieta para la rejilla.
    #
    # De una cartela hay dos cosas que mirar y se miran en dos sitios: en la
    # rejilla, QUE PONE --y ahi una animacion solo estorba--; en el repaso, si
    # sus palabras entran CUANDO LA VOZ LAS DICE, que es lo unico que no se
    # puede ver en una imagen quieta. Los tiempos son los que calculo el plan
    # (`escritura.tiempos`), o sea exactamente los que va a usar p7; sin ellos
    # --un plan viejo-- se recalculan aqui con los vecinos, que es como los
    # recalcula p7. Una animacion inventada para la pantalla se desincronizaria
    # del render, que es la regla de todas las muestras de esta casa.
    tiempos, escrita = None, False
    if animada:
        escritura = escena.get("escritura") if isinstance(
            escena.get("escritura"), dict) else {}
        escrita = bool(escritura.get("continua")) or bool(sigue_a)
        tiempos = list(escritura.get("tiempos") or [])
        if not tiempos and not escrita:
            antes, despues = cartelas.vecinos_de(plan.get("escenas"), plano)
            tiempos = cartelas.tiempos_dichos(ficha, escena, duracion=duracion,
                                              diseno=diseno, antes=antes,
                                              despues=despues)
    svg = cartelas.svg_carta(ficha, paleta, diseno, duracion=duracion,
                             semilla=plan.get("semilla") or 0, debajo=debajo,
                             tiempos=tiempos or None, animada=bool(animada),
                             escrita=escrita)
    return Response(content=svg, media_type="image/svg+xml")


def _idioma_de_brief(brief):
    """El idioma del video, con respaldo en la clave vieja del eje de idiomas.

    UN VIDEO, UN IDIOMA desde el 24-08-2026. `idiomas_salida`
    ya no se escribe, pero un proyecto guardado antes la trae y su primer codigo
    era el principal: leerla es lo que evita que ese proyecto se abra en otro
    idioma sin que nadie lo diga.
    """
    brief = brief or {}
    codigo = str(brief.get("idioma_salida") or "").strip().lower()
    if codigo:
        return codigo
    lista = brief.get("idiomas_salida") or []
    if isinstance(lista, str):
        lista = [lista]
    return str((list(lista) or ["es"])[0] or "es").strip().lower()


def _idioma_del_video(ctx):
    """El idioma en el que se locuta este video, con su nombre."""
    codigo = _idioma_de_brief(ctx.estado.params("brief") or {})
    p2 = PASOS_MODULOS.p2_brief
    return f"{p2.nombre_idioma(codigo)} ({codigo})"


def _plan_de_planos(ctx, avisar=None):
    """El corte en planos QUE VA A RODAR LA TANDA, replanificado ahora. -> plan

    Las cartelas, la direccion y el redactor deciden ANTES de generar
    —decidirlo despues es pagar una imagen para tirarla— y los tres necesitan el
    corte. Y lo necesitan tal y como va a quedar, no como quedo la ultima vez:
    ver el comentario de dentro.

    En un video recien hecho no hay plan de ninguna clase y la tanda se plantaba
    con «no hay planos todavia», que en el modo editor es un mensaje accionable
    (pulsa el otro boton) y en una tirada de punta a punta es la tanda entera
    caida a la mitad. Por eso, si planificar no da escenas, se corta y se deja
    escrito. Cortar no cuesta nada: son las marcas de palabra de la toma y las
    reglas de ritmo del canal. Ver `p6_assets.cortar`.
    """
    p6 = PASOS_MODULOS.p6_assets
    # SE PLANIFICA DE NUEVO, QUE ES LO QUE VA A HACER LA TANDA.
    #
    # Aqui se leia `plan_actual`, o sea el plan de la ULTIMA version generada, y
    # eso es una foto vieja: `ejecutar` no lo usa, llama a `planificar`. Mientras
    # el plan no cambie da igual; en cuanto cambia --otro catalogo, otro corte, o
    # el propio codigo que reparte los sitios-- lo que se decide aqui describe un
    # video que ya no es el que se va a rodar, y no falla nada: el prompt sale
    # con la descripcion VERBATIM de un sitio y una direccion escrita para otro.
    #
    # Medido el 07-09-2026 en `video_referencia`: con el reparto de beats recien puesto,
    # la direccion se escribio contra el plan de la v2 --S001..S004 los cuatro en
    # `titulares_vacios`-- y la tanda iba a rodarlos en `titulares_vacios`,
    # `bolsa_tranquila`, `cola_banco_vacia` y `monedero_euros`. Tres de cuatro
    # planos con el quiosco escrito dentro de un parque de bolsa.
    #
    # Planificar no cuesta nada --ni un modelo ni una imagen: son las marcas de
    # palabra de la toma y las reglas de ritmo-- y hereda los ids del plan
    # anterior, asi que no mueve la numeracion. Ver `p6_assets.cortar`.
    params = ctx.estado.params("assets") or {}
    try:
        plan = p6.planificar(ctx.proyecto, params) or {}
    except Exception as fallo:
        # NO SE DEJA A NADIE TIRADO. Un video que ya tiene plan pero cuya toma no
        # se puede releer --audio_meta ilegible, la voz movida de sitio-- podia
        # dirigirse antes y tiene que poder seguir dirigiendose: se vuelve al
        # plan guardado, que es exactamente lo que se leia hasta hoy.
        plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
        if not plan.get("escenas"):
            raise
        ctx.bitacora.anotar("plan_viejo", "assets",
                            {"porque": f"no se ha podido replanificar: {fallo}",
                             "planos": len(plan.get("escenas") or [])})
        return plan
    if plan.get("escenas"):
        return plan
    if avisar:
        avisar(0.02, "cortando la narracion en planos (no cuesta nada)")
    plan = p6.cortar(ctx.proyecto, params)
    ctx.bitacora.anotar("plan_cortado", "assets",
                        {"planos": len(plan.get("escenas") or []),
                         "porque": "no habia plan todavia"})
    return plan


def _correr_corte(avisar, ctx, replantear=False):
    """Reparte la narracion en planos. No llama a ningun modelo y no cuesta nada.

    Con `replantear` se corta de cero sin heredar los ids del plan anterior, que
    es lo que hace el boton «Regenerar el corte en planos» del modo editor.
    """
    p6 = PASOS_MODULOS.p6_assets
    avisar(0.05, "cortando la narracion en planos")
    plan = p6.cortar(ctx.proyecto, ctx.estado.params("assets") or {},
                     replantear=bool(replantear))
    escenas = plan.get("escenas") or []
    ctx.bitacora.anotar("plan_cortado", "assets", {
        "planos": len(escenas), "replantear": bool(replantear)})
    resumen = f"{len(escenas)} planos"
    avisar(1.0, resumen)
    return {"planos": len(escenas), "resumen": resumen}


def _correr_plan_cartelas(avisar, ctx, ajuste, aplicar=False):
    cartelas = _cartelas()
    assets = ctx.estado.params("assets") or {}
    plan_assets = _plan_de_planos(ctx, avisar)
    escenas = (plan_assets or {}).get("escenas") or []
    if not escenas:
        raise RuntimeError("no hay planos todavia y no se ha podido cortar la "
                           "narracion: comprueba que la voz haya dejado su "
                           "audio_meta.json")
    ficha = cartelas.proponer(
        escenas, params=assets, ajuste=ajuste, avisar=avisar,
        proyecto_id=ctx.id, cwd=ctx.proyecto.raiz,
        titulo=(assets.get("titulo") or ctx.proyecto.id),
        # EL IDIOMA VA EXPLICITO. El prompt esta escrito en castellano porque es
        # para el modelo, y sin decirselo escribia las cartelas en castellano
        # tambien: un video en ingles salio con «de la facturacion anual
        # global» y «DIAS / ANOS» en pantalla.
        idioma=_idioma_del_video(ctx),
        plantillas=(ctx.estado.params("callouts") or {}).get("plantillas_cartela"))
    ctx.bitacora.anotar("plan_cartelas", "assets", {
        "planos": ficha.get("planos"), "cartelas": ficha.get("cartelas"),
        "propuestas": ficha.get("propuestas"), "ajuste": ajuste,
        "aplicar": bool(aplicar)})
    # Igual que el plan de rotulos: desde una receta se aplica, o la tanda paga
    # la llamada y sigue como si no hubiera pasado nada.
    if aplicar and isinstance(ficha.get("plan"), dict):
        _guardar_cartelas_por_unidad(ctx, cartelas, ficha["plan"])
        ficha["aplicado"] = True
        # Y SE VUELVE A CORTAR, que no cuesta nada. Una cartela FUNDE su tramo
        # en un solo plano mas largo (`p6._fundir_cartelas`), asi que el corte
        # de antes ya no describe este video: tiene mas planos y con otros ids.
        # Lo que viene detras --la direccion de cada plano y las piezas-- decide
        # POR PLANO, asi que leyendo el corte viejo escribiria la direccion de
        # S054 sobre lo que despues es otro plano. No da error: da un video en
        # el que las descripciones estan corridas.
        plan = PASOS_MODULOS.p6_assets.cortar(
            ctx.proyecto, ctx.estado.params("assets") or {})
        ficha["planos_tras_cartelas"] = len(plan.get("escenas") or [])
        avisar(0.98, f"{ficha['planos_tras_cartelas']} planos tras fundir las "
                     f"cartelas")
    avisar(1.0, f"{ficha.get('cartelas')} de {ficha.get('planos')} planos "
                f"serían cartela")
    return ficha


@app.post("/api/proyectos/{pid}/cartelas/plan", status_code=202)
def proponer_plan_cartelas(pid: str, cuerpo: dict = Body(default=None)):
    """Lee el guion y decide que tramos se cuentan mejor con texto que con dibujo.

    Proponer no es aprobar: lo que devuelve se repasa y se guarda con PUT.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    por_fase = CLI_CLAUDE.por_defecto_de("plan_cartelas")
    ajuste = _ajuste_cli(datos, por_fase["modelo"], por_fase["esfuerzo"])
    trabajo_id = ctx.gestor.lanzar("plan_cartelas", _correr_plan_cartelas, ctx,
                                   ajuste, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ajuste": ajuste,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


def _guardar_cartelas_por_unidad(ctx, cartelas, plan):
    """Escribe el plan de cartelas en `unidades` de assets, fusionando.

    Sale del endpoint para poder llamarlo tambien desde la RECETA: proponer sin
    guardar es pagarle al modelo y tirar la respuesta, que es lo que pasaria si
    la tanda de una pestana solo propusiera.
    """
    # CONTRA QUE TEXTO SE DECIDE CADA UNA. El plan se guarda por unidad y el id
    # de un plano es su POSICION: se reparte de nuevo con cada corte, asi que sin
    # esto una cartela se queda en su numero mientras lo que ahi se dice se ha
    # ido a otro sitio. Paso con las siete de `video_referencia`: decididas sobre el
    # plan v1, sesenta y siete versiones despues «TIPO DE INTERES REAL» salia
    # tres planos antes de que se dijera.
    dice = {}
    try:
        actual = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
        dice = {e.get("id"): (e.get("narracion") or "")
                for e in (actual.get("escenas") or []) if e.get("id")}
    except Exception:                                         # noqa: BLE001
        dice = {}        # sin plan no hay ancla; se guarda igual, por su numero
    limpio = {}
    for sid, ficha in plan.items():
        if not isinstance(ficha, dict):
            continue
        plantilla = str(ficha.get("plantilla") or "")
        if plantilla not in cartelas.PLANTILLAS:
            raise ErrorApi(400, f"plantilla de cartela desconocida: "
                                f"{plantilla}. Las que hay son: "
                                f"{', '.join(cartelas.PLANTILLAS)}")
        # Se valida al GUARDAR y no al dibujar: una cartela con un texto de
        # mas se recorta, y ese aviso tiene que salir aqui -- con el id del
        # plano delante -- y no aparecer como una cartela con la letra rara
        # que nadie sabe por que salio asi.
        # con los params del video: el presupuesto de palabras de una cartela
        # cuelga de lo que duran SUS planos (cartelas.techo_de)
        valores, avisos = cartelas.validar(plantilla, ficha.get("datos"),
                                           ctx.estado.params("assets"))
        if valores is None:
            raise ErrorApi(400, f"{sid}: {'; '.join(avisos)}")
        limpio[sid] = {"plantilla": plantilla,
                       "fondo": cartelas.fondo_de(ficha),
                       "datos": valores,
                       "ancla": dice.get(sid, ""),
                       "por_que": str(ficha.get("por_que") or "").strip()}
    # se escribe el plan ENTERO: los planos que ya no salen se quedan sin
    # cartela, o quitar una desde la pantalla no la quitaria de ningun sitio
    antes = _plan_de_cartelas(ctx)
    # SE FUSIONA con lo que ya tenga cada unidad. `actualizar_params`
    # sustituye el diccionario de la unidad entero, asi que escribir solo
    # {"cartela": ...} se llevaria por delante el feedback de ese plano, sus
    # zonas marcadas y su carta forzada. Es la clase de perdida que no da
    # ningun error: la nota simplemente deja de estar.
    previos = (ctx.estado.params("assets") or {}).get("unidades") or {}
    bloque = {}
    for sid in set(limpio) | set(antes):
        uid = f"escena:{sid}"
        actual = previos.get(uid)
        actual = dict(actual) if isinstance(actual, dict) else {}
        if sid in limpio:
            actual["cartela"] = limpio[sid]
        else:
            actual.pop("cartela", None)
        bloque[uid] = actual
    ctx.estado.actualizar_params("assets", {"unidades": bloque})
    return len(limpio)


@app.put("/api/proyectos/{pid}/cartelas")
def guardar_cartelas(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda que planos son cartela (POR UNIDAD) y que plantillas se pueden usar.

    El plan va al bloque `unidades` de assets y NO a un param suelto. Todo lo
    que no es ese bloque entra en la firma GLOBAL del paso, asi que con el plan
    suelto guardar una cartela dejaba obsoletos los cuarenta y nueve planos y
    todos los assets: decidir una cartela pedia regenerar el video entero. Por
    unidad, convertir S013 en cartela ensucia S013 y nada mas.

    Y las plantillas permitidas van a los params de ROTULOS, con el resto del
    grafismo: solo limitan lo que puede elegir el agente la proxima vez, asi que
    no tienen por que ensuciar una sola imagen.
    """
    ctx = contexto(pid)
    cartelas = _cartelas()
    datos = _cuerpo(cuerpo)
    hecho = []
    if isinstance(datos.get("plan"), dict):
        _guardar_cartelas_por_unidad(ctx, cartelas, datos["plan"])
        hecho.append("plan")
    if isinstance(datos.get("plantillas"), list):
        _lista_de_textos(datos, "plantillas")
        desconocidas = [t for t in datos["plantillas"]
                        if t not in cartelas.PLANTILLAS]
        if desconocidas:
            raise ErrorApi(400, f"plantillas desconocidas: {', '.join(desconocidas)}. "
                                f"Las que hay son: {', '.join(cartelas.PLANTILLAS)}")
        ctx.estado.actualizar_params(
            "callouts", {"plantillas_cartela": list(datos["plantillas"])})
        hecho.append("plantillas")
    if not hecho:
        raise ErrorApi(400, "hace falta 'plan' o 'plantillas'")
    ctx.bitacora.anotar("plan_cartelas_guardado", "assets", {
        "cartelas": len(_plan_de_cartelas(ctx))})
    return {"guardado": hecho, "estado": ctx.estado.estado_de("assets"),
            "aguas_abajo": {h: ctx.estado.unidades_obsoletas(h)
                            for h in descendientes_de("assets")}}


# ------------------------------------------------------------- dirección
# QUÉ SE VE EN CADA PLANO. La capa que faltaba: el sitio es el mismo para todos
# los planos rodados ahí y la acción del tramo es la misma para todo su bloque,
# así que dos planos seguidos recibían casi el mismo encargo (medido: 852 de
# 1.280 caracteres idénticos). Ver `pasos/direccion.py`.
#
# Va POR UNIDAD, como las cartelas y por lo mismo: escribir la dirección de un
# plano ensucia ESE plano, no los cuarenta y nueve.


def _direccion():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.direccion


def _plan_de_direccion(ctx):
    """Lo dirigido, POR UNIDAD: {"S013": "a hand covers the screen"}."""
    bloque = (ctx.estado.params("assets") or {}).get("unidades") or {}
    plan = {}
    for uid, datos in bloque.items():
        linea = (datos or {}).get("direccion") if isinstance(datos, dict) else None
        linea = " ".join(str(linea or "").split())
        if linea:
            plan[str(uid).split(":", 1)[-1]] = linea
    return plan


@app.get("/api/proyectos/{pid}/direccion")
def leer_direccion(pid: str):
    """Qué se ve en cada plano: lo dirigido, y los planos que lo admiten."""
    ctx = contexto(pid)
    direccion = _direccion()
    plan_assets = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = plan_assets.get("escenas") or []
    plan = _plan_de_direccion(ctx)
    dirigibles = [e for e in escenas if direccion.dirigible(e)]
    return {
        "plan": plan,
        "planos": [{"id": e["id"], "set": e.get("set") or e.get("componente"),
                    "personajes": e.get("personajes") or [],
                    "narracion": e.get("narracion") or "",
                    "direccion": plan.get(e["id"], "")}
                   for e in dirigibles],
        "dirigibles": len(dirigibles),
        "total": len(escenas),
        "palabras_maximas": direccion.PALABRAS_MAXIMAS,
        "repetidas": direccion.repetidas(plan, dirigibles),
        "resumen": direccion.describir(plan, dirigibles),
    }


def _guardar_direccion_por_unidad(ctx, plan):
    """Escribe la dirección en `unidades` de assets, FUSIONANDO.

    `actualizar_params` sustituye el diccionario de la unidad entero, así que
    escribir sólo {"direccion": ...} se llevaría por delante la cartela de ese
    plano, su feedback y sus zonas marcadas. Es la misma trampa que ya costó una
    ronda con las cartelas, y no da ningún error: la nota deja de estar.
    """
    direccion = _direccion()
    limpio, avisos = {}, []
    for sid, texto in (plan or {}).items():
        sid = str(sid).strip().upper()
        if not str(texto or "").strip():
            continue                       # vacío = quitarla
        linea, motivo = direccion.limpiar_linea(texto)
        if linea is None:
            raise ErrorApi(400, f"{sid}: {motivo}")
        if motivo:
            avisos.append(f"{sid}: {motivo}")
        limpio[sid] = linea
    antes = _plan_de_direccion(ctx)
    previos = (ctx.estado.params("assets") or {}).get("unidades") or {}
    bloque = {}
    for sid in set(limpio) | set(antes):
        uid = f"escena:{sid}"
        actual = previos.get(uid)
        actual = dict(actual) if isinstance(actual, dict) else {}
        if sid in limpio:
            actual["direccion"] = limpio[sid]
        else:
            actual.pop("direccion", None)
        bloque[uid] = actual
    ctx.estado.actualizar_params("assets", {"unidades": bloque})
    return len(limpio), avisos


@app.put("/api/proyectos/{pid}/direccion")
def guardar_direccion(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda qué se ve en cada plano. Un texto vacío la quita."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    if not isinstance(datos.get("plan"), dict):
        raise ErrorApi(400, "hace falta 'plan': {id de plano: qué se ve}")
    cuantas, avisos = _guardar_direccion_por_unidad(ctx, datos["plan"])
    ctx.bitacora.anotar("direccion_guardada", "assets", {"planos": cuantas})
    return {"guardado": cuantas, "avisos": avisos,
            "estado": ctx.estado.estado_de("assets"),
            "aguas_abajo": {h: ctx.estado.unidades_obsoletas(h)
                            for h in descendientes_de("assets")}}


def _redactor():
    """El módulo que escribe el prompt entero de cada plano.

    La guarda es la MISMA que la de `_direccion`, escrita a mano: aqui habia una
    llamada a un `_exigir_pasos()` que no existe en este fichero, asi que el
    redactor entero se caia con un NameError antes de leer un solo plano.
    """
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.redactor


def _guardar_redactado_por_unidad(ctx, plan):
    """Escribe el prompt redactado en `unidades` de assets, FUSIONANDO.

    Misma trampa y mismo cuidado que `_guardar_direccion_por_unidad`:
    `actualizar_params` sustituye el diccionario de la unidad entero, así que
    escribir sólo el prompt se llevaría por delante la cartela de ese plano.

    Son DOS claves: `redactado` (el párrafo) y `redactado_set` (el sitio que
    eligió). La segunda se escribe siempre que haya párrafo, incluso vacía, y
    eso es a propósito: vacía significa «este plano se inventó su sitio y no le
    toca continuidad de nadie», que no es lo mismo que «no opinó».
    """
    redactor = _redactor()
    limpio, avisos = {}, []
    for sid, ficha in (plan or {}).items():
        sid = str(sid).strip().upper()
        if isinstance(ficha, dict) and not str(ficha.get("prompt") or "").strip():
            continue                       # vacío = quitarlo
        limpia, motivo = redactor.limpiar_ficha(ficha)
        if limpia is None:
            raise ErrorApi(400, f"{sid}: {motivo}")
        if motivo:
            avisos.append(f"{sid}: {motivo}")
        limpio[sid] = limpia
    previos = (ctx.estado.params("assets") or {}).get("unidades") or {}
    antes = {uid.split(":", 1)[1] for uid, ficha in previos.items()
             if uid.startswith("escena:") and isinstance(ficha, dict)
             and ficha.get("redactado")}
    bloque = {}
    for sid in set(limpio) | antes:
        uid = f"escena:{sid}"
        actual = previos.get(uid)
        actual = dict(actual) if isinstance(actual, dict) else {}
        if sid in limpio:
            actual["redactado"] = limpio[sid]["prompt"]
            actual["redactado_set"] = limpio[sid]["set"]
        else:
            actual.pop("redactado", None)
            actual.pop("redactado_set", None)
        bloque[uid] = actual
    ctx.estado.actualizar_params("assets", {"unidades": bloque})
    return len(limpio), avisos


@app.put("/api/proyectos/{pid}/redactor")
def guardar_redactado(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda el prompt escrito de cada plano. Un prompt vacío lo quita."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    if not isinstance(datos.get("plan"), dict):
        raise ErrorApi(400, "hace falta 'plan': {id de plano: {set, prompt}}")
    cuantas, avisos = _guardar_redactado_por_unidad(ctx, datos["plan"])
    ctx.bitacora.anotar("redactor_guardado", "assets", {"planos": cuantas})
    return {"guardado": cuantas, "avisos": avisos,
            "estado": ctx.estado.estado_de("assets"),
            "aguas_abajo": {h: ctx.estado.unidades_obsoletas(h)
                            for h in descendientes_de("assets")}}


def _correr_redactor(avisar, ctx, ajuste, aplicar=False):
    """Escribe el encargo entero de cada plano, con TODO el vídeo delante."""
    redactor = _redactor()
    assets = ctx.estado.params("assets") or {}
    plan_assets = _plan_de_planos(ctx, avisar)
    escenas = (plan_assets or {}).get("escenas") or []
    if not escenas:
        raise RuntimeError("no hay planos todavía: corta la narración antes")
    # LO QUE SU TRAMO PONE A MANO. Es la diferencia con `direccion`: el agente
    # no recibe UN sitio ya decidido por el código, recibe los que el director
    # de arte escribió para ese trozo del guion y elige el que va con la frase.
    opciones, catalogo = PASOS_MODULOS.p6_assets.opciones_de_tramo(
        ctx.proyecto, assets, escenas)
    for escena, beats in zip(escenas, opciones):
        escena["_sitios"] = [b.get("set") for b in beats if b.get("set")]
        escena["_acciones"] = [b.get("accion") for b in beats if b.get("accion")]
    ficha = redactor.proponer(
        escenas, ajuste=ajuste, avisar=avisar, proyecto_id=ctx.id,
        titulo=(assets.get("titulo") or ctx.proyecto.id),
        estilo=(assets.get("estilo") or (plan_assets or {}).get("estilo") or {}),
        # EL IDIOMA VA EXPLICITO, igual que en el plan de cartelas y por lo
        # mismo: lo que el agente escribe ENTRE COMILLAS lo dibuja el generador
        # tal cual, y sin este dato lo escribe en el idioma del ejemplo que
        # tenga delante. Ver `_ultima_palabra_idioma` en p6_assets.
        idioma=_idioma_del_video(ctx),
        catalogo=catalogo)
    ctx.bitacora.anotar("redactor", "assets", {
        "planos": ficha.get("planos"), "redactados": ficha.get("redactados"),
        "ajuste": ajuste, "aplicar": bool(aplicar)})
    if aplicar and isinstance(ficha.get("plan"), dict):
        _guardar_redactado_por_unidad(ctx, ficha["plan"])
        ficha["aplicado"] = True
    avisar(1.0, f"{ficha.get('redactados')} de {ficha.get('planos')} planos escritos")
    return ficha


@app.post("/api/proyectos/{pid}/redactor/proponer", status_code=202)
def proponer_redactado(pid: str, cuerpo: dict = Body(default=None)):
    """Escribe el prompt de cada plano, con TODOS los planos delante de una vez."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    por_fase = CLI_CLAUDE.por_defecto_de("redactor")
    ajuste = _ajuste_cli(datos, por_fase["modelo"], por_fase["esfuerzo"])
    trabajo_id = ctx.gestor.lanzar("redactor", _correr_redactor, ctx, ajuste,
                                   paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ajuste": ajuste,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


def _correr_direccion(avisar, ctx, ajuste, aplicar=False):
    direccion = _direccion()
    assets = ctx.estado.params("assets") or {}
    plan_assets = _plan_de_planos(ctx, avisar)
    escenas = (plan_assets or {}).get("escenas") or []
    if not escenas:
        raise RuntimeError("no hay planos todavía y no se ha podido cortar la "
                           "narración: comprueba que la voz haya dejado su "
                           "audio_meta.json")
    # TODO EL CONTEXTO DE UNA VEZ: el estilo tal y como lo recibe el modelo de
    # imagen, los sitios con su descripción literal, el reparto y la acción del
    # tramo de cada plano. Es lo que le permite escribir SABIENDO cómo se va a
    # dibujar, en vez de adivinar — y lo que hace que pueda no contradecirlo.
    ficha = direccion.proponer(
        escenas, ajuste=ajuste, avisar=avisar, proyecto_id=ctx.id,
        titulo=(assets.get("titulo") or ctx.proyecto.id),
        estilo=(assets.get("estilo") or (plan_assets or {}).get("estilo") or {}),
        # EL IDIOMA VA EXPLICITO. Sin el, `direccion` escribia los rotulos en el
        # idioma de su unico ejemplo, que estaba en ingles: en `video_referencia`
        # (07-09-2026) pidio catorce rotulos en ingles --"CITY OPENS NEW PARK",
        # "BANK", "SAVINGS"-- para un video en castellano, y el generador los
        # dibujo. Es el mismo dato que ya recibia el plan de cartelas, y por el
        # mismo motivo.
        idioma=_idioma_del_video(ctx),
        catalogo=(assets.get("catalogo")
                  or (plan_assets or {}).get("catalogo") or {}),
        beats=(plan_assets or {}).get("beats"))
    ctx.bitacora.anotar("direccion", "assets", {
        "planos": ficha.get("planos"), "dirigidos": ficha.get("dirigidos"),
        "ajuste": ajuste, "aplicar": bool(aplicar)})
    # Desde una receta se APLICA, o la tanda paga la llamada y sigue como si no
    # hubiera pasado nada. Es la misma regla que el plan de cartelas.
    if aplicar and isinstance(ficha.get("plan"), dict):
        _guardar_direccion_por_unidad(ctx, ficha["plan"])
        ficha["aplicado"] = True
    avisar(1.0, f"{ficha.get('dirigidos')} de {ficha.get('planos')} planos dirigidos")
    return ficha


@app.post("/api/proyectos/{pid}/direccion/proponer", status_code=202)
def proponer_direccion(pid: str, cuerpo: dict = Body(default=None)):
    """Escribe qué se ve en cada plano, con TODOS los planos delante de una vez.

    De una vez y no plano a plano: el trabajo es que cada plano se distinga del
    de al lado, y eso es comparar. Sin ver el vecino, cuarenta y nueve respuestas
    razonables y repetidas.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    por_fase = CLI_CLAUDE.por_defecto_de("direccion")
    ajuste = _ajuste_cli(datos, por_fase["modelo"], por_fase["esfuerzo"])
    trabajo_id = ctx.gestor.lanzar("direccion", _correr_direccion, ctx, ajuste,
                                   paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ajuste": ajuste,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


# LAS IMÁGENES YA NO SE MIRAN SOLAS. Aquí vivía `mirar`: un agente que abría
# los cuarenta y nueve PNG uno a uno y decía cuál tenía manos raras, el logo
# equivocado o una escena que no era la pedida. Se retiró el 24-08-2026 por
# decisión del canal, con su módulo, su tarea de receta, su ajuste del CLI y su
# pantalla. No cambiaba nada de lo que salía: señalaba, y decidir qué hacer con
# lo señalado ya tenía su botón.
#
# Lo que hace que las imágenes salgan bien sigue en pie y es lo de antes de
# generarlas: la guía de estilo, las referencias, y sobre todo `direccion`, que
# escribe qué se ve en CADA plano con el vídeo entero delante.


def _carpeta_de_escenas(ctx):
    return os.path.join(ctx.proyecto.ruta_paso("assets"), "escenas")


# ----------------------------------------- el previsualizador escena a escena
#
# AQUI VIVIA LA REVISION DE LOS PLANOS CON IA, y esto es lo que la sustituye.
#
# Aquella abria los PNG con un modelo, decidia cuales contradecian el relato y
# rehacia esos. Miraba bien y era barata de mirar, pero se comia el reloj -- una
# llamada por cada seis planos, treinta y seis en un video normal -- y sobre
# todo decidia SOLA sobre lo unico que no deberia decidir sola: que se ve.
#
# Lo que entra en su lugar no es otro agente: es una PANTALLA. Se ve el video
# antes de montarlo, plano a plano y al ritmo de quien mira, con el audio de esa
# escena sonando y un cuadro de feedback debajo.
#
# ESTE ENDPOINT NO MONTA NADA, y ahi esta la gracia. Devuelve las piezas
# sueltas --la imagen, sus dos capas vectoriales y donde empieza y acaba su
# audio-- y quien las junta es el navegador. Que ademas las junta MEJOR que el
# render para esto: el subtitulo es texto de verdad y no pixeles quemados, y
# cambiar de escena es mover el `currentTime` de un <audio>, no cortar un wav.
#
# LO QUE NO VA, y es la mitad del encargo: ni el movimiento de camara
# (`movimiento/{id}.json`) ni las transiciones. Se mira UNA imagen quieta con su
# audio. El zoom y los cortes se ven en el MP4, que es donde importan.


def _ruta_de_version(ctx, paso, *partes):
    """`pasos/assets/v3/escenas/S001.png`, o None si ese paso no tiene version.

    La misma forma que arma la interfaz (`rutaVersion` en app.js) y que entiende
    `GET /a/{pid}/{ruta}`: relativa al proyecto y con barras normales.
    """
    version = ctx.proyecto.version_activa(paso)
    if not version:
        return None
    ruta = os.path.join(ctx.proyecto.ruta_paso(paso, version), *partes)
    if not os.path.exists(ruta):
        return None
    return "/".join(["pasos", paso, f"v{int(version)}"] + list(partes))


def _ficha_de_escena(ctx, sid):
    """La ficha del dibujo de un plano: para QUE texto se dibujo, y su ruta."""
    version = ctx.proyecto.version_activa("assets")
    if not version:
        return {}
    ruta = os.path.join(ctx.proyecto.ruta_paso("assets", version),
                        "escenas", f"{sid}.json")
    return PASOS_MODULOS.medios.leer_json(ruta, {}) or {}


def _obsolescencia(ctx, escena):
    """Si el dibujo de este plano ya no es de lo que el plano dice. -> {}

    SE CALCULA AL MIRAR, no al generar. El texto de un plano cambia cuando se
    reescribe el guion o cuando se vuelve a cortar la narracion, y las dos cosas
    pasan sin que nadie vuelva a pasar por el paso de imagenes: preguntarlo solo
    al dibujar seria preguntarlo cuando todavia estaba bien.

    Y OBSOLETO NO ES PENDIENTE: la imagen se queda, no se rehace sola y no se
    cobra. Lo unico que hace esto es DECIRLO, para que lo decida quien mira
    .
    """
    p6 = PASOS_MODULOS.p6_assets
    ficha = _ficha_de_escena(ctx, str(escena.get("id") or ""))
    if not ficha:
        return {}
    dibujada = p6._texto_clave(ficha)
    dice = p6._texto_clave(escena)
    if not dibujada or not dice or p6._mismo_dicho(dibujada, dice):
        return {}
    # EL DESCARTE SE RECUERDA CONTRA UN TEXTO. Quitar la tarjeta es decir «este
    # dibujo me vale para lo que dice AHORA»; guardarlo como un si o un no haria
    # que la proxima vez que cambiara la frase siguiera aprobado.
    if PASOS_MODULOS.medios.normalizar_texto(ficha.get("vale_para") or "") == dice:
        return {}
    return {"obsoleta": True, "dibujada_para": ficha.get("narracion") or ""}

def _audio_de_la_toma(ctx):
    """El wav que se oye: el de la VOZ, el mismo que monta el render.

    Antes se preferia el de `revision_audio`, y era el equivocado. Los planos
    se cortan contra las marcas de la voz (`p6_assets`, que lee el
    `audio_meta.json` de `voz`) y el MP4 suena con el wav de la voz
    (`p8_render`, `salida_de(proyecto, "voz", ...)`). La toma de la revision es
    una RESINTESIS completa con su propio reloj, que nadie de aguas abajo usa:
    los `t_in`/`t_out` de cada plano no son los suyos. Con ella delante, «Oírla»
    sonaba otra frase, y en los planos que caen pasado su final no sonaba nada
    --el audio saltaba al final y se paraba-- (16-10-2026). Con una revision
    sellada (copia de la voz) daba igual; con una regrabada o vieja, no.

    Se busca IGUAL que el render, y se devuelve relativa al proyecto, que es lo
    que entiende `GET /a/{pid}/{ruta}`. Fuera del proyecto, None.
    """
    try:
        ruta = PASOS_MODULOS.medios.salida_de(
            ctx.proyecto, "voz", claves=("wav", "audio", "narracion"),
            patrones=(r"narracion\.wav", r".*\.wav"), estado=ctx.estado)
    except Exception:                                         # noqa: BLE001
        ruta = None
    if not ruta or not os.path.isfile(ruta):
        return None
    relativa = os.path.relpath(os.path.realpath(ruta),
                               os.path.realpath(ctx.proyecto.raiz))
    if relativa.startswith(".."):
        return None
    return relativa.replace(os.sep, "/")


def _musica_de_la_previa(ctx, render):
    """La musica que suena en «Todo seguido». -> url | ruta del proyecto | None

    LA DE VERDAD, no una clave que nadie escribe (se leia `musica.pista`, que no
    existe: la musica nunca sonaba). Por orden:

      1. la cama que construyo el ultimo montaje (`render/vN/cama.wav`): es la
         musica tal cual suena en el MP4, con sus tramos encadenados;
      2. si no la hay, la escucha del propio tema (`muestra`, una ruta de la API
         que sirve el banco: los temas subidos por ti).

    Un tema de Jamendo sin montaje no suena aqui: escucharlo es salir a
    Jamendo, y esta pantalla no sale a la red por mirar diapositivas.
    """
    cama = _ruta_de_version(ctx, "render", "cama.wav")
    if cama:
        return cama
    ficha = render.get("musica") if isinstance(render.get("musica"), dict) else {}
    muestra = str((ficha or {}).get("muestra") or "")
    return muestra if muestra.startswith("/api/") else None


def _medidor_de_subtitulo(ctx, plan):
    """Con que se mide un subtitulo aqui. -> (medir, banda)

    LO MISMO QUE USA EL RENDER, pedido a quien lo tiene: `p7_callouts` mide con
    la fuente del grafismo y en el peso con el que dibuja (SUB_PESO), porque
    medir con la regular partia un doce por ciento tarde y el texto se salia.
    Repetir esa cuenta aqui seria tener dos medidores que se separan el dia que
    alguien cambie la fuente.

    Si algo falla se devuelve (None, None) y el subtitulo sale sin partir: peor
    corte, pero pantalla.
    """
    try:
        p7 = PASOS_MODULOS.p7_callouts
        # LA MISMA BANDA Y EL MISMO MEDIDOR QUE `p7_callouts.ejecutar`: su
        # margen y su ancho maximo son constantes suyas, y `banda_fija` sin
        # ellos da otra caja. Se le piden a el, no se copian.
        salida = p7.salida_de(plan)
        params_callouts = ctx.estado.params("callouts") or {}
        banda = p7.banda_subtitulo(salida, params_callouts)
        _, ficha_diseno = p7.diseno_de(params_callouts)
        # el cuerpo de ESTA salida: en vertical es mas grande (p7.escala_subtitulo)
        medir = p7._medidor(p7.fuente_subtitulo(params_callouts, ficha_diseno),
                            p7.tamano_subtitulo(params_callouts, salida),
                            negrita=p7.SUB_PESO >= 600)
        return medir, banda
    except Exception:                                         # noqa: BLE001
        return None, None


def _lineas_de_subtitulo(texto, medir, banda):
    """El texto partido en las mismas lineas que dibujara el render."""
    texto = " ".join(str(texto or "").split())
    if not texto:
        return []
    if not medir or not banda:
        return [texto]
    try:
        return list(PASOS_MODULOS.subtitulos.dos_lineas(
            texto, medir, banda["ancho"])) or [texto]
    except Exception:                                         # noqa: BLE001
        return [texto]


@app.post("/api/proyectos/{pid}/escenas/{sid}/vale")
def aceptar_imagen_obsoleta(pid: str, sid: str):
    """«Este dibujo me vale para lo que dice ahora». -> {ok}

    Es el descarte de la tarjeta de obsoleto, y no toca la imagen ni el plan:
    escribe en la ficha CONTRA QUE TEXTO se acepto. Si manana esa frase vuelve
    a cambiar, la tarjeta vuelve, que es justo lo que se quiere -- un «ya lo he
    visto» permanente aprobaria dibujos que nadie ha vuelto a mirar.
    """
    ctx = contexto(pid)
    version = ctx.proyecto.version_activa("assets")
    if not version:
        raise ErrorApi(409, "todavía no hay imágenes de este vídeo")
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escena = next((e for e in (plan.get("escenas") or [])
                   if str(e.get("id") or "") == sid), None)
    if not escena:
        raise ErrorApi(404, f"no hay ningún plano {sid} en este vídeo")
    ruta = os.path.join(ctx.proyecto.ruta_paso("assets", version),
                        "escenas", f"{sid}.json")
    ficha = PASOS_MODULOS.medios.leer_json(ruta, {}) or {}
    if not ficha:
        raise ErrorApi(404, f"{sid} no tiene ficha de imagen")
    ficha["vale_para"] = escena.get("narracion") or ""
    ficha["obsoleta"] = False
    PASOS_MODULOS.medios.escribir_json(ruta, ficha)
    return {"ok": True, "id": sid}


# ------------------------------------------------ QUITAR UNA IMAGEN (unir-planos)
#
# Rama unir-planos (25-10-2026, pedido del dueño). «Quitar esta imagen»: lo que
# se oye en ella pasa a la de antes o a la de después, que conserva su dibujo.
# Se apunta en `<proyecto>/planos_quitados.json` (`pasos/quitar_planos.py`,
# FUERA de params: ahí explica por qué) y se lanza una pasada de imágenes SIN
# NINGUNA UNIDAD PEDIDA, que no dibuja nada: solo vuelve a cortar y deja una
# versión nueva. Detrás quedan los rótulos y el montaje, gratis, con «Montar».
# Deshacer es lo mismo al revés, y tampoco paga: si la imagen quitada ya no
# estuviera, el plano vuelve sin imagen y se dibuja solo si se pide.

def _quitar_planos():
    return getattr(PASOS_MODULOS, "quitar_planos", None) or __import__("quitar_planos")


def _vecinos_para_quitar(plan, sid):
    """{"anterior": id|None, "siguiente": id|None} a los que puede ir la voz de
    `sid`; None en los dos si `sid` no se puede quitar."""
    qp = _quitar_planos()
    sin_imagen = PASOS_MODULOS.p6_assets._sin_imagen
    escenas = [e for e in (plan.get("escenas") or []) if e.get("id")]
    ids = [str(e["id"]) for e in escenas]
    if sid not in ids:
        return None
    i = ids.index(sid)
    salida = {"anterior": None, "siguiente": None}
    if not qp.se_puede_quitar(escenas[i], sin_imagen) or qp.tiene_continuacion(escenas, i):
        return salida
    if i > 0 and qp.puede_recibir(escenas[i - 1], sin_imagen):
        salida["anterior"] = ids[i - 1]
    if i + 1 < len(escenas) and qp.puede_recibir(escenas[i + 1], sin_imagen):
        salida["siguiente"] = ids[i + 1]
    return salida


def _quitar_en_la_previa(plan, escena):
    """Lo que la diapositiva necesita para «Quitar esta imagen» y «Deshacer»."""
    try:
        vecinos = _vecinos_para_quitar(plan, str(escena.get("id") or "")) or {}
    except Exception:                                       # noqa: BLE001
        vecinos = {}
    salida = {}
    if vecinos.get("anterior") or vecinos.get("siguiente"):
        salida["quitar"] = vecinos
    if escena.get("absorbe"):
        salida["absorbe"] = [{"id": a.get("id"), "lado": a.get("lado"),
                              "narracion": a.get("narracion") or "",
                              "n": int(a.get("n") or 0)}
                             for a in escena["absorbe"] if isinstance(a, dict)]
    # e «Insertar una imagen aquí…» y su deshacer (rama insertar-imagen)
    salida.update(_insertar_en_la_previa(plan, escena))
    return salida


def _sin_nada_en_marcha(ctx, que):
    if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
        raise ErrorApi(409, f"hay algo en marcha en este vídeo: {que} cuando termine")
    with _COLA_LOCK:
        if _cola_dibujando(ctx):
            raise ErrorApi(409, f"se están rehaciendo imágenes con tus notas: {que} "
                                "cuando terminen")


def _pasada_sin_dibujar(ctx, nombre, restaurar=None):
    """La pasada de imágenes que solo vuelve a cortar (`solo_cortar`): ninguna
    unidad pedida, sin hojas ni planos nuevos, sin esperar turno de imágenes.
    No se dibuja ni se paga nada. `restaurar`: [{uid, texto}] del plano devuelto,
    que se sella con su imagen de siempre si sigue diciendo eso y su imagen no
    está obsoleta. -> {trabajo, trabajo_id}"""
    opciones = {"solo_cortar": True}
    if restaurar:
        opciones["restaurar"] = list(restaurar)
    tid = lanzar_paso(ctx, "assets", [], nombre=nombre, opciones=opciones)
    return {"trabajo": tid, "trabajo_id": tid}


def _quitados_sin_aplicar(ctx, plan):
    """Lo apuntado como quitado que el plan de ahora NO refleja (la pasada
    fallo o se cancelo, o se volvio a una version anterior): se enseña con su
    «Deshacer» para que nunca quede algo quitado sin forma de devolverlo."""
    p6 = PASOS_MODULOS.p6_assets
    aplicados = set()
    for escena in plan.get("escenas") or []:
        for a in escena.get("absorbe") or []:
            if isinstance(a, dict):
                aplicados.add((p6._texto_clave({"narracion": a.get("narracion")}),
                               int(a.get("n") or 0)))
    return [{"id": e.get("id"), "narracion": e["texto"], "n": e["n"], "hacia": e["hacia"]}
            for e in _quitar_planos().leer(ctx.proyecto.raiz)
            if (e["texto"], e["n"]) not in aplicados]


@app.post("/api/proyectos/{pid}/planos/{sid}/quitar", status_code=202)
def quitar_imagen(pid: str, sid: str, cuerpo: dict = Body(default=None)):
    """Quita la imagen `sid`: su voz pasa a la de antes o a la de después.
    {hacia: "anterior"|"siguiente"} -> el trabajo (gratis) que vuelve a cortar."""
    ctx = contexto(pid)
    p6 = PASOS_MODULOS.p6_assets
    hacia = str(_cuerpo(cuerpo).get("hacia") or "")
    if hacia not in _quitar_planos().HACIA:
        raise ErrorApi(400, "di a qué imagen pasa la voz: «anterior» o «siguiente»")
    with _cerrojo_de_cadena(ctx.id):
        _sin_nada_en_marcha(ctx, "quítala")
        plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
        vecinos = _vecinos_para_quitar(plan, sid)
        if vecinos is None:
            raise ErrorApi(404, f"este vídeo no tiene la imagen {sid}")
        if not vecinos.get(hacia):
            raise ErrorApi(409, f"la voz de {sid} no puede pasar a la imagen {hacia}: "
                                "no la hay, o es una cartela o la continuación de otra")
        escenas = [e for e in plan["escenas"] if e.get("id")]
        i = next(n for n, e in enumerate(escenas) if str(e.get("id")) == sid)
        qp = _quitar_planos()
        unidad = ((ctx.estado.params("assets") or {}).get("unidades") or {}).get(f"escena:{sid}")
        antes = qp.leer(ctx.proyecto.raiz)
        texto = p6._texto_clave(escenas[i])
        # LA OCURRENCIA EN EL CORTE ORIGINAL, como la cuenta `aplicar`: los
        # planos de antes que dicen lo mismo, tambien los ya quitados (viven
        # en el `absorbe` de su vecino; los de `sid` mismo, solo los de antes)
        def quitados_iguales(escena, solo_antes=False):
            return sum(1 for a in escena.get("absorbe") or []
                       if isinstance(a, dict) and (not solo_antes or a.get("lado") == "antes")
                       and p6._texto_clave({"narracion": a.get("narracion")}) == texto)
        n = (qp.ocurrencia(escenas, i, p6._texto_clave)
             + sum(quitados_iguales(e) for e in escenas[:i])
             + quitados_iguales(escenas[i], solo_antes=True))
        # si estaba al dia al quitarla: solo entonces se sella al deshacer
        fresca = f"escena:{sid}" not in set(ctx.estado.unidades_obsoletas("assets") or [])
        qp.quitar(ctx.proyecto.raiz, texto, hacia, sid, n=n,
                  unidad=unidad if isinstance(unidad, dict) else None, fresca=fresca)
        try:
            ficha = _pasada_sin_dibujar(ctx, "quitar_imagen")
        except Exception:
            # sin pasada no se aplica: lo apuntado se deshace, o quedaria
            # quitado a medias (y sin «Deshacer» en la pantalla)
            qp.reponer(ctx.proyecto.raiz, antes)
            raise
    ctx.bitacora.anotar("imagen_quitada", "assets",
                        {"plano": sid, "hacia": hacia, "a": vecinos[hacia]})
    return dict(ficha, quitada=sid, hacia=vecinos[hacia])


@app.post("/api/proyectos/{pid}/planos/devolver", status_code=202)
def devolver_imagen(pid: str, cuerpo: dict = Body(default=None)):
    """Deshace «Quitar esta imagen». {narracion: lo que decía la imagen quitada}
    -> el trabajo (gratis) que vuelve a cortar."""
    ctx = contexto(pid)
    p6 = PASOS_MODULOS.p6_assets
    datos = _cuerpo(cuerpo)
    narracion = str(datos.get("narracion") or "")
    texto = p6._texto_clave({"narracion": narracion})
    try:
        n = max(0, int(datos.get("n") or 0))
    except (TypeError, ValueError):
        raise ErrorApi(400, "'n' tiene que ser un número")
    if not texto:
        raise ErrorApi(400, "manda {narracion}: lo que decía la imagen quitada")
    qp = _quitar_planos()
    with _cerrojo_de_cadena(ctx.id):
        _sin_nada_en_marcha(ctx, "deshazlo")
        entrada = qp.devolver(ctx.proyecto.raiz, texto, n)
        if entrada is None:
            raise ErrorApi(404, "esa imagen no está quitada")
        # SUS PARAMS POR UNIDAD (la dirección, la nota...), que el núcleo borró
        # al retirarla. Solo si el corte de ahora la tiene en el mismo número
        # (el que se lleva su voz la nombra con él): si no, se dejan fuera
        # antes que escribirlos en otro plano.
        uid = f"escena:{entrada['id']}"
        plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
        en_su_sitio = any(a.get("id") == entrada["id"] and int(a.get("n") or 0) == n
                          for e in plan.get("escenas") or []
                          for a in e.get("absorbe") or [] if isinstance(a, dict))
        repuso = False
        if entrada.get("unidad") and entrada["id"] and en_su_sitio:
            unidades = (ctx.estado.params("assets") or {}).get("unidades") or {}
            if uid not in unidades:
                ctx.estado.actualizar_params("assets", {"unidades": {uid: entrada["unidad"]}})
                repuso = True
        restaurar = ([{"uid": uid, "texto": texto}]
                     if en_su_sitio and entrada["id"] and entrada.get("fresca") else None)
        try:
            ficha = _pasada_sin_dibujar(ctx, "devolver_imagen", restaurar=restaurar)
        except Exception:
            qp.restaurar(ctx.proyecto.raiz, entrada)
            if repuso:
                with ctx.estado._lock:
                    params = copy.deepcopy(ctx.estado.params("assets") or {})
                    (params.get("unidades") or {}).pop(uid, None)
                    ctx.estado.set_params("assets", params)
            raise
    ctx.bitacora.anotar("imagen_devuelta", "assets", {"narracion": narracion[:120]})
    return dict(ficha, devuelta=True)


# --------------------------------------- INSERTAR UNA IMAGEN (insertar-imagen)
#
# Rama insertar-imagen (26-10-2026, pedido del dueño). Lo contrario de quitar:
# se elige la palabra de un plano donde empieza una imagen nueva y se escribe en
# español qué se ve. Claude lo pasa al inglés (en un hilo: tarda segundos y el
# proxy corta a los sesenta), se apunta en `<proyecto>/planos_insertados.json`
# (`pasos/insertar_planos.py`, FUERA de params) y se lanza la pasada de
# imágenes con la nueva como ÚNICA unidad pedida: se paga UNA imagen, con el
# precio confirmado antes. El plano partido conserva su dibujo. Deshacer es la
# pasada que solo corta (`_pasada_sin_dibujar`), gratis.

_INSERTANDO = {}
_LOCK_INSERTANDO = threading.Lock()


def _insertar_planos():
    return getattr(PASOS_MODULOS, "insertar_planos", None) or __import__("insertar_planos")


def _precio_de_una_imagen(ctx):
    params = ctx.estado.params("assets") or {}
    calidad = str(params.get("calidad") or "low")
    precio = AJUSTES.precio_por_imagen(calidad, modo=PASOS_MODULOS.p6_assets.modo_de(
        params.get("estilo")))
    return calidad, round(float((precio or {}).get("usd") or 0.0), 4)


def _donde_insertar(plan, sid):
    """-> (escenas, i) del plano `sid` si admite una imagen insertada; si no,
    ErrorApi con el motivo."""
    ip = _insertar_planos()
    escenas = [e for e in (plan.get("escenas") or []) if e.get("id")]
    i = next((n for n, e in enumerate(escenas) if str(e["id"]) == sid), None)
    if i is None:
        raise ErrorApi(404, f"este vídeo no tiene la imagen {sid}")
    if not ip.se_puede_partir(escenas, i, PASOS_MODULOS.p6_assets._sin_imagen):
        raise ErrorApi(409, f"en {sid} no se puede insertar una imagen: es una cartela, "
                            "la continuación de otra, ya es una insertada o lleva la voz "
                            "de una quitada")
    return escenas, i


def _insertar_en_la_previa(plan, escena):
    """Lo que la diapositiva necesita para «Insertar una imagen aquí…» y para
    deshacer una insertada."""
    salida = {}
    try:
        ip = _insertar_planos()
        escenas = [e for e in (plan.get("escenas") or []) if e.get("id")]
        i = next((n for n, e in enumerate(escenas) if e.get("id") == escena.get("id")), None)
        if i is not None and ip.se_puede_partir(escenas, i, PASOS_MODULOS.p6_assets._sin_imagen):
            validas = ip.palabras_validas(escena)
            if validas:
                salida["insertar"] = {"palabras": ip.palabras_de(escena), "validas": validas}
    except Exception:                                       # noqa: BLE001
        pass
    if isinstance(escena.get("insertada"), dict):
        ins = escena["insertada"]
        salida["insertada"] = {"en": ins.get("en"), "texto": ins.get("texto"),
                               "n": int(ins.get("n") or 0), "palabra": int(ins.get("palabra") or 0),
                               "que": ins.get("que") or ""}
    return salida


def _insertados_sin_aplicar(ctx, plan):
    """Lo apuntado como insertado que el corte de ahora NO tiene (la tanda
    falló o se canceló, o se volvió a una versión anterior): se enseña con su
    «Deshacer», como lo quitado (`_quitados_sin_aplicar`)."""
    puestos = {(i.get("texto"), int(i.get("n") or 0), int(i.get("palabra") or 0))
               for e in plan.get("escenas") or [] if isinstance(e.get("insertada"), dict)
               for i in [e["insertada"]]}
    return [{"id": e["id"], "texto": e["texto"], "n": e["n"], "palabra": e["palabra"],
             "que": e.get("que") or ""}
            for e in _insertar_planos().leer(ctx.proyecto.raiz)
            if (e["texto"], e["n"], e["palabra"]) not in puestos]


def _ficha_insertando(ctx):
    calidad, usd = _precio_de_una_imagen(ctx)
    with _LOCK_INSERTANDO:
        marcha = dict(_INSERTANDO.get(ctx.id) or {})
    return dict({"estado": "quieto"}, **marcha, precio={"usd": usd, "calidad": calidad})


@app.get("/api/proyectos/{pid}/planos/insertar")
def leer_insercion(pid: str):
    """Cómo va la última imagen insertada y lo que cuesta una. -> {estado,
    precio: {usd, calidad}, trabajo_id?, nuevo?, error?}"""
    return _ficha_insertando(contexto(pid))


@app.post("/api/proyectos/{pid}/planos/{sid}/insertar", status_code=202)
def insertar_imagen(pid: str, sid: str, cuerpo: dict = Body(default=None)):
    """Inserta una imagen nueva en `sid`. {palabra, que, usd}

    `palabra`: desde qué palabra (0 = la primera; tiene que ser >= 1) va la
    nueva. `que`: lo que se ve, en español. `usd`: el precio de una imagen que
    se confirmó; si ya no es ese, no se lanza nada (409). Claude pasa `que` al
    inglés en un hilo y después se apunta y se lanza la tanda de UNA imagen.
    -> la ficha, con `estado` «pensando»."""
    ctx = contexto(pid)
    p6 = PASOS_MODULOS.p6_assets
    ip = _insertar_planos()
    datos = _cuerpo(cuerpo)
    que = " ".join(str(datos.get("que") or "").split())
    try:
        palabra = int(datos.get("palabra"))
    except (TypeError, ValueError):
        raise ErrorApi(400, "di desde qué palabra va la imagen nueva")
    if not que:
        raise ErrorApi(400, "escribe qué quieres que se vea en la imagen nueva")
    if len(que) > ip.MAX_QUE:
        raise ErrorApi(400, f"escríbelo en menos de {ip.MAX_QUE} letras")
    _calidad, usd = _precio_de_una_imagen(ctx)
    try:
        visto = round(float(datos.get("usd")), 4)
    except (TypeError, ValueError):
        raise ErrorApi(400, "hace falta 'usd': el precio que se confirmó")
    if abs(visto - usd) > 0.0005:
        raise ErrorApi(409, f"una imagen cuesta ahora {usd:.3f} $, no {visto:.3f} $: vuelve a "
                            "mirarlo antes de confirmar", {"usd": usd})
    with _cerrojo_de_cadena(ctx.id):
        _sin_nada_en_marcha(ctx, "insértala")
        plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
        escenas, i = _donde_insertar(plan, sid)
        palabras = ip.palabras_de(escenas[i])
        if not 1 <= palabra < len(palabras):
            raise ErrorApi(400, f"la imagen nueva tiene que empezar entre la palabra 2 y la "
                                f"{len(palabras)} de {sid}")
        if palabra not in ip.palabras_validas(escenas[i]):
            raise ErrorApi(400, f"ahí uno de los dos trozos duraría menos de "
                                f"{ip.MIN_TROZO_S:g} s: elige otra palabra")
        # SOLO SE PARTE UNA IMAGEN DIBUJADA, y sin nada pendiente de insertar:
        # la tanda pide UNA imagen y lo demás no se toca (revisión del 26-10)
        if not _ruta_de_version(ctx, "assets", "escenas", f"{sid}.png"):
            raise ErrorApi(409, f"{sid} todavía no tiene imagen: dibújala antes de insertar otra")
        if _insertados_sin_aplicar(ctx, plan):
            raise ErrorApi(409, "hay una imagen insertada que no llegó a dibujarse: deshazla o "
                                "vuelve a intentarla antes de insertar otra")
        texto = p6._texto_clave(escenas[i])
        # LA OCURRENCIA EN EL CORTE ANTES DE QUITAR, como la cuenta `aplicar`:
        # los planos de antes que dicen lo mismo y los quitados que viven en
        # el `absorbe` de su vecino (los de `sid` mismo no: no se parte uno así)
        n = (sum(1 for e in escenas[:i] if p6._texto_clave(e) == texto and not e.get("insertada"))
             + sum(1 for e in escenas[:i] for a in e.get("absorbe") or []
                   if isinstance(a, dict) and p6._texto_clave({"narracion": a.get("narracion")}) == texto))
        with _LOCK_INSERTANDO:
            if (_INSERTANDO.get(ctx.id) or {}).get("estado") == "pensando":
                raise ErrorApi(409, "ya se está preparando otra imagen nueva en este vídeo")
            _INSERTANDO[ctx.id] = {"estado": "pensando", "plano": sid}
    prompt, narracion = escenas[i].get("prompt") or "", " ".join(palabras[palabra:])

    def hilo():
        ficha = {"plano": sid}
        try:
            pedido = ip.al_ingles(que, prompt=prompt, narracion=narracion, cwd=RAIZ_ESTUDIO)
            with _cerrojo_de_cadena(ctx.id):
                # y el precio que se confirmó sigue siendo el de ahora
                if abs(_precio_de_una_imagen(ctx)[1] - usd) > 0.0005:
                    raise ErrorApi(409, "el precio de una imagen ha cambiado mientras se "
                                        "preparaba: vuelve a mirarlo y confírmalo otra vez")
                # lo de antes de pensar puede haber cambiado: se mira otra vez
                _sin_nada_en_marcha(ctx, "insértala")
                plan_ahora = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
                escenas_ahora, j = _donde_insertar(plan_ahora, sid)
                if p6._texto_clave(escenas_ahora[j]) != texto:
                    raise ErrorApi(409, f"{sid} ha cambiado mientras se preparaba: vuelve a pedirla")
                antes = ip.leer(ctx.proyecto.raiz)
                # NI UNA LETRA CON PARAMS DE OTRA INSERTADA (revisión del 28-10):
                # S004B dirigida, deshecha a medias y vuelta a insertar heredaría
                # la dirección vieja en vez de lo que se acaba de escribir
                declaradas = (ctx.estado.params("assets") or {}).get("unidades") or {}
                ocupadas = {u[len(f"escena:{sid}"):] for u in declaradas
                            if u.startswith(f"escena:{sid}") and len(u) == len(f"escena:{sid}") + 1}
                letra = ip.letra_libre(antes, texto, n, ocupadas)
                if not letra:
                    raise ErrorApi(409, f"{sid} ya tiene todas las imágenes insertadas que admite")
                entradas = ip.insertar(ctx.proyecto.raiz, texto, n, palabra, sid, que=que,
                                       direccion=pedido["direccion"],
                                       personas=pedido["personas"], letra=letra)
                nueva = next(e for e in entradas if (e["texto"], e["n"], e["palabra"]) == (texto, n, palabra))
                nuevo = f"{sid}{nueva['letra']}"
                try:
                    trabajo_id = lanzar_paso(ctx, "assets", [f"escena:{nuevo}"],
                                             nombre="insertar_imagen", evento="imagen_insertada",
                                             datos={"plano": sid, "nuevo": nuevo, "usd": usd},
                                             opciones={"solo_pedidas": True})
                except Exception:
                    # sin tanda no se apunta: quedaría un plano sin imagen
                    ip.reponer(ctx.proyecto.raiz, antes)
                    raise
            ctx.bitacora.anotar("imagen_insertada", "assets",
                                {"plano": sid, "nuevo": nuevo, "palabra": palabra})
            ficha.update(estado="lanzado", nuevo=nuevo, trabajo_id=trabajo_id)
        except Exception as fallo:                          # noqa: BLE001
            mensaje = fallo.mensaje if isinstance(fallo, ErrorApi) else _error_para_persona(fallo)
            ficha.update(estado="error", error=mensaje)
        with _LOCK_INSERTANDO:
            _INSERTANDO[ctx.id] = ficha

    threading.Thread(target=hilo, daemon=True, name=f"insertar-{ctx.id}").start()
    return _ficha_insertando(ctx)


@app.post("/api/proyectos/{pid}/planos/insertadas/deshacer", status_code=202)
def deshacer_imagen_insertada(pid: str, cuerpo: dict = Body(default=None)):
    """Quita una imagen insertada: el plano del que salió recupera toda su voz,
    con su dibujo de siempre. {texto, n, palabra} (lo que trae `insertada` en la
    previa) -> el trabajo (gratis) que vuelve a cortar."""
    ctx = contexto(pid)
    ip = _insertar_planos()
    datos = _cuerpo(cuerpo)
    texto = str(datos.get("texto") or "").strip()
    try:
        n, palabra = int(datos.get("n") or 0), int(datos.get("palabra"))
    except (TypeError, ValueError):
        raise ErrorApi(400, "manda {texto, n, palabra}: lo que trae la imagen insertada")
    if not texto:
        raise ErrorApi(400, "manda {texto, n, palabra}: lo que trae la imagen insertada")
    with _cerrojo_de_cadena(ctx.id):
        _sin_nada_en_marcha(ctx, "deshazlo")
        antes = ip.leer(ctx.proyecto.raiz)
        entrada = ip.deshacer(ctx.proyecto.raiz, texto, n, palabra)
        if entrada is None:
            raise ErrorApi(404, "esa imagen no está insertada")
        try:
            ficha = _pasada_sin_dibujar(ctx, "deshacer_insertada")
        except Exception:
            ip.reponer(ctx.proyecto.raiz, antes)
            raise
    ctx.bitacora.anotar("imagen_insertada_deshecha", "assets",
                        {"plano": entrada.get("id"), "palabra": palabra})
    return dict(ficha, deshecha=True)


# --------------------------------- DESCRIPCIÓN DE CADA PLANO (descripcion-planos)
#
# Rama descripcion-planos (26-10-2026, pedido del dueño). Debajo de cada imagen,
# en Imágenes, una o dos frases en español con lo que su prompt pide dibujar.
# El prompt sigue en inglés y no se toca: la descripción la escribe Claude
# (membresía) y va a `<proyecto>/descripciones.json` por la huella del prompt,
# FUERA de params y firmas (regla 1). Si el prompt cambia, su descripción vieja
# deja de casar sola y se pide otra; nunca se enseña la de otro prompt.

_DESCRIBIENDO = {}
_LOCK_DESCRIBIENDO = threading.Lock()


def _prompts_de_planos(plan):
    """[(sid, prompt en inglés)] de los planos con imagen, en orden."""
    salida = []
    for escena in plan.get("escenas") or []:
        sid, prompt = str(escena.get("id") or ""), " ".join(str(escena.get("prompt") or "").split())
        if sid and prompt:
            salida.append((sid, prompt))
    return salida


def _ficha_descripciones(ctx, plan=None):
    """{descripciones: {sid: español}, faltan, total, estado, error?}."""
    if plan is None:
        plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    mod = _traducciones()
    pares = _prompts_de_planos(plan)
    hechas = mod.de(ctx.proyecto.raiz, [p for _s, p in pares], mod.FICHERO_DESCRIPCIONES)
    descripciones = {sid: hechas.get(p) or "" for sid, p in pares}
    with _LOCK_DESCRIBIENDO:
        marcha = dict(_DESCRIBIENDO.get(ctx.id) or {})
    ficha = {"descripciones": {s: d for s, d in descripciones.items() if d},
             # el prompt de cada plano: la pantalla pone la descripción junto
             # al prompt para el que se escribió, nunca junto a otro
             "prompts": dict(pares),
             "faltan": len({p for s, p in pares if not descripciones.get(s)}),
             "total": len({p for _s, p in pares}),
             "estado": marcha.get("estado") or "quieto"}
    if marcha.get("error"):
        ficha["error"] = marcha["error"]
    return ficha


@app.get("/api/proyectos/{pid}/planos/descripciones")
def leer_descripciones_planos(pid: str):
    """Lo que se pidió dibujar en cada plano, en español. -> la ficha"""
    return _ficha_descripciones(contexto(pid))


@app.post("/api/proyectos/{pid}/planos/describir", status_code=202)
def describir_planos(pid: str, cuerpo: dict = Body(default=None)):
    """Pide a Claude, en un hilo, la descripción en español de los planos que
    no la tienen. {auto?: bool}: lo pide la pantalla sola al abrir Imágenes, y
    entonces no se relanza tras un error (una sesión de Claude caída no se
    reintenta en cada repintado); el botón «Reintentar» sí. No dibuja ni
    cambia nada del vídeo. -> la ficha, con `estado` «pensando» si arrancó."""
    ctx = contexto(pid)
    auto = bool(_cuerpo(cuerpo).get("auto"))
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    mod = _traducciones()
    raiz = ctx.proyecto.raiz
    faltan = mod.faltan(raiz, [p for _s, p in _prompts_de_planos(plan)],
                        mod.FICHERO_DESCRIPCIONES)
    with _LOCK_DESCRIBIENDO:
        previo = dict(_DESCRIBIENDO.get(ctx.id) or {})
        lanzar = (bool(faltan) and previo.get("estado") != "pensando"
                  and not (auto and previo.get("estado") == "error"))
        if lanzar:
            _DESCRIBIENDO[ctx.id] = {"estado": "pensando"}

    def hilo():
        try:
            hechas = mod.describir(faltan, cwd=RAIZ_ESTUDIO)
            mod.guardar(raiz, hechas, mod.FICHERO_DESCRIPCIONES)
            if not hechas:
                raise mod.ErrorTraduccion("Claude no ha devuelto ninguna descripción; "
                                          "vuelve a pedirla.")
            ctx.bitacora.anotar("planos_descritos", "assets", {"planos": len(hechas)})
            ficha = {"estado": "listo"}
            if len(hechas) < len(faltan):
                ficha = {"estado": "error", "error": f"Faltan {len(faltan) - len(hechas)} "
                         "descripciones que Claude no devolvió; vuelve a pedirlas."}
        except Exception as fallo:                          # noqa: BLE001
            ficha = {"estado": "error", "error": _error_para_persona(fallo)}
        with _LOCK_DESCRIBIENDO:
            _DESCRIBIENDO[ctx.id] = ficha

    if lanzar:
        threading.Thread(target=hilo, daemon=True, name=f"describir-{ctx.id}").start()
    return _ficha_descripciones(ctx, plan)


@app.get("/api/proyectos/{pid}/previsualizacion")
def leer_previsualizacion(pid: str):
    """Las piezas para ver el video sin montarlo. -> {escenas, audio, ...}"""
    ctx = contexto(pid)
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas_plan = plan.get("escenas") or []
    if not escenas_plan:
        raise ErrorApi(409, "todavía no hay plan de planos: genera el vídeo "
                            "antes de poder mirarlo")
    subtitulos = PASOS_MODULOS.subtitulos
    idioma = plan.get("idioma") or ""
    # Y LOS SUBTITULOS CORREGIDOS A MANO, por el MISMO lector que usa el render
    # (`p7_callouts.texto_subtitulo_de`). Sin esto la vista previa enseñaría el
    # texto de antes de la corrección y el MP4 el de después: dos caminos para
    # lo mismo, y uno de los dos viejo.
    params_callouts = ctx.estado.params("callouts") or {}
    medir, banda = _medidor_de_subtitulo(ctx, plan)
    # lo que se pidió dibujar, en español (rama descripcion-planos)
    descritos = _ficha_descripciones(ctx, plan)["descripciones"]
    escenas = []
    for escena in escenas_plan:
        sid = str(escena.get("id") or "")
        if not sid:
            continue
        # LOS SUBTITULOS, PARTIDOS EN LAS MISMAS DOS LINEAS QUE EL RENDER.
        #
        # Van como texto y con sus tiempos --el navegador los pinta al ritmo del
        # audio, que es lo que hace falta aqui y un fotograma no da-- pero el
        # CORTE no se le deja al navegador. Se salian por los lados y partian
        # donde no toca porque CSS parte por el ancho de la caja y el render
        # parte MIDIENDO con la fuente que dibuja (`subtitulos.dos_lineas` con
        # el medidor de `p7_callouts`, ver SUB_PESO alli). Se parte aqui, con la
        # misma cuenta, y el navegador solo pinta las lineas ya hechas.
        try:
            trozos = subtitulos.de_escena(
                escena, idioma=idioma,
                # los mismos trozos que el render: en vertical son mas cortos
                cap_linea=PASOS_MODULOS.p7_callouts.cap_subtitulo_de(
                    params_callouts, plan),
                cap_trozo=PASOS_MODULOS.p7_callouts.cap_trozo_subtitulo(
                    PASOS_MODULOS.p7_callouts.cap_subtitulo_de(params_callouts, plan),
                    PASOS_MODULOS.p7_callouts.salida_de(plan)),
                texto=PASOS_MODULOS.p7_callouts.texto_subtitulo_de(
                    params_callouts, f"escena:{sid}"),
                ancla=PASOS_MODULOS.p7_callouts.ancla_subtitulo_de(
                    params_callouts, f"escena:{sid}", escena)) or []
        except Exception:                                     # noqa: BLE001
            trozos = []
        escenas.append({
            "id": sid,
            "t_in": round(float(escena.get("t_in") or 0.0), 3),
            "t_out": round(float(escena.get("t_out") or 0.0), 3),
            "duracion": round(float(escena.get("duracion") or 0.0), 3),
            "narracion": escena.get("narracion") or "",
            "bloque": (escena.get("origen") or {}).get("bloque") or "",
            "cartela": (escena.get("cartela") or {}).get("plantilla") or "",
            "imagen": _ruta_de_version(ctx, "assets", "escenas", f"{sid}.png"),
            # y si el dibujo que hay ya no es de lo que aqui se dice. Va vacio
            # cuando esta al dia: es una excepcion, no un campo de todos.
            **_obsolescencia(ctx, escena),
            # «Quitar esta imagen» (a qué vecinos puede ir su voz) y la voz de
            # los quitados que lleva (rama unir-planos)
            **_quitar_en_la_previa(plan, escena),
            # lo que su prompt pide dibujar, en español, y el prompt en inglés
            # (rama descripcion-planos; vacíos en una cartela)
            "descripcion": descritos.get(sid) or "",
            "prompt": " ".join(str(escena.get("prompt") or "").split()),
            # EL CUADRO YA COMPUESTO, cuando existe, y manda sobre todo lo
            # demas. `p7_callouts.previsualizar` compone lo MISMO que renderiza
            # `p8_render` --la imagen dentro del transform de camara, la capa
            # movil con ella, y el subtitulo fuera a 1:1 sobre el cuadro de
            # salida-- y sale un 1920x1080 de verdad.
            #
            # Aqui se estaban mandando por separado la imagen y `capas/{id}.svg`
            # para juntarlas en el navegador, y estaba MAL de dos formas: esa
            # capa vive en el espacio del LIENZO DE GENERACION (1536x1024) y
            # estirarla sobre un cuadro 16:9 descoloca las cartelas, y el
            # subtitulo lo dibujaba el navegador a su manera --con sus propios
            # saltos de linea-- en vez de con la fuente y el corte medidos que
            # usa el render. Dos motivos para lo mismo: lo que se aprueba tiene
            # que ser lo que se renderiza.
            "compuesto": _ruta_de_version(ctx, "callouts", "previo",
                                          f"{sid}.png"),
            # `desde`/`hasta` vienen en el reloj DEL PLANO y asi se dejan: el
            # previsualizador cuenta desde que arranca la escena, no desde que
            # arranca el video, y restar aqui obligaria a volver a sumar alli.
            "subtitulos": [
                {"lineas": _lineas_de_subtitulo(t.get("texto") or "", medir,
                                                banda),
                 "desde": round(float(t.get("desde") or 0.0), 3),
                 "hasta": round(float(t.get("hasta") or 0.0), 3)}
                for t in trozos],
        })
    render = ctx.estado.params("render") or {}
    return {
        "escenas": escenas,
        # lo apuntado como quitado que este corte aún no refleja (unir-planos)
        "quitados_sin_aplicar": _quitados_sin_aplicar(ctx, plan),
        # y lo insertado que no llegó a dibujarse (insertar-imagen)
        "insertados_sin_aplicar": _insertados_sin_aplicar(ctx, plan),
        "audio": _audio_de_la_toma(ctx),
        # LA MUSICA Y LOS EFECTOS SOLO PARA EL PLAY SEGUIDO. Escena a escena se
        # oye la VOZ y nada mas: lo que se esta juzgando ahi es si la imagen
        # cuadra con lo que se dice, y una cama de musica debajo es justo lo que
        # tapa esa pregunta.
        #
        # Dos formas, y la pantalla las distingue: una ruta del proyecto (va por
        # `/a/{pid}/...`) o una ruta de la API que empieza por `/api/`. Los
        # efectos solo existen montados: su banda la construye el render.
        "musica": _musica_de_la_previa(ctx, render),
        "efectos": _ruta_de_version(ctx, "render", "efectos.wav"),
        "resolucion": plan.get("resolucion") or [1920, 1080],
        "formato": PASOS_MODULOS.comun.formato_de_plan(plan),
        "duracion_s": round(float(plan.get("duracion_total") or 0.0), 2),
        "idioma": idioma,
        # si callouts no ha corrido todavia, se puede mirar igual: se veran las
        # imagenes con sus subtitulos y sin cartelas, y decirlo es mejor que
        # ensenar una pantalla a medias sin explicacion
        "con_cartelas": bool(ctx.proyecto.version_activa("callouts")),
        "montado": bool(_ruta_de_version(ctx, "render", "video.mp4")),
    }


# ------------------------------------------- la nota del vídeo terminado
# LO QUE SE ESCRIBE DESPUÉS DE VER EL MP4, y que hasta el 21-08 vivía en los
# params del render. Ahí costaba dinero sin dar nada: los params entran en la
# firma del paso, así que escribir «la música está alta en 0:45» dejaba el
# render entero OBSOLETO — el vídeo se pintaba naranja, como si volver a
# renderizarlo fuera a arreglar la música. Y no lo lee nadie: rehacerlo daba
# exactamente el mismo MP4.
#
# Una nota sobre lo terminado no es una entrada del paso, es un REGISTRO. Y un
# registro no vive en la firma. Aquí vive en su fichero, como el informe de las
# imágenes, que también vivía en un fichero suelto y por el mismo motivo.
#
# La nota POR PLANO se queda donde está a propósito: esa sí marca su clip para
# rehacerlo, que es lo que se quiere cuando lo que falla se arregla arriba.

FICHERO_NOTAS = "notas_del_montaje.json"


def _ruta_notas(ctx):
    return ctx.proyecto.ruta(FICHERO_NOTAS)


# =========================================================================
# EL REPASO: lo que se escribe MIRANDO el vídeo, y cómo se aplica
#
# Es el único sitio del Estudio donde se decide DESPUÉS de ver el resultado, y
# de ahí salen sus dos reglas propias:
#
#   · UNA NOTA NO TOCA NINGUNA FIRMA. Vive en `repaso.json`, que es un registro
#     y no unos params: comentar un vídeo no puede dejarlo obsoleto. Lo que sí
#     toca las firmas es APLICAR, que es un gesto aparte y con su coste delante.
#   · APLICAR AHORRA. Cada nota se reparte en cambios de un vocabulario cerrado
#     (`pasos/repaso.CAMBIOS`), y cada cambio sabe qué hay que rehacer. Bajar la
#     música es volver a mezclar el audio; sólo tocar la imagen de un plano
#     cuesta una imagen. Ver `pasos/repaso.py`.
# =========================================================================

EXT_REPASO = (".png", ".jpg", ".jpeg", ".webp")
MAX_BYTES_REPASO = 12 * 1024 * 1024


def _repaso():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, "los pasos no están cargados")
    return PASOS_MODULOS.repaso


def _cortes_del_mp4(ctx):
    """Los cortes con los que se montó el MP4 que se está viendo.

    Del PLAN y no del render: el plan es quien tiene los tiempos por plano, y el
    render los usa tal cual. Si no hay plan todavía, no hay nada que anclar y
    una nota se queda con su segundo y sin plano, que es peor pero no rompe.
    """
    try:
        plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    except Exception:  # noqa: BLE001
        return []
    # LA NARRACION VIAJA CON EL CORTE, y no es de adorno: es contra lo que se
    # comprueba que una nota siga apuntando a su plano cuando la segmentacion
    # cambia (ver `repaso.reanclar`). Sin ella, re-anclar no encontraria nada
    # y daria por descolgadas todas las notas.
    return [{"id": e.get("id"), "t_in": e.get("t_in"), "t_out": e.get("t_out"),
             "narracion": e.get("narracion") or ""}
            for e in (plan.get("escenas") or []) if e.get("id")]


def _ficha_repaso(ctx):
    repaso = _repaso()
    ficha = repaso.leer(ctx.proyecto)
    cortes = _cortes_del_mp4(ctx)
    # SE RE-ANCLAN AL LEER, no al guardar. El numero de un plano cambia cuando
    # se regraba la voz y se vuelve a segmentar, y eso pasa DESPUES de escribir
    # la nota: comprobarlo al guardar seria comprobarlo cuando todavia estaba
    # bien. Aqui se compara lo que la nota dice que habia con lo que hay.
    notas = repaso.reanclar(ficha["notas"], cortes)
    return {
        "notas": notas,
        "pendientes": len([n for n in notas
                           if n.get("estado") != "aplicado"]),
        "cortes": cortes,
        "aplicado": ficha.get("aplicado") or [],
        "catalogo": repaso.catalogo(),
    }


@app.get("/api/proyectos/{pid}/repaso")
def leer_repaso(pid: str):
    """Las notas escritas sobre el vídeo montado, con los cortes para anclarlas."""
    return _ficha_repaso(contexto(pid))


@app.post("/api/proyectos/{pid}/repaso", status_code=201)
def anadir_nota_repaso(pid: str, cuerpo: dict = Body(default=None)):
    """Una nota nueva, anclada al segundo en el que se pausó.

    El texto es obligatorio y la imagen no: una referencia visual sin una frase
    no dice qué hay que hacer con ella.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    repaso = _repaso()
    try:
        segundo = float(datos.get("t") or 0.0)
    except (TypeError, ValueError):
        raise ErrorApi(400, "hace falta 't', el segundo del vídeo")
    plano = str(datos.get("plano") or "") or repaso.plano_en(
        _cortes_del_mp4(ctx), segundo)
    imagenes = [str(i) for i in (_lista_de_textos(datos, "imagenes") or [])]
    try:
        # DE QUE PANTALLA VIENE. Imagenes y Video no comparten cuaderno: en una
        # se anota sobre el dibujo y en la otra sobre lo que se monta encima.
        # EL ANCLA: lo que se decia en ese plano cuando se escribio la nota. Es
        # lo que permite volver a encontrarlo si los planos se renumeran. Lo
        # manda la pantalla, que es quien lo tiene delante; si no llega, se saca
        # de los cortes del MP4.
        ancla = str(datos.get("ancla") or "")
        if not ancla:
            for corte in _cortes_del_mp4(ctx):
                if corte.get("id") == plano:
                    ancla = str(corte.get("narracion") or "")
                    break
        nota = repaso.anadir(ctx.proyecto, datos.get("texto"), segundo,
                             plano=plano, imagenes=imagenes,
                             pantalla=str(datos.get("pantalla") or "video"),
                             ancla=ancla)
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    ctx.bitacora.anotar("repaso_nota", "render",
                        {"id": nota["id"], "t": nota["t"], "plano": plano})
    return {"nota": nota, **_ficha_repaso(ctx)}


@app.put("/api/proyectos/{pid}/repaso/{nid}")
def editar_nota_repaso(pid: str, nid: str, cuerpo: dict = Body(default=None)):
    """Cambia el texto, el instante o las imágenes de una nota."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    repaso = _repaso()
    try:
        nota = repaso.editar(
            ctx.proyecto, nid,
            texto=datos.get("texto"),
            t=datos.get("t"),
            imagenes=(datos.get("imagenes")
                      if isinstance(datos.get("imagenes"), list) else None),
            regenerado=datos.get("regenerado"))
    except KeyError:
        raise ErrorApi(404, f"no hay ninguna nota {nid}")
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    return {"nota": nota, **_ficha_repaso(ctx)}


# ------------------------------------------- las notas de IMAGENES, en el servidor
#
# Rehacer las imagenes con nota vivia en una cola DEL NAVEGADOR que mandaba
# tandas de tres planos en un solo trabajo. Dos problemas reales (10-10-2026):
#
#   · una imagen que OpenAI rechazaba tumbaba la tanda entera -- las otras dos
#     se daban por fallidas sin haberse intentado -- y el error se quedaba como
#     el del paso, saliendo arriba en TODAS las pantallas (tambien en Encargo);
#   · recargar la pagina perdia la cola.
#
# Ahora la cola vive aqui: UN trabajo que rehace los planos UNO DETRAS DE OTRO
# (la regla 2 de la casa: las tandas, de una en una), y lo que le pasa a cada
# uno se apunta EN SU NOTA (`error`, `aviso`). Un rechazo no para a los demas.
# Las notas del MISMO plano se juntan en UNA imagen: dos notas no son dos pagos.

#: Lo que suele tardar una imagen, para decir «suele tardar ~1:20». Se afina con
#: lo que van tardando de verdad.
_SEGUNDOS_IMAGEN = [75.0]


def _segundos_por_imagen():
    ultimos = _SEGUNDOS_IMAGEN[-12:]
    return round(sorted(ultimos)[len(ultimos) // 2], 1)


#: La cola de cada video, EN EL SERVIDOR: {pid: {"cola": [nid...], "actual":
#: {"plano", "notas", "desde"} | None, "trabajo": id}}. Sobrevive a recargar la
#: pagina (no a reiniciar el servicio, y entonces no hay nada corriendo).
_COLA_NOTAS = {}
_COLA_LOCK = threading.Lock()


def _notas_de_imagenes(ctx):
    repaso = _repaso()
    return [n for n in _ficha_repaso(ctx)["notas"]
            if repaso.pantalla_de(n) == "imagenes"
            and n.get("estado") != "aplicado" and n.get("plano")]


def _texto_de_grupo(notas):
    if len(notas) == 1:
        return notas[0]["texto"]
    return " | ".join(f"({i + 1}) {n['texto']}" for i, n in enumerate(notas))


def _feedback_de_grupo(ctx, notas):
    """Lo que se escribe en `feedback` del plano para estas notas.

    Una nota: su texto, que es lo de siempre (p6 la casa con su nota del repaso
    y de ahi saca sus imagenes adjuntas). VARIAS del mismo plano: el historial
    que p6 ya entiende (`_texto_feedback` junta los textos y `_ultima_nota` lee
    la ultima entrada), y la ultima lleva las imagenes de TODAS. Con el texto
    juntado a mano, p6 no casaba ninguna nota y se quedaba con las imagenes de
    una sola.
    """
    desde_cero = any(n.get("desde_cero") for n in notas)
    if len(notas) == 1 and not desde_cero:
        return notas[0]["texto"]
    carpeta = _repaso().carpeta_imagenes(ctx.proyecto)
    imagenes = []
    for nota in notas:
        for nombre in nota.get("imagenes") or []:
            ruta = os.path.join(carpeta, os.path.basename(str(nombre)))
            if os.path.isfile(ruta) and ruta not in imagenes:
                imagenes.append(ruta)
    historial = [{"texto": n["texto"]} for n in notas[:-1]]
    ultima = {"texto": notas[-1]["texto"], "de": "repaso", "imagenes": imagenes}
    # «DESDE CERO»: p6 no le pone delante la imagen de ahora («sustituye», ver
    # `p6_assets._adjuntos_de_la_nota`). Con ella delante el generador la
    # retoca, y un cambio grande salia casi igual (10-10-2026).
    if desde_cero:
        ultima["alcance"] = "sustituye"
    historial.append(ultima)
    return historial


def _devolver_unidad(ctx, uid, previo):
    """Deja los params de un plano como estaban antes de pedirle nada."""
    try:
        params = ctx.estado.params("assets") or {}
        unidades = dict(params.get("unidades") or {})
        if previo is None:
            unidades.pop(uid, None)
        else:
            unidades[uid] = previo
        params["unidades"] = unidades
        ctx.estado.set_params("assets", params)
    except Exception as fallo:                              # noqa: BLE001
        ctx.bitacora.anotar("aviso", "assets", {"devolver_unidad": str(fallo)})


def _apartar_imagen_de_nota(ctx, plano, desde):
    """Aparta la imagen que una nota dejo en `trabajo/` sin llegar a sellar. -> ruta | None

    F5 del analisis del 13-10-2026: si la nota se cancela o falla DESPUES de
    pagar la imagen, el PNG nuevo se quedaba en `pasos/assets/trabajo/escenas/`
    y, como al sembrar lo de `trabajo/` gana, la siguiente tanda lo sellaba sin
    que nadie lo hubiera visto ni aceptado. No se borra (esta pagada): se aparta
    a `pasos/assets/_apartados/`, que no empieza por «v» y nada siembra de ahi.
    Solo lo escrito en ESTE intento (`desde`): lo que ya habia es la copia de la
    version activa, y esa no se toca.
    """
    carpeta = os.path.join(ctx.proyecto.ruta_trabajo("assets", crear=False), "escenas")
    png = os.path.join(carpeta, f"{plano}.png")
    try:
        if not os.path.isfile(png) or os.path.getmtime(png) < desde - 1:
            return None
        activa = _ruta_de_version(ctx, "assets", "escenas", f"{plano}.png")
        activa = os.path.join(ctx.proyecto.raiz, activa) if activa else ""
        if activa and os.path.isfile(activa):
            import filecmp                                  # noqa: PLC0415
            if filecmp.cmp(png, activa, shallow=False):
                return None                # la copia de la activa: nada nuevo
        marca = time.strftime("%Y%m%dT%H%M%S")
        destino = ctx.proyecto.ruta("pasos", "assets", "_apartados",
                                    f"nota_{plano}_{marca}")
        os.makedirs(destino, exist_ok=True)
        for extension in (".png", ".json"):
            origen = os.path.join(carpeta, f"{plano}{extension}")
            if os.path.isfile(origen):
                os.replace(origen, os.path.join(destino, f"{plano}{extension}"))
        return os.path.relpath(destino, ctx.proyecto.raiz)
    except OSError as fallo:
        ctx.bitacora.anotar("aviso", "assets", {"apartar_imagen_de_nota": str(fallo)})
        return None


def _siguiente_plano(ctx, cola):
    """(plano, [notas]) del primero de la cola, con TODAS sus notas en cola."""
    vivas = {n["id"]: n for n in _notas_de_imagenes(ctx)}
    cola[:] = [nid for nid in cola if nid in vivas]
    if not cola:
        return None, []
    plano = str(vivas[cola[0]]["plano"])
    notas = [vivas[nid] for nid in cola if str(vivas[nid]["plano"]) == plano]
    return plano, notas


#: Los pasos cuyos trabajos tiene que esperar la cola de notas antes de dibujar.
_PASOS_QUE_ESPERA_LA_COLA = ("voz", "assets", "callouts", "render")
#: Y los trabajos que ACABAN en esos pasos aunque empiecen por otro: la cadena
#: (`generar:`) guarda como paso el de su primera tarea (el guion, por ejemplo)
#: y llega a las imagenes y al montaje mas tarde.
_TRABAJOS_QUE_ESPERA_LA_COLA = ("generar:", "receta:", "repaso", "subtitulos", "capturas:")


def _otros_trabajos(ctx):
    """Los trabajos del video en marcha que no son la cola de notas. Sin
    cerrojo: se llama con el _COLA_LOCK tomado."""
    return [f for f in ctx.gestor.listar(activos=True)
            if f.get("nombre") != "notas_imagenes"
            and (f.get("paso") in _PASOS_QUE_ESPERA_LA_COLA
                 or str(f.get("nombre") or "").startswith(_TRABAJOS_QUE_ESPERA_LA_COLA))]


#: Lo que una tanda no puede tocar mientras la cola de notas dibuja: las
#: imagenes, y lo que se monta encima de ellas.
_PASOS_QUE_DIBUJA_O_MONTA = ("assets", "callouts", "render")


def _cola_dibujando(ctx):
    """Si la cola de notas de este video tiene su trabajo en marcha. Con el
    _COLA_LOCK tomado. La que solo ESPERA no cuenta: espera justo a que
    acaben las tandas (`_lanzar_cuando_libre`)."""
    trabajo = (_COLA_NOTAS.get(ctx.id) or {}).get("trabajo")
    if not trabajo:
        return False
    try:
        return ctx.gestor.estado(trabajo)["estado"] in ("pendiente", "ejecutando")
    except KeyError:
        return False


def _que_se_espera(otros):
    """El nombre para la persona de lo que la cola esta esperando."""
    pasos = {f.get("paso") for f in otros}
    nombres = " ".join(str(f.get("nombre") or "") for f in otros)
    if "voz" in pasos:
        return "la grabación de la voz"
    if "generar:" in nombres or "receta:" in nombres:
        return "la tanda en marcha"
    if "assets" in pasos:
        return "las imágenes en marcha"
    return "el montaje del vídeo"


def _lanzar_cola(ctx):
    """Lanza el trabajo de la cola. Con el _COLA_LOCK tomado."""
    estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
    # con el revisor detras (modos autonomo y automatico): ver el bloque REVISOR
    trabajo_id = ctx.gestor.lanzar("notas_imagenes", _correr_notas_y_revisar,
                                   ctx, paso="assets")
    estado["trabajo"] = trabajo_id
    _registrar_trabajo(trabajo_id, ctx.id)
    return trabajo_id


def _lanzar_cuando_libre(ctx):
    """Espera FUERA del gestor a que acabe el otro trabajo y lanza la cola.

    Fuera del gestor a proposito: un trabajo del gestor con paso='assets'
    marca el paso como en marcha mientras espera, y eso se cruzaria con el
    montaje que se esta esperando."""
    while True:
        time.sleep(2)
        if _otros_trabajos(ctx):
            continue
        with _COLA_LOCK:
            # se vuelve a mirar CON el cerrojo: entre mirar y lanzar puede
            # haber arrancado un montaje
            otros = _otros_trabajos(ctx)
            estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
            if otros and estado.get("cola"):
                estado["esperando"] = _que_se_espera(otros)
                continue
            estado.pop("esperando", None)
            if estado.get("cola") and not estado.get("trabajo"):
                _lanzar_cola(ctx)
            return


def _correr_notas_imagenes(avisar, ctx):
    from nucleo.trabajos import Cancelado                    # noqa: PLC0415
    repaso = _repaso()
    hechas, rechazadas, fallidas = [], [], []
    try:
        while True:
            with _COLA_LOCK:
                estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
                plano, notas = _siguiente_plano(ctx, estado["cola"])
                if not plano:
                    # en el MISMO cerrojo que mira la cola: si no, una nota que
                    # llegase justo ahora se sumaria a un trabajo que ya se va
                    estado["actual"] = None
                    estado["trabajo"] = None
                    break
                ids = [n["id"] for n in notas]
                cero = estado.get("desde_cero") or set()
                notas = [dict(n, desde_cero=n["id"] in cero) for n in notas]
                cero.difference_update(ids)
                estado["cola"] = [x for x in estado["cola"] if x not in ids]
                estado["actual"] = {"plano": plano, "notas": ids, "desde": time.time()}
                pendientes = len({str(n["plano"]) for n in _notas_de_imagenes(ctx)
                                  if n["id"] in estado["cola"]})
            hechos = len(hechas) + len(rechazadas) + len(fallidas)
            total = hechos + 1 + pendientes
            etiqueta = f"{plano} · {hechos + 1} de {total}"
            avisar(hechos / total, f"dibujando {etiqueta}", f"Dibujando {etiqueta}")
            uid = f"escena:{plano}"
            # UN PLANO QUE YA NO EXISTE no se «hace»: los planos se renumeran al
            # volver a cortar, y p6 se saltaria la unidad sin decir nada --la
            # nota saldria «Hecha ✓» sin haberse dibujado--
            if uid not in set(ctx.estado.unidades_declaradas("assets") or ()):
                for nota in notas:
                    try:
                        repaso.editar(ctx.proyecto, nota["id"], aviso="", error=(
                            f"la imagen {plano} ya no está en el vídeo (se volvieron "
                            "a cortar los planos): borra esta nota y escríbela en la "
                            "imagen que toque"))
                    except (KeyError, ValueError):
                        pass
                fallidas.append(plano)
                continue
            # SE FUSIONA con lo que ya tenia el plano (su direccion, su parrafo
            # redactado...): poner `{feedback}` a secas se los llevaba por delante
            # LA IMAGEN DE AHORA, para enseñarla al lado de la nueva
            imagen_antes = _ruta_de_version(ctx, "assets", "escenas", f"{plano}.png") or ""
            unidades_antes = dict((ctx.estado.params("assets") or {}).get("unidades") or {})
            previo = copy.deepcopy(unidades_antes.get(uid))
            actual = dict(previo or {})
            actual["feedback"] = _feedback_de_grupo(ctx, notas)
            ctx.estado.actualizar_params("assets", {"unidades": {uid: actual}})
            ctx.estado.marcar_ejecutando("assets")
            arranque = time.time()

            def avisar_plano(valor, mensaje="", publico="", hechos=hechos,
                             total=total, etiqueta=etiqueta):
                # `publico` solo llega de la espera de turno («esperando
                # turno: ... de "X"»): es lo que tiene que leer la pantalla
                return avisar((hechos + min(1.0, max(0.0, float(valor or 0)))) / total,
                              f"{etiqueta} — {mensaje}" if mensaje else "",
                              publico or "")
            # la cancelacion en el acto llega tambien a traves de este envoltorio
            avisar_plano.al_cancelar = getattr(avisar, "al_cancelar", None)
            try:
                _correr_paso(avisar_plano, ctx, "assets", [uid], {"rehacer": True})
            except Cancelado:
                _devolver_unidad(ctx, uid, previo)
                apartada = _apartar_imagen_de_nota(ctx, plano, arranque)
                if apartada:
                    for nota in notas:
                        try:
                            repaso.editar(ctx.proyecto, nota["id"], error="", aviso=(
                                "parado a mitad: la imagen nueva ya se había pagado y "
                                f"no se ha puesto; está guardada aparte en {apartada}"))
                        except (KeyError, ValueError):
                            pass
                raise
            except Exception as fallo:                           # noqa: BLE001
                ctx.estado.limpiar_marca("assets")
                # LO PEDIDO NO SE QUEDA ESCRITO si no salio: dejaria el plano
                # obsoleto y la proxima «regenerar lo obsoleto» lo volveria a
                # pedir (y a pagar, o a que lo rechacen)
                _devolver_unidad(ctx, uid, previo)
                apartada = _apartar_imagen_de_nota(ctx, plano, arranque)
                rechazo = type(fallo).__name__ == "RechazoSeguridad"
                motivo = str(fallo)
                aviso_apartada = (f"la imagen nueva ya se había pagado y no se ha "
                                  f"puesto; está guardada aparte en {apartada}"
                                  if apartada else "")
                for nota in notas:
                    try:
                        repaso.editar(ctx.proyecto, nota["id"], error=motivo,
                                      aviso=aviso_apartada)
                    except (KeyError, ValueError):
                        pass
                (rechazadas if rechazo else fallidas).append(plano)
                ctx.bitacora.anotar("nota_imagen_fallida", "assets",
                                    {"plano": plano, "rechazo": rechazo,
                                     "error": motivo[:300]})
                continue
            _SEGUNDOS_IMAGEN.append(time.time() - arranque)
            del _SEGUNDOS_IMAGEN[:-50]
            # SE BUSCA POR SU PROMPT, el que quedo en la ficha del plano: por la
            # hora se colaria la reescritura de otro video que corriera a la vez.
            # El motor se vuelve a pedir: si se recargo, el que la apunto es el
            # nuevo.
            imagen = PASOS_MODULOS.medios.motor("imagen_openai/imagen.py")
            reescrita = None
            ficha_json = os.path.join(ctx.proyecto.raiz, _ruta_de_version(
                ctx, "assets", "escenas", f"{plano}.json") or "-")
            try:
                with open(ficha_json, encoding="utf-8") as fh:
                    prompt_usado = json.load(fh).get("prompt") or ""
                reescrita = (getattr(imagen, "REESCRITURAS", {}) or {}).get(
                    imagen.huella_prompt(prompt_usado))
            except (OSError, ValueError, AttributeError):
                reescrita = None
            aviso = ""
            if reescrita and reescrita.get("salio") \
                    and float(reescrita.get("cuando") or 0) >= arranque:
                cambios = reescrita.get("cambios") or []
                lista = "; ".join(f"«{a}» → «{b}»" for a, b in cambios[:4])
                aviso = ("OpenAI la rechazó con los nombres de marca, y se dibujó "
                         "describiéndola sin ellos" + (f": {lista}" if lista else "."))
            for nota in notas:
                try:
                    repaso.editar(ctx.proyecto, nota["id"], regenerado=nota["texto"],
                                  error="", aviso=aviso, antes=imagen_antes)
                except (KeyError, ValueError):
                    pass
            hechas.append(plano)
    finally:
        with _COLA_LOCK:
            estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
            estado["actual"] = None
            estado.pop("esperando", None)
            # cortado (cancelado o un fallo del propio bucle): lo que quedaba
            # en cola no lo va a dibujar nadie, y decir «en cola» seria mentir
            if estado.get("trabajo"):
                estado["cola"] = []
            # y lo pedido «desde cero» que no se llego a dibujar no se queda
            # apuntado para un retoque de otro dia
            if not estado.get("cola"):
                estado.pop("desde_cero", None)
            estado["trabajo"] = None
    avisar(1.0, f"{len(hechas)} hechas, {len(rechazadas)} rechazadas, "
                f"{len(fallidas)} con error")
    return {"hechas": hechas, "rechazadas": rechazadas, "fallidas": fallidas}


def _usd_por_imagen(ctx):
    assets = ctx.estado.params("assets") or {}
    calidad = str(assets.get("calidad") or "low")
    try:
        # CON SU MODO: un plano de foto no cuesta lo que uno de ilustracion
        return round(float(AJUSTES.usd_por_imagen(
            calidad, modo=PASOS_MODULOS.p6_assets.modo_de(assets.get("estilo"))) or 0.0), 4)
    except Exception:                                       # noqa: BLE001
        return 0.0


def _ficha_cola(ctx):
    with _COLA_LOCK:
        estado = dict(_COLA_NOTAS.get(ctx.id) or {})
    actual = estado.get("actual")
    trabajo = None
    if estado.get("trabajo"):
        try:
            trabajo = ctx.gestor.estado(estado["trabajo"])
        except KeyError:
            trabajo = None
    return {"cola": list(estado.get("cola") or []),
            "actual": dict(actual, segundos=round(time.time() - actual["desde"], 1))
                      if actual else None,
            "trabajo": trabajo,
            # la cola espera a que termine otro trabajo (el montaje) antes de dibujar
            "esperando": estado.get("esperando") or "",
            "segundos_por_imagen": _segundos_por_imagen(),
            "usd_por_imagen": _usd_por_imagen(ctx)}


def _texto_roto_en(ctx):
    """Cuantos planos tienen el subtitulo DIBUJADO con «TÃº» (voz grabada antes
    del 10-10-2026, ver `subtitulos.reparar_mojibake`).

    Se mira lo dibujado (las capas SVG de la version activa de `callouts`) y no
    la narracion: la narracion se queda rota para siempre --entra en la firma
    de las imagenes y no se toca--, pero un plano cuyos rotulos se rehicieron
    con el codigo nuevo ya sale bien y no hay nada que arreglar."""
    version = ctx.proyecto.version_activa("callouts")
    if not version:
        return 0
    patron = PASOS_MODULOS.subtitulos._MOJIBAKE
    rotos = set()
    base = os.path.join(ctx.proyecto.raiz, "pasos", "callouts", f"v{version}")
    for carpeta in ("capas_fijas", "capas"):
        directorio = os.path.join(base, carpeta)
        if not os.path.isdir(directorio):
            continue
        for nombre in os.listdir(directorio):
            if not nombre.endswith(".svg"):
                continue
            try:
                with open(os.path.join(directorio, nombre), encoding="utf-8",
                          errors="replace") as fh:
                    texto = html_lib.unescape(fh.read())
            except OSError:
                continue
            if patron.search(texto):
                rotos.add(nombre[:-4])
    return len(rotos)


@app.get("/api/proyectos/{pid}/subtitulos/rotos")
def subtitulos_rotos(pid: str):
    """{planos}: cuantos planos tienen los subtitulos dibujados con las tildes
    rotas («TÃº»)."""
    return {"planos": _texto_roto_en(contexto(pid))}


def _correr_rehacer_subtitulos(avisar, ctx):
    """Vuelve a dibujar los rotulos y subtitulos de TODOS los planos y monta.

    No toca la voz, ni las imagenes, ni ningun param: los subtitulos salen de
    la misma narracion, pero ahora se dibujan reparados. Nada se paga: los
    rotulos y el montaje son trabajo de esta maquina.
    """
    for paso, desde, hasta in (("callouts", 0.0, 0.3), ("render", 0.3, 1.0)):
        def tramo(valor, mensaje="", publico="", desde=desde, hasta=hasta):
            return avisar(desde + (hasta - desde) * min(1.0, max(0.0, float(valor or 0))),
                          mensaje)
        ctx.estado.marcar_ejecutando(paso)
        try:
            _correr_paso(tramo, ctx, paso, None)
        except BaseException:
            ctx.estado.limpiar_marca(paso)
            raise
    avisar(1.0, "subtítulos rehechos y vídeo montado")
    return {"planos": _texto_roto_en(ctx)}


@app.post("/api/proyectos/{pid}/subtitulos/rehacer", status_code=202)
def rehacer_subtitulos(pid: str):
    """Rehace los subtitulos (y monta) de un video cuya voz llego con las
    tildes rotas. Gratis: no dibuja imagenes ni graba voz."""
    ctx = contexto(pid)
    for paso in ("voz", "assets", "callouts", "render"):
        otro = _trabajo_activo(ctx, paso)
        if otro is not None:
            raise ErrorApi(409, "este vídeo ya tiene un trabajo en marcha: espera a que termine",
                           {"trabajo_id": otro["id"]})
    trabajo_id = ctx.gestor.lanzar("subtitulos", _correr_rehacer_subtitulos, ctx,
                                   paso="callouts")
    _registrar_trabajo(trabajo_id, ctx.id)
    ctx.bitacora.anotar("subtitulos_rehechos", "callouts", {"trabajo": trabajo_id})
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id)}


# --------------------------------------------------------------- la ortografia
#
# Ver pasos/ortografia.py. Se pide y se pregunta (como «Revisar»): una revision
# de cien subtitulos tarda mas de lo que el proxy deja durar una peticion.

_ORTOGRAFIA = {}
_LOCK_ORTOGRAFIA = threading.Lock()


def _subtitulos_por_plano(pid):
    """{plano: texto del subtitulo tal y como se dibuja} (con lo corregido a mano)."""
    ficha = leer_previsualizacion(pid)
    salida = {}
    for escena in ficha.get("escenas") or []:
        texto = " ".join(" ".join(t.get("lineas") or []) for t in escena.get("subtitulos") or [])
        texto = " ".join(texto.split())
        if texto:
            salida[escena["id"]] = texto
    return salida


def _narracion_por_plano(ctx):
    """{plano: narracion} del plan de ahora: el ancla de un subtitulo corregido."""
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    return {str(e.get("id")): " ".join(str(e.get("narracion") or "").split())
            for e in plan.get("escenas") or [] if e.get("id")}


@app.post("/api/proyectos/{pid}/ortografia/revisar", status_code=202)
def revisar_ortografia(pid: str, cuerpo: dict = Body(default=None)):
    """Revisa la ortografia de {fuente: "subtitulos"} (los del video) o de
    {fuente: "guion", textos: {bloque: texto}}. -> {id}; el resultado, en GET.
    No cambia nada: propone. Lo ya revisado sale de la memoria del proyecto
    (pasos/ortografia.py) y no vuelve al CLI. Con {modo: "editorial"} (solo
    el guion) es la REVISION EDITORIAL: sintaxis y redaccion, ver
    `_revision_editorial`."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    fuente = str(datos.get("fuente") or "subtitulos")
    modo = str(datos.get("modo") or "ortografia")
    if modo not in ("ortografia", "editorial"):
        raise ErrorApi(400, "modo: «ortografia» o «editorial»")
    if modo == "editorial":
        return _revision_editorial(ctx, fuente, datos)
    if fuente == "subtitulos":
        textos = _subtitulos_por_plano(pid)
        if not textos:
            raise ErrorApi(400, "este vídeo todavía no tiene subtítulos que revisar")
    elif fuente == "guion":
        textos = datos.get("textos") if isinstance(datos.get("textos"), dict) else {}
        textos = {str(k): str(v) for k, v in textos.items() if str(v or "").strip()}
        if not textos:
            raise ErrorApi(400, "manda los textos del guion a revisar")
    else:
        raise ErrorApi(400, "fuente: «subtitulos» o «guion»")
    rid = _nueva_revision_ortografia(fuente, ctx.id)
    anclas = _narracion_por_plano(ctx) if fuente == "subtitulos" else {}
    _lanzar_ortografia(rid, textos, fuente, ctx.id, ctx.proyecto.raiz, anclas)
    return {"id": rid, "estado": "pensando", "revisados": len(textos)}


def _revision_editorial(ctx, fuente, datos):
    """LA REVISION EDITORIAL DEL GUION (arreglos del 19-10, 5): sintaxis,
    concordancia, puntuacion, repeticiones, claridad y registro, como un
    corrector editorial (`ortografia.revisar_editorial`, sonnet con esfuerzo
    medio). Propone trozos sueltos {original, propuesta, motivo}; aceptar uno
    lo pone la pantalla en el bloque por el MISMO camino que escribir a mano
    (`firma_propia`), asi que esta ruta no escribe nada. Se pregunta igual que
    la ortografia (`GET .../ortografia/{rid}`), con `fuente: "editorial"`."""
    if fuente != "guion":
        raise ErrorApi(400, "la revisión editorial es del guion: fuente «guion»")
    textos = datos.get("textos") if isinstance(datos.get("textos"), dict) else {}
    textos = {str(k): str(v) for k, v in textos.items() if str(v or "").strip()}
    if not textos:
        raise ErrorApi(400, "manda los textos del guion a revisar")
    rid = _nueva_revision_ortografia("editorial", ctx.id)
    dueno = ctx.id

    def correr():
        try:
            informe = {}
            propuestas = PASOS_MODULOS.ortografia.revisar_editorial(
                textos, cwd=RAIZ_ESTUDIO, informe=informe)
            lista = []
            for bloque in textos:              # en el orden del guion
                for n, p in enumerate(propuestas.get(bloque) or [], 1):
                    lista.append({"id": f"{bloque}#{n}", "bloque": bloque,
                                  "antes": textos[bloque], **p})
            ficha = {"estado": "listo", "fuente": "editorial", "proyecto": dueno,
                     "revisados": len(textos),
                     "sin_revisar": int(informe.get("sin_revisar") or 0),
                     "detalle": str(informe.get("detalle") or "")[:600],
                     "propuestas": lista}
        except Exception as fallo:                          # noqa: BLE001
            error = str(fallo)[:600]
            if CLI_CLAUDE.es_pasajero(fallo):
                error = ("La sesión de Claude se estaba renovando y no ha contestado. "
                         "Pulsa «Revisar otra vez» en un minuto; no se ha cambiado nada."
                         f"\n\n{error}")
            ficha = {"estado": "error", "fuente": "editorial", "proyecto": dueno,
                     "error": error}
        with _LOCK_ORTOGRAFIA:
            _ORTOGRAFIA[rid] = ficha

    threading.Thread(target=correr, daemon=True, name=f"editorial-{rid}").start()
    ctx.bitacora.anotar("revision_editorial", "guion", {"bloques": len(textos)})
    return {"id": rid, "estado": "pensando", "revisados": len(textos), "modo": "editorial"}


def _lanzar_ortografia(rid, textos, fuente, dueno, memoria, anclas=None):
    """Revisa `textos` en un hilo y deja la ficha en `_ORTOGRAFIA[rid]`. `dueno`
    es el proyecto (o «_textos» para los campos sueltos) y `memoria` la carpeta
    donde se recuerda lo revisado."""
    anclas = anclas or {}

    def correr():
        try:
            # `informe` trae cuantos textos se quedaron sin revisar porque su
            # tanda devolvio un JSON roto ni a la segunda: lo demas se
            # conserva y la pantalla lo dice (N6 de las notas de mejoras,
            # 13-10-2026)
            informe = {}
            propuestas = PASOS_MODULOS.ortografia.revisar_con_memoria(
                textos, memoria, cwd=RAIZ_ESTUDIO, informe=informe)
            ficha = {"estado": "listo", "fuente": fuente, "proyecto": dueno,
                     "revisados": len(textos), "_anclas": anclas,
                     "de_memoria": int(informe.get("de_memoria") or 0),
                     "sin_revisar": int(informe.get("sin_revisar") or 0),
                     "detalle": str(informe.get("detalle") or "")[:600],
                     "propuestas": [{"id": k, "antes": textos[k], "despues": v["texto"],
                                     "cambios": v.get("cambios") or []}
                                    for k, v in propuestas.items() if k in textos]}
        except Exception as fallo:                          # noqa: BLE001
            error = str(fallo)[:600]
            if CLI_CLAUDE.es_pasajero(fallo):
                # la sesion de Claude renovandose en otro proceso, y ya se ha
                # repetido dos veces (cli_claude): el titular es para la persona
                error = ("La sesión de Claude se estaba renovando y no ha contestado. "
                         "Pulsa «Revisar otra vez» en un minuto; no se ha cambiado nada."
                         f"\n\n{error}")
            ficha = {"estado": "error", "fuente": fuente, "proyecto": dueno,
                     "error": error}
        with _LOCK_ORTOGRAFIA:
            _ORTOGRAFIA[rid] = ficha

    threading.Thread(target=correr, daemon=True, name=f"ortografia-{rid}").start()


def _nueva_revision_ortografia(fuente, dueno):
    rid = uuid.uuid4().hex[:12]
    with _LOCK_ORTOGRAFIA:
        for viejo in list(_ORTOGRAFIA)[:-59]:
            _ORTOGRAFIA.pop(viejo, None)
        _ORTOGRAFIA[rid] = {"estado": "pensando", "fuente": fuente, "proyecto": dueno}
    return rid


#: Dueño de las revisiones de campos sueltos (no son de ningun proyecto).
_DUENO_TEXTOS = "_textos"
#: Cuantos textos (lineas) se revisan de una vez en un campo suelto.
MAX_TEXTOS_ORTOGRAFIA = 400


def _memoria_textos():
    return os.path.join(raiz_proyectos(), "_sistema", "ortografia")


@app.post("/api/ortografia/textos", status_code=202)
def revisar_ortografia_textos(cuerpo: dict = Body(default=None)):
    """Revisa la ortografia de campos sueltos que se ven o se publican: {textos:
    {campo: texto}}. -> {id}; el resultado, en GET. No cambia nada: propone, y
    quien lo pide pone lo que se acepte en su campo por su camino de siempre."""
    textos = _cuerpo(cuerpo).get("textos")
    textos = textos if isinstance(textos, dict) else {}
    # SIN RECORTAR EN SILENCIO: lo que no se revisara no puede salir como
    # «Sin faltas». Lo largo lo cuenta `revisar_con_memoria` como sin revisar.
    if len(textos) > MAX_TEXTOS_ORTOGRAFIA:
        raise ErrorApi(400, f"son {len(textos)} líneas; se revisan como mucho "
                            f"{MAX_TEXTOS_ORTOGRAFIA} de una vez")
    textos = {str(k)[:120]: str(v) for k, v in textos.items() if str(v or "").strip()}
    if not textos:
        raise ErrorApi(400, "manda {textos: {campo: texto}}")
    rid = _nueva_revision_ortografia("textos", _DUENO_TEXTOS)
    _lanzar_ortografia(rid, textos, "textos", _DUENO_TEXTOS, _memoria_textos())
    return {"id": rid, "estado": "pensando", "revisados": len(textos)}


@app.get("/api/ortografia/textos/{rid}")
def leer_ortografia_textos(rid: str):
    """Como va la revision de unos campos sueltos, y lo que propone al terminar."""
    with _LOCK_ORTOGRAFIA:
        ficha = _ORTOGRAFIA.get(rid)
    if not ficha or ficha.get("proyecto") != _DUENO_TEXTOS:
        raise ErrorApi(404, "esa revisión de ortografía ya no está: vuelve a pedirla")
    return {k: v for k, v in ficha.items() if not k.startswith("_")}


@app.post("/api/ortografia/textos/descartar")
def descartar_ortografia_textos(cuerpo: dict = Body(default=None)):
    """Lo que se deja como estaba: {rid, ids: [...]}. No se vuelve a proponer."""
    return _descartar_ortografia(_DUENO_TEXTOS, _memoria_textos(), cuerpo)


@app.get("/api/proyectos/{pid}/ortografia/{rid}")
def leer_ortografia(pid: str, rid: str):
    """Como va la revision de ortografia, y lo que propone al terminar."""
    with _LOCK_ORTOGRAFIA:
        ficha = _ORTOGRAFIA.get(rid)
    if not ficha or ficha.get("proyecto") != pid:
        raise ErrorApi(404, "esa revisión de ortografía ya no está: vuelve a pedirla")
    return {k: v for k, v in ficha.items() if not k.startswith("_")}


@app.post("/api/proyectos/{pid}/ortografia/descartar")
def descartar_ortografia(pid: str, cuerpo: dict = Body(default=None)):
    """Lo que se deja SIN marcar al aplicar: {rid, ids: [...]}. Esos textos se
    apuntan como buenos en la memoria del proyecto y no se vuelven a proponer
    mientras no cambien. No toca ningun param."""
    ctx = contexto(pid)
    return _descartar_ortografia(ctx.id, ctx.proyecto.raiz, cuerpo)


def _descartar_ortografia(dueno, memoria, cuerpo):
    datos = _cuerpo(cuerpo)
    ids = datos.get("ids")
    if not isinstance(ids, list):
        raise ErrorApi(400, "manda {rid, ids: [...]}")
    with _LOCK_ORTOGRAFIA:
        ficha = _ORTOGRAFIA.get(str(datos.get("rid") or ""))
    if not ficha or ficha.get("proyecto") != dueno or ficha.get("estado") != "listo":
        raise ErrorApi(409, "esa revisión de ortografía ya no está: vuelve a pedirla")
    antes = {str(p["id"]): p.get("antes") for p in ficha.get("propuestas") or []}
    textos = [antes[str(i)] for i in ids if antes.get(str(i))]
    PASOS_MODULOS.ortografia.descartar(memoria, textos)
    return {"descartados": len(textos)}


@app.post("/api/proyectos/{pid}/ortografia/aplicar")
def aplicar_ortografia_subtitulos(pid: str, cuerpo: dict = Body(default=None)):
    """Pone los subtitulos corregidos: {cambios: {plano: texto}}.

    Van al texto escrito a mano de cada plano (`subtitulo_texto` de callouts),
    asi que solo queda obsoleto el rotulo de esos planos: ni voz ni imagenes.
    Volver a montar es gratis."""
    ctx = contexto(pid)
    cambios = _cuerpo(cuerpo).get("cambios")
    if not isinstance(cambios, dict) or not cambios:
        raise ErrorApi(400, "manda {cambios: {plano: texto}}")
    for paso in ("callouts", "render"):
        if _trabajo_activo(ctx, paso) is not None:
            raise ErrorApi(409, "el vídeo se está montando: aplica la corrección cuando termine")
    # CON LA REVISION QUE LO PROPUSO (`rid`): solo planos de ESA revision, de
    # ESTE proyecto y de los subtitulos. Sin esto, una pantalla que se quedo con
    # la revision de otro video escribia sus textos en estos planos (los ids
    # S001, S002... se repiten en todos). Y cada texto se guarda con lo que se
    # leia al revisarlo (`subtitulo_ancla`): si luego cambia la narracion de ese
    # plano, el texto corregido se ignora en vez de mentir (subtitulos.de_escena).
    anclas = {}
    rid = _cuerpo(cuerpo).get("rid")
    if rid:
        with _LOCK_ORTOGRAFIA:
            ficha = _ORTOGRAFIA.get(str(rid))
        if not ficha or ficha.get("proyecto") != pid or ficha.get("fuente") != "subtitulos":
            raise ErrorApi(409, "esa revisión de ortografía no es de los subtítulos de este vídeo: vuelve a pedirla")
        propuestas = {str(p["id"]) for p in ficha.get("propuestas") or []}
        anclas = ficha.get("_anclas") or {}
        ajenos = sorted(str(k) for k in cambios if str(k) not in propuestas)
        if ajenos:
            raise ErrorApi(400, f"esos planos no estaban en la revisión: {', '.join(ajenos[:10])}")
    declaradas = set(ctx.estado.unidades_declaradas("callouts") or ())
    previas = (ctx.estado.params("callouts") or {}).get("unidades") or {}
    bloque = {}
    for plano, texto in cambios.items():
        uid = f"escena:{plano}"
        texto = " ".join(str(texto or "").split())
        if not texto or (declaradas and uid not in declaradas):
            continue
        actual = previas.get(uid)
        actual = dict(actual) if isinstance(actual, dict) else {}
        actual["subtitulo_texto"] = texto
        if anclas.get(str(plano)):
            actual["subtitulo_ancla"] = " ".join(anclas[str(plano)].split())
        else:
            actual.pop("subtitulo_ancla", None)
        bloque[uid] = actual
    if not bloque:
        raise ErrorApi(400, "ninguno de esos planos está en el vídeo")
    ctx.estado.actualizar_params("callouts", {"unidades": bloque})
    ctx.bitacora.anotar("ortografia_subtitulos", "callouts", {"planos": sorted(bloque)})
    return {"aplicados": len(bloque), "planos": sorted(k.split(":", 1)[-1] for k in bloque)}


@app.post("/api/proyectos/{pid}/imagenes/rehacer", status_code=202)
def rehacer_imagenes_con_notas(pid: str, cuerpo: dict = Body(default=None)):
    """Pone en la cola las notas de imagenes: {notas?: [ids], desde_cero?} (sin ids, todas).

    Con `desde_cero` la imagen se dibuja SIN la de ahora delante: para cambios
    grandes, que con ella delante salian casi iguales.

    Se rehacen UNA DETRAS DE OTRA en un solo trabajo del servidor; si ya hay uno
    en marcha, las nuevas se suman a su cola. Las notas del mismo plano salen en
    UNA sola imagen.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    pedidas = datos.get("notas") if isinstance(datos.get("notas"), list) else None
    # UNA YA HECHA SE PUEDE PEDIR OTRA VEZ «desde cero»: es justo el caso de
    # «la rehice y salio igual». Cuenta como viva aqui, pero NO se toca hasta
    # pasar las comprobaciones de abajo: devolverla a pendiente y contestar
    # despues un 409 la dejaba pendiente con su imagen ya hecha, y el
    # siguiente «Aplicar» la volvia a pagar.
    rehechas = []
    if datos.get("desde_cero") and pedidas:
        quiero = {str(x) for x in pedidas}
        rehechas = [n for n in _ficha_repaso(ctx)["notas"]
                    if n.get("id") in quiero and n.get("estado") == "aplicado"
                    and _repaso().pantalla_de(n) == "imagenes" and n.get("plano")]
    vivas = _notas_de_imagenes(ctx)
    if pedidas is not None:
        quiero = {str(x) for x in pedidas}
        vivas = [n for n in vivas if n["id"] in quiero]
    vivas += [n for n in rehechas if n["id"] not in {v["id"] for v in vivas}]
    if not vivas:
        raise ErrorApi(400, "no hay ninguna nota pendiente con su imagen")
    # ¿HAY OTRA TANDA DE IMAGENES? Si es la de esta misma cola y esta
    # terminando (ya miro que no quedaba nada), se espera a que acabe: si no,
    # en ese segundo se contestaba 409 a una nota que tenia que entrar.
    otro = _trabajo_activo(ctx, "assets")
    with _COLA_LOCK:
        propio = (_COLA_NOTAS.get(ctx.id) or {}).get("trabajo")
    if otro is not None and otro.get("nombre") == "notas_imagenes" and otro["id"] != propio:
        ctx.gestor.esperar(otro["id"], 10)
        otro = _trabajo_activo(ctx, "assets")
    # CON OTRO TRABAJO EN MARCHA (el montaje, una tanda, la musica) ya no se
    # contesta 409: la nota entra en la cola y la cola ESPERA a que termine
    # antes de dibujar (`_lanzar_cuando_libre`). Dibujar a la vez dejaria un
    # MP4 con la imagen vieja sellado como al dia, y dos tandas de imagenes a
    # la vez van contra la regla 2 de CLAUDE.md (11-10-2026).
    # ya aceptada: las hechas que se piden «desde cero» vuelven a pendiente
    for nota in rehechas:
        try:
            _repaso().editar(ctx.proyecto, nota["id"], regenerado="")
        except (KeyError, ValueError):
            pass
    repaso = _repaso()
    # lo que paso la vez anterior ya no vale para esta: se borra YA aceptada
    # (pasada la comprobacion de arriba) y ANTES de que el hilo pueda escribir
    with _COLA_LOCK:
        ocupadas = set((_COLA_NOTAS.get(ctx.id) or {}).get("cola") or []) | set(
            ((_COLA_NOTAS.get(ctx.id) or {}).get("actual") or {}).get("notas") or [])
    for nota in vivas:
        if nota.get("error") and nota["id"] not in ocupadas:
            try:
                repaso.editar(ctx.proyecto, nota["id"], error="")
            except (KeyError, ValueError):
                pass
    with _COLA_LOCK:
        estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
        en_marcha = False
        if estado.get("trabajo"):
            try:
                en_marcha = ctx.gestor.estado(estado["trabajo"])["estado"] in (
                    "pendiente", "ejecutando")
            except KeyError:
                en_marcha = False
        ya = set(estado["cola"]) | set((estado.get("actual") or {}).get("notas") or [])
        nuevas = [n for n in vivas if n["id"] not in ya]
        estado["cola"].extend(n["id"] for n in nuevas)
        # «Desde cero» (sin la imagen de ahora delante): se apunta por nota,
        # tambien en las que ya esperaban en la cola; y pedir un retoque la quita
        cero = estado.setdefault("desde_cero", set())
        pedidas_ahora = {n["id"] for n in vivas} - {
            x for x in ((estado.get("actual") or {}).get("notas") or [])}
        if datos.get("desde_cero"):
            cero.update(pedidas_ahora)
        else:
            cero.difference_update(pedidas_ahora)
        if not en_marcha:
            estado["trabajo"] = None
            otros = _otros_trabajos(ctx)
            if otros:
                # se monta (o se dibuja) otra cosa: la cola espera y arranca sola
                if not estado.get("esperando"):
                    estado["esperando"] = _que_se_espera(otros)
                    threading.Thread(target=_lanzar_cuando_libre, args=(ctx,), daemon=True,
                                     name=f"cola-espera-{ctx.id}").start()
            else:
                _lanzar_cola(ctx)
    ctx.bitacora.anotar("notas_imagenes", "assets", {"notas": [n["id"] for n in vivas]})
    return _ficha_cola(ctx)


@app.get("/api/proyectos/{pid}/imagenes/cola")
def cola_de_imagenes(pid: str):
    """La cola de notas de imagenes: cual se dibuja, cuanto lleva y que espera."""
    return _ficha_cola(contexto(pid))


@app.delete("/api/proyectos/{pid}/imagenes/cola/{nid}")
def sacar_de_la_cola(pid: str, nid: str):
    """Saca una nota de la cola (la que ya se esta dibujando no se para)."""
    ctx = contexto(pid)
    with _COLA_LOCK:
        estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
        estado["cola"] = [x for x in estado["cola"] if x != nid]
        (estado.get("desde_cero") or set()).discard(nid)
    return _ficha_cola(ctx)


# ===================================================================== REVISOR
#
# EL REVISOR DE IMAGENES (pasos/revisor_imagenes.py, 18-10-2026). Mira cada
# plano dibujado contra su trozo de guion, el estilo, el Encargo y las reglas de
# la casa, y deja una nota por plano en el repaso (pantalla «imagenes», autor
# «revisor»). Rehacerlas va por la MISMA cola de notas de arriba: el revisor no
# dibuja nada por su cuenta.
#
# Tres modos (ajuste `revisor_modo`):
#   manual      solo «Revisar imágenes»; la persona decide que se rehace.
#   autonomo    tras cada tanda, revisa lo nuevo y rehace SOLO lo grave, una
#               vuelta, dentro de los topes.
#   automatico  tras cada tanda, rehace todo lo marcado y vuelve a revisar, hasta
#               `revisor_vueltas` vueltas.
# El enganche de los dos ultimos va en `lanzar_paso` (el boton de generar las
# imagenes) y en `_correr_assets_de_tanda` (la tanda del video entero), DENTRO
# del mismo trabajo: asi nada se monta con las imagenes a medio corregir y no
# hay dos tandas de imagenes a la vez (regla 2 de CLAUDE.md).

#: {pid: trabajo_id} del «Revisar imágenes» a mano en marcha.
_REVISOR = {}
#: {pid: {"desde", "mensaje"}} mientras el revisor trabaja SOLO, al final de una
#: tanda o de la cola de notas: la pantalla lo ensena en su panel.
_REVISOR_AUTO = {}
_REVISOR_LOCK = threading.Lock()


def _revisor():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, "los pasos no están cargados")
    import importlib                                         # noqa: PLC0415
    return importlib.import_module("pasos.revisor_imagenes")


def _imagenes_de_planos(ctx, plan):
    """{plano: ruta absoluta del PNG de la version activa}, en orden de video."""
    salida = {}
    for escena in plan.get("escenas") or []:
        sid = str(escena.get("id") or "")
        relativa = _ruta_de_version(ctx, "assets", "escenas", f"{sid}.png") if sid else None
        if relativa:
            salida[sid] = os.path.join(ctx.proyecto.raiz, *relativa.split("/"))
    return salida


def _huellas_de_planos(ctx):
    """{plano: huella del PNG activo}: la foto de antes de una tanda. Vacia en
    modo manual: ahi nadie la va a mirar y leer ochenta PNG no es gratis."""
    try:
        if AJUSTES.leer().get("revisor_modo") not in ("autonomo", "automatico"):
            return {}
        plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
        revisor = _revisor()
        return {p: revisor.huella(r) for p, r in _imagenes_de_planos(ctx, plan).items()}
    except Exception:                                        # noqa: BLE001
        return {}


def _reglas_para_revisor(estilo, plan):
    """Las reglas de la casa que se le dieron al generador, en texto."""
    try:
        reglas = PASOS_MODULOS.medios.motor("reglas/reglas.py")
        p6 = PASOS_MODULOS.p6_assets
        if p6.modo_de(estilo) == "foto":
            contexto = " ".join([p6.contexto_de_reglas(estilo)] + [
                str(e.get("prompt") or "") for e in plan.get("escenas") or []])
            # con las de la ficha del negocio en su hueco (Etapa Foto C), las mismas
            # que recibió el generador (`p6_assets._prompt_completo`)
            lineas = reglas.para("prompt_imagen", modo="foto", contexto=contexto,
                                 extra=p6.dominios.reglas_de_foto(estilo))
        else:
            lineas = reglas.para("prompt_imagen")
        return "\n".join(f"  - {l}" for l in lineas)
    except Exception:                                        # noqa: BLE001
        return ""


def _revisar_y_apuntar(avisar, ctx, planos=None, forzar=False):
    """Revisa los planos sin revisar (o `planos`) y deja sus notas. -> resumen"""
    revisor = _revisor()
    p6 = PASOS_MODULOS.p6_assets
    plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    imagenes = _imagenes_de_planos(ctx, plan)
    if planos is not None:
        pedidos = {str(p) for p in planos}
        imagenes_pedidas = {p: r for p, r in imagenes.items() if p in pedidos}
        mirar = revisor.sin_revisar(ctx.proyecto, imagenes_pedidas, forzar=forzar)
    else:
        mirar = revisor.sin_revisar(ctx.proyecto, imagenes, forzar=forzar)
    if not mirar:
        return {"revisados": 0, "bien": 0, "marcadas": [], "fallos": []}
    assets = ctx.estado.params("assets") or {}
    estilo = assets.get("estilo") if isinstance(assets.get("estilo"), dict) else {}
    try:
        guia = "\n".join("  " + l for l in p6.guia_escrita(estilo))
    except Exception:                                        # noqa: BLE001
        guia = ""
    encargo = str((ctx.estado.params("guion") or {}).get("prompt_general") or "")
    veredictos = revisor.revisar(
        ctx.proyecto, plan, imagenes, mirar, estilo=estilo, encargo=encargo,
        reglas=_reglas_para_revisor(estilo, plan), guia=guia,
        formato=str(plan.get("formato") or ""),
        avisar=avisar,
        # las reglas del estilo, con su gravedad (pasos/reglas_estilo.py)
        reglas_estilo=_reglas_estilo().para_revisor(_reglas_estilo().de_estilo(estilo)),
        # las imagenes base aprobadas (tipo de relato explicito; si no, {}):
        # los planos editados desde una se comparan con ella
        bases=p6.rutas_de_bases(ctx.proyecto, assets))
    resumen = revisor.apuntar(ctx.proyecto, plan, veredictos)
    ctx.bitacora.anotar("revisor_imagenes", "assets", {
        "revisados": resumen.get("revisados"), "bien": resumen.get("bien"),
        "marcadas": [m["plano"] for m in resumen.get("marcadas") or []],
        "fallos": (resumen.get("fallos") or [])[:3]})
    return resumen


def _mi_trabajo(ctx):
    """El id del trabajo del gestor en el que corre este hilo, o None."""
    nombre = threading.current_thread().name
    if nombre.startswith("trabajo-"):
        candidato = nombre.rsplit("-", 1)[-1]
        try:
            ctx.gestor.estado(candidato)
            return candidato
        except KeyError:
            pass
    # una tarea de receta que corre a la vez que otra va en un hilo del pool,
    # sin el nombre del trabajo: es la tanda viva que dibuja imagenes
    for ficha in ctx.gestor.listar(activos=True):
        if ficha.get("nombre") in ("notas_imagenes", "revisor_imagenes"):
            continue
        if ficha.get("paso") == "assets" or "assets" in (ficha.get("toca") or ()):
            return ficha["id"]
    return None


def _rehacer_en_linea(avisar, ctx, retoque, sustituye):
    """Dibuja YA, dentro de este trabajo, esas notas (y lo que hubiera en la
    cola). Si la cola de notas esta dibujando en otro trabajo, espera a que
    acabe: dos tandas de imagenes a la vez no (regla 2)."""
    ids = list(retoque) + list(sustituye)
    if not ids:
        return {"hechas": [], "rechazadas": [], "fallidas": []}
    mio = _mi_trabajo(ctx)
    if not mio:
        # SIN TRABAJO AL QUE COLGARLO no se dibuja: la cola apuntaria «nadie
        # dibuja» y otra tanda podria arrancar a la vez (regla 2). Las notas
        # se quedan para rehacerlas a mano.
        ctx.bitacora.anotar("revisor_sin_trabajo", "assets", {"notas": ids})
        return {"hechas": [], "rechazadas": [], "fallidas": [], "sin_trabajo": True}
    while True:
        with _COLA_LOCK:
            # la cola «dibujando» con ESTE mismo trabajo (el de la cola de notas,
            # que revisa al final) no es otra tanda: es esta
            propia = (_COLA_NOTAS.get(ctx.id) or {}).get("trabajo") == mio
            if propia or not _cola_dibujando(ctx):
                estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
                ya = set(estado["cola"]) | set((estado.get("actual") or {}).get("notas") or ())
                estado["cola"].extend(i for i in ids if i not in ya)
                cero = estado.setdefault("desde_cero", set())
                cero.update(sustituye)
                cero.difference_update(retoque)
                # ESTE trabajo es ahora el de la cola: una nota que llegue
                # mientras tanto se suma aqui en vez de lanzar otra tanda
                estado["trabajo"] = mio
                estado.pop("esperando", None)
                break
        avisar(0.99, "el revisor espera a que acaben las imágenes en marcha")
        time.sleep(2)
    return _correr_notas_imagenes(avisar, ctx)


def _revisar_y_corregir(avisar, ctx, modo, ajustes, planos=None):
    """El bucle de los modos autonomo y automatico. -> informe

    autonomo: revisa, rehace lo grave, y revisa lo rehecho (una vuelta).
    automatico: lo mismo hasta `revisor_vueltas` vueltas, con todo lo marcado.
    Las imagenes por pasada y los dolares por video los limita `elegir`."""
    revisor = _revisor()
    vueltas = 1 if modo == "autonomo" else max(1, int(ajustes.get("revisor_vueltas") or 1))
    usd = _usd_por_imagen(ctx)
    cupo = max(0, int(ajustes.get("revisor_max_imagenes") or 0))
    informe = {"modo": modo, "vueltas": [], "rehechas": 0, "mandadas": 0, "porque": ""}
    # LO QUE ESTA TANDA DIBUJO, y nada mas: se mira y se rehace solo eso. Sin
    # acotar, en un video de antes del revisor (o revisado a mano) una tanda de
    # un plano revisaba los ochenta y rehacia notas que nadie habia pedido.
    objetivo = {str(p) for p in (planos or ())}
    for vuelta in range(vueltas + 1):
        # en cada vuelta se pide lo mismo; `sin_revisar` deja fuera lo que no
        # cambio desde que se miro, asi que en la segunda solo entra lo rehecho
        resumen = _revisar_y_apuntar(avisar, ctx, planos=sorted(objetivo))
        if vuelta == vueltas:
            informe["vueltas"].append({"revisados": resumen.get("revisados", 0),
                                       "marcadas": len(resumen.get("marcadas") or [])})
            break
        retoque, sustituye, porque = revisor.elegir(
            ctx.proyecto, modo, cupo - informe["mandadas"],
            float(ajustes.get("revisor_max_usd") or 0.0), usd,
            # SOLO lo que ESTA vuelta acaba de mirar y marcar: una nota vieja de
            # un plano cuya imagen nueva no se pudo revisar (cupo, tiempo) es de
            # la imagen de antes, y rehacerla seria pagar a ciegas
            planos={m["plano"] for m in resumen.get("marcadas") or []} & objetivo)
        informe["porque"] = porque
        informe["vueltas"].append({"revisados": resumen.get("revisados", 0),
                                   "marcadas": len(resumen.get("marcadas") or []),
                                   "a_rehacer": len(retoque) + len(sustituye)})
        if not retoque and not sustituye:
            break
        if not _mi_trabajo(ctx):
            # sin trabajo al que colgar el dibujo no se dibuja (ver
            # `_rehacer_en_linea`), y tampoco se apunta como intento ni gasto
            informe["porque"] = "no se pudo colgar del trabajo: quedan como nota"
            ctx.bitacora.anotar("revisor_sin_trabajo", "assets",
                                {"notas": retoque + sustituye})
            break
        # EL TOPE CUENTA LO MANDADO, no lo que salio: un redibujo que falla
        # tambien pudo cobrarse, y las notas de una persona que se dibujen en la
        # misma cola no son del revisor
        informe["mandadas"] += revisor.contar_intento(ctx.proyecto, retoque + sustituye, usd)
        avisar(0.99, f"el revisor rehace {len(retoque) + len(sustituye)} imágenes",
               "Corrigiendo las imágenes")
        hecho = _rehacer_en_linea(avisar, ctx, retoque, sustituye)
        if hecho.get("sin_trabajo"):
            informe["porque"] = "no se pudo colgar del trabajo: quedan como nota"
            break
        informe["rehechas"] += len(hecho.get("hechas") or [])
    ctx.bitacora.anotar("revisor_corrige", "assets", informe)
    return informe


def _revisor_tras_tanda(avisar, ctx, antes):
    """El enganche de despues de una tanda de imagenes. `antes` son las huellas
    de los planos antes de dibujar: se revisa SOLO lo que cambio. Nunca tumba la
    tanda: un fallo del revisor se apunta y la tanda sigue."""
    try:
        ajustes = AJUSTES.leer()
        modo = ajustes.get("revisor_modo")
        if modo not in ("autonomo", "automatico"):
            return None
        despues = _huellas_de_planos(ctx)
        cambiados = [p for p, h in despues.items() if h and antes.get(p) != h]
        if not cambiados:
            return None
        # CON UN «Revisar imágenes» A MANO EN MARCHA no se revisa otra vez lo
        # mismo a la vez: se pagaria dos veces la lectura y las dos escribirian
        # las mismas copias. Lo de esta tanda queda sin revisar y lo coge el
        # siguiente «Revisar imágenes».
        with _REVISOR_LOCK:
            manual = _REVISOR.get(ctx.id)
        if manual:
            try:
                if ctx.gestor.estado(manual)["estado"] in ("pendiente", "ejecutando"):
                    return None
            except KeyError:
                pass

        def tramo(valor, mensaje="", publico=""):
            if mensaje:
                with _REVISOR_LOCK:
                    if ctx.id in _REVISOR_AUTO:
                        _REVISOR_AUTO[ctx.id]["mensaje"] = str(mensaje)[:200]
            return avisar(0.99, mensaje, publico)
        with _REVISOR_LOCK:
            _REVISOR_AUTO[ctx.id] = {"desde": time.time(), "modo": modo,
                                     "planos": len(cambiados), "mensaje": "",
                                     "trabajo": _mi_trabajo(ctx)}
        try:
            return _revisar_y_corregir(tramo, ctx, modo, ajustes, planos=cambiados)
        finally:
            with _REVISOR_LOCK:
                _REVISOR_AUTO.pop(ctx.id, None)
    except _Cancelado:
        raise
    except Exception as fallo:                               # noqa: BLE001
        ctx.bitacora.anotar("revisor_fallo", "assets", {"error": str(fallo)[:400]})
        return None


def _correr_notas_y_revisar(avisar, ctx):
    """El trabajo de la cola de notas, con el revisor detras.

    Lo que acaba de dibujar la cola (las notas de una persona, o «Rehacer las
    marcadas») lo mira el revisor si su modo no es «manual»: es justo el caso de
    «la rehice y sigue mal». Mientras revisa, ESTE trabajo sigue siendo el de la
    cola: una nota que llegue entra aqui y se dibuja al final, en vez de lanzar
    otra tanda a la vez (regla 2). Los redibujos del propio revisor no pasan por
    aqui (`_rehacer_en_linea` llama a `_correr_notas_imagenes`), asi que no se
    revisa a si mismo en bucle."""
    if AJUSTES.leer().get("revisor_modo") not in ("autonomo", "automatico"):
        return _correr_notas_imagenes(avisar, ctx)
    antes = _huellas_de_planos(ctx)
    resultado = _correr_notas_imagenes(avisar, ctx)
    mio = _mi_trabajo(ctx)
    if not mio:
        return resultado
    # YA, antes de mirar que cambio: la pantalla pregunta en cuanto la cola se
    # vacia, y tiene que saber que el revisor viene detras
    with _REVISOR_LOCK:
        _REVISOR_AUTO[ctx.id] = {"desde": time.time(), "modo": AJUSTES.leer().get("revisor_modo"),
                                 "planos": 0, "mensaje": "comprobando qué imágenes cambiaron",
                                 "trabajo": mio}
    try:
        while True:
            with _COLA_LOCK:
                _COLA_NOTAS.setdefault(ctx.id, {"cola": []})["trabajo"] = mio
            informe = _revisor_tras_tanda(avisar, ctx, antes)
            if informe and isinstance(resultado, dict):
                resultado = dict(resultado, revisor=informe)
            with _COLA_LOCK:
                estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
                if not estado.get("cola"):
                    break
            # llegaron notas mientras revisaba: se dibujan, y se revisa eso
            antes = _huellas_de_planos(ctx)
            _correr_notas_imagenes(avisar, ctx)
    finally:
        with _REVISOR_LOCK:
            _REVISOR_AUTO.pop(ctx.id, None)
        with _COLA_LOCK:
            estado = _COLA_NOTAS.setdefault(ctx.id, {"cola": []})
            if estado.get("trabajo") == mio:
                estado["trabajo"] = None
    return resultado


def _correr_assets_y_revisar(avisar, ctx, paso_id, unidades, opciones=None):
    """`_correr_paso` de las imagenes desde su boton, con el revisor detras."""
    antes = _huellas_de_planos(ctx)
    resultado = _correr_paso(avisar, ctx, paso_id, unidades, opciones)
    informe = _revisor_tras_tanda(avisar, ctx, antes)
    if informe and isinstance(resultado, dict):
        resultado = dict(resultado, revisor=informe)
    return resultado


def _correr_revisor_a_mano(avisar, ctx, planos, forzar):
    try:
        resumen = _revisar_y_apuntar(avisar, ctx, planos=planos, forzar=forzar)
    finally:
        with _REVISOR_LOCK:
            _REVISOR.pop(ctx.id, None)
    avisar(1.0, f"{resumen.get('revisados', 0)} revisadas, "
                f"{len(resumen.get('marcadas') or [])} con nota",
           "Imágenes revisadas")
    return resumen


@app.post("/api/proyectos/{pid}/imagenes/revisar", status_code=202)
def revisar_imagenes(pid: str, cuerpo: dict = Body(default=None)):
    """Revisa las imagenes: {planos?: [ids], forzar?}. Sin planos, las que no se
    han revisado con su imagen de ahora; con `forzar`, otra vez aunque ya se
    hayan mirado. Deja una nota por plano a corregir; NO rehace nada (eso es
    `/imagenes/revision/aplicar`). -> {trabajo_id, trabajo}"""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    planos = datos.get("planos")
    if planos is not None and not (isinstance(planos, list)
                                   and all(isinstance(p, str) for p in planos)):
        raise ErrorApi(400, "'planos' es una lista de ids de plano (p. ej. [\"S001\"])")
    otro = _trabajo_que_toca(ctx, "assets")
    if otro is not None:
        raise ErrorApi(409, "se están dibujando imágenes: revísalas cuando terminen",
                       {"trabajo_id": otro["id"]})
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    if not _imagenes_de_planos(ctx, plan):
        raise ErrorApi(400, "este vídeo todavía no tiene imágenes que revisar")
    with _REVISOR_LOCK:
        previo = _REVISOR.get(ctx.id)
        if previo:
            try:
                vivo = ctx.gestor.estado(previo)["estado"] in ("pendiente", "ejecutando")
            except KeyError:
                vivo = False
            if vivo:
                raise ErrorApi(409, "ya se están revisando las imágenes de este vídeo",
                               {"trabajo_id": previo})
        trabajo_id = ctx.gestor.lanzar("revisor_imagenes", _correr_revisor_a_mano, ctx,
                                       planos, bool(datos.get("forzar")))
        _REVISOR[ctx.id] = trabajo_id
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id)}


@app.get("/api/proyectos/{pid}/imagenes/revision")
def revision_de_imagenes(pid: str):
    """La ultima revision, las notas del revisor sin aplicar, lo que falta por
    mirar, el modo y lo que costaria rehacer las marcadas."""
    ctx = contexto(pid)
    revisor = _revisor()
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    ficha = revisor.resumen(ctx.proyecto, _imagenes_de_planos(ctx, plan))
    with _REVISOR_LOCK:
        trabajo = _REVISOR.get(ctx.id)
    try:
        ficha["trabajo"] = ctx.gestor.estado(trabajo) if trabajo else None
    except KeyError:
        ficha["trabajo"] = None
    ajustes = AJUSTES.leer()
    with _REVISOR_LOCK:
        auto = dict(_REVISOR_AUTO.get(ctx.id) or {})
    ficha["automatico"] = (dict(auto, segundos=round(time.time() - auto["desde"], 1))
                           if auto else None)
    ficha.update({"modo": ajustes["revisor_modo"],
                  "max_imagenes": ajustes["revisor_max_imagenes"],
                  "max_usd": ajustes["revisor_max_usd"],
                  "vueltas": ajustes["revisor_vueltas"],
                  "usd_por_imagen": _usd_por_imagen(ctx)})
    return ficha


@app.post("/api/proyectos/{pid}/imagenes/revision/aplicar", status_code=202)
def aplicar_revision_de_imagenes(pid: str, cuerpo: dict = Body(default=None)):
    """Rehace las notas pendientes del revisor ({notas?: [ids]}; sin ids, todas)
    por la cola de notas: las de retoque con la imagen de ahora delante y las
    que piden otra imagen, desde cero. -> la cola"""
    ctx = contexto(pid)
    pedidas = _cuerpo(cuerpo).get("notas")
    pendientes = _revisor().resumen(ctx.proyecto)["pendientes"]
    if isinstance(pedidas, list):
        quiero = {str(x) for x in pedidas}
        pendientes = [p for p in pendientes if p["nota"] in quiero]
    if not pendientes:
        raise ErrorApi(400, "el revisor no tiene ninguna nota pendiente")
    retoque = [p["nota"] for p in pendientes if p["alcance"] != "sustituye"]
    sustituye = [p["nota"] for p in pendientes if p["alcance"] == "sustituye"]
    ficha = None
    if retoque:
        ficha = rehacer_imagenes_con_notas(pid, {"notas": retoque})
    if sustituye:
        ficha = rehacer_imagenes_con_notas(pid, {"notas": sustituye, "desde_cero": True})
    return ficha


@app.post("/api/proyectos/{pid}/imagenes/revision/descartar")
def descartar_revision_de_imagen(pid: str, cuerpo: dict = Body(default=None)):
    """«Esta imagen está bien así»: {plano}. Quita la nota pendiente del revisor
    de ese plano y no la vuelve a marcar mientras la imagen no cambie."""
    ctx = contexto(pid)
    plano = str(_cuerpo(cuerpo).get("plano") or "").strip()
    if not plano:
        raise ErrorApi(400, "manda {plano}")
    quitada = _revisor().descartar(ctx.proyecto, plano)
    return {"plano": plano, "quitada": quitada, **_revisor().resumen(ctx.proyecto)}


@app.post("/api/proyectos/{pid}/repaso/{nid}/sin-marcas")
def nota_sin_marcas(pid: str, nid: str):
    """Propone la nota reescrita sin marcas ni personajes: NO la guarda."""
    ctx = contexto(pid)
    nota = next((n for n in _repaso().leer(ctx.proyecto)["notas"]
                 if n.get("id") == nid), None)
    if nota is None:
        raise ErrorApi(404, f"no hay ninguna nota {nid}")
    propuesta = PASOS_MODULOS.sin_marcas.reescribir_nota(
        nota.get("texto"), cwd=ctx.proyecto.raiz)
    return {"nota": nid, **propuesta,
            "con_imagenes": bool(nota.get("imagenes"))}


@app.delete("/api/proyectos/{pid}/repaso/{nid}")
def borrar_nota_repaso(pid: str, nid: str):
    """Quita una nota del repaso."""
    ctx = contexto(pid)
    try:
        _repaso().borrar(ctx.proyecto, nid)
    except KeyError:
        raise ErrorApi(404, f"no hay ninguna nota {nid}")
    return _ficha_repaso(ctx)


@app.post("/api/proyectos/{pid}/repaso/imagenes", status_code=201)
async def subir_imagenes_repaso(pid: str, peticion: Request):
    """Las imágenes de referencia que acompañan a una nota.

    Van a la carpeta del PROYECTO y no a un buzón: una nota del repaso pertenece
    a este vídeo y tiene que seguir ahí cuando se abra mañana.
    """
    ctx = await _en_hilo(contexto, pid)
    tipo = (peticion.headers.get("content-type") or "").lower()
    if not tipo.startswith("multipart/"):
        raise ErrorApi(400, "manda las imágenes como multipart")
    try:
        formulario = await peticion.form()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(400, f"multipart ilegible: {fallo}")
    carpeta = await _en_hilo(lambda: _repaso().carpeta_imagenes(ctx.proyecto, crear=True))
    guardadas, avisos = [], []
    for _clave, valor in formulario.multi_items():
        if not hasattr(valor, "read"):
            continue
        origen = os.path.basename(str(getattr(valor, "filename", "") or ""))
        extension = os.path.splitext(origen)[1].lower()
        if extension not in EXT_REPASO:
            avisos.append(f"«{origen or 'sin nombre'}» no es una imagen "
                          f"({', '.join(EXT_REPASO)})")
            continue
        # UNA NOTA LLEVA COMO MUCHO `repaso.MAX_IMAGENES` (R3 del analisis del
        # 13-10-2026): lo que pase de ahi la nota lo tiraria igual, y sin tope
        # una sola peticion podia llenar el disco del proyecto.
        if len(guardadas) >= _repaso().MAX_IMAGENES:
            avisos.append(f"«{origen}» no se ha subido: una nota lleva como "
                          f"mucho {_repaso().MAX_IMAGENES} imágenes")
            continue
        contenido = await valor.read()
        if len(contenido) > MAX_BYTES_REPASO:
            avisos.append(f"«{origen}» pesa "
                          f"{len(contenido) / 1024 / 1024:.1f} MB y el tope son "
                          f"{MAX_BYTES_REPASO // 1024 // 1024}")
            continue
        # LA MISMA REVISION QUE LAS REFERENCIAS DEL ESTILO (M4): una imagen rota
        # se aceptaba y el agente del repaso se encontraba con ella al aplicar
        motivo = await _en_hilo(_motivo_para_no_aceptar, contenido, origen, False)
        if motivo:
            avisos.append(motivo)
            continue
        nombre = f"{uuid.uuid4().hex[:12]}{extension}"
        await _en_hilo(_escribir_bytes, os.path.join(carpeta, nombre), contenido)
        guardadas.append({"nombre": nombre, "origen": origen,
                          "bytes": len(contenido)})
    if not guardadas and avisos:
        raise ErrorApi(400, "no se ha podido guardar ninguna: " + "; ".join(avisos))
    return {"imagenes": guardadas, "avisos": avisos}


@app.get("/api/proyectos/{pid}/repaso/imagenes/{nombre}")
def servir_imagen_repaso(pid: str, nombre: str, peticion: Request):
    """Una imagen de referencia de una nota."""
    ctx = contexto(pid)
    carpeta = _repaso().carpeta_imagenes(ctx.proyecto)
    # `ruta_contenida` LANZA al salirse (no devuelve False): con `..` esto era un
    # 500 con traza en vez de un 404. Y `isfile`, no `exists`: con `.` la ruta
    # es la propia carpeta, que existe pero no se puede servir.
    try:
        ruta = ruta_contenida(carpeta, os.path.basename(nombre))
    except ValueError:
        raise ErrorApi(404, f"esa imagen no está: {nombre}")
    if not os.path.isfile(ruta):
        raise ErrorApi(404, f"esa imagen no está: {nombre}")
    return servir_fichero(peticion, ruta)


#: EL MODO CON EL QUE SE REGENERA TRAS UN REPASO, y no es «todo» ni
#: «pendientes»: es un tercer camino y hace falta que lo sea.
#:
#:   todo         rehace de cero y REPLANTEA. Con esto, aplicar una nota sobre
#:                un plano volvería a pagar las ochenta imágenes del vídeo.
#:   pendientes   se SALTA lo que está al día, y eso también está mal aquí: el
#:                corte se da por al día en cuanto existe un plan, así que tras
#:                reescribir un bloque no se volvería a cortar.
#:   sucio        corre TODAS las tareas que los cambios han ensuciado, y cada
#:                una sobre sus unidades sucias. Ni salta ni rehace de más.
#:
#: Funciona sin código nuevo porque las dos ramas de arriba comparan por
#: igualdad: `_correr_receta` sólo salta con 'pendientes' y `_un_paso` sólo
#: fuerza `rehacer` con 'todo'.
MODO_TRAS_REPASO = "sucio"


def _correr_repaso(avisar, ctx, ajuste, modo=MODO_TRAS_REPASO,
                   sin_montar=False):
    """Reparte las notas en cambios, los aplica y vuelve a generar lo justo.

    Los tres pasos van juntos en UN trabajo a propósito: desde el navegador es
    un botón, y encadenar tres llamadas se rompe al recargar -- justo en un
    flujo pensado para dejarlo generando y volver luego.
    """
    repaso = _repaso()
    # SOLO LAS DEL REPASO DEL VIDEO. Las de Imagenes se accionan una a una en su
    # pantalla y no pasan por aqui: contarlas aqui las daria por aplicadas sin
    # que nadie las hubiera aplicado.
    notas = repaso.pendientes(ctx.proyecto, pantalla="video")
    if not notas:
        avisar(1.0, "no hay notas pendientes")
        return {"notas": [], "tareas": [], "resumen": "no hay notas pendientes"}

    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = {e.get("id"): e for e in (plan.get("escenas") or [])}
    orden = [e.get("id") for e in (plan.get("escenas") or [])]
    guion = (PASOS_MODULOS.comun.leer_salida(
        ctx.proyecto, "guion", "guion.json", obligatorio=False) or {})
    bloques = guion.get("guion") or []
    por_bloque = {b.get("id"): b for b in bloques}
    # LOS SUBTITULOS QUE YA SE CORRIGIERON A MANO, para que el enrutador lea lo
    # que se ve AHORA. Sin esto, una segunda vuelta de notas leería el subtítulo
    # de antes de la primera corrección.
    puestos = {}
    for uid, bloque in ((ctx.estado.params("callouts") or {}).get("unidades")
                        or {}).items():
        if isinstance(bloque, dict) and bloque.get("subtitulo_texto"):
            puestos[str(uid).split(":", 1)[-1]] = bloque["subtitulo_texto"]
    contextos = {n["id"]: repaso.contexto_de_nota(
        n, escenas, por_bloque, orden, _carpeta_de_escenas(ctx),
        textos_subtitulo=puestos)
        for n in notas}
    carpeta = repaso.carpeta_imagenes(ctx.proyecto)
    rutas = {nombre: os.path.join(carpeta, nombre)
             for nota in notas for nombre in (nota.get("imagenes") or [])}

    reproductor = PASOS_MODULOS.p8_render.reproductor(ctx.proyecto)
    avisar(0.05, f"repartiendo {len(notas)} nota(s) del repaso")
    reparto = repaso.enrutar(
        [dict(n) for n in notas], contextos, bloques,
        titulo=guion.get("titulo") or ctx.proyecto.id,
        duracion=float(reproductor.get("duracion") or 0.0),
        estado=PASOS_MODULOS.sonido.describir(ctx.estado.params("render") or {}),
        ajuste=ajuste, avisar=lambda v, m="": avisar(0.05 + 0.15 * float(v or 0), m),
        proyecto_id=ctx.id, rutas_imagenes=rutas,
        # CADA PANTALLA ARREGLA LO SUYO, y el repaso del video arregla lo que se
        # MONTA ENCIMA del plano y lo que se OYE: cartela, subtitulo,
        # transicion, musica y efectos. Los otros tres ambitos tienen su sitio
        # y se vetan aqui:
        #
        #   imagen      -> la pantalla de Imagenes, plano a plano
        #   guion, voz  -> la pantalla de Guion, que es donde se reescribe
        #
        # Se veta al VALIDAR y no en el prompt: pedirselo al agente es pedirlo.
        # Y la nota no se pierde, vuelve como aviso diciendo donde se arregla.
        ambitos_vetados=("imagen", "guion", "voz"))

    resumen = repaso.resumen_de(reparto)
    avisos = list(reparto.get("avisos") or [])
    aplicados = _aplicar_cambios_del_repaso(ctx, reparto, avisos)
    tareas = resumen["tareas"]
    ctx.bitacora.anotar("repaso_aplicado", "render", {
        "notas": len(notas), "cambios": len(reparto.get("cambios") or []),
        "tareas": tareas, "por_ambito": resumen["por_ambito"]})

    if tareas:
        avisar(0.22, f"volviendo a generar: {', '.join(tareas)}")
        # ¿HACE FALTA DIBUJAR ALGO, O SOLO VOLVER A MEZCLAR? Si todas las
        # notas son de música o de efectos, no cambia un solo fotograma: se
        # remonta el MP4 sobre los clips que ya hay. La promesa estaba escrita
        # en `AMBITOS["musica"]["cuesta"]` desde el primer día y no se cumplía:
        # pedir «baja la música» redibujaba los 98 planos en Edge.
        solo_montar = repaso.solo_mezcla(
            [c for n in (reparto.get("notas") or [])
             for c in (n.get("cambios") or [])])
        # APLICAR NO ES MONTAR, y desde las diapositivas son dos gestos.
        #
        # Aplicando desde ahi se redibuja lo que las notas tocan --el plano, su
        # capa, la cartela-- y se PARA: lo que se acaba de arreglar se mira en
        # las diapositivas, que es donde se escribio la nota. Montar el MP4 es
        # lo que se hace despues, con el boton de la pantalla del video, y es
        # el paso caro en tiempo de maquina.
        #
        # Solo se quita la tarea del MP4: `banda_sonora` y `efectos` viven en
        # la misma pestaña pero son PREPARACION --traen material al banco-- y
        # dejarlas fuera obligaria a pagar esa espera al montar.
        if sin_montar:
            tareas = [x for x in tareas if x != "render"]
        if tareas:
            _regenerar_tras_repaso(avisar, ctx, tareas, modo, solo_montar)

    # las notas aplicadas se marcan DESPUÉS de generar: si la tanda se cae, las
    # notas siguen pendientes y volver a darle al botón las vuelve a intentar
    aplicadas = {n["id"] for n in reparto.get("notas") or [] if n.get("cambios")}
    with repaso.CERROJO:                    # ver `repaso.CERROJO`
        ficha = repaso.leer(ctx.proyecto)
        for nota in ficha["notas"]:
            if nota.get("id") in aplicadas:
                nota["estado"] = "aplicado"
                nota["aplicado_en"] = ahora()
        ficha.setdefault("aplicado", []).append({
            "cuando": ahora(), "notas": sorted(aplicadas), "tareas": tareas,
            "por_ambito": resumen["por_ambito"]})
        repaso.guardar(ctx.proyecto, ficha)

    frase = (f"{len(aplicadas)} de {len(notas)} notas aplicadas · "
             + (resumen["frase"] or "sin cambios"))
    avisar(1.0, frase)
    return {"notas": reparto.get("notas"), "tareas": tareas,
            "por_ambito": resumen["por_ambito"], "aplicados": aplicados,
            "avisos": avisos, "resumen": frase}


def _regenerar_tras_repaso(avisar, ctx, tareas, modo, solo_montar=False):
    """Corre SOLO las tareas que los cambios han ensuciado, en su orden.

    Se agrupan por pestaña y se corre cada pestaña con su receta recortada a lo
    que hay que rehacer, que es exactamente lo que ya sabe hacer `_correr_receta`.

    Y con `solo_montar`, el MP4 se REMONTA en vez de renderizarse: ni un plano
    se vuelve a dibujar. Es lo que hace que «baja la música» cueste segundos y
    no el render entero. Ver `repaso.solo_mezcla`.
    """
    recetas = _recetas()
    por_pestana = {}
    for tarea in tareas:
        ficha = recetas.TAREAS_POR_ID.get(tarea)
        if ficha:
            por_pestana.setdefault(ficha["pestana"], []).append(tarea)
    pestanas = [p for p in recetas.PESTANAS if p in por_pestana]
    for indice, pestana in enumerate(pestanas):
        base = 0.25 + 0.7 * indice / max(1, len(pestanas))
        techo = 0.25 + 0.7 * (indice + 1) / max(1, len(pestanas))
        receta = _receta_de_video(ctx, pestana)

        def avisar_pestana(v, m="", p="", _b=base, _t=techo):
            return avisar(_b + (_t - _b) * float(v or 0), m, p)
        # CANCELAR EN EL ACTO también a través de este envoltorio: sin el
        # atributo, «Parar» un montaje esperaba a que ffmpeg acabara (19-10)
        avisar_pestana.al_cancelar = getattr(avisar, "al_cancelar", None)
        _correr_receta(avisar_pestana, ctx, pestana, receta, por_pestana[pestana], modo,
                       solo_montar)


def _aplicar_cambios_del_repaso(ctx, reparto, avisos):
    """Escribe en params lo que dicen los cambios. -> [descripciones]

    Cada tipo se escribe en SU cajón, y el cajón es el mismo que usa la pantalla
    para lo mismo: el feedback de un plano va al feedback de esa unidad, el
    texto de un bloque a `params.guion.bloques`, la música a los params del
    render. Ni un cajón nuevo -- un segundo camino para lo mismo se queda viejo.
    """
    hechos = []
    unidades_assets, params_callouts, unidades_callouts = {}, {}, {}
    params_render, params_guion, params_brief = {}, {}, {}
    for cambio in (reparto.get("cambios") or []):
        tipo = cambio["tipo"]
        if tipo == "feedback_plano":
            uid = f"escena:{cambio['plano']}"
            unidades_assets.setdefault(uid, {}).setdefault("feedback_nuevo", [])                 .append({"texto": cambio["texto"],
                          "alcance": cambio.get("alcance") or "sustituye",
                          "imagenes": list(cambio.get("imagenes") or [])})
        elif tipo == "feedback_asset":
            uid = f"asset:{cambio['asset']}"
            unidades_assets.setdefault(uid, {}).setdefault("feedback_nuevo", [])                 .append({"texto": cambio["texto"],
                          "imagenes": list(cambio.get("imagenes") or [])})
        elif tipo == "cartela_texto":
            uid = f"escena:{cambio['plano']}"
            unidades_assets.setdefault(uid, {})["cartela_campos"] =                 cambio["campos_cartela"]
        elif tipo == "quitar_cartela":
            uid = f"escena:{cambio['plano']}"
            unidades_assets.setdefault(uid, {})["quitar_cartela"] = True
        elif tipo == "subtitulo_tam":
            params_callouts["subtitulo_tam"] = cambio["valor"]
        elif tipo == "grafismo":
            params_callouts["diseno"] = cambio["valor"]
        elif tipo == "subtitulo_texto":
            # POR UNIDAD, como el resto de decisiones de un plano: corregir lo
            # escrito en S072 deja obsoleto S072 y ninguno más. Lo lee
            # `p7_callouts.texto_subtitulo_de`, que es lo que hace que esto no
            # sea un cajón muerto.
            unidades_callouts[f"escena:{cambio['plano']}"] = cambio["texto"]
        elif tipo == "transicion_duracion":
            params_render["duracion_transicion"] = float(cambio["valor"])
        elif tipo == "transiciones":
            params_render["transiciones"] = list(cambio["lista"])
        elif tipo == "musica_db":
            params_render["musica_db"] = float(cambio["valor"])
        elif tipo == "efectos_db":
            params_render["efectos_db"] = float(cambio["valor"])
        elif tipo == "sin_musica":
            params_render["musica"] = {}
        elif tipo == "otra_musica":
            params_render["musica"] = {}
        elif tipo == "sin_efectos":
            params_render["efectos"] = {}
        elif tipo == "otros_efectos":
            params_render["efectos"] = {}
        elif tipo == "bloque_texto":
            params_guion.setdefault("bloques", {})[cambio["bloque"]] =                 cambio["texto"]
        elif tipo == "velocidad":
            params_brief["velocidad"] = float(cambio["valor"])
        elif tipo == "anotar":
            avisos.append(f"queda por decidir a mano: {cambio['texto']}")
            continue
        hechos.append(f"{tipo}: " + ", ".join(
            f"{k}={v}" for k, v in cambio.items()
            # las rutas de las imágenes no entran en el resumen: es una línea
            # para leer, y una ruta absoluta por nota la deja ilegible
            if k not in ("tipo", "ambito", "rehacer", "imagenes")))

    if unidades_assets:
        # LO QUE NO SE PUDO ESCRIBIR SALE DE `hechos`. Un resumen que dice
        # «cambiado el texto de la cartela de S099» cuando ese plano no lleva
        # ninguna es la misma clase de mentira que una nota marcada como
        # aplicada sin aplicar.
        fallidos = _escribir_unidades_del_repaso(ctx, unidades_assets, avisos)
        for uid in fallidos:
            plano = uid.split(":", 1)[-1]
            hechos = [h for h in hechos
                      if not (h.startswith("cartela_texto:") and plano in h)]
    if unidades_callouts:
        # Fusionando lo que ya hubiera en esa unidad, igual que en assets:
        # `actualizar_params` sustituye el diccionario de la unidad ENTERO, así
        # que escribir sólo el subtítulo borraría sus zonas a evitar y su
        # `sin_callout`.
        previas = (ctx.estado.params("callouts") or {}).get("unidades") or {}
        # LA NARRACION DE AHORA DE CADA PLANO, que es su ancla (28-10): si
        # después cambia lo que dice ese plano --se quita la imagen de al lado
        # y se lleva su voz, o se inserta una dentro--, lo escrito a mano se
        # deja de usar en vez de repetir o perder palabras (ver de_escena)
        try:
            dichas = {f"escena:{e.get('id')}": " ".join(str(e.get("narracion") or "").split())
                      for e in (PASOS_MODULOS.p6_assets.plan_actual(
                          ctx.proyecto, "assets", estado=ctx.estado) or {}).get("escenas") or []}
        except Exception:                                   # noqa: BLE001
            dichas = {}
        bloque = {}
        for uid, texto in unidades_callouts.items():
            actual = previas.get(uid)
            actual = dict(actual) if isinstance(actual, dict) else {}
            actual["subtitulo_texto"] = texto
            # escrito a mano contra la narracion de AHORA: el ancla de una
            # corrección de ortografía anterior ya no vale (ver de_escena)
            if dichas.get(uid):
                actual["subtitulo_ancla"] = dichas[uid]
            else:
                actual.pop("subtitulo_ancla", None)
            bloque[uid] = actual
        params_callouts["unidades"] = bloque
    if params_callouts:
        ctx.estado.actualizar_params("callouts", params_callouts)
    if params_render:
        ctx.estado.actualizar_params("render", params_render)
    if params_guion:
        actuales = ctx.estado.params("guion") or {}
        if "bloques" in params_guion:
            fusion = dict(actuales.get("bloques") or {})
            fusion.update(params_guion["bloques"])
            params_guion["bloques"] = fusion
        ctx.estado.actualizar_params("guion", params_guion)
    if params_brief:
        ctx.estado.actualizar_params("brief", params_brief)
    return hechos


def _escribir_unidades_del_repaso(ctx, cambios, avisos=None):
    """Fusiona lo que toca a cada unidad, sin llevarse por delante lo que había.

    `actualizar_params` sustituye el diccionario de la unidad ENTERO, así que
    escribir sólo el feedback borraría la cartela de ese plano y su dirección.
    Es la misma trampa que ya costó una ronda con las cartelas y con la
    dirección, y no da ningún error: la nota deja de estar.
    """
    previos = (ctx.estado.params("assets") or {}).get("unidades") or {}
    bloque, fallidos = {}, []
    for uid, pedido in cambios.items():
        actual = previos.get(uid)
        actual = dict(actual) if isinstance(actual, dict) else {}
        for nota in (pedido.get("feedback_nuevo") or []):
            historial = actual.get("feedback")
            historial = list(historial) if isinstance(historial, list) else []
            historial.append({
                "id": f"F{len(historial) + 1:03d}", "fecha": ahora(),
                "texto": nota["texto"], "modo": "directo", "trazos": 0,
                "zonas": "", "de": "repaso",
                # QUE CLASE DE CORRECCION ES, y con qué se acompaña. Lo lee
                # `p6_assets._referencias_escena` para decidir si al generador
                # se le adjunta la imagen rechazada. Ver `repaso.ALCANCES`.
                **({"alcance": nota["alcance"]} if nota.get("alcance") else {}),
                **({"imagenes": list(nota["imagenes"])}
                   if nota.get("imagenes") else {})})
            actual["feedback"] = historial
        sin_cartela = False
        if pedido.get("cartela_campos"):
            # SOLO SI ESE PLANO YA ES UNA CARTELA. Escribir `datos` sobre un
            # plano que no la lleva crearía una cartela SIN PLANTILLA, y
            # `cartelas._desmontar` la rellenaría con el EJEMPLO de la de por
            # defecto: un plano del vídeo diciendo el texto de muestra. Cambiar
            # lo que dice una cartela y crear una son dos cosas.
            cartela = actual.get("cartela")
            if isinstance(cartela, dict) and cartela.get("plantilla"):
                cartela = dict(cartela)
                datos = dict(cartela.get("datos") or {})
                datos.update({k: v for k, v in pedido["cartela_campos"].items()
                              if isinstance(k, str)})
                cartela["datos"] = datos
                actual["cartela"] = cartela
            else:
                sin_cartela = True
        if pedido.get("quitar_cartela"):
            actual.pop("cartela", None)
        bloque[uid] = actual
        if sin_cartela:
            fallidos.append(uid)
            if isinstance(avisos, list):
                avisos.append(f"{uid}: se pidió cambiar el texto de su cartela y "
                              f"ese plano no lleva ninguna, así que no se ha "
                              f"tocado")
    ctx.estado.actualizar_params("assets", {"unidades": bloque})
    return fallidos


@app.post("/api/proyectos/{pid}/repaso/aplicar", status_code=202)
def aplicar_repaso(pid: str, cuerpo: dict = Body(default=None)):
    """Aplica las notas del repaso y vuelve a generar SOLO lo que cambian.

    Un botón y un trabajo: reparte las notas en cambios, los escribe en su cajón
    y corre las tareas que han quedado sucias, en orden de pipeline. Una nota
    sobre la música vuelve a mezclar el audio; ninguna imagen se repaga si nada
    lo pide.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    por_fase = CLI_CLAUDE.por_defecto_de("repaso")
    ajuste = _ajuste_cli(datos, por_fase["modelo"], por_fase["esfuerzo"])
    modo = str(datos.get("modo") or MODO_TRAS_REPASO)
    # `sin_montar`: aplica y para antes del MP4. Lo pide la pantalla de las
    # diapositivas, donde lo que se quiere es MIRAR lo arreglado; la del video
    # no lo manda, porque alli aplicar y montar son el mismo gesto.
    sin_montar = bool(datos.get("sin_montar"))
    # NI DOS A LA VEZ NI ENCIMA DE OTRA COSA (D8 del analisis del 13-10-2026):
    # dos clics lanzaban dos repasos que montaban a la vez sobre la misma
    # carpeta `trabajo/`, y tambien con la tanda del video corriendo. Mirar y
    # lanzar van con los mismos cerrojos que `/generar`, y el trabajo declara
    # los pasos que puede tocar para que los demas lo vean (`_trabajo_que_toca`).
    todos = [p["id"] for p in PASOS]
    with _cerrojo_de_cadena(ctx.id):
        otro = _trabajo_de_cadena(ctx) or _trabajo_que_toca(ctx, todos)
        if otro is not None:
            raise ErrorApi(409, f"«{otro.get('nombre')}» está corriendo en este "
                                "vídeo: espera a que termine para aplicar las notas",
                           {"trabajo_id": otro["id"], "progreso": otro["progreso"]})
        with _COLA_LOCK:
            if _cola_dibujando(ctx):
                raise ErrorApi(409, "se están rehaciendo imágenes con tus notas: "
                                    "espera a que terminen (o páralas) y vuelve a "
                                    "aplicar")
            trabajo_id = ctx.gestor.lanzar("repaso", _correr_repaso, ctx, ajuste, modo,
                                           sin_montar, paso="render", toca=todos)
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "ajuste": ajuste,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@app.get("/api/proyectos/{pid}/montaje/notas")
def leer_notas_montaje(pid: str):
    """Lo escrito sobre el vídeo terminado. No toca ninguna firma."""
    ctx = contexto(pid)
    ficha = leer_json(_ruta_notas(ctx), {}) or {}
    return {"nota": str(ficha.get("nota") or ""), "cuando": ficha.get("cuando")}


@app.put("/api/proyectos/{pid}/montaje/notas")
def guardar_notas_montaje(pid: str, cuerpo: dict = Body(default=None)):
    """Guarda la nota del vídeo entero. Autoguardado, como todo lo demás."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    nota = str(datos.get("nota") or "").strip()
    ruta = _ruta_notas(ctx)
    ficha = {"nota": nota, "cuando": time.strftime("%Y-%m-%dT%H:%M:%S")}
    temporal = ruta + ".parcial"
    with open(temporal, "w", encoding="utf-8") as fh:
        json.dump(ficha, fh, ensure_ascii=False, indent=1)
    os.replace(temporal, ruta)
    ctx.bitacora.anotar("nota_montaje", "render", {"letras": len(nota)})
    # se devuelve el estado para que la pantalla vea que NO se ha movido: el
    # vídeo sigue al día por mucho que se escriba encima
    return {"guardado": True, "estado": ctx.estado.estado_de("render"), **ficha}


# ------------------------------------------------------------- transiciones
# El catalogo de shaders de hyperframes, elegido MIRANDOLO: la pantalla corre el
# mismo GLSL que el render, asi que la muestra no puede ensenar otra cosa.

@app.get("/api/proyectos/{pid}/transiciones")
def leer_transiciones(pid: str):
    """Las transiciones que existen, con su GLSL, y cuales entran en este video."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    trans = PASOS_MODULOS.transiciones
    render = ctx.estado.params("render") or {}
    elegidas = render.get("transiciones") or []
    ficha = trans.catalogo_para_pantalla(elegidas or None)
    ficha["duracion"] = render.get(
        "duracion_transicion", PASOS_MODULOS.p8_render.PARAMS_POR_DEFECTO["duracion_transicion"])
    ficha["todas_de_fabrica"] = not elegidas
    # Los tres colores de acento con los que se pintan, para que la muestra de
    # la pantalla salga del color de ESTE video y no de un naranja de catalogo.
    ficha["acento"] = trans.acentos(_paleta_del_video(ctx))
    # QUE TRANSICION LLEVA CADA PLANO, resuelta por el motor.
    #
    # El plan solo trae la RANURA (suave / acento), que es una decision del
    # corte; cual la ocupa lo decide `transiciones.resolver` con la semilla del
    # video, y es determinista. Viaja hasta la pantalla para que el repaso del
    # montaje pueda correr EL MISMO shader que el render en cada corte, en vez
    # de la aproximacion CSS que enseniaba antes (un destello y un encadenado).
    # Sin esto, el repaso tendria que adivinar cual toca -- y adivinaria mal en
    # cuanto cambiara la paleta elegida.
    #
    # Va el reparto y no el GLSL de cada plano: el frag de cada transicion ya
    # viaja UNA vez en el catalogo, y repetirlo por plano serian doscientas
    # copias del mismo texto.
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = plan.get("escenas") or []
    reparto = trans.resolver(escenas, render, semilla=(plan.get("semilla") or 0),
                             montaje=PASOS_MODULOS.camara.normalizar_montaje(
                                 (ctx.estado.params("callouts") or {}).get("montaje")))
    ficha["reparto"] = {sid: {k: v for k, v in corte.items() if k != "shader"}
                        for sid, corte in reparto.items()}
    return ficha


# ------------------------------------------------------- música y efectos
# Dos momentos separados a propósito (ver pasos/sonido.py): aquí se BUSCA y se
# ELIGE, con la red delante; renderizar no sale a la red, coge del banco lo que
# digan los params. Una búsqueda en una API devuelve cosas distintas cada
# semana, y el mismo plan tiene que dar el mismo vídeo.

def _sonido():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.sonido


@app.get("/api/proyectos/{pid}/sonido")
def leer_sonido(pid: str):
    """Qué suena en este vídeo: el tema puesto, los efectos surtidos y el catálogo."""
    ctx = contexto(pid)
    sonido = _sonido()
    render = ctx.estado.params("render") or {}
    crudo = render.get("efectos") or {}
    hay_jamendo, hay_freesound = sonido.hay_claves()
    # CADA EFECTO, CON SU MUESTRA Y SU VETO. La pantalla tiene que poder oír lo
    # que acaba de sonar y ponerle la ✕ ahí mismo: un veto que hay que escribir
    # en otra pantalla es un veto que no se pone. Ver `sonido.vetar`.
    prohibidos = sonido.vetados()
    surtido = {}
    for papel, fichas in crudo.items():
        lista = [{
            **(f if isinstance(f, dict) else {}),
            "clave": sonido.clave_de(f),
            "vetado": sonido.clave_de(f) in prohibidos,
            "muestra": f"/api/efectos/{sonido._nombre_de(f)}",
            # cuánto de su energía está por encima de 4 kHz. Ordena la lista para
            # encontrar «ese que suena como un láser» sin escuchar los doce: un
            # láser es filo y un aire es cuerpo. No decide, ordena.
            "agudo": sonido.agudeza(f),
        } for f in (fichas or []) if isinstance(f, dict)]
        surtido[papel] = sorted(lista, key=lambda x: -(x.get("agudo") or 0))
    return {
        "activo": render.get("sonido", True),
        "musica": render.get("musica") or {},
        "efectos_volumen": _volumen_de_efectos(render.get("efectos_db")),
        "efectos": surtido,
        "efectos_fijos": list(render.get("efectos_fijos") or []),
        # LOS VETADOS DEL CANAL. Viajan a la pantalla para poder pintar la ✕ ya
        # marcada en el efecto que se veto: si no, la lista enseñaria un sonido
        # con aspecto de estar puesto que en el vídeo no suena.
        "vetados": [prohibidos[k] for k in sorted(prohibidos)],
        # `surtidos` cuenta los que DE VERDAD pueden sonar: un papel con seis
        # efectos de los que cinco están vetados no tiene seis, tiene uno.
        "papeles": [{"id": k, **{c: v[c] for c in
                                 ("nombre", "descripcion", "cuantos")},
                     "surtidos": sum(1 for f in (surtido.get(k) or [])
                                     if not f.get("vetado")),
                     "vetados": sum(1 for f in (surtido.get(k) or [])
                                    if f.get("vetado"))}
                    for k, v in sonido.PAPELES.items()],
        "animos": sorted(sonido.ANIMOS),
        "nombres_animos": sonido.NOMBRES_ANIMOS,
        "hay_jamendo": hay_jamendo,
        "hay_freesound": hay_freesound,
        "lufs": render.get("musica_lufs", sonido.MUSICA_LUFS),
        # EL VOLUMEN FINO, en dB sobre la presencia (N9 de las notas de
        # mejoras, 13-10-2026): el deslizador de la pantalla lo lee de aquí.
        "musica_db": _musica_db_de(render),
        "resumen": sonido.describir(render),
        # los créditos, en una lista lista para pegar en la descripción: los
        # temas son de Jamendo y varios piden atribución
        "creditos": [{"titulo": t.get("titulo"), "artista": t.get("artista"),
                      "licencia": t.get("licencia")}
                     for t in (render.get("musica") or {}).get("tramos") or []],
    }


@app.post("/api/proyectos/{pid}/sonido/musica")
def buscar_musica(pid: str, cuerpo: dict = Body(default=None)):
    """Temas de Jamendo que pegan con el tono. Devuelve candidatos, no elige."""
    ctx = contexto(pid)
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    try:
        temas = sonido.buscar_musica(
            animo=str(datos.get("animo") or ("" if datos.get("texto") else "sobrio")),
            duracion_s=float(plan.get("duracion_total") or 0),
            velocidad=str(datos.get("velocidad") or "low"),
            extra=str(datos.get("extra") or "")[:80],
            texto=str(datos.get("texto") or "")[:80],
            pagina=int(datos.get("pagina") or 0),
            instrumental=datos.get("instrumental") is not False,
            cuantas=int(datos.get("cuantas") or 12))
    except Exception as fallo:
        # una API caída no puede tumbar la pantalla: se dice y se sigue
        raise ErrorApi(502, f"no se ha podido buscar música: {fallo}")
    for tema in temas:
        tema.update(licencia_de_tema(tema.get("licencia")))
    return {"temas": temas, "duracion_video": plan.get("duracion_total")}


@app.post("/api/musica/buscar")
def buscar_musica_suelta(cuerpo: dict = Body(default=None)):
    """Temas de Jamendo por animo, sin video: el borrador de un video nuevo."""
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    try:
        temas = sonido.buscar_musica(
            animo=str(datos.get("animo") or ("" if datos.get("texto") else "sobrio")),
            duracion_s=0,
            velocidad=str(datos.get("velocidad") or "low"),
            extra=str(datos.get("extra") or "")[:80],
            texto=str(datos.get("texto") or "")[:80],
            pagina=int(datos.get("pagina") or 0),
            instrumental=datos.get("instrumental") is not False,
            cuantas=max(1, min(20, int(datos.get("cuantas") or 10))))
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(502, f"no se ha podido buscar música: {fallo}")
    for tema in temas:
        tema.update(licencia_de_tema(tema.get("licencia")))
    return {"temas": temas}


def licencia_de_tema(url):
    """Lo que dice la licencia Creative Commons de un tema, en claro. -> dict

    Los videos de este estudio son, muchas veces, para un CLIENTE: un tema
    «NC» (no comercial) no se puede usar ahi sin comprar la licencia en
    Jamendo. Se lee de la URL de la licencia (`.../licenses/by-nc-sa/3.0/`).
    """
    texto = str(url or "").lower()
    encaje = re.search(r"/licenses/([a-z-]+)/", texto)
    clave = encaje.group(1) if encaje else ""
    partes = clave.split("-") if clave else []
    return {"licencia_nombre": ("CC " + " ".join(p.upper() for p in partes)) if partes else "sin datos",
            "comercial": bool(partes) and "nc" not in partes,
            "atribucion": "by" in partes}


def _ficha_de_audio_valida(ficha, fuentes, hosts):
    """Lo que manda la pantalla de un tema o un efecto, comprobado: su id hace
    de nombre de fichero en el banco y su `descarga` es a donde se sale a
    pedirlo (con la clave de FreeSound, si es de alli)."""
    from urllib.parse import urlparse                       # noqa: PLC0415
    if ficha.get("fuente") not in fuentes:
        raise ErrorApi(400, f"fuente desconocida: {ficha.get('fuente')!r}")
    if not re.match(r"^[A-Za-z0-9_-]{1,64}$", str(ficha.get("id") or "")):
        raise ErrorApi(400, "id de audio no válido")
    url = str(ficha.get("descarga") or "")
    if url:
        destino = urlparse(url)
        host = (destino.hostname or "").lower()
        if destino.scheme != "https" or not any(host == h or host.endswith("." + h)
                                                for h in hosts):
            raise ErrorApi(400, "esa descarga no es de donde dice")


@app.put("/api/proyectos/{pid}/sonido")
def guardar_sonido(pid: str, cuerpo: dict = Body(default=None)):
    """Fija el tema (bajándolo al banco), el interruptor o el nivel de música."""
    ctx = contexto(pid)
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    cambios = {}
    if "activo" in datos:
        cambios["sonido"] = bool(datos["activo"])
    if isinstance(datos.get("lufs"), (int, float)):
        cambios["musica_lufs"] = max(-40.0, min(-10.0, float(datos["lufs"])))
    # EL VOLUMEN FINO DE LA MÚSICA, en dB (N9 de las notas de mejoras,
    # 13-10-2026). `musica_db` y no `lufs`: el `lufs` solo mueve el tema suelto
    # y la música automática (la cama) lo ignora, y `musica_db` va en la misma
    # suma que la presencia en las dos (`sonido.filtro_de_mezcla`). Es el mismo
    # mando que el repaso («la música está alta») y con su mismo margen. Lo que
    # ya suena no se escribe (regla 1): la firma del render no se mueve.
    db_igual = False
    if isinstance(datos.get("musica_db"), (int, float)) \
            and not isinstance(datos.get("musica_db"), bool):
        pedido = round(max(-12.0, min(6.0, float(datos["musica_db"]))), 1)
        if pedido == _musica_db_de(ctx.estado.params("render") or {}):
            db_igual = True
        else:
            cambios["musica_db"] = pedido
    if db_igual and not cambios and "musica" not in datos and "activo" not in datos:
        return {"guardado": [], "cambiado": False, "trabajo_id": None,
                "estado": ctx.estado.estado_de("render")}
    if "musica" in datos:
        ficha = datos["musica"] or {}
        if not isinstance(ficha, dict):       # R7: un texto aqui era un 500
            raise ErrorApi(400, "'musica' tiene que ser la ficha de un tema (o null)")
        if not ficha:
            cambios["musica"] = {}
        else:
            propio = ficha.get("fuente") == "propia"
            _ficha_de_audio_valida(ficha, ("jamendo", "propia"), ("jamendo.com",))
            if not ficha.get("id") or not (ficha.get("descarga") or propio):
                raise ErrorApi(400, "el tema tiene que traer 'id' y 'descarga'")
            if propio and not os.path.isfile(sonido.banco("musica", sonido._nombre_de(ficha))):
                raise ErrorApi(400, "ese audio tuyo ya no está: vuelve a subirlo")
            # Se BAJA aquí, al elegirlo, y no al renderizar: el render no sale a
            # la red, y enterarse de que el enlace ya no vale cuando llevas
            # veinte minutos de clips es la versión cara del mismo error.
            # SIN LA CLAVE DE JAMENDO: una ficha que la pantalla tenia de antes
            # puede traerla en sus enlaces, y aqui se guardaria en el proyecto
            ficha = dict(ficha)
            for campo in ("escucha", "descarga"):
                if ficha.get(campo):
                    ficha[campo] = sonido.url_sin_clave(ficha[campo])
            try:
                sonido.traer(ficha, "musica")
            except Exception as fallo:
                # sin el texto de la excepcion: lleva la URL de la descarga
                raise ErrorApi(502, f"no se ha podido bajar el tema "
                                    f"({type(fallo).__name__})")
            cambios["musica"] = ficha
    if not cambios:
        raise ErrorApi(400, "hace falta 'musica', 'activo', 'lufs' o 'musica_db'")
    al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
    ctx.estado.actualizar_params("render", cambios)
    # ELEGIR OTRO TEMA solo vuelve a mezclar el audio, si el video estaba
    # montado y al dia. Con `musica: {}` (volver a la automatica) no: hay que
    # montar la banda otra vez, y eso lo hace el boton de montar.
    trabajo_id = None
    if datos.get("remontar") and cambios.get("musica"):
        trabajo_id = _remontar_si_estaba_al_dia(ctx, al_dia, montado,
                                                "volver a mezclar la música")
    elif datos.get("remontar") and "musica" in cambios and al_dia and montado:
        # VOLVER A LA AUTOMATICA: hay que montar la banda otra vez (la elige el
        # ritmo) y despues mezclar. Sigue sin dibujar nada.
        trabajo_id = ctx.gestor.lanzar("musica automatica", _correr_rehacer_montaje,
                                       ctx, ["banda_sonora", "render"], True,
                                       paso="render")
        _registrar_trabajo(trabajo_id, ctx.id)
    elif datos.get("remontar") and "musica" not in cambios \
            and ("musica_db" in cambios or "musica_lufs" in cambios):
        # SUBIR O BAJAR LA MÚSICA: lo mismo que la presencia, solo mezclar
        # (N9 de las notas de mejoras, 13-10-2026)
        trabajo_id = _remontar_si_estaba_al_dia(ctx, al_dia, montado,
                                                "volver a mezclar la música")
    ctx.bitacora.anotar("sonido", "render", {
        "musica": (cambios.get("musica") or {}).get("titulo"),
        "activo": cambios.get("sonido"), "musica_db": cambios.get("musica_db")})
    if trabajo_id is None:
        _apuntar_montaje_pendiente(ctx)
    return {"guardado": list(cambios), "cambiado": True,
            "estado": ctx.estado.estado_de("render"),
            "trabajo_id": trabajo_id, "montado": montado}


def _musica_db_de(render):
    """El volumen fino de la música guardado en el render, en dB (0 si no hay)."""
    try:
        return round(float((render or {}).get("musica_db") or 0.0), 1)
    except (TypeError, ValueError):
        return 0.0


def _antes_de_cambiar_el_montaje(ctx):
    """(al_dia, montado) del render ANTES de tocar sus params. 409 si se monta.

    Se mira antes porque escribir un param del render lo deja «obsoleto»: si se
    mirara despues, nunca estaria al dia y nunca se podria solo remezclar.
    """
    if _trabajo_activo(ctx, "render") is not None:
        raise ErrorApi(409, "el vídeo se está montando ahora: cámbialo cuando termine")
    return (ctx.estado.estado_de("render") == "listo",
            bool(_ruta_de_version(ctx, "render", "video.mp4")))


def _remontar_si_estaba_al_dia(ctx, al_dia, montado, nombre):
    """Vuelve a MONTAR el MP4 sobre los clips que hay (`solo_montar`). -> trabajo|None

    Solo si el montaje estaba al dia: con planos pendientes, montar sobre los
    clips viejos sellaria como hechos unos clips que no lo estan. Entonces el
    cambio queda guardado y se aplica al montar el video.
    """
    if not (al_dia and montado):
        return None
    return lanzar_paso(ctx, "render", None, nombre=nombre,
                       opciones={"solo_montar": True})


# ----------------------------------- los cambios del montaje SIN APLICAR (19-10)
# En el Encargo se tocan varias cosas seguidas (la música, su volumen, el logo,
# los subtítulos) y montar con CADA una dejaba la siguiente en 409 («el vídeo
# se está montando ahora») y el resultado dependía del orden. Ahí se guardan
# con `remontar: false` y se aplican todas a la vez con «Aplicar y volver a
# montar» (`POST /montaje/aplicar`): un solo trabajo, y si lo pendiente es solo
# la mezcla, una mezcla (segundos), no un render.
#
# La marca vive en `proyecto.json` (config), FUERA de los params: no entra en
# ninguna firma. Dice para qué versión del render se apuntó --un montaje
# posterior la deja sin valor-- y si hace falta mezclar aunque el estado diga
# «al día» (un efecto vetado no toca ningún param).

CONFIG_MONTAJE_PENDIENTE = "montaje_pendiente"

#: Las claves del render que solo cambian la MEZCLA o el muxeado final (lo que
#: `p8_render.ejecutar(solo_montar=True)` vuelve a hacer sobre los clips que
#: hay): la música, los efectos, sus volúmenes y el logo. Ninguna cambia un
#: fotograma de un clip.
CLAVES_DE_MEZCLA = frozenset({
    "sonido", "musica", "musica_lufs", "musica_db", "musica_presencia",
    "efectos", "efectos_fijos", "efectos_db", "logo"})


def _remontar_pedido(datos, defecto=True):
    """El `remontar` de un cuerpo (o de la consulta): False solo si se pide."""
    valor = (datos or {}).get("remontar", defecto)
    if isinstance(valor, str):
        return valor.strip().lower() not in ("0", "false", "no", "")
    return bool(valor)


def _apuntar_montaje_pendiente(ctx, mezcla=False):
    """Apunta que hay cambios del montaje guardados sin montar (si hay MP4)."""
    if getattr(ctx, "proyecto", None) is None or not _ruta_de_version(ctx, "render", "video.mp4"):
        return
    version = ctx.proyecto.version_activa("render")
    marca = dict(ctx.proyecto.config.get(CONFIG_MONTAJE_PENDIENTE) or {})
    if marca.get("version") != version:
        marca = {}
    nueva = {"version": version, "mezcla": bool(marca.get("mezcla") or mezcla),
             "desde": marca.get("desde") or time.strftime("%Y-%m-%dT%H:%M:%S")}
    if nueva != marca:
        ctx.proyecto.config[CONFIG_MONTAJE_PENDIENTE] = nueva
        ctx.proyecto.guardar_config()


def _montaje_pendiente(ctx):
    """La marca de cambios sin aplicar, si sigue valiendo; si no, se borra. -> dict|None"""
    marca = ctx.proyecto.config.get(CONFIG_MONTAJE_PENDIENTE)
    if not marca:
        return None
    vale = (isinstance(marca, dict)
            and marca.get("version") == ctx.proyecto.version_activa("render")
            and bool(_ruta_de_version(ctx, "render", "video.mp4"))
            and (marca.get("mezcla")
                 or ctx.estado.estado_de("callouts") == "obsoleto"
                 or ctx.estado.estado_de("render") == "obsoleto"))
    if not vale:
        _olvidar_montaje_pendiente(ctx)
        return None
    return marca


def _olvidar_montaje_pendiente(ctx):
    if ctx.proyecto.config.pop(CONFIG_MONTAJE_PENDIENTE, None) is not None:
        ctx.proyecto.guardar_config()


def _solo_falta_mezclar(ctx):
    """Si lo único pendiente del vídeo montado es volver a MEZCLAR. -> bool

    El render está obsoleto, las capas no, y lo que cambió en sus params desde
    la versión activa son solo claves de mezcla (`CLAVES_DE_MEZCLA`); y con esas
    claves como estaban, el render estaría al día (no hay nada que venga de
    pasos anteriores). Entonces basta `solo_montar`: ni un clip.

    Para saber lo último se calcula el estado con los params de mezcla de la
    versión activa, en ESTA instancia y bajo su cerrojo, y se devuelven los de
    verdad antes de soltarlo: no se escribe nada.
    """
    estado = ctx.estado
    if not _ruta_de_version(ctx, "render", "video.mp4"):
        return False
    if estado.estado_de("render") != "obsoleto" or not estado.al_dia("callouts"):
        return False
    params = estado.params("render") or {}
    cambiadas = _params_cambiados(estado, "render", params)
    if not cambiadas or not set(cambiadas) <= CLAVES_DE_MEZCLA:
        return False
    activa = next((v for v in estado.versiones("render") if v.get("activa")), None) or {}
    antes = activa.get("params") or {}
    with estado._lock:
        datos = estado._datos("render")
        de_verdad = datos.get("params")
        supuesto = copy.deepcopy(de_verdad or {})
        for clave in cambiadas:
            if clave in antes:
                supuesto[clave] = copy.deepcopy(antes[clave])
            else:
                supuesto.pop(clave, None)
        datos["params"] = supuesto
        estado._cache = {}
        try:
            return estado.al_dia("render")
        finally:
            datos["params"] = de_verdad
            estado._cache = {}


def _vuelve_a_la_automatica(ctx):
    """Si la música pasó de un tema elegido a la automática (hay que montar la
    banda otra vez antes de mezclar)."""
    activa = next((v for v in ctx.estado.versiones("render") if v.get("activa")), None) or {}
    antes = (activa.get("params") or {}).get("musica")
    ahora = (ctx.estado.params("render") or {}).get("musica")
    # sin música en el vídeo («Qué lleva») no hay banda que montar
    return bool(antes) and not ahora and lleva_de(ctx).get("musica", True)


# ------------------------------------------------------------------- el logo

EXT_LOGO = (".png", ".jpg", ".jpeg", ".webp")
MAX_BYTES_LOGO = 5 * 1024 * 1024


def _carpeta_logo(ctx):
    return os.path.join(ctx.proyecto.raiz, PASOS_MODULOS.p8_render.CARPETA_LOGO)


def _carpeta_logos():
    """Los logos subidos ANTES de tener video (el borrador, el de un proyecto)."""
    return os.path.join(raiz_proyectos(), "_sistema", "logos")


def _ruta_logo_suelto(nombre):
    nombre = os.path.basename(str(nombre or ""))
    if not re.match(r"^logo_[0-9a-f]{10}\.(png|jpg|jpeg|webp)$", nombre):
        return None
    ruta = os.path.join(_carpeta_logos(), nombre)
    return ruta if os.path.isfile(ruta) else None


async def _leer_logo_subido(peticion):
    """(contenido, extension) del campo «logo» de un multipart, validado."""
    try:
        formulario = await peticion.form()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(400, f"multipart ilegible: {fallo}")
    fichero = formulario.get("logo")
    if not hasattr(fichero, "read"):
        raise ErrorApi(400, "manda la imagen en el campo «logo»")
    extension = os.path.splitext(str(getattr(fichero, "filename", "") or ""))[1].lower()
    if extension not in EXT_LOGO:
        raise ErrorApi(400, f"el logo tiene que ser {', '.join(EXT_LOGO)}")
    contenido = await fichero.read()
    if not contenido or len(contenido) > MAX_BYTES_LOGO:
        raise ErrorApi(400, f"el logo tiene que pesar menos de "
                            f"{MAX_BYTES_LOGO // 1024 // 1024} MB")
    # LA MISMA REVISION QUE LAS REFERENCIAS DEL ESTILO (M4, R3 del analisis del
    # 13-10-2026): un logo roto se aceptaba y el montaje reventaba al 97 %,
    # dejando un MP4 de 0 bytes
    motivo = await _en_hilo(_motivo_para_no_aceptar, contenido,
                            os.path.basename(str(getattr(fichero, "filename", "") or "logo")),
                            False)
    if motivo:
        raise ErrorApi(400, motivo)
    return contenido, extension


@app.post("/api/logos", status_code=201)
async def subir_logo_suelto(peticion: Request):
    """Guarda un logo sin video todavia: el de un borrador o el de un proyecto."""
    contenido, extension = await _leer_logo_subido(peticion)
    nombre = f"logo_{hashlib.sha1(contenido).hexdigest()[:10]}{extension}"

    def guardar():
        os.makedirs(_carpeta_logos(), exist_ok=True)
        _escribir_bytes(os.path.join(_carpeta_logos(), nombre), contenido)
    await _en_hilo(guardar)
    return {"nombre": nombre}


@app.get("/api/logos/{nombre}")
def servir_logo_suelto(nombre: str, peticion: Request):
    """Un logo subido que todavia no esta en ningun video."""
    ruta = _ruta_logo_suelto(nombre)
    if not ruta:
        raise ErrorApi(404, "ese logo no está")
    return servir_fichero(peticion, ruta)


def _poner_logo_suelto(ctx, ficha):
    """Copia un logo del buzon al video y lo deja en sus params. -> ficha"""
    ruta = _ruta_logo_suelto(ficha.get("fichero"))
    if not ruta:
        raise ErrorApi(400, "ese logo ya no está: vuelve a subirlo")
    carpeta = _carpeta_logo(ctx)
    os.makedirs(carpeta, exist_ok=True)
    nombre = os.path.basename(ruta)
    shutil.copyfile(ruta, os.path.join(carpeta, nombre))
    p8 = PASOS_MODULOS.p8_render
    limpio = {"fichero": nombre,
              "posicion": ficha.get("posicion") if ficha.get("posicion") in p8.POSICIONES_LOGO
              else "arriba_derecha"}
    for clave, bajo, alto, defecto in (("tamano", 0.04, 0.4, 0.12), ("opacidad", 0.1, 1.0, 0.9)):
        try:
            limpio[clave] = round(min(alto, max(bajo, float(ficha.get(clave, defecto)))), 3)
        except (TypeError, ValueError):
            limpio[clave] = defecto
    ctx.estado.actualizar_params("render", {"logo": limpio})
    return limpio


@app.get("/api/proyectos/{pid}/logo")
def leer_logo(pid: str):
    """El logo de este video y donde va, o null si no lleva."""
    ctx = contexto(pid)
    ficha = (ctx.estado.params("render") or {}).get("logo") or None
    if ficha and not os.path.isfile(os.path.join(_carpeta_logo(ctx),
                                                 str(ficha.get("fichero") or ""))):
        ficha = None
    return {"logo": ficha,
            "posiciones": list(PASOS_MODULOS.p8_render.POSICIONES_LOGO)}


@app.get("/api/proyectos/{pid}/logo/imagen")
def imagen_del_logo(pid: str, peticion: Request):
    ctx = contexto(pid)
    ficha = (ctx.estado.params("render") or {}).get("logo") or {}
    nombre = os.path.basename(str(ficha.get("fichero") or ""))
    ruta = os.path.join(_carpeta_logo(ctx), nombre)
    if not nombre or not os.path.isfile(ruta):
        raise ErrorApi(404, "este vídeo no lleva logo")
    return servir_fichero(peticion, ruta)


@app.post("/api/proyectos/{pid}/logo")
async def subir_logo(pid: str, peticion: Request):
    """Sube el logo (PNG con transparencia, mejor) y lo pone arriba a la derecha.

    Cambiarlo, moverlo o quitarlo SOLO vuelve a montar el MP4 (`poner_logo`):
    ni una imagen ni un clip.
    """
    ctx = await _en_hilo(contexto, pid)
    # la MISMA lectura que el logo suelto: eran dos copias, y solo una revisaba
    contenido, extension = await _leer_logo_subido(peticion)
    remontar = _remontar_pedido(dict(peticion.query_params))
    return await _en_hilo(_poner_logo_subido, ctx, contenido, extension, remontar)


def _poner_logo_subido(ctx, contenido, extension, remontar=True):
    """Lo de `subir_logo` que toca disco y estado, fuera del bucle de eventos."""
    carpeta = _carpeta_logo(ctx)
    os.makedirs(carpeta, exist_ok=True)
    # nombre nuevo cada vez: es lo que hace que la firma cambie al cambiar de logo
    nombre = f"logo_{hashlib.sha1(contenido).hexdigest()[:10]}{extension}"
    _escribir_bytes(os.path.join(carpeta, nombre), contenido)
    al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
    ficha = dict((ctx.estado.params("render") or {}).get("logo") or {})
    ficha.update({"fichero": nombre})
    ficha.setdefault("posicion", "arriba_derecha")
    ficha.setdefault("tamano", 0.12)
    ficha.setdefault("opacidad", 0.9)
    ctx.estado.actualizar_params("render", {"logo": ficha})
    trabajo_id = _remontar_si_estaba_al_dia(ctx, al_dia and remontar, montado, "poner el logo")
    if trabajo_id is None:
        _apuntar_montaje_pendiente(ctx)
    return {"logo": ficha, "trabajo_id": trabajo_id, "montado": montado}


@app.put("/api/proyectos/{pid}/logo")
def colocar_logo(pid: str, cuerpo: dict = Body(default=None)):
    """Donde va y como: {posicion?, tamano? (0,04-0,4), opacidad?} o {quitar: true}."""
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    p8 = PASOS_MODULOS.p8_render
    actual = dict((ctx.estado.params("render") or {}).get("logo") or {})
    # `remontar: false` (el Encargo): se guarda y se aplica con los demás
    # cambios del montaje, en un solo montaje (`POST /montaje/aplicar`)
    remontar = _remontar_pedido(datos)

    def remontado(al_dia, montado, nombre):
        trabajo_id = _remontar_si_estaba_al_dia(ctx, al_dia and remontar, montado, nombre)
        if trabajo_id is None:
            _apuntar_montaje_pendiente(ctx)
        return trabajo_id
    if datos.get("usar"):
        # el logo del proyecto (o cualquiera del buzon), puesto en este video
        al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
        ficha = dict(datos["usar"]) if isinstance(datos["usar"], dict) else {"fichero": datos["usar"]}
        nuevo = _poner_logo_suelto(ctx, ficha)
        return {"logo": nuevo, "montado": montado,
                "trabajo_id": remontado(al_dia, montado, "poner el logo")}
    if datos.get("quitar"):
        if not actual:
            return {"logo": None, "trabajo_id": None}
        al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
        # se QUITA la clave, no se deja vacia: un video que nunca tuvo logo
        # vuelve a tener exactamente los params de antes
        params = copy.deepcopy(ctx.estado.params("render") or {})
        params.pop("logo", None)
        ctx.estado.set_params("render", params)
        return {"logo": None, "montado": montado,
                "trabajo_id": remontado(al_dia, montado, "quitar el logo")}
    if not actual.get("fichero"):
        raise ErrorApi(409, "primero sube el logo")
    nuevo = dict(actual)
    if "posicion" in datos:
        if datos["posicion"] not in p8.POSICIONES_LOGO:
            raise ErrorApi(400, "posicion: " + ", ".join(p8.POSICIONES_LOGO))
        nuevo["posicion"] = datos["posicion"]
    for clave, bajo, alto in (("tamano", 0.04, 0.4), ("opacidad", 0.1, 1.0)):
        if clave in datos:
            try:
                nuevo[clave] = round(min(alto, max(bajo, float(datos[clave]))), 3)
            except (TypeError, ValueError):
                raise ErrorApi(400, f"'{clave}' tiene que ser un número")
    if nuevo == actual:
        return {"logo": actual, "trabajo_id": None}
    al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
    ctx.estado.actualizar_params("render", {"logo": nuevo})
    return {"logo": nuevo, "montado": montado,
            "trabajo_id": remontado(al_dia, montado, "mover el logo")}


# --------------------------------------------------------- los subtitulos

#: Lo que se puede elegir de los subtitulos de UN video. Sin elegir, lo del
#: estilo (que es lo que habia). Cambiarlo rehace las capas y el montaje: ni
#: una imagen.
TAMANOS_SUBTITULO = ("pequeno", "normal", "grande", "enorme")
DISENOS_SUBTITULO = ("dibujo", "realista", "editorial")
CONFIG_SUBTITULOS_ESTILO = "subtitulos_del_estilo"


CLAVES_SUBTITULOS = ("subtitulo_tam", "subtitulo_caja", "diseno", "paleta",
                     "subtitulo_fuente", "subtitulo_posicion")

#: Donde puede ir el subtitulo, en el orden en que se ensena. «auto» es no
#: elegir: la clave NO se escribe (regla 1) y va donde siempre.
POSICIONES_SUBTITULO = ("abajo", "tercio", "centro", "arriba")


def _subtitulos_de(params_callouts, config=None):
    """Lo que la pantalla ensena de los subtitulos de un video (o de un borrador)."""
    p = params_callouts or {}
    p7 = PASOS_MODULOS.p7_callouts
    paleta = p.get("paleta") or {}
    return {"tam": p.get("subtitulo_tam") or p7.PARAMS_POR_DEFECTO["subtitulo_tam"],
            "caja": p.get("subtitulo_caja", "auto"),
            "diseno": p.get("diseno") or p7.PARAMS_POR_DEFECTO["diseno"],
            "color": ((paleta.get("fijados") or {}).get("texto") or ""),
            # "" = sin elegir (la letra del diseno / donde siempre)
            "fuente": p7.fuente_subtitulo(p) if p.get("subtitulo_fuente") else "",
            "posicion": p7.posicion_subtitulo(p),
            "fuentes": list(p7.SUB_FUENTES),
            "posiciones": list(POSICIONES_SUBTITULO),
            "propios": bool((config or {}).get(CONFIG_SUBTITULOS_ESTILO)),
            "tamanos": list(TAMANOS_SUBTITULO),
            "disenos": [{"id": d, "nombre": (p7.SETS_DISENO.get(d) or {}).get("nombre") or d,
                         "descripcion": (p7.SETS_DISENO.get(d) or {}).get("descripcion") or ""}
                        for d in DISENOS_SUBTITULO]}


def _cambios_de_subtitulos(p, datos):
    """Lo pedido, validado, como cambios de los params de callouts. -> dict"""
    p7 = PASOS_MODULOS.p7_callouts
    cambios = {}
    if "tam" in datos:
        if datos["tam"] not in TAMANOS_SUBTITULO:
            raise ErrorApi(400, "tam: " + ", ".join(TAMANOS_SUBTITULO))
        cambios["subtitulo_tam"] = datos["tam"]
    if "caja" in datos:
        caja = datos["caja"]
        if caja != "auto":
            try:
                caja = round(min(1.0, max(0.0, float(caja))), 2)
            except (TypeError, ValueError):
                raise ErrorApi(400, "caja: «auto» o un número de 0 a 1")
        cambios["subtitulo_caja"] = caja
    if "diseno" in datos:
        if datos["diseno"] not in DISENOS_SUBTITULO:
            raise ErrorApi(400, "diseno: " + ", ".join(DISENOS_SUBTITULO))
        cambios["diseno"] = datos["diseno"]
    if "color" in datos:
        color = str(datos["color"] or "").strip()
        if color and not re.match(r"^#[0-9a-fA-F]{6}$", color):
            raise ErrorApi(400, "color: «#rrggbb» o vacío")
        paleta = dict(p7.PARAMS_POR_DEFECTO["paleta"])
        paleta.update(p.get("paleta") or {})
        fijados = dict(paleta.get("fijados") or {})
        if color:
            fijados["texto"] = color
        else:
            fijados.pop("texto", None)
        paleta["fijados"] = fijados
        cambios["paleta"] = paleta
    # FUENTE Y POSICION (N9 de las notas de mejoras, paso 4). «auto» o vacio es
    # volver a no elegir: el cambio es None y `_aplicar_subtitulos` QUITA la
    # clave -- escribir "auto" seria un param que el proyecto nunca tuvo, y
    # moveria la firma de callouts sin cambiar nada (regla 1).
    if "fuente" in datos:
        fuente = str(datos["fuente"] or "").strip()
        if fuente in ("", "auto"):
            cambios["subtitulo_fuente"] = None
        else:
            buena = next((f for f in p7.SUB_FUENTES if f.lower() == fuente.lower()), "")
            if not buena:
                raise ErrorApi(400, "fuente: «auto», " + ", ".join(p7.SUB_FUENTES))
            cambios["subtitulo_fuente"] = buena
    if "posicion" in datos:
        posicion = str(datos["posicion"] or "").strip().lower()
        if posicion in ("", "auto"):
            cambios["subtitulo_posicion"] = None
        elif posicion not in POSICIONES_SUBTITULO:
            raise ErrorApi(400, "posicion: «auto», " + ", ".join(POSICIONES_SUBTITULO))
        else:
            cambios["subtitulo_posicion"] = posicion
    return {k: v for k, v in cambios.items() if p.get(k) != v}


def _aplicar_subtitulos(ctx, datos):
    """Escribe los subtitulos pedidos en los params de callouts. -> cambiado

    La primera vez se apunta COMO ESTABAN (y que claves no estaban), y
    «automatico» los deja exactamente asi: las claves que no existian se
    QUITAN, no se rellenan con un valor de fabrica. Volver es volver: la firma
    de callouts vuelve a ser la de antes y lo ya hecho vuelve a estar al dia.
    """
    p = ctx.estado.params("callouts") or {}
    if datos.get("automatico"):
        guardado = ctx.proyecto.config.get(CONFIG_SUBTITULOS_ESTILO)
        if not isinstance(guardado, dict):
            return False
        valores = guardado.get("valores") or {}
        params = copy.deepcopy(p)
        for clave in CLAVES_SUBTITULOS:
            if clave in valores:
                params[clave] = copy.deepcopy(valores[clave])
            else:
                params.pop(clave, None)
        ctx.estado.set_params("callouts", params)
        ctx.proyecto.config.pop(CONFIG_SUBTITULOS_ESTILO, None)
        ctx.proyecto.guardar_config()
        ctx.bitacora.anotar("subtitulos_del_estilo", "callouts", {})
        return True
    cambios = _cambios_de_subtitulos(p, datos)
    if not cambios:
        return False
    if not ctx.proyecto.config.get(CONFIG_SUBTITULOS_ESTILO):
        ctx.proyecto.config[CONFIG_SUBTITULOS_ESTILO] = {
            "valores": {k: copy.deepcopy(p[k]) for k in CLAVES_SUBTITULOS if k in p}}
        ctx.proyecto.guardar_config()
    quitar = [k for k, v in cambios.items() if v is None]
    if quitar:
        # volver a «sin elegir» QUITA la clave (ver `_cambios_de_subtitulos`).
        # Leer y escribir dentro del cerrojo (reentrante): un rótulo del repaso
        # que se guarde en medio no se pierde.
        with ctx.estado._lock:
            params = copy.deepcopy(ctx.estado.params("callouts") or {})
            for clave in quitar:
                params.pop(clave, None)
            params.update({k: v for k, v in cambios.items() if v is not None})
            ctx.estado.set_params("callouts", params)
    else:
        ctx.estado.actualizar_params("callouts", cambios)
    ctx.bitacora.anotar("subtitulos_cambiados", "callouts", {"claves": sorted(cambios)})
    return True


@app.get("/api/proyectos/{pid}/subtitulos")
def leer_subtitulos(pid: str):
    """Como son los subtitulos de este video, y si son los del estilo."""
    ctx = contexto(pid)
    salida = _subtitulos_de(ctx.estado.params("callouts"), ctx.proyecto.config)
    salida["montado"] = bool(_ruta_de_version(ctx, "render", "video.mp4"))
    salida["pendiente"] = ctx.estado.estado_de("callouts") == "obsoleto"
    return salida


@app.put("/api/proyectos/{pid}/subtitulos")
def cambiar_subtitulos(pid: str, cuerpo: dict = Body(default=None)):
    """{tam?, caja? ("auto" o 0-1), diseno?, color? ("#rrggbb" o ""),
    fuente? ("auto" o Verdana/Arial/Georgia), posicion? ("auto", abajo, tercio,
    centro, arriba)} o {automatico: true}.

    Cambiarlos deja pendientes las capas de texto y el montaje (no las
    imagenes). Se aplican con `POST .../subtitulos/aplicar` o al montar.
    """
    ctx = contexto(pid)
    if _trabajo_activo(ctx, "callouts") or _trabajo_activo(ctx, "render"):
        raise ErrorApi(409, "el vídeo se está montando ahora: cámbialo cuando termine")
    cambiado = _aplicar_subtitulos(ctx, _cuerpo(cuerpo))
    if cambiado:
        _apuntar_montaje_pendiente(ctx)
    return {"cambiado": cambiado, "estado": ctx.estado.estado_de("callouts")}


# ------------------------------------------------- el montaje (18-10-2026)
# Movimiento de camara, subtitulos de redes, gancho, cifras y barra
# (`callouts.montaje`, ver pasos/camara.py) y las transiciones que entran
# (`render.transiciones`). Nada de esto toca una imagen: cambiarlo deja
# pendientes las capas y el montaje, que se rehacen gratis.

@app.get("/api/montaje")
def datos_del_montaje():
    """Lo que la pantalla necesita para elegir el montaje antes de que exista
    el video: el de los cortos, el de siempre, hasta cuanto es corto y el
    catalogo de transiciones con su GLSL para las muestras."""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    camara = PASOS_MODULOS.camara
    trans = PASOS_MODULOS.transiciones
    ficha = trans.catalogo_para_pantalla(None)
    ficha.update({
        "montaje_cortos": camara.normalizar_montaje(camara.MONTAJE_CORTOS),
        "montaje_siempre": dict(camara.MONTAJE_DE_SIEMPRE),
        "duracion_corta_s": camara.DURACION_CORTA_S,
        "niveles": list(camara.NIVELES),
        "acento": trans.acentos(None)})
    # la profundidad 2.5D necesita su modelo: la pantalla lo dice si falta
    si, por_que = PASOS_MODULOS.profundidad.disponible()
    ficha["profundidad"] = {"disponible": si, "por_que": por_que}
    return ficha


_CERROJO_MONTAJE = threading.Lock()


@app.get("/api/proyectos/{pid}/montaje")
def leer_montaje(pid: str):
    """El montaje de este video, las transiciones elegidas y si esta aplicado."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    camara = PASOS_MODULOS.camara
    callouts = ctx.estado.params("callouts") or {}
    render = ctx.estado.params("render") or {}
    return {"montaje": camara.normalizar_montaje(callouts.get("montaje")),
            "elegido": bool(callouts.get("montaje")),
            "transiciones": list(render.get("transiciones") or []),
            "niveles": list(camara.NIVELES),
            "montado": bool(_ruta_de_version(ctx, "render", "video.mp4")),
            "pendiente": (ctx.estado.estado_de("callouts") == "obsoleto"
                          or ctx.estado.estado_de("render") == "obsoleto"),
            # cambios guardados sin montar (el Encargo): la franja «Aplicar»
            "sin_aplicar": bool(_montaje_pendiente(ctx)),
            "solo_mezcla": _solo_falta_mezclar(ctx)}


@app.put("/api/proyectos/{pid}/montaje")
def cambiar_montaje(pid: str, cuerpo: dict = Body(default=None)):
    """{montaje?: {movimiento, subtitulos, gancho, cifras, barra}, transiciones?: [..]}

    Solo se escribe lo que cambia, y lo que vuelve a ser lo de siempre QUITA la
    clave (regla 1). Deja pendientes las capas y el montaje; se aplica con
    `POST .../montaje/aplicar` o al montar.
    """
    ctx = contexto(pid)
    camara = PASOS_MODULOS.camara
    # _trabajo_que_toca y no _trabajo_activo: una tanda se registra en su
    # PRIMER paso y corre tambien las capas y el montaje (`toca`).
    if _trabajo_que_toca(ctx, ("callouts", "render")):
        raise ErrorApi(409, "el vídeo se está montando ahora: cámbialo cuando termine")
    datos = _cuerpo(cuerpo)
    cambiado = False
    if datos.get("montaje") is not None:
        try:
            pedido = camara.normalizar_montaje(
                dict(camara.normalizar_montaje((ctx.estado.params("callouts") or {}).get("montaje")),
                     **datos["montaje"]) if isinstance(datos["montaje"], dict) else datos["montaje"],
                estricto=True)
        except ValueError as fallo:
            raise ErrorApi(400, f"montaje: {fallo}")
        guardar = camara.para_guardar(pedido)
        with ctx.estado._lock:
            params = copy.deepcopy(ctx.estado.params("callouts") or {})
            if params.get("montaje") != guardar:
                if guardar:
                    params["montaje"] = guardar
                else:
                    params.pop("montaje", None)
                ctx.estado.set_params("callouts", params)
                cambiado = True
    if datos.get("transiciones") is not None:
        nuevas = _transiciones_validas(datos["transiciones"])
        with ctx.estado._lock:
            params = copy.deepcopy(ctx.estado.params("render") or {})
            if list(params.get("transiciones") or []) != nuevas:
                if nuevas:
                    params["transiciones"] = nuevas
                else:
                    params.pop("transiciones", None)
                ctx.estado.set_params("render", params)
                cambiado = True
    if cambiado:
        ctx.bitacora.anotar("montaje_cambiado", "callouts", {
            "montaje": datos.get("montaje"), "transiciones": datos.get("transiciones")})
        _apuntar_montaje_pendiente(ctx)
    return dict(leer_montaje(pid), cambiado=cambiado)


@app.post("/api/proyectos/{pid}/montaje/aplicar", status_code=202)
def aplicar_montaje(pid: str):
    """Aplica lo que quede del montaje en UN solo trabajo. Ni una imagen.

    Lo usan «Aplicar ahora» (movimiento, subtítulos) y «Aplicar y volver a
    montar» del Encargo (los cambios guardados con `remontar: false`, 19-10).
    Si lo pendiente es solo la MEZCLA (música, efectos, volúmenes, logo), se
    vuelve a mezclar sobre los clips que hay (`solo_montar`, segundos); si la
    música volvió a la automática, antes se monta la banda. Si no, se rehacen
    las capas y el montaje como siempre."""
    ctx = contexto(pid)
    if not _ruta_de_version(ctx, "render", "video.mp4"):
        raise ErrorApi(409, "este vídeo todavía no está montado: se aplicará al montarlo")
    # Mirar y lanzar bajo el mismo cerrojo: un doble clic no lanza dos montajes.
    # Y con _trabajo_que_toca: la tanda del video corre las capas sin estar
    # registrada en ellas, y dos pasadas sobre `trabajo/` se pisan al sellar.
    with _CERROJO_MONTAJE:
        if _trabajo_que_toca(ctx, ("callouts", "render")):
            raise ErrorApi(409, "el vídeo ya se está montando")
        marca = _montaje_pendiente(ctx)
        solo_mezcla = _solo_falta_mezclar(ctx) or bool(
            marca and marca.get("mezcla") and ctx.estado.al_dia("render")
            and ctx.estado.al_dia("callouts"))
        if solo_mezcla and not _vuelve_a_la_automatica(ctx):
            # el paso directo y no la receta: con solo un veto pendiente el
            # render dice «al día» y la receta en «pendientes» no haría nada
            trabajo_id = lanzar_paso(ctx, "render", None, nombre="montaje",
                                     opciones={"solo_montar": True})
        else:
            tareas = (["banda_sonora", "render"] if solo_mezcla
                      else ["callouts", "render"])
            trabajo_id = ctx.gestor.lanzar("montaje", _correr_rehacer_montaje, ctx,
                                           tareas, solo_mezcla, paso="render",
                                           toca=["callouts", "render"])
            _registrar_trabajo(trabajo_id, ctx.id)
        _olvidar_montaje_pendiente(ctx)
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id),
            "solo_mezcla": solo_mezcla}


# ----------------------------------------- MONTAJE POR PLANO (19-10-2026)
# El movimiento y la 2.5D de UN plano, elegidos en su diapositiva de Imagenes
# (`camara.montaje_propio`). Van en la unidad de callouts
# (`unidades["escena:S013"]["montaje"]`), fuera de la firma global: cambiarlos
# deja obsoleto ESE plano --sus capas y su trozo del montaje, gratis-- y ni una
# imagen. Sin elegir, la clave no existe y el plano sigue al video (regla 1).

def _planos_sin_montaje_propio(plan):
    """Los planos donde la camara no se puede tocar: las cartelas y las
    cabeceras (su texto viaja dentro del zoom). Ahi va lo de siempre."""
    cartelas = PASOS_MODULOS.cartelas
    return [e["id"] for e in (plan.get("escenas") or [])
            if cartelas.sin_imagen(e) or cartelas.sobre_imagen(e) or e.get("capitulo_svg")]


@app.get("/api/proyectos/{pid}/planos/montaje")
def leer_montaje_de_planos(pid: str):
    """{video, planos: {sid: {movimiento?, profundidad?}}, no_aplica, niveles, profundidad}"""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    camara = PASOS_MODULOS.camara
    callouts = ctx.estado.params("callouts") or {}
    planos = {}
    for uid, bloque in (callouts.get("unidades") or {}).items():
        propio = camara.montaje_propio(bloque.get("montaje")) if isinstance(bloque, dict) else {}
        if propio and str(uid).startswith("escena:"):
            planos[str(uid)[len("escena:"):]] = propio
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    si, por_que = PASOS_MODULOS.profundidad.disponible()
    return {"video": camara.normalizar_montaje(callouts.get("montaje")),
            "planos": planos,
            "planos_del_video": [str(e.get("id")) for e in (plan.get("escenas") or [])],
            "no_aplica": _planos_sin_montaje_propio(plan),
            "niveles": list(camara.NIVELES_PLANO),
            "profundidad": {"disponible": si, "por_que": por_que}}


@app.put("/api/proyectos/{pid}/planos/{sid}/montaje")
def cambiar_montaje_de_plano(pid: str, sid: str, cuerpo: dict = Body(default=None)):
    """{movimiento?: quieto|sobrio|vivo|dinamico|null, profundidad?: true|false|null}

    null (o no mandarla) en una clave la deja «como el video». Lo que queda
    vacio QUITA el bloque: un plano devuelto a «como el video» tiene la misma
    firma que uno que nunca se toco. Deja pendientes ese plano en las capas y
    el montaje; se aplica al montar.
    """
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    camara = PASOS_MODULOS.camara
    datos = _cuerpo(cuerpo)
    try:
        pedido = camara.montaje_propio(datos, estricto=True)
    except ValueError as fallo:
        raise ErrorApi(400, f"montaje del plano: {fallo}")
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    ids = [str(e.get("id")) for e in (plan.get("escenas") or [])]
    if sid not in ids:
        raise ErrorApi(404, f"este vídeo no tiene el plano {sid}")
    if sid in _planos_sin_montaje_propio(plan) and pedido:
        raise ErrorApi(400, "este plano es una cartela o una cabecera: su texto va con la imagen "
                            "y no se le puede cambiar el movimiento")
    uid = f"escena:{sid}"
    previo = (ctx.estado.params("callouts") or {}).get("unidades") or {}
    ya_tenia = camara.montaje_propio((previo.get(uid) or {}).get("montaje")
                                     if isinstance(previo.get(uid), dict) else None)
    # solo al ENCENDERLA: un plano que ya la lleva (y un modelo que se fue) no
    # puede quedarse sin poder cambiar su movimiento
    if (pedido.get("profundidad") and not ya_tenia.get("profundidad")
            and not PASOS_MODULOS.profundidad.disponible()[0]):
        raise ErrorApi(409, "la profundidad 2.5D no está disponible: "
                            + PASOS_MODULOS.profundidad.disponible()[1])
    if _trabajo_que_toca(ctx, ("callouts", "render")):
        raise ErrorApi(409, "el vídeo se está montando ahora: cámbialo cuando termine")
    with ctx.estado._lock:
        params = copy.deepcopy(ctx.estado.params("callouts") or {})
        unidades = params.get("unidades") if isinstance(params.get("unidades"), dict) else {}
        bloque = dict(unidades.get(uid)) if isinstance(unidades.get(uid), dict) else {}
        # un bloque que YA existia (aunque vacio) se queda: quitarlo moveria la
        # firma de ese plano sin que nadie lo pidiera
        existia = isinstance(unidades.get(uid), dict) and "montaje" not in unidades[uid]
        antes = camara.montaje_propio(bloque.get("montaje"))
        cambiado = antes != pedido or (bool(pedido) and bloque.get("montaje") != pedido)
        if cambiado:
            if pedido:
                bloque["montaje"] = pedido
            else:
                bloque.pop("montaje", None)
            if bloque or existia:
                unidades[uid] = bloque
            else:
                unidades.pop(uid, None)
            if unidades:
                params["unidades"] = unidades
            else:
                params.pop("unidades", None)
            ctx.estado.set_params("callouts", params)
    if cambiado:
        ctx.bitacora.anotar("montaje_de_plano", "callouts", {"plano": sid, "montaje": pedido})
    return dict(leer_montaje_de_planos(pid), cambiado=cambiado,
                pendiente=(ctx.estado.estado_de("callouts") == "obsoleto"
                           or ctx.estado.estado_de("render") == "obsoleto"))


# ------------------------------------------------ ELEMENTOS (19-10-2026)
# El grafismo encima de cada plano, al ritmo de la voz (rama elementos-video;
# ver pasos/elementos_video.py). Como el montaje por plano, van en la unidad de
# callouts (`unidades["escena:S013"]["elementos"]`): cambiarlos deja obsoleto
# ESE plano --capas y montaje, gratis-- y ni una imagen. Sin elementos la clave
# no existe (regla 1). Proponerlos con Claude NO guarda nada: se guarda al
# aplicarlos.

_PROPUESTAS_ELEMENTOS = {}
_LOCK_ELEMENTOS = threading.Lock()


def _elementos_video():
    return getattr(PASOS_MODULOS, "elementos_video", None) or __import__("elementos_video")


def _escenas_del_video(ctx):
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    return plan, [e for e in (plan.get("escenas") or []) if e.get("id")]


def _es_vertical(ctx, plan):
    try:
        salida = PASOS_MODULOS.p7_callouts.salida_de(plan)
        return int(salida[1]) > int(salida[0])
    except Exception:                                       # noqa: BLE001
        return str(plan.get("formato") or "") == "vertical"


def _guardar_elementos(ctx, cambios):
    """{sid: [elementos]} -> los planos que cambiaron. Una lista vacia QUITA la
    clave; un bloque que ya existia (aunque quede vacio) se queda, por lo mismo
    que en el montaje por plano: quitarlo moveria la firma sin que nadie lo
    pidiera."""
    EV = _elementos_video()
    cambiados = []
    with ctx.estado._lock:
        params = copy.deepcopy(ctx.estado.params("callouts") or {})
        unidades = params.get("unidades") if isinstance(params.get("unidades"), dict) else {}
        for sid, lista in cambios.items():
            uid = f"escena:{sid}"
            limpios = EV.limpiar(lista)
            bloque = dict(unidades.get(uid)) if isinstance(unidades.get(uid), dict) else {}
            existia = isinstance(unidades.get(uid), dict) and EV.CLAVE not in unidades[uid]
            antes = EV.limpiar(bloque.get(EV.CLAVE))
            if antes == limpios and (bool(limpios) == (EV.CLAVE in bloque)):
                continue
            if limpios:
                bloque[EV.CLAVE] = limpios
            else:
                bloque.pop(EV.CLAVE, None)
            if bloque or existia:
                unidades[uid] = bloque
            else:
                unidades.pop(uid, None)
            cambiados.append(sid)
        if cambiados:
            if unidades:
                params["unidades"] = unidades
            else:
                params.pop("unidades", None)
            ctx.estado.set_params("callouts", params)
    return cambiados


def _comprobar_planos(ctx, sids):
    plan, escenas = _escenas_del_video(ctx)
    ids = {str(e["id"]) for e in escenas}
    no = _planos_sin_montaje_propio(plan)
    for sid in sids:
        if sid not in ids:
            raise ErrorApi(404, f"este vídeo no tiene el plano {sid}")
    return plan, escenas, set(no)


@app.get("/api/proyectos/{pid}/planos/elementos")
def leer_elementos_de_planos(pid: str):
    """{planos: {sid: [elementos]}, no_aplica, tipos, entradas, intensidades,
    posiciones, iconos}: lo puesto en cada plano y lo que se puede poner."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    EV = _elementos_video()
    callouts = ctx.estado.params("callouts") or {}
    planos = {}
    for uid, bloque in (callouts.get("unidades") or {}).items():
        if str(uid).startswith("escena:") and isinstance(bloque, dict) and bloque.get(EV.CLAVE):
            planos[str(uid)[len("escena:"):]] = EV.limpiar(bloque.get(EV.CLAVE))
    plan, escenas = _escenas_del_video(ctx)
    return {"planos": planos, "no_aplica": _planos_sin_montaje_propio(plan),
            "vertical": _es_vertical(ctx, plan),
            "tipos": list(EV.TIPOS), "entradas": list(EV.ENTRADAS),
            "intensidades": EV.INTENSIDADES, "iconos": list(_motor_grafismo().ICONOS),
            "posiciones": EV.POSICIONES["vertical" if _es_vertical(ctx, plan) else "horizontal"]}


@app.put("/api/proyectos/{pid}/planos/{sid}/elementos")
def cambiar_elementos_de_plano(pid: str, sid: str, cuerpo: dict = Body(default=None)):
    """{elementos: [...]} de UN plano (vacia, los quita). Deja pendientes ese
    plano en las capas y el montaje; se aplica al montar (gratis)."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    lista = _cuerpo(cuerpo).get("elementos")
    if not isinstance(lista, list):
        raise ErrorApi(400, "manda {elementos: [...]}")
    _plan, _escenas, no = _comprobar_planos(ctx, [sid])
    if sid in no and lista:
        raise ErrorApi(400, "este plano es una cartela o una cabecera: ya lleva su texto encima")
    if _trabajo_que_toca(ctx, ("callouts", "render")):
        raise ErrorApi(409, "el vídeo se está montando ahora: cámbialo cuando termine")
    cambiados = _guardar_elementos(ctx, {sid: lista})
    if cambiados:
        ctx.bitacora.anotar("elementos_de_plano", "callouts", {"plano": sid, "n": len(lista)})
    return dict(leer_elementos_de_planos(pid), cambiado=bool(cambiados),
                pendiente=(ctx.estado.estado_de("callouts") == "obsoleto"
                           or ctx.estado.estado_de("render") == "obsoleto"))


@app.post("/api/proyectos/{pid}/elementos/proponer", status_code=202)
def proponer_elementos(pid: str, cuerpo: dict = Body(default=None)):
    """Claude propone elementos para el video (o para {planos: [sid]}) con la
    {intensidad} pedida. -> {id}; la propuesta, en GET. No guarda nada."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    datos = _cuerpo(cuerpo)
    EV = _elementos_video()
    intensidad = datos.get("intensidad") if datos.get("intensidad") in EV.INTENSIDADES else "vivo"
    plan, escenas = _escenas_del_video(ctx)
    no = set(_planos_sin_montaje_propio(plan))
    pedidos = [str(x) for x in (datos.get("planos") or [])] if isinstance(datos.get("planos"), list) else []
    escenas = [e for e in escenas if str(e["id"]) not in no and (not pedidos or str(e["id"]) in pedidos)]
    escenas = [e for e in escenas if str(e.get("narracion") or "").strip()]
    if not escenas:
        raise ErrorApi(400, "no hay planos con narración a los que ponerles elementos")
    vertical = _es_vertical(ctx, plan)
    rid = uuid.uuid4().hex[:12]
    with _LOCK_ELEMENTOS:
        for viejo in list(_PROPUESTAS_ELEMENTOS)[:-19]:
            _PROPUESTAS_ELEMENTOS.pop(viejo, None)
        _PROPUESTAS_ELEMENTOS[rid] = {"estado": "pensando", "proyecto": ctx.id, "intensidad": intensidad}

    def correr():
        try:
            propuesta = EV.proponer(escenas, intensidad, vertical, cwd=RAIZ_ESTUDIO)
            ficha = {"estado": "listo", "proyecto": ctx.id, "intensidad": intensidad,
                     "propuesta": propuesta, "planos": len(escenas),
                     "elementos": sum(len(v) for v in propuesta.values())}
        except Exception as fallo:                          # noqa: BLE001
            error = str(fallo)[:600]
            if CLI_CLAUDE.es_pasajero(fallo):
                error = ("La sesión de Claude se estaba renovando y no ha contestado. "
                         f"Vuelve a pedirlo en un minuto.\n\n{error}")
            ficha = {"estado": "error", "proyecto": ctx.id, "error": error}
        with _LOCK_ELEMENTOS:
            _PROPUESTAS_ELEMENTOS[rid] = ficha

    threading.Thread(target=correr, daemon=True, name=f"elementos-{rid}").start()
    return {"id": rid, "estado": "pensando", "planos": len(escenas)}


@app.get("/api/proyectos/{pid}/elementos/proponer/{rid}")
def leer_propuesta_elementos(pid: str, rid: str):
    """Como va la propuesta de elementos, y cual es al terminar."""
    with _LOCK_ELEMENTOS:
        ficha = _PROPUESTAS_ELEMENTOS.get(rid)
    if not ficha or ficha.get("proyecto") != pid:
        raise ErrorApi(404, "esa propuesta ya no está: vuelve a pedirla")
    return ficha


@app.post("/api/proyectos/{pid}/elementos/aplicar")
def aplicar_elementos(pid: str, cuerpo: dict = Body(default=None)):
    """Pone los elementos de varios planos de una vez: {planos: {sid: [...]},
    reemplazar?}. Sin `reemplazar`, se SUMAN a los que ya tenia cada plano.
    Los planos que no se mandan no se tocan. Se aplica al montar (gratis)."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    datos = _cuerpo(cuerpo)
    planos = datos.get("planos")
    if not isinstance(planos, dict) or not planos:
        raise ErrorApi(400, "manda {planos: {plano: [elementos]}}")
    _plan, _escenas, no = _comprobar_planos(ctx, [str(s) for s in planos])
    if _trabajo_que_toca(ctx, ("callouts", "render")):
        raise ErrorApi(409, "el vídeo se está montando ahora: aplícalo cuando termine")
    EV = _elementos_video()
    previos = ((ctx.estado.params("callouts") or {}).get("unidades") or {})
    cambios, recortados = {}, []
    for sid, lista in planos.items():
        sid = str(sid)
        if sid in no or not isinstance(lista, list):
            continue
        ya = [] if datos.get("reemplazar") else EV.limpiar(((previos.get(f"escena:{sid}") or {})
                                                            if isinstance(previos.get(f"escena:{sid}"), dict)
                                                            else {}).get(EV.CLAVE))
        juntos = ya + EV.limpiar(lista)
        if len(juntos) > EV.MAX_POR_PLANO:
            recortados.append(sid)
        cambios[sid] = juntos[:EV.MAX_POR_PLANO]
    cambiados = _guardar_elementos(ctx, cambios)
    if cambiados:
        ctx.bitacora.anotar("elementos_aplicados", "callouts", {"planos": cambiados})
    # los que no cabian (mas de MAX_POR_PLANO) se dicen, no se tiran callando
    return dict(leer_elementos_de_planos(pid), cambiados=cambiados, recortados=recortados,
                pendiente=(ctx.estado.estado_de("callouts") == "obsoleto"
                           or ctx.estado.estado_de("render") == "obsoleto"))


@app.post("/api/proyectos/{pid}/planos/{sid}/elementos/vista")
def vista_elementos_de_plano(pid: str, sid: str, cuerpo: dict = Body(default=None)):
    """La imagen del plano con sus elementos encima, quietos (todos a la vez),
    en pequeno: {elementos?} (sin ellos, los guardados). PNG."""
    ctx = contexto(pid)
    plan, escenas, _no = _comprobar_planos(ctx, [sid])
    EV = _elementos_video()
    lista = _cuerpo(cuerpo).get("elementos")
    if not isinstance(lista, list):
        lista = EV.de_plano(ctx.estado.params("callouts") or {}, f"escena:{sid}")
    ruta = _imagenes_de_planos(ctx, plan).get(sid)
    if not ruta or not os.path.isfile(ruta):
        raise ErrorApi(404, "este plano todavía no tiene imagen")
    salida = PASOS_MODULOS.p7_callouts.salida_de(plan)
    W, H = int(salida[0]), int(salida[1])
    try:
        paleta = _paleta_del_video(ctx)
    except Exception:                                       # noqa: BLE001
        paleta = {}
    G = _motor_grafismo()
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" width="{W // 3}" height="{H // 3}" viewBox="0 0 {W} {H}">'
           + G.imagen_cubre(G.data_uri(ruta), 0, 0, W, H) + EV.estatico(lista, (W, H), paleta) + "</svg>")
    # UNA CARPETA TEMPORAL POR PETICION (fuera del proyecto): dos vistas a la
    # vez no se borran la una a la otra
    carpeta_tmp = tempfile.mkdtemp(prefix="vista_elementos_")
    destino = os.path.join(carpeta_tmp, f"{sid}.png")
    try:
        PASOS_MODULOS.medios.rasterizar(svg, destino, W // 3, H // 3 + 160, transparente=False, espera_ms=1000)
        from PIL import Image                               # noqa: PLC0415
        with Image.open(destino) as im:
            recorte = im.convert("RGB").crop((0, 0, W // 3, H // 3))
            salida_png = io.BytesIO()
            recorte.save(salida_png, "PNG")
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(500, f"no he podido pintar la vista: {fallo}")
    finally:
        shutil.rmtree(carpeta_tmp, ignore_errors=True)
    return Response(salida_png.getvalue(), media_type="image/png", headers={"Cache-Control": "no-store"})


@app.post("/api/proyectos/{pid}/planos/{sid}/elementos/nota-ia", status_code=201)
def nota_texto_dentro_de_imagen(pid: str, sid: str, cuerpo: dict = Body(default=None)):
    """LA OTRA OPCION (se paga al aplicarla): una nota de imagen que pide
    volver a dibujar ESTE plano con {texto} DENTRO de la imagen. Va a la lista
    de notas de siempre; nada se dibuja hasta que alguien la aplica."""
    ctx = contexto(pid)
    texto = " ".join(str(_cuerpo(cuerpo).get("texto") or "").split())
    if not texto:
        raise ErrorApi(400, "¿qué texto quieres dentro de la imagen?")
    _plan, escenas, no = _comprobar_planos(ctx, [sid])
    if sid in no:
        raise ErrorApi(400, "este plano es una cartela o una cabecera: su texto ya va escrito")
    escena = next(e for e in escenas if str(e["id"]) == sid)
    return anadir_nota_repaso(pid, {"texto": _elementos_video().nota_texto_en_imagen(texto),
                                    "t": float(escena.get("t_in") or 0.0), "plano": sid,
                                    "pantalla": "imagenes", "ancla": escena.get("narracion") or ""})


def _correr_rehacer_montaje(avisar, ctx, tareas, solo_montar=False):
    """Rehace lo que se pida del montaje (rotulos, banda sonora, MP4). Gratis."""
    _regenerar_tras_repaso(avisar, ctx, tareas, "pendientes", solo_montar)
    return {"tareas": tareas}


@app.post("/api/proyectos/{pid}/subtitulos/aplicar", status_code=202)
def aplicar_subtitulos(pid: str):
    """Rehace las capas de texto y vuelve a montar el video. Ni una imagen."""
    ctx = contexto(pid)
    if not _ruta_de_version(ctx, "render", "video.mp4"):
        raise ErrorApi(409, "este vídeo todavía no está montado: se aplicará al montarlo")
    if _trabajo_activo(ctx, "callouts") or _trabajo_activo(ctx, "render"):
        raise ErrorApi(409, "el vídeo ya se está montando")
    trabajo_id = ctx.gestor.lanzar("subtitulos", _correr_rehacer_montaje, ctx,
                                   ["callouts", "render"], paso="render")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id)}


# ------------------------------------------------- escuchar un tema de Jamendo

@app.get("/api/musica/escucha")
def escuchar_tema(url: str = Query(...)):
    """Pasa por aqui la escucha de un tema de Jamendo antes de elegirlo.

    Por el servidor y no directo desde el navegador: la politica de seguridad
    del acceso de delante no deja cargar audio de otros dominios. Solo Jamendo.
    """
    from urllib.parse import urlparse
    destino = urlparse(str(url))
    host = (destino.hostname or "").lower()
    permitidos = ("jamendo.com", "freesound.org")
    if destino.scheme != "https" or not any(
            host == d or host.endswith("." + d) for d in permitidos):
        raise ErrorApi(400, "solo se escuchan temas de Jamendo y sonidos de FreeSound")
    import requests
    # LA ATRIBUCION LA PONE EL SERVIDOR. La ficha que tiene el navegador va sin
    # la clave (`sonido.url_sin_clave`); Jamendo la quiere en `from`, asi que se
    # añade aqui, en la peticion que sale del servidor, y no baja nunca.
    pedir = str(url)
    if host == "jamendo.com" or host.endswith(".jamendo.com"):
        sonido = _sonido()
        clave = (sonido._claves() or {}).get("JAMENDO_CLIENT_ID") or ""
        pedir = sonido.url_sin_clave(pedir)
        if clave:
            pedir += ("&" if "?" in pedir else "?") + f"from=app-{clave}"
    try:
        respuesta = requests.get(pedir, stream=True, timeout=30)
        respuesta.raise_for_status()
    except requests.HTTPError as fallo:
        raise ErrorApi(502, f"Jamendo no deja escuchar ese tema "
                            f"({fallo.response.status_code})")
    except Exception as fallo:                              # noqa: BLE001
        # el texto de la excepcion lleva la URL, y la URL ahora lleva la clave
        raise ErrorApi(502, f"no se puede escuchar ese tema ahora "
                            f"({type(fallo).__name__})")
    return StreamingResponse(respuesta.iter_content(64 * 1024),
                             media_type=respuesta.headers.get("content-type") or "audio/mpeg")


@app.get("/api/proyectos/{pid}/musica/presencia")
def leer_presencia_musica(pid: str):
    """Cuánto se oye la música bajo la voz en este vídeo, y los niveles que hay."""
    ctx = contexto(pid)
    sonido = _sonido()
    guardada = (ctx.estado.params("render") or {}).get("musica_presencia")
    nombre, _ = sonido.presencia_de(guardada)
    return {"presencia": nombre, "elegida": bool(guardada),
            "por_defecto": sonido.PRESENCIA_POR_DEFECTO,
            "niveles": list(sonido.PRESENCIAS)}


@app.put("/api/proyectos/{pid}/musica/presencia")
def cambiar_presencia_musica(pid: str, cuerpo: dict = Body(default=None)):
    """Fija cuánto se oye la música y, si el vídeo ya está montado, lo REMONTA.

    Remontar es volver a mezclar el audio sobre los clips que ya hay
    (`solo_montar`): ni una imagen ni un clip, segundos de máquina. Solo se hace
    si el montaje estaba al día: con planos pendientes, mezclar sobre los clips
    viejos sellaría como hechos unos clips que no lo están, y entonces se
    guarda y se deja para el siguiente montaje.

    No se escribe nada si lo pedido es lo que ya suena (regla 1 de CLAUDE.md):
    elegir «normal» en un vídeo que nunca eligió no mueve la firma.
    """
    ctx = contexto(pid)
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    pedida = str(datos.get("presencia") or "").strip().lower()
    if pedida not in sonido.PRESENCIAS:
        raise ErrorApi(400, "«presencia» tiene que ser una de: "
                            + ", ".join(sonido.PRESENCIAS))
    render = ctx.estado.params("render") or {}
    actual, _ = sonido.presencia_de(render.get("musica_presencia"))
    # UN VIDEO MONTADO SIN NIVEL GUARDADO se mezclo con lo que hubiera ese dia:
    # si es de antes del 10-10-2026, con la musica enterrada («suave»), aunque
    # la pantalla le marque «normal». Asi que ahi elegir «normal» SI se aplica
    # --y vuelve a mezclar--; solo se ignora en un video sin montar, donde no
    # escribir nada es lo que manda la regla 1.
    montado_ya = bool(_ruta_de_version(ctx, "render", "video.mp4"))
    if pedida == actual and (render.get("musica_presencia") or not montado_ya):
        return {"presencia": actual, "cambiado": False, "remontando": False,
                "trabajo_id": None, "estado": ctx.estado.estado_de("render")}
    al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
    ctx.estado.actualizar_params("render", {"musica_presencia": pedida})
    ctx.bitacora.anotar("musica_presencia", "render",
                        {"antes": actual, "ahora": pedida})
    trabajo_id = _remontar_si_estaba_al_dia(
        ctx, al_dia and _remontar_pedido(datos), montado,
        "volver a mezclar la música")
    if trabajo_id is None:
        _apuntar_montaje_pendiente(ctx)
    return {"presencia": pedida, "cambiado": True,
            "remontando": bool(trabajo_id), "trabajo_id": trabajo_id,
            "montado": montado,
            "trabajo": ctx.gestor.estado(trabajo_id) if trabajo_id else None,
            "estado": ctx.estado.estado_de("render")}


def _correr_surtir_efectos(avisar, ctx, papeles, salteado):
    sonido = _sonido()
    render = ctx.estado.params("render") or {}
    surtido = dict(render.get("efectos") or {})
    # los que se eligieron a mano no se vuelven a surtir: se pidieron ASI
    fijos = set(render.get("efectos_fijos") or [])
    papeles = [p for p in papeles if p not in fijos or not surtido.get(p)]
    total = len(papeles)
    nuevos = {}
    for indice, papel in enumerate(papeles):
        avisar(0.05 + 0.9 * (indice / max(1, total)),
               f"buscando y bajando «{sonido.PAPELES[papel]['nombre']}»")
        nuevos[papel] = sonido.surtir(papel, salteado=salteado)
    # SE RELEE ANTES DE ESCRIBIR: si mientras se buscaba alguien fijo un
    # efecto a mano, ese papel se queda como lo dejo
    ahora = ctx.estado.params("render") or {}
    surtido = dict(ahora.get("efectos") or {})
    fijos_ahora = set(ahora.get("efectos_fijos") or [])
    for papel, fichas in nuevos.items():
        if papel not in fijos_ahora or not surtido.get(papel):
            surtido[papel] = fichas
    ctx.estado.actualizar_params("render", {"efectos": surtido})
    cuantos = sum(len(v or []) for v in surtido.values())
    avisar(1.0, f"{cuantos} efectos en el banco")
    return {"efectos": surtido, "cuantos": cuantos}


def _correr_banda(avisar, ctx, tramos):
    """Monta la banda sonora entera sin preguntar nada. Ver sonido.montar_banda."""
    sonido = _sonido()
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = plan.get("escenas") or []
    if not escenas:
        raise RuntimeError("no hay planos todavía: la música se monta sobre el "
                           "ritmo del montaje, así que primero hay que cortarlo")
    largo = float(plan.get("duracion_total") or 0) or None
    if not largo:
        largo = (float(escenas[-1].get("t_out") or 0)
                 - float(escenas[0].get("t_in") or 0))
    avisar(0.05, "leyendo el ritmo del montaje")
    ficha = sonido.montar_banda(escenas, largo, avisar=avisar, tramos=tramos)
    ctx.estado.actualizar_params("render", {"musica": ficha})
    ctx.bitacora.anotar("banda_sonora", "render", {
        "tramos": len(ficha["tramos"]),
        "animos": [t["animo"] for t in ficha["tramos"]]})
    avisar(1.0, sonido.describir(ctx.estado.params("render") or {}))
    return {**ficha, "resumen": sonido.describir(ctx.estado.params("render") or {})}


def _sonido_que_no_tumba(avisar, ctx, correr, clave, evento, avisos):
    """Corre la musica o los efectos de una tanda sin dejar que tumben el MP4.

    La musica y los efectos son prescindibles y el MP4 no. Con Jamendo o
    FreeSound caidos (o sin su clave), la tarea lanzaba, la excepcion cortaba la
    receta y «Montar el video» se caia entero por algo que el video puede no
    llevar (A3 del informe de la Etapa Foto A, y lo mismo con FreeSound). Aqui
    el fallo se apunta en la bitacora, se avisa y la tanda sigue: el render sin
    `musica`/`efectos` en params monta sin ellos, como siempre.

    NO SE ESCRIBE NADA EN PARAMS: la clave sigue vacia, asi que la tarea sigue
    sin estar al dia (`_esta_al_dia`) y la proxima tanda vuelve a intentarlo
    sola. Escribir un «sin musica» moveria la firma del render (regla 1). Con
    «Rehacer todo» se vuelve a pedir aunque ya hubiera, y si falla se queda lo
    de antes: por eso el aviso mira si ya habia.

    Cancelar SI corta: es una persona pidiendo parar, no un fallo del sonido.
    Los botones sueltos de «Musica y efectos», el repaso y «volver a la
    automatica» siguen fallando a la vista: ahi lo pedido es justo eso.
    """
    try:
        return correr()
    except Exception as fallo:                              # noqa: BLE001
        if type(fallo).__name__ == "Cancelado":
            raise
        motivo = str(fallo).strip() or type(fallo).__name__
        ctx.bitacora.anotar(evento, "render", {"error": motivo[:300]})
        # LO QUE SE ENSEÑA, corto y sin la peticion: el error crudo de requests
        # (FreeSound sin red) es una linea de doscientos caracteres con la URL,
        # y un 503 trae el HTML de la pagina de error
        import requests                                     # noqa: PLC0415
        if isinstance(fallo, requests.RequestException):
            motivo = f"el servicio no responde ({type(fallo).__name__})"
        elif len(motivo) > 160:
            motivo = motivo[:160].rstrip() + "…"
        # «ya tenia» es que habia algo de verdad: unos efectos que se buscaron y
        # no trajeron nada quedan guardados como listas vacias
        antes = ((ctx.estado.params("render") if ctx.estado else None) or {}).get(clave)
        tenia = (any(antes.values()) if isinstance(antes, dict) and clave == "efectos"
                 else bool(antes))
        aviso = avisos[1].format(motivo=motivo) if tenia else avisos[0].format(motivo=motivo)
        avisar(None, f"AVISO: {aviso}")
        return {"resumen": avisos[3] if tenia else avisos[2], "avisos": [aviso]}


def _correr_banda_de_tanda(avisar, ctx):
    """La banda sonora DENTRO de una tanda: si no sale, el video sigue sin ella."""
    return _sonido_que_no_tumba(
        avisar, ctx, lambda: _correr_banda(avisar, ctx, None), "musica",
        "banda_sonora_fallida",
        ("El vídeo sale sin música: {motivo}. Cuando se pueda, móntala en "
         "«Música y efectos» y vuelve a montar el vídeo.",
         "No se ha podido montar otra música ({motivo}): el vídeo se queda con "
         "la que ya tenía.",
         "sin música", "música de antes"))


def _correr_efectos_de_tanda(avisar, ctx):
    """Los efectos DENTRO de una tanda: si FreeSound no responde, sin ellos."""
    return _sonido_que_no_tumba(
        avisar, ctx,
        lambda: _correr_surtir_efectos(avisar, ctx, list(_sonido().PAPELES), False),
        "efectos", "efectos_fallidos",
        ("El vídeo sale sin efectos de sonido: {motivo}. Cuando se pueda, "
         "búscalos en «Música y efectos» y vuelve a montar el vídeo.",
         "No se han podido buscar otros efectos ({motivo}): el vídeo se queda "
         "con los que ya tenía.",
         "sin efectos", "efectos de antes"))


@app.get("/api/proyectos/{pid}/sonido/arco")
def leer_arco(pid: str):
    """El arco que sale del RITMO del montaje. Gratis, sin salir a la red.

    Es lo que la pantalla enseña antes de montar nada: en cuántos tramos se
    parte el vídeo, cuántos planos tiene cada uno y qué ánimo pide. Sirve para
    entender la decisión, no para tomarla.
    """
    tramos, largo, planos = _arco_de(contexto(pid))
    return {"tramos": tramos, "duracion": largo, "planos": planos}


def _arco_de(ctx):
    """(tramos, largo, planos) del arco que sale del ritmo del montaje."""
    sonido = _sonido()
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = plan.get("escenas") or []
    largo = float(plan.get("duracion_total") or 0)
    if not largo and escenas:
        largo = (float(escenas[-1].get("t_out") or 0)
                 - float(escenas[0].get("t_in") or 0))
    return sonido.arco_del_video(escenas, largo), largo, len(escenas)


@app.put("/api/proyectos/{pid}/musica/animo", status_code=202)
def cambiar_animo_musica(pid: str, cuerpo: dict = Body(default=None)):
    """Rehace la música AUTOMÁTICA con un ánimo para todo el vídeo, y remezcla.

    N9 de las notas de mejoras (13-10-2026): «a la música cambiarle de tipo».
    Los ánimos de la automática salían solos del ritmo (`sonido.arco_del_video`)
    y no había forma de pedir, por ejemplo, una alegre. Es el MISMO camino que
    «volver a la automática» —montar la banda y volver a mezclar con
    `solo_montar`— y el ánimo viaja en los `tramos` que ya acepta
    `sonido.montar_banda`: los del ritmo, con su `animo` cambiado (los cortes y
    la velocidad siguen saliendo del montaje). Ni una imagen ni la voz.

    NO SE ESCRIBE NADA AL PEDIRLO: la banda nueva entra en los params al
    terminar de montarse. Con Jamendo caído el vídeo se queda con la música que
    tenía, en vez de quedarse sin ninguna. Y no hace falta ningún param nuevo:
    el ánimo queda apuntado en cada tramo de `render.musica`.
    """
    ctx = contexto(pid)
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    animo = str(datos.get("animo") or "").strip().lower()
    if animo not in sonido.ANIMOS:
        raise ErrorApi(400, "«animo» tiene que ser uno de: " + ", ".join(sorted(sonido.ANIMOS)))
    if not sonido.hay_claves()[0]:
        raise ErrorApi(409, "falta la clave de Jamendo: ponla en Configuración")
    al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
    tramos, _largo, _planos = _arco_de(ctx)
    if not tramos:
        raise ErrorApi(409, "no hay planos todavía: la música se monta sobre el "
                            "ritmo del montaje, así que primero hay que cortarlo")
    nombre = dict(sonido.NOMBRES_ANIMOS).get(animo, animo)
    tramos = [dict(t, animo=animo, por_que=f"elegido a mano: {nombre.lower()}")
              for t in tramos]
    # SOLO SE REMEZCLA SI EL MONTAJE ESTABA AL DÍA (`_remontar_si_estaba_al_dia`):
    # con planos pendientes la banda se queda puesta y entra al montar el vídeo
    remezclar = bool(al_dia and montado)
    trabajo_id = ctx.gestor.lanzar("música con otro ánimo", _correr_banda_y_mezcla,
                                   ctx, tramos, remezclar, paso="render")
    _registrar_trabajo(trabajo_id, ctx.id)
    ctx.bitacora.anotar("musica_animo", "render", {"animo": animo, "tramos": len(tramos)})
    return {"animo": animo, "tramos": len(tramos), "trabajo_id": trabajo_id,
            "remontando": remezclar, "montado": montado,
            "trabajo": ctx.gestor.estado(trabajo_id)}


def _correr_banda_y_mezcla(avisar, ctx, tramos, remezclar):
    """La banda con los tramos dados y, si toca, el MP4 vuelto a MEZCLAR."""
    ficha = _correr_banda(lambda v, m="", p="": avisar(0.6 * float(v or 0), m),
                          ctx, tramos)
    if remezclar:
        def avisar_mezcla(v, m="", p=""):
            return avisar(0.6 + 0.4 * float(v or 0), m, p)
        # «Parar» corta la mezcla en el acto (ver `medios.correr`)
        avisar_mezcla.al_cancelar = getattr(avisar, "al_cancelar", None)
        _regenerar_tras_repaso(avisar_mezcla, ctx, ["render"], "pendientes", True)
    return {"tramos": len(ficha.get("tramos") or []), "remezclado": bool(remezclar),
            "resumen": ficha.get("resumen")}


@app.post("/api/proyectos/{pid}/sonido/banda", status_code=202)
def montar_banda_sonora(pid: str, cuerpo: dict = Body(default=None)):
    """Monta la banda sonora SOLA: un tema por tramo, elegido por el ritmo.

    No hay nada que elegir. El montaje ya dice dónde acelera y dónde respira
    (`sonido.arco_del_video`), cada tramo pide su ánimo, y de los candidatos se
    queda el que mejor deja libre la banda de la voz — medido, no escuchado.
    """
    ctx = contexto(pid)
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    if not sonido.hay_claves()[0]:
        raise ErrorApi(409, "falta la clave de Jamendo: ponla en Configuración")
    # los tramos se pueden pasar retocados desde avanzadas (otro ánimo), pero el
    # camino normal es no pasar nada y que los deduzca del ritmo
    tramos = datos.get("tramos") if isinstance(datos.get("tramos"), list) else None
    trabajo_id = ctx.gestor.lanzar("banda_sonora", _correr_banda, ctx, tramos,
                                   paso="render")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


# ---------------------------------------- tu música, tus efectos, y buscar más

@app.post("/api/sonido/subir", status_code=201)
async def subir_audio_propio(peticion: Request, familia: str = Query(default="musica")):
    """Sube un audio tuyo (MP3, WAV, M4A, OGG) para la música o un efecto."""
    sonido = await _en_hilo(_sonido)
    if familia not in ("musica", "efectos"):
        raise ErrorApi(400, "familia: «musica» o «efectos»")
    tipo = (peticion.headers.get("content-type") or "").lower()
    if not tipo.startswith("multipart/"):
        raise ErrorApi(400, "manda el audio como multipart")
    try:
        formulario = await peticion.form()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(400, f"multipart ilegible: {fallo}")
    for _clave, valor in formulario.multi_items():
        if not hasattr(valor, "read"):
            continue
        # COMO MUCHO EL TOPE MAS UNO: leerlo entero para despues decir «pesa
        # demasiado» es meter en memoria lo que se va a rechazar
        contenido = await valor.read(sonido.MAX_BYTES_AUDIO + 1)
        if len(contenido) > sonido.MAX_BYTES_AUDIO:
            raise ErrorApi(400, f"pesa más de {sonido.MAX_BYTES_AUDIO // 1024 // 1024} MB")
        try:
            ficha = await asyncio.to_thread(
                sonido.guardar_propio, contenido, getattr(valor, "filename", ""), familia)
        except ValueError as fallo:
            raise ErrorApi(400, str(fallo))
        ficha["muestra"] = (f"/api/efectos/{sonido._nombre_de(ficha)}" if familia == "efectos"
                            else f"/api/musica/propia/{sonido._nombre_de(ficha)}")
        await _en_hilo(anotar_global, "audio_propio",
                       {"familia": familia, "id": ficha["id"], "titulo": ficha["titulo"]})
        return {"ficha": ficha}
    raise ErrorApi(400, "no ha llegado ningún audio")


@app.get("/api/musica/propia/{archivo}")
def servir_musica_propia(archivo: str, peticion: Request):
    """Un tema tuyo del banco, para escucharlo."""
    sonido = _sonido()
    if not archivo.startswith("propia_"):
        raise ErrorApi(404, "solo se sirven aquí los temas subidos")
    destino = ruta_segura(sonido.banco("musica"), archivo)
    if not os.path.isfile(destino):
        raise ErrorApi(404, f"no hay ningún tema {archivo!r}")
    return servir_fichero(peticion, destino)


@app.post("/api/efectos/buscar")
def buscar_efectos_a_mano(cuerpo: dict = Body(default=None)):
    """Efectos de FreeSound por texto libre, para elegir uno: {texto, papel?, pagina?}."""
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    texto = " ".join(str(datos.get("texto") or "").split())[:80]
    papel = str(datos.get("papel") or "")
    if not texto:
        texto = " ".join(sonido.PAPELES.get(papel, {}).get("consultas", ("whoosh",))[:1])
    dur_min, dur_max = sonido.PAPELES.get(papel, {}).get("duracion", (0.1, 10.0))
    try:
        fichas = sonido.buscar_efectos(texto, dur_min, dur_max,
                                       cuantos=max(1, min(30, int(datos.get("cuantos") or 15))))
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(502, f"no se ha podido buscar en FreeSound: {fallo}")
    prohibidos = sonido.vetados()
    for ficha in fichas:
        ficha["vetado"] = sonido.clave_de(ficha) in prohibidos
        ficha.update(licencia_de_efecto(ficha.get("licencia")))
    return {"efectos": fichas, "texto": texto}


def licencia_de_efecto(url):
    """La licencia de un sonido de FreeSound, en claro (CC0, BY, BY-NC)."""
    texto = str(url or "").lower()
    if "publicdomain" in texto or "/zero/" in texto:
        return {"licencia_nombre": "CC0 (libre)", "comercial": True, "atribucion": False}
    return licencia_de_tema(url)


@app.put("/api/proyectos/{pid}/sonido/efecto")
def fijar_efecto(pid: str, cuerpo: dict = Body(default=None)):
    """Fija UN sonido para un papel ({papel, efecto}) o lo devuelve a automático
    ({papel, efecto: null}). Vuelve a montar el vídeo si estaba al día."""
    ctx = contexto(pid)
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    papel = str(datos.get("papel") or "")
    if papel not in sonido.PAPELES:
        raise ErrorApi(400, f"papel desconocido: {papel!r}. Son: {', '.join(sonido.PAPELES)}")
    ficha = datos.get("efecto") if isinstance(datos.get("efecto"), dict) else None
    render = ctx.estado.params("render") or {}
    surtido = dict(render.get("efectos") or {})
    fijos = [p for p in (render.get("efectos_fijos") or []) if p in sonido.PAPELES]
    if ficha:
        propio = ficha.get("fuente") == "propia"
        _ficha_de_audio_valida(ficha, ("freesound", "propia"), ("freesound.org",))
        if not ficha.get("id") or not (ficha.get("descarga") or propio):
            raise ErrorApi(400, "el efecto tiene que traer 'id' y 'descarga'")
        if not propio:
            try:
                sonido.traer(ficha, "efectos")
            except Exception as fallo:                      # noqa: BLE001
                raise ErrorApi(502, f"no se ha podido bajar el sonido: {fallo}")
        if not os.path.isfile(sonido.banco("efectos", sonido._nombre_de(ficha))):
            raise ErrorApi(400, "ese sonido no está en el banco: vuelve a subirlo")
        limpio = {k: ficha.get(k) for k in ("fuente", "id", "titulo", "autor", "duracion",
                                            "licencia", "pagina", "descarga", "escucha")}
        limpio["papel"] = papel
        surtido[papel] = [limpio]
        if papel not in fijos:
            fijos.append(papel)
    else:
        # A AUTOMATICO: el surtido de FreeSound otra vez (se busca al montar)
        surtido.pop(papel, None)
        fijos = [p for p in fijos if p != papel]
    al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
    ctx.estado.actualizar_params("render", {"efectos": surtido, "efectos_fijos": fijos})
    trabajo_id = None
    if datos.get("remontar"):
        # los efectos se mezclan al montar el MP4: no se dibuja ni se surte nada
        trabajo_id = _remontar_si_estaba_al_dia(ctx, al_dia, montado,
                                                "volver a mezclar los efectos")
    ctx.bitacora.anotar("efecto_fijado", "render",
                        {"papel": papel, "efecto": (ficha or {}).get("titulo")})
    if trabajo_id is None:
        _apuntar_montaje_pendiente(ctx)
    lista = [dict(f, muestra=f"/api/efectos/{sonido._nombre_de(f)}")
             for f in (surtido.get(papel) or []) if isinstance(f, dict)]
    return {"papel": papel, "fijos": fijos, "efectos": lista,
            "trabajo_id": trabajo_id, "montado": montado}


@app.get("/api/efectos/{archivo}")
def servir_efecto(archivo: str, peticion: Request):
    """Sirve un efecto del banco del canal, para poder oírlo antes de vetarlo.

    Del BANCO y no del enlace de Freesound a propósito: lo que hay que escuchar
    es el fichero que va a sonar en el vídeo, que es este. El de Freesound puede
    haber cambiado, o no estar, y entonces se vetaría a ciegas.
    """
    sonido = _sonido()
    destino = ruta_segura(sonido.banco("efectos"), archivo)
    if not os.path.isfile(destino):
        raise ErrorApi(404, f"no hay ningún efecto {archivo!r} en el banco")
    return servir_fichero(peticion, destino)


@app.post("/api/proyectos/{pid}/sonido/vetados")
def vetar_efecto(pid: str, cuerpo: dict = Body(default=None)):
    """Prohíbe un efecto en TODO el canal, o levanta el veto con `quitar`.

    Es la contraparte de `camara_vetada` para el sonido, con una diferencia que
    importa: la cámara se veta para UN plano de UN vídeo, y un sonido que no
    gusta no gusta nunca más. Por eso el veto es del canal y vive al lado del
    banco, no en los params del proyecto.

    Y NO SE BORRA EL FICHERO. Freesound ordena por descargas: borrarlo sólo
    consigue que la siguiente búsqueda lo vuelva a bajar.
    """
    ctx = contexto(pid)                # el proyecto tiene que existir
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    ficha = datos.get("efecto") if isinstance(datos.get("efecto"), dict) else None
    clave = str(datos.get("clave") or "").strip() or (
        sonido.clave_de(ficha) if ficha else "")
    if not clave:
        raise ErrorApi(400, "hace falta 'clave' o 'efecto' con fuente e id")
    # CON `remontar`, el video montado se vuelve a MEZCLAR ya sin (o con) ese
    # sonido: vetar no toca ningun param, asi que el montaje seguiria «al dia»
    # con el efecto dentro y no habria boton que lo quitara (11-10-2026).
    # el veto se apunta SIEMPRE; si se esta montando (o buscando efectos) solo
    # se deja el remontaje para el siguiente montaje
    remontar = bool(datos.get("remontar")) and _trabajo_activo(ctx, "render") is None
    al_dia, montado = _antes_de_cambiar_el_montaje(ctx) if remontar else (False, False)
    if datos.get("quitar"):
        quitado = sonido.desvetar(clave)
        trabajo_id = _remontar_si_estaba_al_dia(ctx, al_dia, montado, "volver a mezclar los efectos") \
            if remontar and quitado else None
        if quitado and trabajo_id is None:
            # un veto no toca ningún param: sin la marca, «Aplicar» no sabría
            # que hay que volver a mezclar
            _apuntar_montaje_pendiente(ctx, mezcla=True)
        return {"vetado": False, "quitado": quitado, "trabajo_id": trabajo_id,
                "vetados": [sonido.vetados()[k] for k in sorted(sonido.vetados())]}
    try:
        entrada = sonido.vetar(ficha or clave, papel=datos.get("papel"),
                               motivo=str(datos.get("motivo") or ""))
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    trabajo_id = _remontar_si_estaba_al_dia(ctx, al_dia, montado, "volver a mezclar los efectos") \
        if remontar else None
    if trabajo_id is None:
        _apuntar_montaje_pendiente(ctx, mezcla=True)
    return {"vetado": True, "efecto": entrada, "trabajo_id": trabajo_id,
            "vetados": [sonido.vetados()[k] for k in sorted(sonido.vetados())]}


#: Cuanto se oyen los efectos, en tres palabras (`render.efectos_db`, que el
#: mezclador ya entendia y solo se podia tocar con una nota del repaso).
VOLUMEN_EFECTOS = {"bajos": -8.0, "normales": 0.0, "altos": 4.0}


def _volumen_de_efectos(db):
    try:
        valor = float(db or 0.0)
    except (TypeError, ValueError):
        valor = 0.0
    return min(VOLUMEN_EFECTOS, key=lambda k: abs(VOLUMEN_EFECTOS[k] - valor))


@app.put("/api/proyectos/{pid}/sonido/efectos/volumen")
def cambiar_volumen_efectos(pid: str, cuerpo: dict = Body(default=None)):
    """Fija cuánto se oyen los efectos ({nivel: bajos|normales|altos}) y, si
    el vídeo ya está montado y al día, lo vuelve a MEZCLAR (no se dibuja nada).
    No se escribe nada si lo pedido es lo que ya suena (regla 1)."""
    ctx = contexto(pid)
    nivel = str(_cuerpo(cuerpo).get("nivel") or "").strip().lower()
    if nivel not in VOLUMEN_EFECTOS:
        raise ErrorApi(400, "«nivel» tiene que ser: " + ", ".join(VOLUMEN_EFECTOS))
    render = ctx.estado.params("render") or {}
    actual = _volumen_de_efectos(render.get("efectos_db"))
    if nivel == actual:
        return {"nivel": actual, "cambiado": False, "trabajo_id": None}
    al_dia, montado = _antes_de_cambiar_el_montaje(ctx)
    ctx.estado.actualizar_params("render", {"efectos_db": VOLUMEN_EFECTOS[nivel]})
    ctx.bitacora.anotar("efectos_volumen", "render", {"antes": actual, "ahora": nivel})
    trabajo_id = _remontar_si_estaba_al_dia(ctx, al_dia and _remontar_pedido(_cuerpo(cuerpo)),
                                            montado, "volver a mezclar los efectos")
    if trabajo_id is None:
        _apuntar_montaje_pendiente(ctx)
    return {"nivel": nivel, "cambiado": True, "trabajo_id": trabajo_id, "montado": montado}


@app.post("/api/proyectos/{pid}/sonido/efectos", status_code=202)
def surtir_efectos(pid: str, cuerpo: dict = Body(default=None)):
    """Llena el banco de efectos del canal para los papeles que se pidan.

    Va en un trabajo porque baja ficheros: cuatro papeles son una veintena de
    peticiones a Freesound y otras tantas descargas.
    """
    ctx = contexto(pid)
    sonido = _sonido()
    datos = _cuerpo(cuerpo)
    pedidos = _lista_de_textos(datos, "papeles") or list(sonido.PAPELES)
    desconocidos = [p for p in pedidos if p not in sonido.PAPELES]
    if desconocidos:
        raise ErrorApi(400, f"papeles desconocidos: {', '.join(desconocidos)}. "
                            f"Los que hay son: {', '.join(sonido.PAPELES)}")
    if not sonido.hay_claves()[1]:
        raise ErrorApi(409, "falta la clave de FreeSound: ponla en Configuración")
    # 'salteado' rota por qué consulta se empieza: volver a pulsar trae OTROS
    # sonidos en vez de los mismos, que es lo que se espera de «buscar más».
    salteado = int(datos.get("salteado") or 0)
    trabajo_id = ctx.gestor.lanzar("efectos", _correr_surtir_efectos, ctx,
                                   list(pedidos), salteado, paso="render")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


