# ----------------------------------------------------------- presets de canal
# Lo que se decide una vez por canal (idioma, estilo grafico, ritmo, voz) y se
# repite igual en todos sus videos. Viven FUERA de los proyectos porque un canal
# sobrevive a cualquier video suyo.
#
# Aplicar COPIA los valores a los params del paso que toque; no se guarda el
# nombre del preset en ningun sitio. Asi, borrar un preset no puede romper un
# video ya terminado -- que es justo lo que pasa con los presets de voz escritos
# en el codigo, donde un nombre desconocido lanza ValueError.

def _presets():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.presets_canal


def _preset_o_400(tarea):
    """Traduce el fallo del modulo a un 400 con su mensaje, no a un 500 mudo."""
    presets = _presets()
    try:
        return tarea(presets)
    except presets.ErrorPreset as fallo:
        raise ErrorApi(400, str(fallo))


@app.get("/api/presets-canal")
def listar_presets_canal():
    """Presets guardados, agrupados por tipo, mas su papelera y el catalogo."""
    return _preset_o_400(lambda p: p.listar())


@app.post("/api/presets-canal")
def guardar_preset_canal(cuerpo: dict = Body(default=None)):
    """Guarda un preset nuevo, o sustituye el contenido de uno que ya existe."""
    datos = _cuerpo(cuerpo)
    ficha = _preset_o_400(lambda p: p.guardar(
        datos.get("tipo"), datos.get("nombre"), datos.get("datos"),
        nota=datos.get("nota") or "", miniatura=datos.get("miniatura") or "",
        pid=datos.get("id") or None))
    # LA FICHA DEL NEGOCIO, AL MOMENTO (Etapa Foto C, decisión del dueño 28-10):
    # guardar aquí un estilo de canal (p. ej. «Guardar como estilo» desde un
    # vídeo, o sustituir su contenido) puede dejarlo en foto y con láminas sin
    # el negocio de su proyecto. Se le pone ya; sin ficha en el proyecto, o en
    # un estilo de dibujo, no se escribe nada (lo general, como hasta ahora).
    if ficha.get("tipo") == "canal":
        try:
            antes = ((ficha.get("datos") or {}).get("estilo") or {}).get("dominio") or ""
            if _negocio_al_estilo(ficha["id"]) != antes:
                ficha = _presets().leer(ficha["id"])
        except Exception as fallo:                           # noqa: BLE001
            anotar_global("aviso", {"negocio": str(fallo), "preset": ficha.get("id")})
    anotar_global("preset_guardado", {"id": ficha["id"], "tipo": ficha["tipo"],
                                      "nombre": ficha["nombre"]})
    return {"preset": ficha, **_presets().listar()}


@app.patch("/api/presets-canal/{pid}")
def renombrar_preset_canal(pid: str, cuerpo: dict = Body(default=None)):
    """Cambia solo el nombre o la nota. Lo que el preset guarda no se toca."""
    datos = _cuerpo(cuerpo)
    ficha = _preset_o_400(lambda p: p.renombrar(
        pid, nombre=datos.get("nombre"), nota=datos.get("nota")))
    anotar_global("preset_renombrado", {"id": pid, "nombre": ficha["nombre"]})
    return {"preset": ficha, **_presets().listar()}


@app.get("/api/presets-canal/{pid}/miniatura")
def miniatura_preset_canal(pid: str, peticion: Request):
    """La cara del preset en el desplegable: uno de sus propios fotogramas."""
    ficha = _preset_o_400(lambda p: p.leer(pid))
    presets = _presets()
    # LA RUTA GUARDADA NO SE USA TAL CUAL, solo su nombre: la miniatura vive
    # dentro de la carpeta del preset y solo ahi, asi que una ficha escrita en
    # otra maquina --o antes de mover el banco-- trae una ruta que aqui no
    # existe. `ruta_de_miniatura` la vuelve a pegar a la carpeta de ahora.
    ruta = presets.ruta_de_miniatura(ficha)
    # y se comprueba igual que antes: la ficha es un JSON que alguien puede
    # editar a mano, y una ruta suelta serviria cualquier fichero del disco
    carpeta = os.path.abspath(presets.carpeta_de(pid))
    if not ruta or not os.path.abspath(ruta).startswith(carpeta + os.sep):
        raise ErrorApi(404, f"el preset {pid} no tiene miniatura")
    if not os.path.isfile(ruta):
        raise ErrorApi(404, f"la miniatura del preset {pid} ya no está en el disco")
    return servir_fichero(peticion, ruta)


@app.get("/api/presets-canal/{pid}/fichero/{archivo:path}")
def fichero_preset_canal(pid: str, archivo: str, peticion: Request):
    """Un fichero de la carpeta del preset (fotogramas, laminas del moodboard).

    Existe para poder PREVISUALIZAR un preset entero: sus referencias viven en
    banco/presets/<id>/ y, sin esto, la unica cara visible era la miniatura y
    el resto se listaba como rutas de texto.
    """
    _preset_o_400(lambda p: p.leer(pid))
    presets = _presets()
    carpeta = os.path.abspath(presets.carpeta_de(pid))
    try:
        destino = ruta_contenida(carpeta, archivo)
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    if not os.path.isfile(destino):
        raise ErrorApi(404, f"el preset {pid} no tiene el fichero {archivo!r}")
    return servir_fichero(peticion, destino)


@app.delete("/api/presets-canal/{pid}")
def apartar_preset_canal(pid: str):
    """A la papelera. No borra nada: la ficha y sus fotogramas siguen enteros."""
    ficha = _preset_o_400(lambda p: p.apartar(pid))
    anotar_global("preset_apartado", {"id": pid, "tipo": ficha.get("tipo"),
                                      "nombre": ficha.get("nombre")})
    return {"apartado": pid, "preset": ficha,
            "aviso": "sigue entero en la papelera; se puede devolver",
            **_presets().listar()}


@app.post("/api/presets-canal/papelera/{pid}/restaurar")
def restaurar_preset_canal(pid: str):
    """Devuelve a la lista un preset apartado. Y si es un estilo, su taller con
    él: se apartaron juntos (`borrar_preset_light`) y sin el taller el estilo
    vuelve sin sus láminas ni su escucha."""
    ficha = _preset_o_400(lambda p: p.restaurar(pid))
    # mientras estuvo en la papelera pudo cambiar la ficha de su proyecto
    if PASOS_MODULOS is not None:
        _negocio_al_estilo(pid)
    taller = ((ficha.get("datos") or {}).get("origen") or {}).get("taller") if isinstance(ficha, dict) else ""
    devuelto = ""
    if taller and not os.path.isdir(os.path.join(raiz_proyectos(), taller)):
        base = raiz_papelera()
        candidatas = sorted((n for n in (os.listdir(base) if os.path.isdir(base) else [])
                             if n.rpartition("__")[0] == taller), reverse=True)
        if candidatas:
            try:
                restaurar_proyecto(candidatas[0])
                devuelto = taller
            except ErrorApi:
                devuelto = ""
    return {"restaurado": pid, "preset": ficha, "taller": devuelto, **_presets().listar()}


@app.get("/api/presets-canal/papelera/{pid}")
def peso_preset_canal(pid: str):
    """Que hay dentro de un preset apartado, para decir que se pierde."""
    return _preset_o_400(lambda p: p.peso(pid))


@app.delete("/api/presets-canal/papelera/{pid}")
def borrar_preset_canal(pid: str, confirmar: int = Query(default=0)):
    """Borrado definitivo. Solo alcanza a lo que ya esta en la papelera."""
    salida = _preset_o_400(lambda p: p.borrar(pid, confirmar=bool(confirmar)))
    anotar_global("preset_borrado", salida)
    return {**salida, **_presets().listar()}


@app.post("/api/proyectos/{pid}/presets-canal/{preset_id}/aplicar")
def aplicar_preset_canal(pid: str, preset_id: str):
    """Copia los valores del preset a los params de los pasos que toque.

    Se aplica en el SERVIDOR y no en la interfaz porque quien sabe que clave va
    a que paso es el catalogo de tipos, y porque el estilo tiene que fusionarse
    con lo que ya hubiera en assets.estilo (el prompt escrito a mano de los
    proyectos antiguos vive ahi). Repartir esa regla entre los dos lados es como
    se acaba con dos versiones que se contradicen.
    """
    ctx = contexto(pid)
    presets = _presets()
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    actuales = {paso: (ctx.estado.params(paso) or {})
                for paso in presets.TIPOS[ficha["tipo"]]["pasos"]}
    cambios = _preset_o_400(lambda p: p.cambios_para(ficha, actuales))
    # Las referencias dibujadas que guarda el preset vuelven al banco global si
    # alli ya no estan. Normalmente no hace nada: la clave sale de la huella de
    # los fotogramas, y los del preset son copia byte a byte de los originales.
    devueltas = presets.restaurar_moodboard(ficha)

    # actualizar_params devuelve si el paso ha cambiado de firma de verdad:
    # aplicar un preset que ya estaba puesto no obsoleta nada, y decirlo evita
    # el aviso de "queda obsoleto todo" cuando no ha pasado nada
    cambiados = {paso: bool(ctx.estado.actualizar_params(paso, valores))
                 for paso, valores in cambios.items()}
    ctx.bitacora.anotar("preset_aplicado", None, {
        "id": preset_id, "tipo": ficha["tipo"], "nombre": ficha.get("nombre"),
        "pasos": sorted(cambios),
        "cambiados": sorted(p for p, c in cambiados.items() if c)})
    afectados = {p for p, c in cambiados.items() if c}
    return {
        "aplicado": preset_id, "preset": presets.publicar(ficha),
        "moodboard_devuelto": devueltas.get("ejes") or [],
        "pasos": sorted(cambios), "cambiados": cambiados,
        "estado": {paso: ctx.estado.estado_de(paso) for paso in cambios},
        "aguas_abajo": sorted({h for paso in afectados for h in descendientes_de(paso)}
                              - afectados),
    }


# ==========================================================================
# MODO LIGHT: el preset de canal entero, de una tirada
#
# La tabla de tareas, los tiempos y la miniatura viven en `pasos/presets_light`;
# aqui vive lo unico que no cabe alli: QUE FUNCION corre cada tarea. Y es a
# proposito la MISMA que corre su boton del modo editor -- no hay un camino
# "automatico" y otro "a mano", porque entonces habria dos comportamientos que
# mantener y uno de los dos se quedaria viejo. Misma regla que las recetas.
#
# EL TALLER. Todo esto necesita un proyecto: ahi viven los fotogramas, los params
# y la bitacora. Asi que cada preset tiene el suyo, oculto de la lista de
# proyectos (`config['taller_de_preset']`) y borrado con el. Que se quede
# despues de guardar es lo que hace barato corregir: rehacer la guia no vuelve a
# bajar el video.
# ==========================================================================

CONFIG_TALLER = "taller_de_preset"


def _light():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.presets_light


def _encargo_o_400(cuerpo):
    try:
        return _light().validar_encargo(cuerpo)
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(400, str(fallo))


def _crear_taller(encargo):
    """Un proyecto oculto donde generar este preset. -> ctx"""
    os.makedirs(raiz_proyectos(), exist_ok=True)
    base = f"taller {encargo['nombre']}"[:60]
    nombre, intento = base, 1
    while os.path.isdir(os.path.join(raiz_proyectos(), identificador(nombre))):
        intento += 1
        nombre = f"{base} {intento}"
    try:
        proyecto = Proyecto.crear(raiz_proyectos(), nombre)
    except OSError as fallo:
        raise ErrorApi(500, f"no se ha podido crear el taller del preset: {fallo}")
    ctx = contexto(proyecto.id)
    ctx.proyecto.config[CONFIG_TALLER] = True
    ctx.proyecto.guardar_config()
    return ctx


#: Donde esperan las imagenes que se suben junto a una descripcion, ANTES de que
#: exista el taller. Se suben mientras se rellena el formulario y el taller no
#: nace hasta pulsar «Generar», asi que hace falta un sitio intermedio; al crear
#: el preset se copian dentro del taller y esto se vacia.
CARPETA_APORTADAS = "_imagenes_aportadas"

#: Lo que se acepta subir. Las mismas que sabe abrir el CLI y que sabe
#: normalizar el motor de imagen.
EXT_APORTADAS = (".png", ".jpg", ".jpeg", ".webp")

#: Tope por fichero. Un fotograma de un video pesa decimas de mega; diez son de
#: sobra para una captura de pantalla o una foto de movil, y ponen un techo a lo
#: que puede llenar el disco alguien que arrastre una carpeta entera.
MAX_BYTES_APORTADA = 10 * 1024 * 1024

#: Lado minimo, en pixeles, de una imagen de referencia. Por debajo no hay estilo
#: que copiar: es un icono. Bajo a proposito -- esto para lo que no sirve, no
#: juzga si una imagen es buena.
MIN_LADO_APORTADA = 64

#: Pixeles como mucho. Sobra para la foto de cualquier movil (50 MP) y pone
#: techo a lo que cuesta en memoria abrirla para revisarla.
MAX_PIXELES_APORTADA = 60_000_000


def _motivo_para_no_aceptar(contenido, origen, de_estilo=True):
    """Por que esta imagen NO vale como referencia de estilo, o None si vale.

    `de_estilo=False` (el logo y las imagenes del repaso, R3 del analisis del
    13-10-2026) mira solo lo que rompe algo: que se pueda abrir de punta a punta
    y que no sea gigante. Un logo de texto de 200×40 o una muestra de un solo
    color («este rojo») son legitimos ahi, aunque no sirvan para copiar un estilo.

    SE MIRA AL SUBIRLA, que es cuando se puede decir. Antes solo se miraban la
    extension y el peso: un «.jpg» que no era una imagen salia como miniatura
    rota, el boton Generar se habilitaba, y el estilo trabajaba dos minutos con
    Claude para caerse al 92 % con un `UnidentifiedImageError` -- perdiendo el
    formulario y dejando un taller huerfano (M4 del informe de la Etapa Foto A).

    Tres cosas, las tres medidas en ese informe: que se pueda ABRIR (de punta a
    punta: `verify` solo mira la cabecera, y un fichero cortado pasa), que no
    sea diminuta y que no sea de un solo color (toda negra, toda blanca). Sin
    PIL no se mira nada: es lo de antes, y no se rompe la subida por ello.
    """
    try:
        from PIL import Image, ImageStat  # noqa: PLC0415 - perezoso, como en las miniaturas
    except ImportError:
        return None
    import io  # noqa: PLC0415
    # SOLO LOS FORMATOS QUE SE ACEPTAN (EXT_APORTADAS): `Image.open` abriria
    # cualquier cosa que PIL conozca, y alguno (EPS) llama a un programa externo
    formatos = ["PNG", "JPEG", "WEBP"]
    try:
        with Image.open(io.BytesIO(contenido), formats=formatos) as imagen:
            imagen.verify()
        with Image.open(io.BytesIO(contenido), formats=formatos) as imagen:
            ancho, alto = imagen.size
            # ANTES de descomprimir: diez megas de PNG liso pueden ser cien
            # millones de pixeles y casi un giga de memoria al abrirlos
            if ancho * alto > MAX_PIXELES_APORTADA:
                return (f"«{origen}» mide {ancho}×{alto} px: es demasiado grande "
                        f"(como mucho {MAX_PIXELES_APORTADA // 1_000_000} "
                        f"megapíxeles)")
            if de_estilo and min(ancho, alto) < MIN_LADO_APORTADA:
                return (f"«{origen}» mide {ancho}×{alto} px: es demasiado pequeña "
                        f"para copiar un estilo de ella (mínimo "
                        f"{MIN_LADO_APORTADA} px de lado)")
            imagen.load()
            if not de_estilo:
                return None
            # CON LA TRANSPARENCIA: un logo negro sobre fondo transparente tiene
            # todo el dibujo en el canal alfa, y no es de un solo color
            muestra = imagen.convert("RGBA")
            muestra.thumbnail((256, 256))
            if max(ImageStat.Stat(muestra).stddev) < 1.0:
                return (f"«{origen}» es entera de un solo color: no hay nada "
                        f"que copiar de ella")
    except Exception:                                       # noqa: BLE001
        return (f"«{origen}» no se puede abrir como imagen: el fichero está "
                f"dañado o no es una imagen de verdad")
    return None


def _carpeta_aportadas():
    return os.path.join(raiz_proyectos(), CARPETA_APORTADAS)


def _rutas_aportadas(nombres):
    """De los nombres que devolvio la subida a rutas de verdad. -> [rutas]

    Se valida el nombre y se comprueba que el fichero este: lo que llega es una
    lista que ha viajado por el navegador, y componer una ruta con ella sin
    mirar es como se sale de la carpeta.
    """
    carpeta = _carpeta_aportadas()
    rutas = []
    for nombre in nombres or []:
        limpio = os.path.basename(str(nombre or "").strip())
        if not limpio or not FICHERO_WEB.match(limpio):
            continue
        ruta = os.path.join(carpeta, limpio)
        if os.path.isfile(ruta):
            rutas.append(ruta)
    return rutas


def _carpeta_aportadas_de(ctx):
    return os.path.join(ctx.proyecto.raiz, "estilo", "aportadas")


def _aportadas_del_taller(ctx):
    """Las imagenes de apoyo que se subieron con la descripcion. -> [rutas]

    SE LEEN DE SU CARPETA Y NO DE `estilo.referencias`, y esa es la parte que
    importa: sin video, `referencias` acaba siendo lo que DIBUJA el paso de
    laminas (`_correr_light_referencias`), asi que guardarlas ahi hacia que al
    rehacer el estilo la guia se mirara su propia salida en vez del material que
    dio una persona. Cada cosa en su sitio.
    """
    carpeta = _carpeta_aportadas_de(ctx)
    if not os.path.isdir(carpeta):
        return []
    return [os.path.join(carpeta, n) for n in sorted(os.listdir(carpeta))
            if os.path.splitext(n)[1].lower() in EXT_APORTADAS]


def _sembrar_aportadas(ctx, encargo, conservar=None):
    """Mete en el taller las imagenes subidas, y vacia la carpeta de espera.

    EN EL TALLER: es lo que sobrevive al preset y lo que permite rehacer el
    estilo sin volver a pedir nada. La carpeta de espera es un buzon, no un
    almacen -- lo que se copia se borra de ahi, o se queda para siempre.

    `conservar` (nombres sin «NN_») son las del taller que SIGUEN: la ficha de
    un estilo deja quitar unas y anadir otras sin volver a subir las demas.
    `None` es lo de siempre: las nuevas sustituyen a todas.
    """
    rutas = _rutas_aportadas(encargo.get("estilo_imagenes"))
    if conservar is not None:
        destino = _carpeta_aportadas_de(ctx)
        sin = _light()._sin_prefijo
        quedan = set(str(n) for n in conservar)
        viejas = [r for r in _aportadas_del_taller(ctx) if sin(r) in quedan]
        if not viejas and not rutas:
            raise RuntimeError("el estilo se quedaría sin ninguna imagen de referencia")
        apartado = destino + ".conservar"
        shutil.rmtree(apartado, ignore_errors=True)
        os.makedirs(apartado, exist_ok=True)
        guardadas = []
        for ruta in viejas:
            final = os.path.join(apartado, sin(ruta))
            shutil.copyfile(ruta, final)
            guardadas.append(final)
        shutil.rmtree(destino, ignore_errors=True)
        os.makedirs(destino, exist_ok=True)
        dentro = []
        for indice, ruta in enumerate(guardadas + rutas):
            final = os.path.join(destino, _presets().nombre_numerado(indice, ruta))
            try:
                shutil.copyfile(ruta, final)
            except OSError:
                continue
            dentro.append(final)
            if ruta in rutas:
                try:
                    os.remove(ruta)
                except OSError:
                    pass
        shutil.rmtree(apartado, ignore_errors=True)
        return dentro
    if not rutas:
        # sin nada nuevo NO se borra lo que ya hubiera: retomar un taller a
        # medias tiene que conservar el material con el que se lanzo
        return _aportadas_del_taller(ctx)
    destino = _carpeta_aportadas_de(ctx)
    shutil.rmtree(destino, ignore_errors=True)
    os.makedirs(destino, exist_ok=True)
    dentro = []
    for indice, ruta in enumerate(rutas):
        final = os.path.join(destino, _presets().nombre_numerado(indice, ruta))
        try:
            shutil.copyfile(ruta, final)
        except OSError:
            continue
        dentro.append(final)
        try:
            os.remove(ruta)
        except OSError:
            pass            # que no se vacie el buzon no puede tumbar la tanda
    return dentro


@app.post("/api/presets-light/imagenes", status_code=201)
async def subir_imagenes_light(peticion: Request):
    """Guarda las imagenes que acompanan a una descripcion de estilo.

    Se suben ANTES de crear nada --el taller no existe hasta pulsar «Generar»--
    y por eso esperan en una carpeta aparte. Devuelve el nombre con el que se han
    guardado, que es lo que el navegador manda despues en `estilo_imagenes`.
    """
    tipo = (peticion.headers.get("content-type") or "").lower()
    if not tipo.startswith("multipart/"):
        raise ErrorApi(400, "manda las imágenes como multipart")
    try:
        formulario = await peticion.form()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(400, f"multipart ilegible: {fallo}")

    carpeta = _carpeta_aportadas()
    await _en_hilo(os.makedirs, carpeta, exist_ok=True)
    guardadas, avisos = [], []
    for _clave, valor in formulario.multi_items():
        if not hasattr(valor, "read"):
            continue
        origen = os.path.basename(str(getattr(valor, "filename", "") or ""))
        extension = os.path.splitext(origen)[1].lower()
        if extension not in EXT_APORTADAS:
            avisos.append(f"«{origen or 'sin nombre'}» no es una imagen de las "
                          f"que se pueden abrir ({', '.join(EXT_APORTADAS)})")
            continue
        contenido = await valor.read()
        if len(contenido) > MAX_BYTES_APORTADA:
            avisos.append(f"«{origen}» pesa "
                          f"{len(contenido) / 1024 / 1024:.1f} MB y el tope son "
                          f"{MAX_BYTES_APORTADA // 1024 // 1024}")
            continue
        # que de verdad sea una imagen que sirva, AHORA y no al 92 % del estilo
        motivo = await asyncio.to_thread(_motivo_para_no_aceptar, contenido, origen)
        if motivo:
            avisos.append(motivo)
            continue
        # nombre propio: dos ficheros distintos pueden llamarse igual, y el
        # segundo se llevaria al primero por delante
        sello = uuid.uuid4().hex[:12]
        nombre = f"{sello}{extension}"
        await _en_hilo(_escribir_bytes, os.path.join(carpeta, nombre), contenido)
        guardadas.append({"nombre": nombre, "origen": origen,
                          "bytes": len(contenido)})
    if not guardadas and avisos:
        raise ErrorApi(400, "no se ha podido guardar ninguna: " + "; ".join(avisos))
    return {"imagenes": guardadas, "avisos": avisos,
            "tope": await _en_hilo(lambda: _light().max_imagenes_estilo())}


@app.get("/api/presets-light/imagenes/{nombre}")
def servir_imagen_light(nombre: str, peticion: Request):
    """La miniatura de una imagen que espera en el buzon."""
    rutas = _rutas_aportadas([nombre])
    if not rutas:
        raise ErrorApi(404, f"esa imagen no está: {nombre}")
    return servir_fichero(peticion, rutas[0])


@app.delete("/api/presets-light/imagenes/{nombre}")
def borrar_imagen_light(nombre: str):
    """Quita una imagen de la carpeta de espera. Quitarla de la lista es esto."""
    rutas = _rutas_aportadas([nombre])
    if not rutas:
        raise ErrorApi(404, f"esa imagen ya no está: {nombre}")
    try:
        os.remove(rutas[0])
    except OSError as fallo:
        raise ErrorApi(500, f"no se ha podido borrar: {fallo}")
    return {"borrada": os.path.basename(rutas[0])}


def _talleres_sueltos():
    """Talleres sin preset: intentos que se quedaron a medias. -> [ficha]

    Un taller nace ANTES que su preset —el preset se guarda al final, con lo que
    el taller produjo—, asi que una generacion que falla deja la carpeta sin
    nadie que la borre: son cientos de megas y unos fotogramas que ya no puede
    aplicar nadie.

    En vez de barrerlos por edad —borrar solo, por reloj, lo que quiza estabas a
    punto de retomar— se ENSENAN en la galeria con sus dos salidas: retomarlo
    (que se salta lo que ya salio bien) o descartarlo. Es la misma regla que la
    papelera: nada se pierde sin que alguien lo diga.
    """
    presets = _presets()
    guardado = _preset_o_400(lambda p: p.listar())
    usados = set()
    for grupo in (list((guardado.get("presets") or {}).values())
                  + [guardado.get("papelera") or []]):
        for ficha in grupo:
            tid = ((ficha.get("datos") or {}).get("origen") or {}).get("taller")
            if tid:
                usados.add(str(tid))
    sueltos = []
    for ficha in _listar_proyectos():
        if not ficha.get(CONFIG_TALLER):
            continue
        if str(ficha.get("id")) in usados:
            continue
        sueltos.append({"id": ficha.get("id"),
                        "cliente": ficha.get("cliente_del_taller") or "",
                        "nombre": ficha.get("nombre") or ficha.get("id"),
                        "creado": ficha.get("creado", ""),
                        "actualizado": ficha.get("actualizado", "")})
    sueltos.sort(key=lambda f: str(f.get("actualizado") or ""), reverse=True)
    return sueltos


def _taller_de(ficha):
    """El taller de un preset ya guardado, o 409 si ya no esta.

    Se dice en voz alta en vez de crear uno nuevo: un taller nuevo no tiene los
    fotogramas, asi que rehacer el estilo volveria a bajar el video sin avisar y
    la correccion tardaria diez minutos en vez de dos.
    """
    tid = ((ficha.get("datos") or {}).get("origen") or {}).get("taller")
    if not tid:
        raise ErrorApi(409, "este preset no se hizo en el modo light, así que no "
                            "tiene taller donde rehacer una parte. Edítalo desde "
                            "el modo editor, o crea uno nuevo aquí")
    try:
        return contexto(tid)
    except ErrorApi:
        raise ErrorApi(409, f"el taller de este preset ({tid}) ya no está en el "
                            f"disco: no se puede rehacer una parte sin el "
                            f"material con el que se hizo. Crea un preset nuevo")


def _sembrar_voz(ctx, cambios):
    """Los mandos de voz del estilo, tambien en su taller.

    El taller es de donde sale la ESCUCHA y de donde saldria una regeneracion,
    asi que dejarlo con la voz anterior haria que lo que oyes no sea lo que has
    elegido -- el fallo mudo de tener el mismo dato en dos sitios.
    """
    ctx.estado.actualizar_params("voz", dict(cambios))
    return cambios


def _sembrar_taller(ctx, encargo):
    """Escribe en el taller lo que se decide con un mando: el idioma y el ritmo.

    NADA DE ESTO ES LOGICA NUEVA. Son los mismos params que escribe el modo
    editor a mano —`assets.min_s/max_s/min_s_rotulos` en la tarjeta de estilo,
    `voz.hueco_minimo` en la de voz— y las mismas claves que ya guarda un preset
    de canal. El ritmo no toca el segmentador ni las cabeceras: rellena.
    """
    light = _light()
    idioma = encargo["idioma"]
    ctx.estado.actualizar_params("brief", {"idioma_salida": idioma})
    ctx.estado.actualizar_params("voz", {"idioma": idioma})
    # LA VARIANTE (espanol de Latinoamerica), al guion. Solo si cambia: un taller
    # que nunca la tuvo no recibe una clave vacia que moveria su firma.
    variante = str(encargo.get("variante_idioma") or "")
    if variante != str((ctx.estado.params("guion") or {}).get("variante_idioma") or ""):
        ctx.estado.actualizar_params("guion", {"variante_idioma": variante})
    # Y LAS LLAMADAS A LA ACCION, que tambien son un mando: se eligen al crear
    # el estilo y de aqui salen a su preset de guion (`datos_de_params`), que es
    # lo que hace que cada video nazca con ellas puestas.
    if encargo.get("cta"):
        ctx.estado.actualizar_params("guion", {"cta": encargo["cta"]})
    for paso, valores in light.params_de_ritmo(encargo.get("ritmo")).items():
        ctx.estado.actualizar_params(paso, valores)
    _sembrar_modo(ctx, encargo)
    return idioma


def _sembrar_modo(ctx, encargo):
    """El tipo de imagen del encargo, a `assets.estilo.modo` del taller.

    Etapa Foto A. Es de donde lo leen la guia, las laminas y, al guardar, el
    preset. Solo si el encargo lo trae (los encargos a medias de idioma y ritmo
    no) y solo si cambia: "foto" se escribe, ilustracion es QUITARLO si estaba.
    Nunca se escribe "ilustracion": seria un param que el taller no tenia.
    """
    if "estilo_modo" not in (encargo or {}):
        return
    nuevo = _light().estilo_con_modo(
        (ctx.estado.params("assets") or {}).get("estilo"),
        encargo.get("estilo_modo"))
    if nuevo is not None:
        ctx.estado.actualizar_params("assets", {"estilo": nuevo})


# ------------------------------------------------------------ las ocho tareas

def _correr_light_guia(avisar, ctx, encargo):
    estilo = _estilo()
    peticion = (encargo.get("feedback") or {}).get("estilo") or ""
    # LAS IMAGENES SON LA FUENTE y lo escrito acompana: la guia se escribe
    # MIRANDOLAS, y las indicaciones son el «esto pero mas frio» que una imagen
    # no puede decir sola. Van aparte del feedback, que es de esta pasada y gana
    # si chocan.
    #
    # Se leen del TALLER y no del encargo: el encargo trae los nombres del buzon
    # y el buzon se vacia al copiarlas dentro.
    aportadas = _aportadas_del_taller(ctx)
    bloque = dict((ctx.estado.params("assets") or {}).get("estilo") or {})
    # LO QUE SE DIJO DE CADA IMAGEN viaja con las indicaciones, nombrando el
    # fichero tal y como lo abre la guia (`presets_light.indicaciones_con_...`)
    indicaciones = _light().indicaciones_con_descripciones(
        encargo.get("estilo_prompt"), aportadas,
        encargo.get("estilo_descripciones"))
    # con el contrato del tipo de imagen del taller (Etapa Foto A): una guia
    # de foto pregunta por lente y luz, no por trazo y dedos
    guia = estilo.generar_guia(ctx.proyecto, aportadas, avisar=avisar,
                               proyecto_id=ctx.id, peticion=peticion,
                               indicaciones=indicaciones,
                               modo=PASOS_MODULOS.p6_assets.modo_de(bloque))
    bloque["guia"] = guia
    ctx.estado.actualizar_params("assets", {"estilo": bloque})
    ctx.bitacora.anotar("guia_estilo", "assets", {
        "imagenes": len(guia.get("fotogramas") or []),
        "palabras": guia.get("palabras")})
    avisar(1.0, f"guía de {guia.get('palabras')} palabras")
    return guia


@_con_turno
def _correr_light_referencias(avisar, ctx, encargo):
    """Las laminas dibujadas, que SON las referencias del estilo.

    No son un moodboard encima de unos fotogramas: no hay fotogramas. Se dibujan
    a partir de la guia --que a su vez se escribio mirando las imagenes que
    adjuntaste-- y por eso se escriben en `referencias` y no se aprueba nada: no
    hay clave que aprobar.

    Y se dibujan en vez de usar tus imagenes tal cual a proposito: una lamina
    dibujada ya esta EN el estilo de salida, mientras que una foto de referencia
    trae su propio encuadre, su luz y su formato. Lo que cada plano copia tiene
    que parecerse al video, no a la fuente.

    LAS SEIS O UNA SOLA. `encargo["laminas"]` es {eje: "que cambiarle}, lo pone
    el reparto de la correccion (`enrutar_estilo.laminas_de`) y va por
    INVOCACION: describe lo que se corrige hoy, no lo que el estilo es. Vacio
    --que es el caso normal, y el unico que existia-- son las seis.

    El motor ya sabia hacer esto por los dos caminos (`ejes=`, `peticiones=`):
    se escribio para cuando derivan unos ejes y otros salen clavados. Lo que
    faltaba era que alguien se lo pidiera.
    """
    mod = _moodboard()
    lam = _laminas()
    calidad = str((ctx.estado.params("assets") or {}).get("calidad") or "medium")
    bloque = dict((ctx.estado.params("assets") or {}).get("estilo") or {})
    # LAS LAMINAS DE ESTE ESTILO (`laminas.py`): las seis de fabrica menos las
    # quitadas, mas las anadidas. Sin tocar nada son las seis de siempre.
    ids = lam.ids_de(encargo)
    # Se filtra contra las laminas que existen de verdad: una peticion escrita
    # para una inventada no daria error, dibujaria todas sin decirlo.
    peticiones = {eje: " ".join(str(texto).split())
                  for eje, texto in (encargo.get("laminas") or {}).items()
                  if eje in ids and str(texto or "").strip()}
    # `laminas_solo` (por INVOCACION, de la pantalla de laminas): redibujar
    # estas aunque no lleven correccion. Una lista VACIA es «no dibujes
    # ninguna, solo rehaz la lista» --quitar o devolver una lamina--.
    solo = encargo.get("laminas_solo")
    if isinstance(solo, list):
        pedidos = [e for e in ids if e in solo or e in peticiones]
        sin_dibujar = not pedidos
    else:
        pedidos = [e for e in ids if e in peticiones] or list(ids)
        sin_dibujar = False
    # EL IDIOMA DEL CANAL, hasta la lamina. Sin esto, un canal en espanol saca
    # el eje «diagrama» rotulado en ingles --paso: «PLAN / DO / REVIEW»-- porque
    # el encargo entero va en ingles y el generador rotula en el idioma en que
    # se le habla. Y esa lamina no se queda en la ficha del preset: viaja como
    # imagen de referencia dentro de cada plano que lleve un componente, o sea
    # que ensena a rotular mal con un ejemplo dibujado.
    idioma = str(encargo.get("idioma") or "").strip().lower()
    destino = os.path.join(ctx.proyecto.raiz, "estilo", "dibujadas")
    # LAS IMAGENES QUE SE SUBIERON, hasta el dibujo. Se leen del taller, igual
    # que la guia (`_correr_light_guia`): sin pasarlas, cada lamina salia a la
    # API sin adjuntos y la tanda caia con «generar() necesita al menos una
    # imagen de referencia» aunque el estilo tuviera catorce.
    aportadas = _aportadas_del_taller(ctx)
    _, propias, hoja = lam.config_de(encargo)
    # OCHO COMO MUCHO en la hoja: con 50 cada foto quedaria de 768x41
    # (`para_la_hoja`). Con «repartida» cada lamina mira OTRO grupo de ocho
    # --las marcadas con ★ en todos-- y entre todas cuentan todas tus imagenes.
    comun = _light().para_la_hoja(aportadas, encargo.get("estilo_descripciones"),
                                  destacadas=encargo.get("estilo_destacadas"))
    if hoja == "repartida" and len(aportadas) > len(comun):
        marcadas = {_light()._sin_prefijo(n)
                    for n in (encargo.get("estilo_destacadas") or [])}
        fijas = [r for r in aportadas if _light()._sin_prefijo(r) in marcadas]
        grupos = dict(zip(ids, lam.repartir(aportadas, len(ids),
                                            lam.MAX_LAMINAS, fijas)))
    else:
        grupos = {}
    # Las de fabrica sin cambiar y con la hoja comun van por el camino de
    # siempre (en paralelo); las cambiadas, las anadidas y las de hoja
    # repartida, una a una con su descripcion y su grupo de imagenes.
    de_fabrica = [e for e in pedidos if e in mod.EJES and not propias.get(e)
                  and e not in grupos]
    sueltas = [e for e in pedidos if e not in de_fabrica]
    hecho = {"rutas": [], "ejes": [], "coste_usd": 0.0}
    # El modo va con la guia (Etapa Foto A): sin el, las laminas de un estilo
    # de fotos se pedirian como imagen neutra. Solo si es foto: sin `modo`, el
    # diccionario de siempre.
    para_dibujar = {"guia": bloque.get("guia")}
    if bloque.get("modo") == "foto":
        para_dibujar["modo"] = "foto"
    if de_fabrica:
        parcial = mod.dibujar_desde_guia(
            para_dibujar, destino, ejes=de_fabrica,
            peticiones=peticiones, calidad=calidad,
            avisar=(avisar if not sueltas else
                    lambda v, m="": avisar(0.6 * float(v or 0), m)),
            idioma=idioma, referencias=comun,
            # pedirlas a proposito (la pantalla de laminas) es pedir otras:
            # solo una pasada que repite la que fallo reutiliza lo ya pagado
            reutilizar=not isinstance(solo, list))
        hecho["rutas"] += parcial["rutas"]
        hecho["ejes"] += parcial["ejes"]
        hecho["coste_usd"] += float(parcial.get("coste_usd") or 0.0)
    for indice, eje in enumerate(sueltas):
        base = 0.6 if de_fabrica else 0.0
        avisar(base + (1 - base) * indice / max(1, len(sueltas)),
               f"dibujando la lámina «{lam.titulo_de(eje, encargo)}»")
        descripcion = (mod.EJES[eje]["prompt"] if eje in mod.EJES
                       else lam.descripcion_extra(eje, encargo))
        parcial = lam.dibujar_suelta(
            para_dibujar, destino, eje, descripcion,
            calidad=calidad, idioma=idioma,
            peticion=lam.peticion_de(eje, encargo, peticiones.get(eje, "")),
            referencias=grupos.get(eje) or comun,
            reutilizar=not isinstance(solo, list))
        hecho["rutas"].append(parcial["ruta"])
        hecho["ejes"].append(eje)
        hecho["coste_usd"] += parcial["coste_usd"]
    hecho["coste_usd"] = round(hecho["coste_usd"], 4)
    # UN REDIBUJO ENTERO deja viejas las quitadas: su fichero se borra para
    # que «Devolver» la dibuje con la guia de ahora y no traiga la de antes
    if not isinstance(solo, list) and not peticiones:
        for eje in mod.EJES:
            if eje not in ids:
                try:
                    os.remove(os.path.join(destino, f"{eje}.png"))
                except OSError:
                    pass
    # LA LISTA SE REHACE DESDE EL DISCO, en el orden de las laminas. Cada una se
    # escribe en `<id>.png`, encima de la que habia, asi que las que no se han
    # redibujado siguen en su sitio. Escribir aqui solo lo recien dibujado
    # dejaria un estilo con UNA referencia: sin error, sin aviso, y con el
    # video montado despues sobre una sola lamina de apoyo. Una quitada sale de
    # la lista pero su fichero se queda: devolverla no cuesta nada.
    previas = {os.path.splitext(os.path.basename(str(r)))[0]: r
               for r in (bloque.get("referencias") or []) if r}
    lista = []
    for eje in ids:
        ruta = os.path.join(destino, f"{eje}.png")
        if os.path.isfile(ruta):
            lista.append(ruta)
        elif previas.get(eje) and os.path.isfile(previas[eje]):
            lista.append(previas[eje])
    bloque["referencias"] = lista[:lam.MAX_LAMINAS]
    ctx.estado.actualizar_params("assets", {"estilo": bloque})
    # LA PASADA HA TERMINADO BIEN: lo apuntado para no repagar un reintento ya
    # no es un intento a medias, y «Regenerar» tiene que dibujar otra de verdad
    mod.olvidar_laminas_apuntadas(destino)
    ctx.bitacora.anotar("estilo_dibujado", "assets", {
        "ejes": hecho["ejes"], "coste_usd": hecho["coste_usd"],
        "pedidos": pedidos if not sin_dibujar else "ninguna (solo la lista)",
        "laminas": ids, "hoja": hoja})
    if not sin_dibujar:
        avisar(1.0, f"{len(hecho['ejes'])} lámina(s) dibujadas, "
                    f"{hecho['coste_usd']:.3f} USD")
    else:
        avisar(1.0, f"{len(lista)} láminas en el estilo")
    return hecho


def _laminas():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.laminas


def _enrutar_estilo():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.enrutar_estilo


def _frase_del_estilo(encargo, antes, peticion):
    """Qué ha escrito de verdad para corregir el estilo. -> str

    Son DOS cajas y hay que mirar las dos, porque la que se usa no es la que
    parece: el bloque del estilo gráfico NO tiene caja de «qué le cambiarías»
    —se quitó a propósito— así que la corrección se escribe en «Indicaciones
    (opcional)», que viaja como `estilo_prompt` dentro de `origen`.

    Un enrutador que mirase sólo `feedback["estilo"]` no vería nunca nada: esa
    clave no la escribe nadie en la pantalla para el estilo.

    Del `estilo_prompt` sólo cuenta si CAMBIÓ: es una indicación permanente del
    preset («igual pero más frío»), no una corrección de esta pasada, y
    enrutarla otra vez en cada regeneración repetiría un cambio que ya está
    puesto.
    """
    if peticion:
        return peticion
    ahora = " ".join(str(encargo.get("estilo_prompt") or "").split())
    antes_prompt = " ".join(str((antes or {}).get("estilo_prompt") or "").split())
    return ahora if ahora and ahora != antes_prompt else ""


def _laminas_para_el_reparto(encargo):
    """{id: {titulo, que_se_ve}} de las laminas de ESTE estilo, en su orden:
    las de fabrica que quedan (con lo que se les cambio, si se cambio) y las
    añadidas con su descripcion."""
    lam = _laminas()
    mod = _moodboard()
    salida = {}
    for lamina in lam.ids_de(encargo):
        propia = lam.descripcion_extra(lamina, encargo)
        que = propia or (mod.EJES.get(lamina) or {}).get("prompt") or ""
        titulo = lam.titulo_de(lamina, encargo)
        if lamina not in mod.EJES and propia:
            # todas las añadidas se titulan «Lámina añadida»: con dos, el
            # resumen y la lista numerada no las distinguirian
            titulo = f"{titulo}: {propia[:40]}"
        salida[lamina] = {"titulo": titulo, "que_se_ve": que}
    return salida


def _estado_del_estilo(ctx, laminas=None):
    """Cómo está el canal ahora, para que el reparto no decida a ciegas.

    Y desde que se puede corregir UNA de las seis referencias sin tocar las
    otras cinco, esto es además lo único que dice CUÁL es cuál. El vocabulario
    del reparto describe qué se le pidió a cada eje —tres personas de pie, una
    calle, un objeto— y con eso basta para «la de los tres cuerpos»; lo que el
    vocabulario no puede saber es en qué ORDEN se ven en este estilo, que es lo
    que hace falta para «la segunda». Ese orden no es el mismo con vídeo que sin
    él, así que se lee del propio estilo (`_laminas_por_eje`) en vez de
    escribirse a mano.

    Van también las correcciones que ya lleva encima cada lámina: son de las
    pasadas anteriores, y sin ellas «vuelve a dejarla como estaba» o «esa misma
    pero con menos gente» se leen a ciegas.
    """
    p7 = _p7()
    mod = _moodboard()
    callouts = ctx.estado.params("callouts") or {}
    estilo = (ctx.estado.params("assets") or {}).get("estilo") or {}
    guia = estilo.get("guia") or {}
    nombre, _ficha = p7.diseno_de(callouts, guia)
    trozos = [
        f"grafismo: {nombre}",
        f"subtítulo: tamaño {callouts.get('subtitulo_tam') or 'normal'}, "
        f"caja al {p7.opacidad_de_caja(callouts):g}",
    ]
    if guia.get("trazo"):
        trozos.append(f"trazo: {str(guia['trazo'])[:160]}")
    linea = " · ".join(trozos)

    nombres = laminas or {}
    laminas = _laminas_por_eje(ctx, validos=set(nombres))
    if not laminas:
        return linea                    # todavía no hay nada dibujado
    rutas, _e = _referencias_de_estilo(ctx)
    peticiones = (mod.ficha_de(rutas) or {}).get("peticiones") or {}
    filas = []
    for orden, (eje, _ruta) in enumerate(laminas, start=1):
        if not eje:
            continue                    # sin eje no se puede señalar
        titulo = ((nombres.get(eje) or {}).get("titulo")
                  or (mod.EJES.get(eje) or {}).get("titulo") or eje)
        pedido = " ".join(str(peticiones.get(eje) or "").split())
        filas.append(f"  {orden}. {eje} — {titulo}"
                     + (f"  [ya se le pidió: «{pedido[:140]}»]" if pedido else ""))
    if not filas:
        return linea
    return (linea + "\n\nlas referencias dibujadas, numeradas en el "
            "orden en que se ven en pantalla:\n" + "\n".join(filas))


def _correr_light_grafismo(avisar, ctx, encargo):
    """El grafismo sale de la guia y no cuesta nada: es una cuenta.

    Lo que decide `p7.diseno_sugerido` y `p7.paleta_de_guia` es lo mismo que
    ensena el desplegable del modo editor con su «lo que sugiere la guia». Aqui
    se ESCRIBE en vez de sugerirse, que es toda la diferencia entre los dos
    modos.
    """
    p7 = _p7()
    guia = ((ctx.estado.params("assets") or {}).get("estilo") or {}).get("guia")
    avisar(0.3, "leyendo la guía para decidir el grafismo")
    puestos = ctx.estado.params("callouts") or {}
    diseno, porque = p7.diseno_sugerido(guia)
    paleta = p7.paleta_de_guia(guia, dict(p7.PARAMS_POR_DEFECTO["paleta"]))
    # LO QUE SE ELIGIO A MANO MANDA SOBRE LO DEDUCIDO. Esta tarea vuelve a
    # deducir el set de la guia cada vez que corre, asi que sin esto una
    # correccion --«los rotulos mas sobrios», que escribe `diseno`-- se
    # revertiria en silencio en la siguiente regeneracion. `p7.diseno_de` ya lo
    # dice al reves («elegir a mano gana siempre») y aqui se le hacia caso solo
    # con el tamano del subtitulo.
    elegido = str(puestos.get("diseno") or "")
    if elegido in p7.SETS_DISENO:
        diseno, porque = elegido, "elegido a mano; no se deduce de la guía"
    cambios = {"diseno": diseno, "paleta": paleta,
               "subtitulo_tam": puestos.get("subtitulo_tam") or "normal",
               "subtitulo_caja": puestos.get("subtitulo_caja", "auto")}
    ctx.estado.actualizar_params("callouts", cambios)
    ctx.bitacora.anotar("grafismo_deducido", "callouts",
                        {"diseno": diseno, "por_que": porque})
    avisar(1.0, f"grafismo «{diseno}»")
    return {"diseno": diseno, "por_que": porque, "paleta": paleta}


def _correr_light_tono(avisar, ctx, encargo):
    tono = _tono()
    peticion = (encargo.get("feedback") or {}).get("tono") or ""
    idioma = encargo.get("idioma") or "es"
    ficha = tono.desde_descripcion(ctx.proyecto, encargo["tono_prompt"],
                                   avisar=avisar, proyecto_id=ctx.id,
                                   peticion=peticion, idioma=idioma)
    # Al BRIEF, que es donde viven las instrucciones del guion. Lo que se pega es
    # el texto COMPLETO (el parrafo mas los cinco rasgos): el nivel tecnico y el
    # publico son justo lo que hay que decirle al redactor.
    ctx.estado.actualizar_params("brief",
                                 {"instrucciones": ficha["texto_completo"]})
    # UN RESUMEN PARA LA TARJETA. Lo que se guarda en el preset son las
    # instrucciones enteras --400-700 palabras, que es lo que lee el redactor--
    # y eso no se puede enseñar en una ficha. El resumen sale de los rasgos que
    # el propio modelo ha escrito, no de recortar el parrafo por la mitad.
    encargo["tono_resumen"] = _resumen_de_tono(ficha)
    ctx.bitacora.anotar("tono_escrito", "brief",
                        {"palabras": ficha.get("palabras")})
    return ficha


def _resumen_de_tono(ficha):
    """Tres o cuatro lineas cortas de lo que ha salido. -> str

    Se queda con los rasgos que de verdad distinguen un canal de otro cuando se
    miran dos fichas seguidas: como suena, a quien le habla, como ordena y que
    hace con las fuentes. Lo demas esta dentro y se lee en el modo editor.
    """
    trozos = []
    for clave in ("resumen", "registro", "publico", "estructura", "fuentes"):
        texto = " ".join(str(ficha.get(clave) or "").split())
        if not texto:
            continue
        if len(texto) > 150:
            texto = texto[:149].rsplit(" ", 1)[0] + "…"
        trozos.append(texto)
    return "\n".join(trozos[:4])


def _correr_light_voz(avisar, ctx, encargo):
    """La voz, con el ritmo del montaje delante.

    DOS EJES, NO UNO. La velocidad de la voz y la duracion de un plano no son la
    misma decision: un montaje rapido con voz normal funciona, y la voz al tope
    sobre planos de dos segundos es un anuncio de teletienda. Asi que el ritmo
    entra como DATO en el prompt —cambia que voz encaja, no solo cuanto corre— y
    solo RELLENA la velocidad cuando el encargo no ha dicho nada de ella. Quien
    dice si el encargo hablaba de velocidad es el propio modelo que lo ha leido
    (`velocidad_pedida`), porque buscar «rapida» en el texto fallaria con «sin
    prisa».

    El AIRE entre bloques si lo pone el ritmo siempre: no es caracter de la voz,
    es tiempo muerto de montaje.
    """
    light = _light()
    ficha_ritmo = light.ritmo_de(encargo.get("ritmo"))
    peticion = (encargo.get("feedback") or {}).get("voz") or ""
    elegido = PASOS_MODULOS.voz_descrita.proponer(
        encargo["voz_prompt"], idioma=encargo["idioma"], avisar=avisar,
        proyecto_id=ctx.id, cwd=ctx.proyecto.raiz, peticion=peticion,
        ritmo=light.contexto_de_ritmo(encargo.get("ritmo")),
        # la voz elegida a mano (la clonada del canal): el agente solo pone
        # los mandos
        voz_fija=encargo.get("voz_id") or "",
        variante=encargo.get("variante_idioma") or "")
    cambios = {c: elegido[c] for c in ("modelo", "voz_id", "voz_nombre",
                                       "velocidad", "emociones", "hueco_minimo")
               if elegido.get(c) is not None}
    cambios["idioma"] = encargo["idioma"]
    rellenada = not elegido.get("velocidad_pedida")
    if rellenada:
        cambios["velocidad"] = ficha_ritmo["velocidad"]
    cambios["hueco_minimo"] = ficha_ritmo["hueco_minimo"]
    ctx.estado.actualizar_params("voz", cambios)
    # CON QUE SE HIZO, para que RETOMAR sepa si sigue valiendo (`_light_hecha`)
    ctx.proyecto.config[CONFIG_VOZ_HECHA] = {
        "voz_prompt": encargo.get("voz_prompt") or "",
        "voz_id": encargo.get("voz_id") or ""}
    ctx.proyecto.guardar_config()
    ctx.bitacora.anotar("voz_descrita", "voz", {
        "encargo": encargo["voz_prompt"][:200],
        "voz": elegido.get("voz_nombre"), "velocidad": cambios["velocidad"],
        "velocidad_del_ritmo": rellenada, "ritmo": ficha_ritmo["id"]})
    return dict(elegido, velocidad=cambios["velocidad"],
                hueco_minimo=cambios["hueco_minimo"])


def _laminas_por_eje(ctx, validos=()):
    """Las referencias dibujadas, CON SU EJE y en el orden en que se ven.

    Son las MISMAS que copia cada plano del video, y por eso son las que se
    ensenan: cualquier otra cosa seria una promesa que el render no tiene por que
    cumplir. Dos caminos, los mismos dos que las dibujan
    (`_correr_light_referencias`):

        con video    el moodboard, guardado en el banco global bajo la huella de
                     los fotogramas elegidos. Seis laminas, una por eje, por
                     orden alfabetico de eje.
        sin video    las laminas dibujadas a partir de la guia SON las
                     referencias del estilo, asi que estan en `referencias`, en
                     el orden en que se dibujaron, y el eje es el nombre de su
                     fichero.

    EL EJE VA CON LA RUTA porque es lo que permite corregir UNA («la de los tres
    cuerpos») en vez de las seis, y EL ORDEN ES EL QUE SE VE porque es lo que
    permite corregir «la segunda». Los dos caminos no lo tienen igual, y eso es
    exactamente por lo que se calcula aqui en vez de escribirse a mano en el
    prompt del reparto: un numero fijo acertaria en la mitad de los estilos.

    Una ruta cuyo fichero no se llame como un eje conocido sale con el eje en
    blanco. No se le adivina uno: mandar ahi una correccion la aplicaria a la
    lamina de al lado.
    """
    mod = _moodboard()
    rutas, _estilo = _referencias_de_estilo(ctx)
    if not rutas:
        return []
    ejes = (mod.ficha_de(rutas) or {}).get("ejes") or {}
    laminas = [(eje, ejes[eje]) for eje in sorted(ejes)
               if ejes.get(eje) and os.path.exists(ejes[eje])]
    if laminas:
        return laminas
    # SIN TOCAR EL ORDEN GUARDADO. Reordenarlo aqui no daria un error, daria
    # otras muestras: `presets_light._escena_muestra` decide POR INDICE cual de
    # las seis lleva cartela.
    # `validos` añade las laminas AÑADIDAS de este estilo (`extra_1`...): se
    # llaman como su id y sin esto salian sin eje, o sea sin poder señalarlas
    conocidos = set(mod.EJES) | set(validos or ())
    return [(os.path.splitext(os.path.basename(r))[0]
             if os.path.splitext(os.path.basename(r))[0] in conocidos else "", r)
            for r in rutas]


def _laminas_del_estilo(ctx):
    """Las referencias dibujadas del estilo, en orden. -> [rutas]"""
    return [ruta for _eje, ruta in _laminas_por_eje(ctx)]


def _correr_light_muestra(avisar, ctx, encargo):
    """Las referencias del estilo con su cartela y su subtitulo, y la 2x2.

    NO SE DIBUJA NADA: las laminas ya estan --son las que copia cada plano-- y lo
    unico que se hace aqui es ponerles encima el texto con el mismo codigo que el
    repaso del montaje. Antes esto generaba cuatro planos de ejemplo a proposito,
    cuatro imagenes pagadas por estilo, para ensenar lo mismo. Ver la cabecera de
    `presets_light`.

    Como no cuesta nada y la lamina limpia esta siempre, recomponer en otro
    idioma es gratis por construccion: no hay ningun caso en el que haya que
    volver a pagar por cambiar el texto de encima.
    """
    light = _light()
    assets = ctx.estado.params("assets") or {}
    estilo = dict(assets.get("estilo") or {})
    carpeta = os.path.join(ctx.proyecto.raiz, "muestras")
    shutil.rmtree(carpeta, ignore_errors=True)
    os.makedirs(carpeta, exist_ok=True)

    avisar(0.1, "buscando las referencias del estilo")
    laminas = _laminas_del_estilo(ctx)
    if not laminas:
        raise RuntimeError("este estilo no tiene ninguna referencia dibujada "
                           "con la que hacer las muestras")

    avisar(0.3, f"montando {len(laminas)} muestras con su cartela y su subtítulo")
    params = dict(ctx.estado.params("callouts") or {})
    params.setdefault("estilo", estilo)
    # EL IDIOMA DEL ESTILO, que es el de sus muestras: un subtitulo de ejemplo
    # en otro idioma no ensena ni la longitud de linea ni donde parte.
    params["idioma"] = encargo["idioma"]
    hecho = light.componer(laminas, os.path.join(carpeta, "miniatura.png"),
                           params, semilla=ctx.id)
    ctx.bitacora.anotar("muestras_preset", "callouts",
                        {"laminas": len(laminas), "idioma": encargo["idioma"]})
    avisar(1.0, "muestras listas")
    return {"miniatura": hecho["miniatura"], "celdas": hecho["celdas"],
            "laminas": laminas}


def _light_hecha(ctx, tarea_id, encargo):
    """Si esta tarea ya esta hecha EN ESTE TALLER. Solo la mira `retomar`.

    Existe por un caso real: YouTube devolvio un 403 —de los que se reintentan
    solos y a veces fallan los cinco— cuando el tono y la voz ya estaban
    escritos, y la tanda entera se fue con el. Volver a pulsar rehacia dos
    llamadas al CLI que ya habian salido bien.

    Se mira EL RESULTADO en el disco y en los params, no una bandera aparte: es
    la misma regla que `_esta_al_dia` de las recetas, y la unica que no puede
    mentir despues de un corte a medias.
    """
    assets = ctx.estado.params("assets") or {}
    estilo = assets.get("estilo") or {}
    if tarea_id == "frames":
        return bool((_estilo().ficha(ctx.proyecto) or {}).get("candidatos"))
    if tarea_id == "guia":
        guia = estilo.get("guia")
        return bool((guia or {}).get("guia") if isinstance(guia, dict) else guia)
    if tarea_id == "referencias":
        # las laminas dibujadas SON las referencias del estilo
        return any("dibujadas" in str(r) for r in (estilo.get("referencias") or []))
    if tarea_id == "grafismo":
        return bool((ctx.estado.params("callouts") or {}).get("diseno"))
    if tarea_id == "tono":
        return bool((ctx.estado.params("brief") or {}).get("instrucciones"))
    if tarea_id == "voz":
        # HECHA CON LO QUE SE PIDE AHORA, no solo hecha. Retomar tras cambiar la
        # voz en el formulario se quedaba con la del primer intento: la ficha
        # del estilo enseñaba otra voz que la elegida (10-10-2026).
        puesta = (ctx.estado.params("voz") or {}).get("voz_id")
        if not puesta:
            return False
        pedida = str(encargo.get("voz_id") or "").strip()
        if pedida and pedida != puesta:
            return False
        hecha = ctx.proyecto.config.get(CONFIG_VOZ_HECHA)
        if isinstance(hecha, dict) and (
                hecha.get("voz_prompt") != (encargo.get("voz_prompt") or "")
                or hecha.get("voz_id") != (encargo.get("voz_id") or "")):
            return False
        return True
    if tarea_id == "muestra":
        return os.path.isfile(os.path.join(ctx.proyecto.raiz, "muestras",
                                           "miniatura.png"))
    return False


#: En la config del taller: con que encargo se eligio la voz (`_light_hecha`).
CONFIG_VOZ_HECHA = "voz_hecha_con"


_LIGHT_QUE_HACE = {
    "guia": _correr_light_guia,
    "referencias": _correr_light_referencias,
    "grafismo": _correr_light_grafismo,
    "tono": _correr_light_tono,
    "voz": _correr_light_voz,
    "muestra": _correr_light_muestra,
}


@_medido_en("estilo")
def _correr_preset_light(avisar, ctx, encargo, solo, preset_id, retomar=False,
                         deshacer=None):
    """Recorre el plan tanda a tanda y congela el resultado en el preset.

    `deshacer` es {paso: {clave: (antes, escrito)}}: los params que la PETICION
    escribio antes de lanzar (el reparto de la frase). Si el trabajo se
    cancela, se devuelven a como estaban --solo los que siguen valiendo lo que
    se escribio--: el preset no se ha vuelto a guardar, y dejarlos en el taller
    hacia que el siguiente «Rehacer» los guardara sin que nadie lo pidiera.

    LA BARRA VA POR TIEMPO, no por numero de tareas. Cada tanda ocupa en la barra
    lo que se espera que tarde (`presets_light.plan_de`, que mira el historial
    medido), y dentro de una tanda manda la mas lenta: es lo unico que hace que
    «bajando el vídeo» no sea el 12 % de la barra durante tres minutos y despues
    seis tareas cortas se coman el resto de golpe.
    """
    try:
        return _correr_preset_light_dentro(avisar, ctx, encargo, solo, preset_id,
                                           retomar, deshacer)
    except _Cancelado:
        _deshacer_params(ctx, deshacer)
        raise


#: Lo que no estaba antes en los params (ver `_deshacer_params`).
_NO_ESTABA = object()


def _deshacer_params(ctx, deshacer):
    """Devuelve a como estaban los params que escribio la peticion. -> [claves]

    Solo los que SIGUEN valiendo lo que se escribio: si alguien los ha cambiado
    a mano mientras tanto, lo suyo manda. Nunca lanza: corre al cancelar."""
    vueltos = []
    for paso, claves in (deshacer or {}).items():
        try:
            with ctx.estado._lock:
                params = ctx.estado.params(paso) or {}
                tocado = False
                for clave, (antes, escrito) in claves.items():
                    if params.get(clave, _NO_ESTABA) != escrito:
                        continue
                    if antes is _NO_ESTABA:
                        params.pop(clave, None)
                    else:
                        params[clave] = antes
                    tocado = True
                    vueltos.append(f"{paso}.{clave}")
                if tocado:
                    ctx.estado.set_params(paso, params)
        except Exception as fallo:                          # noqa: BLE001
            try:
                ctx.bitacora.anotar("aviso", None, {"deshacer": str(fallo)})
            except Exception:                               # noqa: BLE001
                pass
    if vueltos:
        try:
            ctx.bitacora.anotar("reparto_deshecho", None, {"params": vueltos})
        except Exception:                                   # noqa: BLE001
            pass
    return vueltos


def _correr_preset_light_dentro(avisar, ctx, encargo, solo, preset_id, retomar,
                                deshacer=None):
    """El cuerpo de `_correr_preset_light`."""
    light = _light()
    presets = _presets()
    plan = light.plan_de(encargo, solo)
    total = max(1.0, float(plan["segundos"]))
    salida = {"tareas": [], "preset": preset_id, "coste_usd": 0.0}
    cerrojo = threading.Lock()

    for tanda in plan["tandas"]:
        # RETOMAR se salta lo que ya salio bien en este taller. Nunca se salta
        # nada en una pasada normal ni al rehacer una parte: ahi el encargo es
        # justamente volver a hacerlo.
        if retomar:
            tanda = [f for f in tanda if not _light_hecha(ctx, f["id"], encargo)]
            if not tanda:
                continue

        def correr(ficha):
            desde = float(ficha["desde"]) / total
            trozo = float(ficha["tanda_segundos"]) / total

            ultimo = {"frase": light.publico_de(ficha["id"], 0.0)}

            def avisar_tarea(valor, mensaje=""):
                if valor is not None:
                    ultimo["frase"] = light.publico_de(ficha["id"], valor)
                avisar(desde + trozo * min(1.0, max(0.0, float(valor or 0))),
                       ficha["nombre"] + (f" — {mensaje}" if mensaje else ""),
                       ultimo["frase"])
            # CANCELAR EN EL ACTO llega hasta la tarea: la guia espera al CLI y
            # se registra aqui para que lo corten al cancelar, sin esperar a su
            # latido (ver `GestorTrabajos.al_cancelar`)
            avisar_tarea.al_cancelar = getattr(avisar, "al_cancelar", None)

            avisar_tarea(0.0, "")
            arranque = time.time()
            resultado = _LIGHT_QUE_HACE[ficha["id"]](avisar_tarea, ctx, encargo)
            with cerrojo:
                salida["tareas"].append({"tarea": ficha["id"],
                                         "segundos": round(time.time() - arranque, 1)})
                if isinstance(resultado, dict):
                    salida["coste_usd"] += float(resultado.get("coste_usd") or 0.0)
            return resultado

        if len(tanda) == 1:
            correr(tanda[0])
            continue
        # una excepcion (una cancelacion lo es) sube y corta la tanda, y lo que
        # quede en cola no arranca (`moodboard.en_paralelo`)
        _moodboard().en_paralelo(len(tanda), correr, [(f,) for f in tanda])

    avisar(0.99, "guardando el preset", "Guardando tu estilo")
    ficha = _congelar_preset(ctx, encargo, preset_id)
    # GUARDADO: lo que escribio el reparto ya esta en el preset. Una
    # cancelacion que llegue ahora (el avisar del final la lanza) no puede
    # devolver el taller a lo de antes: quedarian distintos al reves.
    if deshacer:
        deshacer.clear()
    salida["preset"] = ficha["id"]
    # EL PROYECTO (cliente) en el que se creo, si se creo dentro de uno. Solo
    # al crear: rehacer una parte no lo mueve de donde este.
    if encargo.get("cliente") and not preset_id:
        try:
            CLIENTES.asignar(raiz_proyectos(), ficha["id"], encargo["cliente"])
        except CLIENTES.ErrorCliente as fallo:
            ctx.bitacora.anotar("aviso", None, {"cliente": str(fallo)})
    # LA FICHA DEL NEGOCIO DE SU PROYECTO (Etapa Foto C), al crearlo y al rehacerlo:
    # rehacer puede ser el momento en que el estilo tiene láminas por primera vez,
    # o en que pasa a foto
    try:
        _negocio_al_estilo(ficha["id"])
    except Exception as fallo:                                # noqa: BLE001
        ctx.bitacora.anotar("aviso", None, {"negocio": str(fallo)})
    salida["resumen"] = ficha.get("resumen") or ""
    salida["coste_usd"] = round(salida["coste_usd"], 4)
    avisar(1.0, f"preset «{ficha['nombre']}» listo", PUBLICO_LISTO)
    return salida


def _congelar_preset(ctx, encargo, preset_id=None):
    """Guarda lo que ha producido el taller como preset de canal. -> ficha."""
    presets = _presets()
    params = {paso: (ctx.estado.params(paso) or {})
              for paso in ("brief", "guion", "assets", "voz", "callouts")}
    datos = presets.datos_de_params(params)
    # LAS REGLAS DEL ESTILO NO SALEN DEL TALLER: se escriben a mano en el
    # preset (`guardar_reglas_estilo`). Congelar desde el taller --al rehacer
    # cualquier parte del estilo-- se las llevaria por delante sin decir nada.
    if preset_id:
        try:
            anterior = presets.leer(preset_id)
            reglas = ((anterior.get("datos") or {}).get("estilo") or {}).get("reglas")
            # el negocio del estilo, por lo mismo (rama dominio-negocio)
            dominio = ((anterior.get("datos") or {}).get("estilo") or {}).get("dominio")
            # el tipo de relato por defecto, por lo mismo (rama tipo-de-relato)
            relato = ((anterior.get("datos") or {}).get("estilo") or {}).get("relato")
        except Exception:                                    # noqa: BLE001
            reglas = dominio = relato = None
        if reglas:
            datos.setdefault("estilo", {})["reglas"] = copy.deepcopy(reglas)
        if dominio:
            datos.setdefault("estilo", {})["dominio"] = dominio
        if relato:
            datos.setdefault("estilo", {})["relato"] = copy.deepcopy(relato)
    # `estilo_modo` solo si es foto (ver `presets_light.origen_de`)
    datos["origen"] = _light().origen_de(encargo, presets.CLAVES_ORIGEN)
    datos["origen"]["taller"] = ctx.id
    taller_muestras = os.path.join(ctx.proyecto.raiz, "muestras")
    miniatura = os.path.join(taller_muestras, "miniatura.png")
    if not os.path.exists(miniatura):
        miniatura = ""
    sueltas = [os.path.join(taller_muestras, n)
               for n in _light().nombres_de_muestra()]
    datos["origen"]["muestras"] = [os.path.basename(r) for r in sueltas
                                   if os.path.exists(r)]
    try:
        ficha = presets.guardar("canal", encargo["nombre"], datos,
                                miniatura=miniatura, pid=preset_id)
    except presets.ErrorPreset as fallo:
        raise RuntimeError(str(fallo))

    # LAS CUATRO SUELTAS TAMBIEN AL BANCO, y DESPUES de guardar: la siembra del
    # estilo rehace la carpeta del preset entera, asi que copiarlas antes seria
    # copiarlas para que se las lleve por delante. Fallar aqui no puede tumbar
    # un estilo que ya esta guardado: lo que se pierde es el banner, y la
    # miniatura sigue.
    destino = presets.carpeta_de(ficha["id"])
    for ruta in sueltas:
        if not os.path.exists(ruta):
            continue
        try:
            os.makedirs(destino, exist_ok=True)
            shutil.copyfile(ruta, os.path.join(destino, os.path.basename(ruta)))
        except OSError:
            pass
    return ficha


# ------------------------------------------------------------------ endpoints

def _rescatar_del_taller(ficha, carpeta):
    """Las muestras que el taller todavia tiene. -> [nombres] copiados.

    Se dibujaron ahi y ahi siguen: el taller no se borra al guardar el preset,
    que es justo lo que permite rehacer solo el tono sin volver a bajar el video.
    Asi que un preset al que le faltan sus muestras no es un preset que haya que
    regenerar; es uno al que hay que devolverselas, y eso no cuesta nada.
    """
    tid = ((ficha.get("datos") or {}).get("origen") or {}).get("taller") or ""
    if not tid:
        return []
    try:
        origen = os.path.join(contexto(tid).proyecto.raiz, "muestras")
    except ErrorApi:
        return []
    if not os.path.isdir(origen):
        return []
    salida = []
    os.makedirs(carpeta, exist_ok=True)
    # la 2x2 se rescata con ellas: es la cara de la tarjeta de la galeria y se
    # perdia en el mismo sitio y por el mismo motivo
    for nombre in ["miniatura.png"] + _light().nombres_de_muestra():
        fuente = os.path.join(origen, nombre)
        if not os.path.isfile(fuente):
            continue
        try:
            shutil.copyfile(fuente, os.path.join(carpeta, nombre))
        except OSError:
            continue
        if nombre != "miniatura.png":
            salida.append(nombre)
    return salida


def _curar_muestras(ficha):
    """Las muestras sueltas de un estilo, devueltas si le faltan.

    Se hace AQUI --al listar-- y no en una migracion aparte porque es lo unico
    que garantiza que pase: una migracion que hay que acordarse de ejecutar es
    una migracion que no se ejecuta. Es idempotente y solo toca a los que les
    falta: el segundo listado no hace nada.

    DOS CASOS, y ninguno cuesta una imagen:

        las declara y no
        estan en el disco  se las llevo por delante un guardado posterior, de
                           cuando sembrar el estilo borraba la carpeta entera
                           (`presets_canal._apartar_propios`). Se recuperan del
                           taller, que las tiene intactas.
        no las declara     un estilo anterior a que se guardaran sueltas. Su 2x2
                           se parte en cuatro ficheros, que son los mismos cuatro
                           planos ya pagados.

    Falla en silencio a proposito. Lo que se pierde si no puede recuperarlas es
    la fila de muestras, y eso no puede impedir que la galeria se lea.
    """
    datos = ficha.get("datos") or {}
    origen = datos.get("origen") or {}
    presets = _presets()
    carpeta = presets.carpeta_de(ficha["id"])
    propia = os.path.join(carpeta, "miniatura.png")
    declaradas = list(origen.get("muestras") or [])
    ya = [n for n in _light().nombres_de_muestra()
          if os.path.isfile(os.path.join(carpeta, n))]
    if not ya:
        ya = _rescatar_del_taller(ficha, carpeta)
    # LA 2x2 Y SOLO LA 2x2. Partir en cuatro `ficha['miniatura']` a secas era
    # partir un FOTOGRAMA cuando el canal venia del modo editor: cuatro
    # cuadrantes de una imagen suelta presentados como «planos de ejemplo con su
    # cartela y su subtitulo». La hoja de muestras se llama siempre igual y vive
    # siempre en el mismo sitio, asi que se pide por su nombre.
    if not ya and os.path.isfile(propia):
        try:
            ya = [os.path.basename(r) for r in
                  _light().partir_miniatura(propia, carpeta)]
        except Exception:                                   # noqa: BLE001
            ya = []
    # y la cara del preset vuelve a ser esa hoja: sin esto, el guardado que se
    # llevo las muestras dejaba la tarjeta de la galeria con un fotograma crudo
    miniatura = propia if os.path.isfile(propia) else (ficha.get("miniatura") or "")
    if ya == declaradas and miniatura == (ficha.get("miniatura") or ""):
        return
    # se anota en la ficha QUE SE PUBLICA y tambien en el almacen, para no
    # volver a mirar el disco en cada listado
    ficha.setdefault("datos", {}).setdefault("origen", {})["muestras"] = ya
    ficha["miniatura"] = miniatura
    ficha["hay_miniatura"] = bool(miniatura and os.path.exists(miniatura))
    try:
        contenido = copy.deepcopy(datos)
        contenido.setdefault("origen", {})["muestras"] = ya
        presets.guardar("canal", ficha.get("nombre") or ficha["id"], contenido,
                        nota=ficha.get("nota") or "",
                        miniatura=miniatura, pid=ficha["id"])
    except Exception:                                       # noqa: BLE001
        pass


@app.get("/api/presets-light")
def listar_presets_light(peticion: Request):
    """Los presets de canal, con sus viñetas y su plan de generacion.

    `plan` viaja aqui y no en un endpoint aparte porque la pantalla lo necesita
    ANTES de pulsar: es lo que dice cuanto va a tardar y cuanto va a costar.
    """
    presets = _presets()
    light = _light()
    # `listar` agrupa por tipo; aqui solo interesan los de canal, que son los
    # que este modo entiende. Los de guion, estilo, voz y grafismo siguen
    # existiendo y siguen siendo del modo editor: no se ensenan ni se tocan.
    fichas = (_preset_o_400(lambda p: p.listar())["presets"] or {}).get("canal") or []
    cerrados = _cerrados(peticion)
    if cerrados:
        asignaciones = CLIENTES._leer(raiz_proyectos())
        fichas = [f for f in fichas if CLIENTES.cliente_de(
            raiz_proyectos(), f.get("id"), datos=asignaciones) not in cerrados]
    for ficha in fichas:
        _curar_muestras(ficha)
        # LA CALIDAD CON LA QUE NACERIA UN VIDEO DE ESTE ESTILO, la misma regla
        # que `crear_video_light`: con ella el deslizador de ritmo ensena el
        # $/min de verdad (un estilo de foto nace, como poco, en medium)
        bloque = ((ficha.get("datos") or {}).get("estilo") or {})
        try:
            ficha["calidad_nuevo"] = calidad_de_video_nuevo(
                PASOS_MODULOS.p6_assets.modo_de(bloque), bloque.get("calidad"))
        except Exception:                                   # noqa: BLE001
            pass
    try:
        calidades_nuevo = {m: calidad_de_video_nuevo(m) for m in ("ilustracion", "foto")}
    except Exception:                                       # noqa: BLE001
        calidades_nuevo = {"ilustracion": "low", "foto": CALIDAD_MINIMA_FOTO}
    return {"presets": fichas,
            # con la que nace un video nuevo de cada modo si su estilo no trae
            # calidad (Configuracion, y en foto como poco medium)
            "calidad_nuevo": calidades_nuevo,
            "idiomas": [{"valor": c, "nombre": presets.NOMBRES_IDIOMA.get(c, c)}
                        for c in light.IDIOMAS_PANTALLA],
            "partes": {k: v["nombre"] for k, v in light.PARTES.items()},
            # lo que cuesta rehacer cada parte, para poder decirlo ANTES de
            # pulsar sin que la pantalla se invente la cifra
            "imagenes_por_parte": {k: light.imagenes_de_parte(k)
                                   for k in light.PARTES},
            # cuantas imagenes de apoyo admite una descripcion de estilo: las
            # mismas que se eligen de un video, y lo dice quien lo sabe
            "max_imagenes_estilo": light.max_imagenes_estilo(),
            # El deslizador de ritmo, con las dos unicas cifras que ensena: el
            # plano medio y lo que cuesta un minuto de video a ese ritmo.
            "ritmos": [light.ficha_de_ritmo(r["id"], calidades_nuevo["ilustracion"],
                                            por_calidad=True) for r in light.RITMOS],
            "ritmo_por_defecto": light.RITMO_POR_DEFECTO,
            "sueltos": _talleres_sueltos(),
            "tareas": [{"id": t["id"], "nombre": t["nombre"],
                        "porque": t.get("porque", ""), "cuesta": t["cuesta"],
                        "imagenes": t.get("imagenes") or 0,
                        "solo": t.get("solo") or ""} for t in light.TAREAS]}


@app.post("/api/presets-light/plan")
def plan_preset_light(cuerpo: dict = Body(default=None)):
    """Lo que va a hacer, en orden y con sus tiempos. No lanza nada."""
    encargo = _encargo_o_400(_cuerpo(cuerpo))
    plan = _light().plan_de(encargo)
    return {"encargo": encargo, "plan": plan}


@app.post("/api/presets-light", status_code=202)
def crear_preset_light(cuerpo: dict = Body(default=None)):
    """Crea el estilo entero a partir de los cuatro campos.

    Con `taller` se RETOMA uno que se quedo a medias: se salta lo que ya salio
    bien y sigue por donde iba. Es lo que convierte un 403 de YouTube —de los
    que se reintentan solos y a veces fallan los cinco— en volver a pulsar, en
    vez de en rehacer el tono y la voz que ya estaban escritos.
    """
    datos = _cuerpo(cuerpo)
    encargo = _encargo_o_400(datos)
    pedido = str(datos.get("taller") or "").strip()
    retomar = False
    if pedido:
        try:
            ctx = contexto(pedido)
        except ErrorApi:
            raise ErrorApi(404, f"el taller {pedido} ya no está en el disco")
        if not ctx.proyecto.config.get(CONFIG_TALLER):
            raise ErrorApi(400, f"{pedido} no es un taller de estilo")
        retomar = True
    else:
        ctx = _crear_taller(encargo)
    # RETOMAR, DE PRINCIPIO A FIN EN EL CERROJO DEL TALLER. Dos clics en
    # «Reintentar» lanzaban dos trabajos que pagaban las mismas laminas, y el
    # segundo ademas volvia a sembrar el taller por debajo del primero, que ya
    # corria. Mirar que este libre, sembrar y lanzar van juntos (D3 del
    # analisis del 13-10-2026). Un taller recien creado es de esta peticion y
    # de nadie mas: no hace falta.
    # Con la misma espera corta que «Regenerar» (`_taller_reservado`): si otra
    # peticion lo tiene, 409 en un segundo, no un boton colgado sin respuesta.
    with (_taller_reservado(ctx) if retomar else contextlib.nullcontext()):
        if encargo.get("cliente"):
            # para ensenar el intento a medias DENTRO de su proyecto
            ctx.proyecto.config["cliente_del_taller"] = encargo["cliente"]
            ctx.proyecto.guardar_config()
        _sembrar_taller(ctx, encargo)
        # ANTES de lanzar: la guia es la primera tarea que las mira, y retomar
        # un taller no puede perderlas -- se vuelven a copiar y ya estaban.
        aportadas = _sembrar_aportadas(ctx, encargo)
        ctx.bitacora.anotar("preset_light_lanzado", None,
                            {"nombre": encargo["nombre"], "idioma": encargo["idioma"],
                             "ritmo": encargo.get("ritmo"), "retomado": retomar,
                             "aportadas": len(aportadas)})
        trabajo_id = ctx.gestor.lanzar("preset_light", _correr_preset_light, ctx,
                                       encargo, None, None, retomar, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "taller": ctx.id, "encargo": encargo,
            "retomado": retomar, "plan": _light().plan_de(encargo),
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


#: Las muestras de voz que se escuchan ANTES de que exista el estilo (al
#: crearlo). Se cachean por voz e idioma: volver a una ya oida no paga.
_LOCK_MUESTRAS_VOZ = threading.Lock()


def _carpeta_muestras_voz():
    return os.path.join(raiz_proyectos(), "_sistema", "escuchas")


@app.post("/api/voces/muestra")
def muestra_de_voz(cuerpo: dict = Body(default=None)):
    """Doce segundos de una voz del catalogo, sin estilo ni proyecto.

    Es la escucha del formulario de CREAR un estilo: alli todavia no hay taller
    (la de `/presets-light/{id}/voz/previsualizar` necesita uno), y elegir una
    voz sin oirla era elegir por el nombre. Se sintetiza la misma frase de
    muestra del idioma (`presets_light.bloques_de_escucha`) con los mandos por
    defecto: lo que cambia entre dos muestras es la voz y nada mas. Cuesta lo
    que doce segundos de Cartesia, y una sola vez por voz e idioma.
    """
    datos = _cuerpo(cuerpo)
    voz_id = str(datos.get("voz_id") or "").strip()
    if not re.match(r"^[A-Za-z0-9_-]{8,64}$", voz_id):
        raise ErrorApi(400, "«voz_id» no parece un id de voz de Cartesia")
    idioma = str(datos.get("idioma") or "es").strip() or "es"
    p4 = PASOS_MODULOS.p4_voz
    light = _light()
    texto = p4.recortar_texto(light.bloques_de_escucha(idioma), 12, None)
    # Lo que se MANDA lleva la lista «Cómo se pronuncia», como en el vídeo; y
    # entra en la clave, o al cambiar la lista seguiría sonando la muestra vieja.
    # Si no cambia nada, la clave es la de siempre y no se vuelve a pagar.
    para_voz = p4.texto_para_voz(texto)
    clave = hashlib.sha256(json.dumps(
        [voz_id, idioma, texto, p4.simulado()]
        + ([para_voz] if para_voz != texto else []),
        ensure_ascii=False).encode("utf-8")).hexdigest()[:16]
    carpeta = _carpeta_muestras_voz()
    nombre = f"voz_{clave}.wav"
    ruta = os.path.join(carpeta, nombre)
    with _LOCK_MUESTRAS_VOZ:
        if not os.path.exists(ruta):
            os.makedirs(carpeta, exist_ok=True)
            try:
                cfg = p4.resolver_params({"voz_id": voz_id, "idioma": idioma})
                wav, _duracion, _palabras = p4.sintetizar_toma(para_voz, cfg)
            except (Exception, SystemExit) as fallo:  # noqa: BLE001
                raise ErrorApi(502, f"no se ha podido sintetizar la muestra: {fallo}")
            temporal = ruta + ".tmp"
            with open(temporal, "wb") as fh:
                fh.write(wav)
            os.replace(temporal, ruta)
    return {"ruta": f"/api/voces/muestra/{nombre}", "voz_id": voz_id,
            "idioma": idioma}


@app.get("/api/voces/muestra/{nombre}")
def servir_muestra_de_voz(nombre: str, peticion: Request):
    """El wav de una muestra ya sintetizada."""
    if not re.match(r"^voz_[0-9a-f]{16}\.wav$", nombre):
        raise ErrorApi(404, "esa muestra no existe")
    ruta = os.path.join(_carpeta_muestras_voz(), nombre)
    if not os.path.isfile(ruta):
        raise ErrorApi(404, "esa muestra no existe")
    return servir_fichero(peticion, ruta)


@app.post("/api/presets-light/{preset_id}/voz/previsualizar", status_code=202)
def previsualizar_voz_light(preset_id: str, cuerpo: dict = Body(default=None)):
    """Unos segundos con la voz de este estilo, para escucharla.

    Corre en el TALLER, que es un proyecto y por tanto tiene todo lo que
    `p4_voz.previsualizar` necesita. Es el mismo endpoint que el modo editor
    por dentro; lo unico que cambia es que aqui no hay que saber en que
    proyecto esta.

    CON `voz_id` SE ESCUCHA OTRA VOZ SIN ELEGIRLA. En la cuadricula de voces cada
    una lleva su propio play, y darle es AUDICIONARLA: si escuchar guardara, oir
    seis para comparar dejaria puesta la sexta. Todo lo demas --velocidad, color,
    aire-- son los mandos del estilo, que es lo que hace que la comparacion valga:
    cambia la voz y nada mas. La sintesis se cachea por firma (y la voz entra en
    ella), asi que volver a una ya escuchada no vuelve a pagar.
    """
    presets = _presets()
    datos = _cuerpo(cuerpo)
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "esto no es un estilo")
    ctx = _taller_de(ficha)
    params = dict((ficha.get("datos") or {}).get("voz") or {})
    suelta = str(datos.get("voz_id") or "").strip()
    if suelta:
        params["voz_id"] = suelta
    if not params.get("voz_id"):
        raise ErrorApi(409, "este estilo todavía no tiene voz elegida")
    # EL TEXTO QUE SE LEE. En un video sale del paso 3; en un taller no hay
    # guion --no es un video, es donde se monta un estilo-- y sin esto la
    # escucha moria con «no encuentro el guion». Se le pasa por params, que es
    # el primer sitio donde `p4_voz.cargar_guion` mira desde siempre: ninguna
    # logica nueva, solo darle el texto.
    params["bloques"] = _light().bloques_de_escucha(
        params.get("idioma") or presets.idioma_de(ficha) or "es")
    try:
        segundos = float(datos.get("segundos") or 12)
    except (TypeError, ValueError):
        raise ErrorApi(400, "'segundos' debe ser un número")
    if not 1 <= segundos <= 60:
        raise ErrorApi(400, "'segundos' debe estar entre 1 y 60")
    trabajo_id = ctx.gestor.lanzar("voz:previsualizar", _previsualizar_voz,
                                   ctx, params, segundos, paso=None)
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "segundos": segundos,
            "voz_id": params["voz_id"],
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@app.post("/api/presets-light/{preset_id}/duplicar", status_code=201)
def duplicar_preset_light(preset_id: str, cuerpo: dict = Body(default=None)):
    """Una copia del estilo, con su taller.

    CON SU TALLER, y eso es lo que cuesta: sin el, la copia no puede rehacer ni
    el estilo grafico ni el tono ni la voz --no tiene el material con el que se
    hizo-- y seria un estilo de segunda que solo sirve para mirar. `duplicar`
    copia la version ACTIVA de cada paso, no el historial, asi que un taller son
    decenas de megas y no cientos.

    Para que sirve: el mismo dibujo en otro idioma, o con otro ritmo, sin volver
    a bajar el video ni a pagar las referencias.
    """
    presets = _presets()
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "esto no es un estilo")
    datos = _cuerpo(cuerpo)
    nombre = " ".join(str(datos.get("nombre") or "").split()) \
        or f"{ficha.get('nombre') or 'Estilo'} (copia)"

    contenido = copy.deepcopy(ficha.get("datos") or {})
    origen = dict(contenido.get("origen") or {})
    # el taller se copia; si no lo hay, la copia se queda sin el y lo dice al
    # intentar rehacer una parte
    tid = origen.get("taller")
    if tid:
        try:
            viejo = contexto(tid)
            nuevo = viejo.proyecto.duplicar(raiz_proyectos(),
                                            f"taller {nombre}"[:60])
            copia = contexto(nuevo.id)
            copia.proyecto.config[CONFIG_TALLER] = True
            copia.proyecto.guardar_config()
            origen["taller"] = copia.id
        except Exception as fallo:                          # noqa: BLE001
            raise ErrorApi(500, f"no se ha podido copiar el taller: {fallo}")
    contenido["origen"] = origen

    try:
        nueva = presets.guardar("canal", nombre, contenido,
                                nota=ficha.get("nota") or "",
                                miniatura=ficha.get("miniatura") or "")
    except presets.ErrorPreset as fallo:
        raise ErrorApi(400, str(fallo))

    # las muestras sueltas, que no son params y por tanto no viajan en `datos`
    viejas = presets.carpeta_de(preset_id)
    destino = presets.carpeta_de(nueva["id"])
    for nombre_fichero in (origen.get("muestras") or []):
        una = os.path.join(viejas, os.path.basename(str(nombre_fichero)))
        if os.path.exists(una):
            try:
                os.makedirs(destino, exist_ok=True)
                shutil.copyfile(una, os.path.join(destino,
                                                  os.path.basename(una)))
            except OSError:
                pass
    # LA COPIA NO SE LLEVA LA FICHA DEL NEGOCIO del original: la recibe la de su
    # proyecto (ninguna hasta que se meta en uno), Etapa Foto C
    if PASOS_MODULOS is not None:
        _negocio_al_estilo(nueva["id"])
    return {"preset": nueva, "de": preset_id}


@app.delete("/api/presets-light/talleres/{taller_id}")
def descartar_taller_light(taller_id: str):
    """Tira un intento a medias. A la papelera de proyectos, no al vacio."""
    try:
        ctx = contexto(taller_id)
    except ErrorApi:
        raise ErrorApi(404, f"el taller {taller_id} ya no está")
    if not ctx.proyecto.config.get(CONFIG_TALLER):
        raise ErrorApi(400, f"{taller_id} no es un taller de estilo")
    if taller_id in {f["id"] for f in _talleres_sueltos()}:
        apartar_proyecto(taller_id)
        return {"descartado": taller_id}
    raise ErrorApi(409, f"el taller {taller_id} es de un estilo guardado: "
                        f"borra el estilo y se va con él")


@app.post("/api/presets-light/{preset_id}/regenerar", status_code=202)
def regenerar_preset_light(preset_id: str, cuerpo: dict = Body(default=None)):
    """Rehace UNA de las tres partes con una frase de feedback.

    Tres y no ocho: el canal ve tres cosas --el estilo grafico, el tono y la
    voz-- asi que corrige tres cosas. El idioma no esta aqui porque se cambia a
    mano y no hay nada que rehacer (PUT).

    CON `origen` SE CAMBIA LA FUENTE, no solo se corrige, y la tienen DOS de las
    tres partes:

      estilo   «los mismos videos pero en fotografico»: otro video, u otra
               descripcion con otras imagenes, y se rehace el estilo entero
               CONSERVANDO el tono, la voz, el ritmo y el idioma. Con un video
               nuevo hay que bajarlo y volver a elegir fotogramas, asi que la
               lista de tareas sale del encargo nuevo (`light.tareas_de_estilo`).
      tono     otros videos de referencia (hasta `light.MAX_VIDEOS_TONO`), o
               una descripcion en su lugar. Rehace solo las instrucciones del
               guion; no cuesta ninguna imagen.

    La voz no: se corrige con una frase, que ya es su fuente entera.
    """
    light = _light()
    datos = _cuerpo(cuerpo)
    parte = str(datos.get("parte") or "").strip().lower()
    if parte not in light.PARTES:
        raise ErrorApi(400, f"parte desconocida: {parte!r}. Son "
                            + ", ".join(light.PARTES))
    peticion = " ".join(str(datos.get("peticion") or "").split())
    fuente = datos.get("origen") if isinstance(datos.get("origen"), dict) else None
    if fuente and parte not in ("estilo", "tono", "personajes"):
        raise ErrorApi(400, "la voz no tiene fuente que cambiar: se corrige "
                            "con una frase, que ya es su descripción entera")
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "esto no es un preset de canal")
    ctx = _taller_de(ficha)
    # DE MIRAR SI ESTA LIBRE A LANZAR, CON EL TALLER RESERVADO: un segundo
    # toque contesta 409 antes de repartir la frase con Claude o de escribir
    # nada (ver `_taller_reservado`)
    with _taller_reservado(ctx):
        return _regenerar_en_taller(ctx, ficha, preset_id, parte, peticion, fuente)


def _regenerar_en_taller(ctx, ficha, preset_id, parte, peticion, fuente):
    """El cuerpo de `regenerar_preset_light`, con el taller ya reservado."""
    light = _light()
    origen = dict((ficha.get("datos") or {}).get("origen") or {})
    antes = dict(origen)
    origen["nombre"] = ficha.get("nombre") or "canal"
    origen.setdefault("idioma", _presets().idioma_de(ficha) or "es")
    conservar = None
    if fuente and parte == "estilo" and any(
            k in fuente for k in ("estilo_prompt", "estilo_imagenes", "conservar",
                                  "estilo_descripciones")):
        # las DOS a la vez y siempre: dejar la vieja puesta es como se acaba con
        # unas indicaciones que describen unas imagenes que ya no estan
        if "estilo_prompt" in fuente or "estilo_imagenes" in fuente:
            origen["estilo_prompt"] = fuente.get("estilo_prompt") or ""
        # SIN IMAGENES NUEVAS SE QUEDAN LAS QUE HABIA. Cambiar solo las
        # indicaciones mandaba una lista vacia y el encargo caia con «falta el
        # estilo gráfico» aunque el estilo tuviera sus imagenes (10-10-2026).
        origen["estilo_imagenes"] = (fuente.get("estilo_imagenes")
                                     or origen.get("estilo_imagenes") or [])
        # LAS QUE SIGUEN de las que ya tenia (la ficha deja quitar unas y
        # anadir otras): van delante de las nuevas, con su nombre de siempre
        # una lista VACIA sin imagenes nuevas no es «quitalas todas» (el
        # estilo se quedaria sin material): es que la pantalla no las pudo leer
        if isinstance(fuente.get("conservar"), list) and (
                fuente["conservar"] or _rutas_aportadas(fuente.get("estilo_imagenes"))):
            conservar = [str(n) for n in fuente["conservar"] if n][:200]
            origen["estilo_imagenes"] = conservar + [
                n for n in (fuente.get("estilo_imagenes") or [])
                if n not in conservar]
        # las descripciones van con SUS imagenes: con imagenes nuevas, las
        # nuevas; sin imagenes nuevas se quedan las que habia
        if fuente.get("estilo_imagenes") or "estilo_descripciones" in fuente:
            origen["estilo_descripciones"] = fuente.get("estilo_descripciones") or {}
            origen["estilo_destacadas"] = fuente.get("estilo_destacadas") or []
    if fuente and parte == "estilo" and "estilo_modo" in fuente:
        # EL TIPO DE IMAGEN (Etapa Foto A) es otra fuente del estilo: pasar a
        # «Foto realista» con las MISMAS imagenes rehace la guia (con el
        # contrato de foto) y las laminas, y deja el tono, la voz y el ritmo.
        # Puede venir solo: entonces las imagenes y las indicaciones son las
        # que ya tenia el estilo.
        origen["estilo_modo"] = str(fuente.get("estilo_modo") or "")
    if fuente and parte == "tono":
        origen["tono_prompt"] = fuente.get("tono_prompt") or ""
    encargo = _encargo_o_400(origen)

    # ¿HAN CAMBIADO LAS IMAGENES, O SOLO LAS INDICACIONES? Cambiar «igual pero
    # mas frio» con las MISMAS imagenes detras solo obliga a reescribir la guia y
    # lo que cuelga de ella, que es justo lo que rehace la parte «estilo» de
    # siempre. Se compara con lo que habia, no con si vino `origen`: la pantalla
    # manda las dos claves juntas y una de ellas puede no haberse tocado.
    #
    # Lo que SI es material nuevo: imagenes nuevas, quitar o anadir de las que
    # habia, o un TIPO DE IMAGEN distinto (Etapa Foto A), que cambia el
    # contrato de la guia y como se piden las laminas: eso se rehace entero
    # aunque tambien haya cambiado el texto, porque el reparto de la frase
    # podria decidir no tocar la guia.
    modo_antes = "foto" if antes.get("estilo_modo") == "foto" else "ilustracion"
    modo_cambiado = (bool(fuente) and parte == "estilo"
                     and encargo.get("estilo_modo") != modo_antes)
    material = bool(fuente) and parte == "estilo" and (
        bool(_rutas_aportadas(fuente.get("estilo_imagenes")))
        or (conservar is not None and set(conservar) != {
            _light()._sin_prefijo(r) for r in _aportadas_del_taller(ctx)})
        or (modo_cambiado and bool(encargo.get("estilo_imagenes"))))
    # El feedback viaja por INVOCACION y no se guarda en el encargo: describe
    # esta pasada, no lo que el preset es. Guardarlo lo aplicaria otra vez la
    # proxima, y dos correcciones seguidas se sumarian sin que nadie lo pida.
    encargo["feedback"] = {parte: peticion}

    # EL REPARTO: leer la frase ANTES de correr nada y quedarse con lo que hace
    # falta. Corregir el estilo grafico corria siempre las cuatro tareas --24
    # fotogramas mirados otra vez, la guia reescrita y SEIS imagenes nuevas--
    # aunque lo que se pidiera fuera bajarle la opacidad a la caja del
    # subtitulo, que son dos numeros en un fichero de params.
    #
    # NO toca el camino de la fuente nueva: si de verdad hay otro video o otras
    # imagenes, hay que rehacerlo todo y no hay nada que repartir.
    reparto = None
    deshacer = {}
    if parte == "estilo" and not material:
        frase = _frase_del_estilo(encargo, antes, peticion)
        if frase:
            # LAS LAMINAS DE ESTE ESTILO, no las seis de fabrica: con solo esas,
            # una correccion para una lamina AÑADIDA no tenia a donde ir y se
            # redibujaban todas (N2 de las notas de mejoras, 13-10-2026); y
            # una QUITADA se aceptaba, se filtraba despues y tambien caia en
            # todas
            laminas = _laminas_para_el_reparto(encargo)
            reparto = _enrutar_estilo().repartir(
                frase, estado=_estado_del_estilo(ctx, laminas), cwd=ctx.proyecto.raiz,
                proyecto_id=ctx.id, laminas=laminas)
            # LOS PARAMS SE ESCRIBEN AQUI Y NO DENTRO DEL TRABAJO: asi el
            # grafismo que corre despues ya los encuentra puestos. Lo que habia
            # se apunta: si el trabajo se CANCELA, vuelven a como estaban
            # (`_deshacer_params`) -- el preset no se ha vuelto a guardar, y
            # dejarlos en el taller hacia que el siguiente «Rehacer» los
            # guardara sin que nadie lo pidiera.
            for paso_destino, valores in (reparto.get("params") or {}).items():
                previos = ctx.estado.params(paso_destino) or {}
                deshacer.setdefault(paso_destino, {}).update({
                    clave: (previos.get(clave, _NO_ESTABA), copy.deepcopy(valor))
                    for clave, valor in valores.items()})
                ctx.estado.actualizar_params(paso_destino, valores)
            # QUE REFERENCIA REDIBUJAR Y QUE CAMBIARLE. Va en el encargo y NO
            # en los params, por lo mismo que el feedback: describe esta pasada
            # y no lo que el estilo es. Guardado, la siguiente regeneracion
            # volveria a corregir una lamina que ya esta corregida.
            #
            # Vacio son las seis, que es lo de siempre. Lo llena solo
            # `una_referencia`, y `laminas_de` ya se encarga de devolver vacio
            # si algo del reparto pide las seis: media correccion aplicada
            # dejaria cinco laminas con un estilo y una con otro.
            encargo["laminas"] = dict(reparto.get("laminas") or {})
    if material:
        tareas = light.tareas_de_estilo(encargo)
    elif reparto is not None:
        # LA TUPLA VACIA ES UNA RESPUESTA, no la ausencia de una. Es lo que
        # devuelve el reparto cuando dice «esto no tiene mando», y escrito con
        # un `or` se caia al respaldo: se lanzaban las cuatro tareas y las seis
        # imagenes para una frase que el motor acababa de decir que no sabia
        # aplicar -- o sea justo lo contrario de lo que este reparto existe para
        # hacer. Pasó al probarlo con «pon el subtítulo arriba del todo».
        tareas = tuple(reparto.get("tareas") or ())
    else:
        tareas = light.PARTES[parte]["tareas"]
    # UN CAJON ES UNA PROMESA: una tarea que no existe se filtra en silencio mas
    # abajo y deja un plan VACIO -- el trabajo termina «listo» sin haber hecho
    # nada y la pantalla vuelve como si el cambio estuviera aplicado.
    tareas = tuple(t for t in tareas if t in light.TAREAS_POR_ID)
    try:
        aportadas = _sembrar_aportadas(ctx, encargo, conservar) if material else []
    except RuntimeError as fallo:
        raise ErrorApi(400, str(fallo))
    # el tipo de imagen, al taller ANTES de lanzar: la guia es la primera
    # tarea que lo lee (Etapa Foto A)
    if fuente and parte == "estilo":
        _sembrar_modo(ctx, encargo)
    ctx.bitacora.anotar("preset_light_regenerar", None,
                        {"preset": preset_id, "parte": parte,
                         "peticion": peticion[:200],
                         "fuente_nueva": bool(fuente),
                         "material_nuevo": material,
                         "aportadas": len(aportadas),
                         "reparto": (reparto or {}).get("resumen") or "",
                         "laminas": sorted(encargo.get("laminas") or {})})

    # NADA QUE CORRER. Pasa cuando el reparto dice «esto no tiene mando»: es una
    # respuesta, no un fallo, y lo que hay que hacer con ella es DECIRLA. Lanzar
    # un trabajo vacio la enseñaria como un cambio aplicado.
    if not tareas:
        return {"trabajo_id": "", "taller": ctx.id, "parte": parte,
                "fuente_nueva": False, "material_nuevo": False,
                "reparto": reparto, "sin_cambios": True,
                "aviso": (reparto or {}).get("resumen")
                         or "no hay nada que rehacer con eso"}

    trabajo_id = _lanzar_en_taller(
        ctx, "preset_light", _correr_preset_light, ctx, encargo,
        list(tareas), preset_id, paso="assets", deshacer=deshacer)
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "taller": ctx.id, "parte": parte,
            "fuente_nueva": bool(fuente), "material_nuevo": material,
            "reparto": reparto,
            "plan": (_plan_con_laminas(light.plan_de(encargo, tareas),
                                       len(_laminas().ids_de(encargo)))
                     if "referencias" in tareas and not encargo.get("laminas")
                     else light.plan_de(encargo, tareas)),
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


# ------------------------------------------------------------- las laminas
#
# Lo que ve cada plano de cada video de un estilo descrito NO son tus imagenes:
# es la hoja de sus LAMINAS (`pasos/laminas.py`). Aqui se ven una a una, con lo
# que ensena cada una, y se regeneran, se cambian, se quitan o se anaden.
# Nada de esto toca un video ya hecho: sus params son suyos. Lo cambiado lo
# llevan los videos que se creen DESPUES con el estilo (o los que traigan el
# estilo desde su Encargo).

_ID_LAMINA = re.compile(r"^[a-z]{3,12}$|^extra_\d{1,3}$")


def _plan_con_laminas(plan, imagenes):
    """El plan con las imagenes que de verdad se dibujan en la tarea de laminas.

    La tabla de tareas dice seis (las de fabrica); quitar una no dibuja
    ninguna, regenerar una dibuja una y un estilo puede tener de 3 a 8."""
    plan = copy.deepcopy(plan)
    antes = 0
    for tanda in plan.get("tandas") or []:
        for tarea in tanda:
            if tarea.get("id") == "referencias":
                antes += int(tarea.get("imagenes") or 0)
                tarea["imagenes"] = int(imagenes)
    for tarea in plan.get("tareas") or []:
        if isinstance(tarea, dict) and tarea.get("id") == "referencias":
            tarea["imagenes"] = int(imagenes)
    if "imagenes" in plan:
        plan["imagenes"] = max(0, int(plan["imagenes"]) - antes + int(imagenes))
    return plan


#: Los trabajos del taller que NO impiden cambiar el estilo. Una escucha de voz
#: lee una copia de los mandos y escribe solo su wav, con nombre de firma, en
#: `previsualizaciones/` (`p4_voz.previsualizar`): nada que un «Rehacer» toque
#: ni nada suyo que un «Rehacer» pise. Bloquear por ella era quedarse sin poder
#: corregir mientras sonaba una muestra.
_NO_BLOQUEAN_EL_TALLER = ("voz:previsualizar",)


def _que_hace_el_taller(trabajo):
    """Lo que esta haciendo un trabajo del taller, dicho para el 409. -> str"""
    if trabajo.get("cancelando"):
        return ("se está cancelando lo anterior: termina en unos segundos (lo que "
                "ya se estaba dibujando se acaba y se guarda). Vuelve a pulsar "
                "entonces")
    if trabajo.get("nombre") == "voz:previsualizar":
        return "se está preparando una escucha de la voz: espera a que suene"
    ahora = str(trabajo.get("publico") or "").strip()
    return ("este estilo se está generando"
            + (f" («{ahora}»)" if ahora else "")
            + ": espera a que termine para cambiar otra cosa")


def _taller_libre(ctx):
    """409 si el taller de este estilo esta generando algo.

    Lo que se guarde mientras tanto se lo llevaria por delante el trabajo al
    terminar (vuelve a guardar el estilo con SU copia del encargo), y dos
    laminas nuevas seguidas se llamarian igual y se pagarian las dos.

    EL 409 DICE QUE HAY EN MARCHA Y CUAL ES (`trabajo_id`, `cancelando`): la
    pantalla se engancha a ese trabajo en vez de quedarse con un aviso, y quien
    vuelve a pulsar mientras se cancela lee eso y no «se está generando»."""
    for trabajo in ctx.gestor.listar(activos=True):
        if trabajo.get("nombre") in _NO_BLOQUEAN_EL_TALLER:
            continue
        raise ErrorApi(409, _que_hace_el_taller(trabajo),
                       {"trabajo_id": trabajo.get("id") or "",
                        "cancelando": bool(trabajo.get("cancelando")),
                        "segundos": trabajo.get("segundos") or 0,
                        "taller": ctx.id})


#: Cuanto espera una peticion a que otra del MISMO taller suelte el cerrojo
#: antes de contestar 409. Poco: la otra puede estar repartiendo la frase con
#: Claude (segundos), y esperarla seria dejar el boton pulsado sin respuesta.
ESPERA_CERROJO_TALLER_S = 1.0


@contextlib.contextmanager
def _taller_reservado(ctx):
    """El taller para esta peticion, de mirar si esta libre a lanzar.

    DOBLE TOQUE EN «Regenerar» (18-10-2026): la segunda peticion pasaba
    `_taller_libre` mientras la primera repartia la frase con Claude, repartia
    OTRA vez (otra llamada al CLI), escribia params en el taller por debajo del
    trabajo ya lanzado y solo al final se llevaba el 409. Con el cerrojo de la
    cadena (reentrante: `_lanzar_en_taller` lo vuelve a tomar dentro) tomado
    desde el principio, la segunda contesta 409 ANTES de gastar nada.

    No se espera al cerrojo: si en `ESPERA_CERROJO_TALLER_S` no se suelta, es que
    otra peticion esta preparando un cambio de este estilo, y se dice.
    """
    cerrojo = _cerrojo_de_cadena(ctx.id)
    if not cerrojo.acquire(timeout=ESPERA_CERROJO_TALLER_S):
        raise ErrorApi(409, "ya se está preparando un cambio de este estilo: "
                            "espera a que empiece y lo verás en marcha",
                       {"trabajo_id": "", "cancelando": False, "taller": ctx.id,
                        "preparando": True})
    try:
        _taller_libre(ctx)
        yield ctx
    finally:
        cerrojo.release()


def _lanzar_en_taller(ctx, *args, **kwargs):
    """`ctx.gestor.lanzar` en el taller de un estilo, mirando OTRA VEZ que este
    libre y en el mismo cerrojo. -> trabajo_id

    `_taller_libre` mira al principio de la peticion, y entre ese mirar y el
    lanzar hay segundos de trabajo (leer el encargo, repartir la frase con
    Claude): cuatro clics en «Regenerar lamina» pasaban los cuatro y lanzaban
    hasta tres trabajos que pagaban cada uno su imagen (D3 del analisis del
    13-10-2026). Con el cerrojo de la cadena de ese taller, el segundo ya ve
    el primero en marcha.
    """
    with _cerrojo_de_cadena(ctx.id):
        _taller_libre(ctx)
        return ctx.gestor.lanzar(*args, **kwargs)


def _taller_con_laminas(preset_id):
    """(ficha, ctx) de un estilo con laminas dibujadas, o un 409 que lo dice."""
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "esto no es un preset de canal")
    origen = (ficha.get("datos") or {}).get("origen") or {}
    if not origen.get("estilo_imagenes"):
        raise ErrorApi(409, "este estilo no salió de imágenes de referencia: sus "
                            "láminas son las de su vídeo y no se tocan desde aquí")
    return ficha, _taller_de(ficha)


def _ruta_lamina(ctx, lamina):
    if not _ID_LAMINA.match(str(lamina or "")):
        raise ErrorApi(400, f"lámina desconocida: {lamina!r}")
    return os.path.join(ctx.proyecto.raiz, "estilo", "dibujadas", f"{lamina}.png")


def _ficha_lamina(preset_id, ctx, lamina, origen, en_uso):
    lam = _laminas()
    ruta = _ruta_lamina(ctx, lamina)
    hay = os.path.isfile(ruta)
    sello = int(os.path.getmtime(ruta)) if hay else 0
    _, propias, _ = lam.config_de(origen)
    return {"id": lamina, "titulo": lam.titulo_de(lamina, origen),
            "explicacion": lam.explicacion_de(lamina, origen),
            "texto": propias.get(lamina, ""),
            "fabrica": lamina in _moodboard().EJES,
            "en_uso": en_uso,
            "url": (f"/api/presets-light/{preset_id}/laminas/{lamina}/imagen?v={sello}"
                    if hay else "")}


@app.get("/api/presets-light/{preset_id}/laminas")
def laminas_de_preset(preset_id: str):
    """Las laminas de un estilo, limpias y con lo que ensena cada una."""
    lam = _laminas()
    ficha, ctx = _taller_con_laminas(preset_id)
    origen = (ficha.get("datos") or {}).get("origen") or {}
    ids = lam.ids_de(origen)
    quitadas, propias, hoja = lam.config_de(origen)
    calidad = str((ctx.estado.params("assets") or {}).get("calidad") or "medium")
    try:
        usd = float(AJUSTES.usd_por_imagen(calidad) or 0.0)
    except Exception:                                       # noqa: BLE001
        usd = 0.0
    # las anadidas que se quitaron no se guardan: solo vuelven las de fabrica
    return {"laminas": [_ficha_lamina(preset_id, ctx, e, origen, True) for e in ids],
            "quitadas": [_ficha_lamina(preset_id, ctx, e, origen, False)
                         for e in quitadas],
            "hoja": hoja,
            "imagenes": len(_aportadas_del_taller(ctx)),
            "en_la_hoja": _light().MAX_EN_LA_HOJA,
            "max": lam.MAX_LAMINAS, "min": lam.MIN_LAMINAS,
            "max_texto": lam.MAX_TEXTO,
            "calidad": calidad, "usd_por_lamina": round(usd, 4),
            # lo que paga «Regenerar» el estilo entero con ESTAS laminas
            "imagenes_estilo": _light().imagenes_de_parte("estilo", origen)}


@app.get("/api/presets-light/{preset_id}/laminas/{lamina}/imagen")
def imagen_de_lamina(preset_id: str, lamina: str, peticion: Request):
    """Una lamina LIMPIA, sin texto encima: la que va en la hoja de cada plano."""
    _, ctx = _taller_con_laminas(preset_id)
    ruta = _ruta_lamina(ctx, lamina)
    if not os.path.isfile(ruta):
        raise ErrorApi(404, "esa lámina no está dibujada")
    return servir_fichero(peticion, ruta)


@app.post("/api/presets-light/{preset_id}/laminas", status_code=202)
def cambiar_laminas(preset_id: str, cuerpo: dict = Body(default=None)):
    """Una accion sobre las laminas de un estilo.

        regenerar  {lamina, texto?}  la vuelve a dibujar; `texto` es una
                                     correccion de esta vez («sin sombras»)
        cambiar    {lamina, texto}   que ensene otra cosa, guardado: se respeta
                                     al regenerar el estilo. Texto vacio en una
                                     de fabrica la devuelve a lo de fabrica
        nueva      {texto}           una lamina mas (hasta 8, las que caben en
                                     la hoja de cada plano)
        quitar     {lamina}          sale de la hoja; su imagen se queda
        restaurar  {lamina}          vuelve una de fabrica quitada
        hoja       {hoja}            "comun" o "repartida" (ver `laminas.py`)

    Dibujar una lamina cuesta UNA imagen; quitar, restaurar una que ya estaba
    dibujada y cambiar la hoja no cuestan nada. Despues se recomponen las
    muestras (gratis) y se vuelve a guardar el estilo.
    """
    lam = _laminas()
    datos = _cuerpo(cuerpo)
    accion = str(datos.get("accion") or "").strip().lower()
    lamina = str(datos.get("lamina") or "").strip()
    texto = " ".join(str(datos.get("texto") or "").split())
    # UN TEXTO DEMASIADO LARGO SE DICE, no se corta: cortado, la lamina se
    # pagaba dibujando la mitad de lo pedido y nadie se enteraba (19-10-2026)
    if len(texto) > lam.MAX_TEXTO:
        raise ErrorApi(400, f"lo que pides para la lámina tiene {len(texto)} caracteres "
                            f"y el máximo es {lam.MAX_TEXTO}: acórtalo un poco")
    ficha, ctx = _taller_con_laminas(preset_id)
    # reservado de mirar a lanzar, como `regenerar_preset_light`
    with _taller_reservado(ctx):
        return _cambiar_laminas_en_taller(ctx, ficha, preset_id, datos, accion,
                                          lamina, texto)


def _cambiar_laminas_en_taller(ctx, ficha, preset_id, datos, accion, lamina, texto):
    """El cuerpo de `cambiar_laminas`, con el taller ya reservado."""
    lam = _laminas()
    mod = _moodboard()
    light = _light()
    origen = dict((ficha.get("datos") or {}).get("origen") or {})
    ids = lam.ids_de(origen)
    quitadas, propias, hoja = lam.config_de(origen)
    quitadas, propias = list(quitadas), dict(propias)
    correccion = {}
    dibujar = []

    if accion == "regenerar":
        if lamina not in ids:
            raise ErrorApi(400, f"esa lámina no está en el estilo: {lamina!r}")
        dibujar = [lamina]
        if texto:
            correccion[lamina] = texto
    elif accion == "cambiar":
        if lamina not in ids:
            raise ErrorApi(400, f"esa lámina no está en el estilo: {lamina!r}")
        if not texto and lamina not in mod.EJES:
            raise ErrorApi(400, "di qué tiene que enseñar la lámina")
        if texto and len(texto) < 8:
            raise ErrorApi(400, "descríbelo con algo más de detalle")
        if texto:
            propias[lamina] = texto
        else:
            propias.pop(lamina, None)
        dibujar = [lamina]
    elif accion == "nueva":
        if len(ids) >= lam.MAX_LAMINAS:
            raise ErrorApi(409, f"ya hay {lam.MAX_LAMINAS} láminas, las que caben "
                                f"en la hoja de cada plano: quita una antes")
        if len(texto) < 8:
            raise ErrorApi(400, "di qué tiene que enseñar la lámina nueva "
                                "(«una cocina de noche con luz cálida»)")
        lamina = lam.siguiente_extra(origen)
        propias[lamina] = texto
        dibujar = [lamina]
    elif accion == "quitar":
        if lamina not in ids:
            raise ErrorApi(400, f"esa lámina no está en el estilo: {lamina!r}")
        if len(ids) <= lam.MIN_LAMINAS:
            raise ErrorApi(409, f"un estilo necesita al menos {lam.MIN_LAMINAS} "
                                f"láminas: regenera o cambia esta en vez de quitarla")
        if lamina in mod.EJES:
            quitadas.append(lamina)
        else:
            propias.pop(lamina, None)
    elif accion == "restaurar":
        if lamina not in quitadas:
            raise ErrorApi(400, f"esa lámina no está quitada: {lamina!r}")
        if len(ids) >= lam.MAX_LAMINAS:
            raise ErrorApi(409, f"ya hay {lam.MAX_LAMINAS} láminas: quita una antes")
        quitadas.remove(lamina)
        if not os.path.isfile(_ruta_lamina(ctx, lamina)):
            dibujar = [lamina]
    elif accion == "hoja":
        nueva = str(datos.get("hoja") or "")
        if nueva not in lam.HOJAS:
            raise ErrorApi(400, "la hoja es «comun» o «repartida»")
        hoja = nueva
    else:
        raise ErrorApi(400, "acción desconocida: regenerar, cambiar, nueva, "
                            "quitar, restaurar u hoja")

    # SOLO LO QUE NO ES DE FABRICA se escribe: un estilo que vuelve a las seis
    # de siempre no se queda con claves vacias
    for clave, valor in (("laminas_quitadas", quitadas), ("laminas_propias", propias),
                         ("laminas_hoja", hoja if hoja != "comun" else "")):
        if valor:
            origen[clave] = valor
        else:
            origen.pop(clave, None)

    if accion == "hoja":
        # no se dibuja nada: vale para la proxima vez que se dibuje una lamina
        contenido = copy.deepcopy(ficha.get("datos") or {})
        contenido["origen"] = origen
        try:
            nueva_ficha = _presets().guardar(
                "canal", ficha.get("nombre") or "canal", contenido,
                nota=ficha.get("nota") or "",
                miniatura=ficha.get("miniatura") or "", pid=preset_id)
        except _presets().ErrorPreset as fallo:
            raise ErrorApi(400, str(fallo))
        return {"trabajo_id": "", "preset": nueva_ficha, "hoja": hoja}

    origen["nombre"] = ficha.get("nombre") or "canal"
    origen.setdefault("idioma", _presets().idioma_de(ficha) or "es")
    encargo = _encargo_o_400(origen)
    encargo["feedback"] = {}
    encargo["laminas"] = correccion
    encargo["laminas_solo"] = dibujar
    ctx.bitacora.anotar("laminas_estilo", None, {
        "preset": preset_id, "accion": accion, "lamina": lamina,
        "dibujar": dibujar, "texto": texto[:200]})
    trabajo_id = _lanzar_en_taller(
        ctx, "preset_light", _correr_preset_light, ctx, encargo,
        ["referencias", "muestra"], preset_id, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    plan = _plan_con_laminas(light.plan_de(encargo, ("referencias", "muestra")),
                             len(dibujar))
    return {"trabajo_id": trabajo_id, "taller": ctx.id, "accion": accion,
            "lamina": lamina, "imagenes": len(dibujar),
            "plan": plan,
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


# --------------------------------------------- tus imagenes de referencia

@app.get("/api/presets-light/{preset_id}/aportadas")
def aportadas_de_preset(preset_id: str):
    """Las imagenes de referencia de un estilo, con lo que se dijo de cada una."""
    ficha, ctx = _taller_con_laminas(preset_id)
    origen = (ficha.get("datos") or {}).get("origen") or {}
    sin = _light()._sin_prefijo
    descripciones = origen.get("estilo_descripciones") or {}
    destacadas = set(origen.get("estilo_destacadas") or [])
    salida = []
    for ruta in _aportadas_del_taller(ctx):
        base = sin(ruta)
        sello = int(os.path.getmtime(ruta))
        salida.append({"nombre": base,
                       "url": f"/api/presets-light/{preset_id}/aportadas/"
                              f"{base}/imagen?v={sello}",
                       "descripcion": str(descripciones.get(base) or ""),
                       "destacada": base in destacadas})
    return {"imagenes": salida, "tope": _light().max_imagenes_estilo(),
            "en_la_hoja": _light().MAX_EN_LA_HOJA}


@app.get("/api/presets-light/{preset_id}/aportadas/{nombre}/imagen")
def imagen_aportada(preset_id: str, nombre: str, peticion: Request):
    """Una de tus imagenes de referencia, tal cual la subiste."""
    _, ctx = _taller_con_laminas(preset_id)
    sin = _light()._sin_prefijo
    ruta = next((r for r in _aportadas_del_taller(ctx) if sin(r) == nombre), "")
    if not ruta:
        raise ErrorApi(404, "esa imagen no está en el estilo")
    return servir_fichero(peticion, ruta)


@app.put("/api/presets-light/{preset_id}/aportadas")
def describir_aportadas(preset_id: str, cuerpo: dict = Body(default=None)):
    """Guarda lo que se dice de cada imagen y las ★: {descripciones, destacadas}.

    No regenera nada: lo usan la guia (al regenerar el estilo) y la hoja de las
    laminas (al dibujar una). Se dice en pantalla.
    """
    datos = _cuerpo(cuerpo)
    ficha, ctx = _taller_con_laminas(preset_id)
    _taller_libre(ctx)
    light = _light()
    sin = light._sin_prefijo
    hay = {sin(r) for r in _aportadas_del_taller(ctx)}
    descripciones = {}
    for nombre, texto in (datos.get("descripciones") or {}).items():
        texto = " ".join(str(texto or "").split())[:light.MAX_DESCRIPCION]
        if sin(nombre) in hay and texto:
            descripciones[sin(nombre)] = texto
    destacadas = [sin(n) for n in (datos.get("destacadas") or [])
                  if isinstance(n, str) and sin(n) in hay][:light.MAX_EN_LA_HOJA]
    contenido = copy.deepcopy(ficha.get("datos") or {})
    origen = contenido.setdefault("origen", {})
    for clave, valor in (("estilo_descripciones", descripciones),
                         ("estilo_destacadas", destacadas)):
        if valor:
            origen[clave] = valor
        else:
            origen.pop(clave, None)
    try:
        nueva = _presets().guardar("canal", ficha.get("nombre") or "canal", contenido,
                                   nota=ficha.get("nota") or "",
                                   miniatura=ficha.get("miniatura") or "",
                                   pid=preset_id)
    except _presets().ErrorPreset as fallo:
        raise ErrorApi(400, str(fallo))
    return {"preset": nueva}


@app.put("/api/presets-light/{preset_id}")
def editar_preset_light(preset_id: str, cuerpo: dict = Body(default=None)):
    """El nombre, el idioma y la guia de tono: lo que se cambia a mano.

    NINGUNO DE LOS DOS CUESTA UNA IMAGEN. El nombre es una cadena. El idioma
    cambia los params --y con ellos lo que se aplica a un video-- y ademas
    ADAPTA lo que lleva lengua dentro: reescribe las instrucciones del guion (una
    llamada al CLI, por suscripcion) y vuelve a componer el texto de las muestras
    sobre los planos limpios, que siguen ahi sin tocar. Cero imagenes, unos
    cuarenta segundos, y por eso duplicar un estilo y cambiarle el idioma es una
    operacion normal y no una regeneracion.
    """
    presets = _presets()
    light = _light()
    datos = _cuerpo(cuerpo)
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "esto no es un preset de canal")

    nombre = " ".join(str(datos.get("nombre") or "").split()) or ficha["nombre"]
    idioma = str(datos.get("idioma") or "").strip().lower()
    # LA GUIA DE TONO SE EDITA A MANO, y por eso entra por el mismo PUT que el
    # nombre: no cuesta nada, es un texto. Se manda entera --el parrafo mas los
    # rasgos, que es lo que se pega en el brief-- y se guarda tal cual, sin
    # limpiar los saltos de linea: es un texto de mil palabras con su forma.
    #
    # `None` es «no me han mandado nada» y la cadena vacia es «borrala»: con un
    # `or` serian lo mismo y guardar el nombre desde otro sitio se llevaria por
    # delante una guia de mil palabras sin decir nada.
    instrucciones = datos.get("instrucciones")
    instrucciones = None if instrucciones is None else str(instrucciones).strip()
    # «es-419» es «es» con la variante latina (ver presets_light.separar_idioma)
    idioma_pedido = idioma
    idioma, variante = light.separar_idioma(idioma)
    if idioma and idioma not in light.IDIOMAS:
        raise ErrorApi(400, f"idioma desconocido: {idioma_pedido!r}. Los que hay son: "
                            + ", ".join(light.IDIOMAS_PANTALLA))

    contenido = copy.deepcopy(ficha.get("datos") or {})

    # EL RITMO TAMPOCO REGENERA NADA: escribe los mismos tres campos de duracion
    # que el modo editor tiene en su tarjeta de estilo, mas el aire entre
    # bloques. Lo que NO toca es la velocidad de la voz: esa se decidio una vez
    # leyendo lo que pediste, y cambiarla por mover un deslizador seria pisar
    # una decision tuya sin decirlo. Si la quieres mas rapida, se pide en su caja.
    # LOS MANDOS DE LA VOZ, uno a uno. Se eligieron describiendo como querias
    # que sonara, y esto es la vuelta de tuerca fina: cambiar la voz concreta,
    # la velocidad, las emociones o el aire sin volver a describir nada. No
    # cuesta nada --son params-- y por eso viven en el mismo PUT que el nombre.
    voz_pedida = datos.get("voz") if isinstance(datos.get("voz"), dict) else None

    adaptar = bool(idioma and idioma != presets.idioma_de(ficha))
    ritmo = str(datos.get("ritmo") or "").strip().lower()
    if ritmo:
        if ritmo not in light.RITMOS_POR_ID:
            raise ErrorApi(400, f"ritmo desconocido: {ritmo!r}. Los que hay son: "
                                + ", ".join(light.RITMOS_POR_ID))
        cambios_ritmo = light.params_de_ritmo(ritmo)
        estilo = dict(contenido.get("estilo") or {})
        estilo.update(cambios_ritmo["assets"])
        contenido["estilo"] = estilo
        if contenido.get("voz"):
            contenido["voz"] = dict(contenido["voz"], **cambios_ritmo["voz"])
        contenido.setdefault("origen", {})["ritmo"] = ritmo
        try:
            _sembrar_taller(_taller_de(ficha), {"idioma": presets.idioma_de(ficha)
                                                or "es", "ritmo": ritmo})
        except ErrorApi:
            pass                    # sin taller el preset sigue siendo correcto

    if voz_pedida:
        limpios = {c: voz_pedida[c] for c in presets.TIPOS["voz"]["claves"]
                   if c in voz_pedida and voz_pedida[c] not in (None, "")}
        sobran = [c for c in voz_pedida if c not in presets.TIPOS["voz"]["claves"]]
        if sobran:
            raise ErrorApi(400, "un preset de voz no guarda "
                                + ", ".join(sorted(sobran)))
        if limpios:
            contenido["voz"] = dict(contenido.get("voz") or {}, **limpios)
            # y el origen recuerda la voz elegida a mano: rehacer «la voz» con
            # una frase pone los mandos a ESTA, no vuelve a elegir otra
            if limpios.get("voz_id"):
                contenido.setdefault("origen", {})["voz_id"] = limpios["voz_id"]
            try:
                _sembrar_voz(_taller_de(ficha), limpios)
            except ErrorApi:
                pass            # sin taller el preset sigue siendo correcto


    if instrucciones is not None:
        contenido.setdefault("guion", {})["instrucciones"] = instrucciones
        # Y AL TALLER, que es de donde sale la proxima congelacion. Sin esto,
        # rehacer despues la VOZ --o el ritmo, o cualquier cosa-- vuelve a
        # congelar el preset desde los params del taller y se lleva por delante
        # lo editado a mano, en silencio y sin que nadie lo haya pedido.
        try:
            _taller_de(ficha).estado.actualizar_params(
                "brief", {"instrucciones": instrucciones})
        except ErrorApi:
            pass                    # sin taller el preset sigue siendo correcto

    # LA PRESENTACION Y LAS LLAMADAS A LA ACCION, por el mismo PUT que el nombre
    # y la guia de tono: no cuestan nada --son texto y dos desplegables-- y son
    # del canal, que es lo que se escribe una vez y se repite en cada video. Van
    # al bloque `guion` del preset, que es de donde salen los params del guion
    # de cada video que se haga con este estilo.
    if datos.get("cta") is not None:
        try:
            contenido.setdefault("guion", {})["cta"] = _cta().normalizar(
                datos["cta"], estricto=True)
        except ValueError as fallo:
            raise ErrorApi(400, f"cta: {fallo}")
        # Y AL TALLER, por lo mismo que las instrucciones: sin esto, rehacer
        # cualquier parte vuelve a congelar el preset desde los params del
        # taller y se lleva por delante lo que se acaba de escribir.
        try:
            _taller_de(ficha).estado.actualizar_params(
                "guion", {"cta": contenido["guion"]["cta"]})
        except ErrorApi:
            pass                    # sin taller el preset sigue siendo correcto

    idioma_anterior = presets.idioma_de(ficha)
    variante_anterior = presets.variante_de(ficha)
    solo_variante = bool(idioma) and idioma == idioma_anterior \
        and variante != variante_anterior
    if idioma and (idioma != idioma_anterior or solo_variante):
        contenido.setdefault("guion", {})["idioma_salida"] = idioma
        contenido["guion"].pop("idiomas_salida", None)
        if variante:
            contenido["guion"]["variante_idioma"] = variante
        else:
            contenido["guion"].pop("variante_idioma", None)
        if contenido.get("voz"):
            contenido["voz"]["idioma"] = idioma
        contenido.setdefault("origen", {})["idioma"] = idioma
        if variante:
            contenido["origen"]["variante_idioma"] = variante
        else:
            contenido["origen"].pop("variante_idioma", None)
        # Y en el taller, que es de donde saldria la proxima regeneracion: sin
        # esto, corregir el tono despues de cambiar el idioma lo devolveria al
        # anterior en silencio.
        try:
            ctx = _taller_de(ficha)
            _sembrar_taller(ctx, {"idioma": idioma, "variante_idioma": variante})
        except ErrorApi:
            pass                    # sin taller el preset sigue siendo correcto
    try:
        nueva = presets.guardar("canal", nombre, contenido,
                                nota=ficha.get("nota") or "",
                                miniatura=ficha.get("miniatura") or "",
                                pid=preset_id)
    except presets.ErrorPreset as fallo:
        raise ErrorApi(400, str(fallo))

    # CAMBIAR DE IDIOMA ADAPTA, NO REGENERA. Dos cosas llevan lengua dentro --las
    # instrucciones del guion y el texto dibujado en las muestras-- y las dos se
    # rehacen sin pagar una sola imagen: la primera es una llamada al CLI y la
    # segunda es volver a componer el texto sobre los planos limpios, que siguen
    # ahi. Ver `presets_light.TAREAS_DE_IDIOMA`.
    salida = {"preset": nueva}
    # LO QUE NO SE ADAPTA, DICHO Y CON SU PRECIO. Las laminas de estilo pueden
    # llevar letras DENTRO --el eje «diagrama» casi siempre-- y esas se
    # dibujaron en el idioma anterior. Cambiar el idioma no las redibuja (seis
    # imagenes; ver `presets_light.TAREAS_DE_IDIOMA`), y como despues viajan
    # como referencia dentro de cada plano con componentes, callarlo seria
    # dejar que ensenen a rotular en el idioma viejo sin que nadie lo sepa.
    aviso = light.aviso_de_idioma(idioma_anterior, idioma) if idioma else ""
    if aviso:
        salida["aviso_laminas"] = aviso
    if not adaptar:
        return salida
    try:
        ctx = _taller_de(nueva)
    except ErrorApi as fallo:
        # sin taller el estilo sigue siendo correcto: lo que queda es el tono en
        # la lengua anterior, y se dice en vez de callarlo
        salida["aviso"] = (f"el idioma ya está cambiado, pero {fallo.mensaje} — "
                           f"las instrucciones del guion y el texto de las "
                           f"muestras se quedan en el idioma anterior")
        return salida
    origen = dict((nueva.get("datos") or {}).get("origen") or {})
    origen["nombre"] = nombre
    origen["idioma"] = idioma
    encargo = _encargo_o_400(origen)
    _sembrar_taller(ctx, encargo)
    trabajo_id = _lanzar_en_taller(
        ctx, "preset_light", _correr_preset_light, ctx, encargo,
        list(light.TAREAS_DE_IDIOMA), preset_id, False, paso="assets")
    _registrar_trabajo(trabajo_id, ctx.id)
    ctx.bitacora.anotar("preset_light_idioma", None,
                        {"preset": preset_id, "idioma": idioma})
    salida.update({"trabajo_id": trabajo_id, "taller": ctx.id,
                   "plan": light.plan_de(encargo, light.TAREAS_DE_IDIOMA),
                   "trabajo": ctx.gestor.estado(trabajo_id),
                   "eventos": f"/api/trabajos/{trabajo_id}/eventos"})
    return salida


# ======================================================== REGLAS DEL ESTILO
#
# Ver pasos/reglas_estilo.py. Se escriben en el ESTILO (el preset), no en el
# video: viajan a cada video nuevo al crearlo y a uno ya hecho con «Traer el
# estilo», como el resto del estilo. Guardarlas no paga nada; lo que cuesta
# --si se quiere-- es rehacer las imagenes de un video que las trae.

_AFINADOS = {}
_LOCK_AFINADOS = threading.Lock()


def _reglas_estilo():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, "los pasos no están cargados")
    import importlib                                         # noqa: PLC0415
    return importlib.import_module("pasos.reglas_estilo")


@app.get("/api/presets-light/{preset_id}/reglas")
def leer_reglas_estilo(preset_id: str):
    """Las reglas de un estilo. -> {reglas, gravedades, maximo}"""
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "esto no es un preset de canal")
    modulo = _reglas_estilo()
    estilo = (ficha.get("datos") or {}).get("estilo") or {}
    return {"reglas": modulo.de_estilo(estilo), "gravedades": list(modulo.GRAVEDADES),
            "maximo": modulo.MAX_REGLAS}


@app.put("/api/presets-light/{preset_id}/reglas")
def guardar_reglas_estilo(preset_id: str, cuerpo: dict = Body(default=None)):
    """Guarda las reglas de un estilo: {reglas: [{id?, nombre, texto, palabras?,
    gravedad?, en?}]}. Una lista vacia las quita. No toca ningun video: llegan
    a los nuevos al crearlos y a los hechos con «Traer el estilo»."""
    presets = _presets()
    modulo = _reglas_estilo()
    datos = _cuerpo(cuerpo)
    if "reglas" not in datos:
        raise ErrorApi(400, "manda {reglas: [...]} (una lista vacía las quita)")
    try:
        reglas = modulo.normalizar(datos.get("reglas"))
    except modulo.ReglaInvalida as fallo:
        raise ErrorApi(400, str(fallo))
    # LEER, CAMBIAR Y ESCRIBIR CON EL CERROJO DE LOS PRESETS (reentrante: el
    # `guardar` de dentro lo vuelve a coger). Sin el, una congelacion del taller
    # que cayera entre la lectura y la escritura --un «rehacer» del estilo, que
    # se paga-- se perderia: esto volveria a escribir el estilo de antes.
    with presets.lock_de(presets.FICHERO):
        ficha = _preset_o_400(lambda p: p.leer(preset_id))
        if ficha.get("tipo") != "canal":
            raise ErrorApi(400, "esto no es un preset de canal")
        contenido = copy.deepcopy(ficha.get("datos") or {})
        estilo = dict(contenido.get("estilo") or {})
        if reglas and not estilo.get("referencias"):
            raise ErrorApi(400, "este estilo todavía no tiene su estilo gráfico (las "
                                "láminas): genéralo antes de ponerle reglas")
        antes = modulo.de_estilo(estilo)
        if reglas == antes:
            return {"reglas": reglas, "cambiado": False}
        if reglas:
            estilo["reglas"] = reglas
        else:
            estilo.pop("reglas", None)
        if estilo:
            contenido["estilo"] = estilo
        else:
            contenido.pop("estilo", None)
        try:
            nueva = presets.guardar("canal", ficha.get("nombre") or "", contenido,
                                    nota=ficha.get("nota") or "",
                                    miniatura=ficha.get("miniatura") or "",
                                    pid=preset_id)
        except presets.ErrorPreset as fallo:
            raise ErrorApi(400, str(fallo))
    anotar_global("reglas_estilo", {"preset": preset_id, "reglas": len(reglas)})
    return {"reglas": modulo.de_estilo((nueva.get("datos") or {}).get("estilo") or {}),
            "cambiado": True}


@app.get("/api/presets-light/{preset_id}/relato")
def leer_relato_estilo(preset_id: str):
    """El tipo de relato por defecto de un estilo (rama tipo-de-relato).
    -> {relato: {} | {modo, cambia?}, modos, cambia}"""
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "esto no es un preset de canal")
    tr = _tipo_relato()
    estilo = (ficha.get("datos") or {}).get("estilo") or {}
    try:
        relato = tr.normalizar_de_estilo(estilo.get("relato"))
    except ValueError:
        relato = {}
    return {"relato": relato,
            "modos": [{"clave": k, "nombre": v} for k, v in tr.MODOS.items()],
            "cambia": [{"clave": k, "nombre": v} for k, v in tr.CAMBIA.items()]}


@app.put("/api/presets-light/{preset_id}/relato")
def guardar_relato_estilo(preset_id: str, cuerpo: dict = Body(default=None)):
    """Guarda el tipo de relato por defecto de un estilo: {relato: {modo, cambia?}}.
    Documental (o null) lo quita. No toca ningun video: llega a los nuevos al
    crearlos y a los hechos con «Traer el estilo» (con su aviso de siempre)."""
    presets = _presets()
    tr = _tipo_relato()
    datos = _cuerpo(cuerpo)
    if "relato" not in datos:
        raise ErrorApi(400, "manda {relato: {modo, cambia}} (null lo quita)")
    try:
        relato = tr.normalizar_de_estilo(datos.get("relato") or {})
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    with presets.lock_de(presets.FICHERO):
        ficha = _preset_o_400(lambda p: p.leer(preset_id))
        if ficha.get("tipo") != "canal":
            raise ErrorApi(400, "esto no es un preset de canal")
        contenido = copy.deepcopy(ficha.get("datos") or {})
        estilo = dict(contenido.get("estilo") or {})
        try:
            antes = tr.normalizar_de_estilo(estilo.get("relato"))
        except ValueError:
            antes = {}
        if relato == antes:
            return {"relato": relato, "cambiado": False}
        if relato:
            estilo["relato"] = relato
        else:
            estilo.pop("relato", None)
        if estilo:
            contenido["estilo"] = estilo
        else:
            contenido.pop("estilo", None)
        try:
            presets.guardar("canal", ficha.get("nombre") or "", contenido,
                            nota=ficha.get("nota") or "",
                            miniatura=ficha.get("miniatura") or "", pid=preset_id)
        except presets.ErrorPreset as fallo:
            raise ErrorApi(400, str(fallo))
    anotar_global("relato_estilo", {"preset": preset_id, "modo": relato.get("modo")})
    return {"relato": relato, "cambiado": True}


# ------------------------------------------------------------------ DOMINIOS
#
# Rama dominio-negocio (21-10-2026). Lo de cada negocio (servicios, cartas de
# foto, frases del revisor) vive en `pasos/dominios.py`. Un estilo puede fijar
# el suyo (`estilo.dominio`); sin fijar, se detecta por el texto como siempre.
# La pantalla para elegirlo llega con la Etapa Foto C: aqui, leerlo y fijarlo.

@app.get("/api/dominios")
def listar_dominios(peticion: Request = None):
    """El negocio general y las fichas de los clientes (Etapa Foto C).
    -> {dominios, automatico}"""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    cerrados = _cerrados(peticion) if peticion is not None else set()
    return {"dominios": [d for d in PASOS_MODULOS.dominios.listar()
                         if (d.get("cliente") or "") not in cerrados],
            "automatico": "sin ficha: el general, sin reglas de ningún negocio"}


# ------------------------------------------------- LA FICHA DEL NEGOCIO
#
# Etapa Foto C (21-10-2026): el negocio de cada cliente es una FICHA de su
# proyecto (qué hace, sus reglas de foto, lo que vigila el revisor), en
# `<proyectos>/_sistema/dominios.json` (`dominios.ruta_usuario`), fuera del
# código. Los estilos del proyecto la llevan en `estilo.dominio` (la pone
# `_negocio_al_estilo` al guardar la ficha, al borrarla, al mover un estilo de
# proyecto y al crear uno dentro) y llega a los vídeos nuevos al crearlos y a
# los hechos con «Traer el estilo», como el resto del estilo. Cambiar las reglas
# de una ficha que ya usa un vídeo de foto cambia el prompt de sus imágenes:
# quedan para rehacer, y rehacerlas se paga.

def _negocio_al_estilo(preset_id):
    """Pone en el estilo `preset_id` la ficha del negocio de su proyecto (o se
    la quita si su proyecto no tiene). -> el id puesto ("" si ninguno)"""
    dominios = PASOS_MODULOS.dominios
    presets = _presets()
    with presets.lock_de(presets.FICHERO):
        # el proyecto y su ficha se leen DENTRO del cerrojo: quitar la ficha y
        # mover el estilo a la vez dejaba el id de una ficha ya borrada
        cid = CLIENTES.cliente_de(raiz_proyectos(), estilo_id=preset_id) or ""
        negocio = dominios.de_cliente(cid) if cid else None
        tid = negocio["id"] if negocio else ""
        try:
            ficha = presets.leer(preset_id)
        except presets.ErrorPreset:
            return ""
        if ficha.get("tipo") != "canal":
            return ""
        contenido = copy.deepcopy(ficha.get("datos") or {})
        estilo = dict(contenido.get("estilo") or {})
        if not estilo.get("referencias"):
            return ""              # sin estilo gráfico todavía: no hay donde
        if estilo.get("modo") != "foto":
            # la ficha solo cambia las imágenes de FOTO: en un estilo de dibujo
            # no se escribe, y así no mueve la firma de sus vídeos al traerlo
            tid = ""
        if (estilo.get("dominio") or "") == tid:
            return tid
        if tid:
            estilo["dominio"] = tid
        else:
            estilo.pop("dominio", None)
        contenido["estilo"] = estilo
        try:
            presets.guardar("canal", ficha.get("nombre") or "", contenido,
                            nota=ficha.get("nota") or "",
                            miniatura=ficha.get("miniatura") or "", pid=preset_id)
        except presets.ErrorPreset:
            return ""
    return tid


def _estilos_del_cliente(cid):
    """Los ids de los estilos de un proyecto."""
    asignados = (CLIENTES.listar(raiz_proyectos()) or {}).get("estilos") or {}
    return [pid for pid, dueno in asignados.items() if dueno == cid]


def _cliente_que_existe(cid):
    cid = str(cid or "").strip()
    clientes = (CLIENTES.listar(raiz_proyectos()) or {}).get("clientes") or []
    if not any(c.get("id") == cid for c in clientes):
        raise ErrorApi(404, "ese proyecto no existe")
    return cid


def _negocio_abierto(peticion, cid):
    """El proyecto existe y quien pide puede verlo (los de clave, con su pase)."""
    cid = _cliente_que_existe(cid)
    if peticion is not None and cid in _cerrados(peticion):
        raise ErrorApi(403, "este proyecto tiene clave: ábrelo primero")
    return cid


@app.get("/api/clientes/{cid}/negocio")
def leer_negocio_cliente(cid: str, peticion: Request = None):
    """La ficha del negocio de un proyecto. -> {negocio: ficha|null, estilos}"""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    cid = _negocio_abierto(peticion, cid)
    crudo = PASOS_MODULOS.dominios.de_cliente(cid)
    return {"negocio": PASOS_MODULOS.dominios.publicar(crudo) if crudo else None,
            "estilos": len(_estilos_del_cliente(cid))}


@app.put("/api/clientes/{cid}/negocio")
def guardar_negocio_cliente(cid: str, cuerpo: dict = Body(default=None),
                            peticion: Request = None):
    """Crea o cambia la ficha del negocio de un proyecto: {nombre, reglas?,
    revisor?: {equipo?, orientacion?}}. Se la pone a todos sus estilos.
    -> {negocio, estilos: cuántos la llevan}"""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    cid = _negocio_abierto(peticion, cid)
    try:
        crudo = PASOS_MODULOS.dominios.guardar_de_cliente(cid, _cuerpo(cuerpo))
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    puestos = sum(1 for pid in _estilos_del_cliente(cid) if _negocio_al_estilo(pid))
    anotar_global("negocio_guardado", {"cliente": cid, "estilos": puestos})
    return {"negocio": PASOS_MODULOS.dominios.publicar(crudo), "estilos": puestos}


@app.delete("/api/clientes/{cid}/negocio")
def borrar_negocio_cliente(cid: str, peticion: Request = None):
    """Quita la ficha del negocio de un proyecto: sus estilos vuelven a
    automático (general). Los vídeos ya creados no cambian."""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    cid = _negocio_abierto(peticion, cid)
    if not PASOS_MODULOS.dominios.borrar_de_cliente(cid):
        raise ErrorApi(404, "este proyecto no tiene ficha del negocio")
    for pid in _estilos_del_cliente(cid):
        _negocio_al_estilo(pid)
    anotar_global("negocio_borrado", {"cliente": cid})
    return {"borrado": cid}


@app.put("/api/presets-light/{preset_id}/dominio")
def guardar_dominio_estilo(preset_id: str, cuerpo: dict = Body(default=None)):
    """Fija el negocio de un estilo: {dominio: id de un tipo (de fábrica o del
    dueño) | null}.
    null (o "") vuelve a la deteccion automatica. No toca ningun video: llega a
    los nuevos al crearlos y a los hechos con «Traer el estilo»."""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    presets = _presets()
    datos = _cuerpo(cuerpo)
    if "dominio" not in datos:
        raise ErrorApi(400, "manda {dominio: id} (null vuelve a automático)")
    try:
        dominio = PASOS_MODULOS.dominios.normalizar(datos.get("dominio"))
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    # una ficha de cliente, solo la del PROYECTO de este estilo y si sigue viva
    # (Etapa Foto C): la de otro cliente o una borrada no se eligen
    if dominio and dominio not in PASOS_MODULOS.dominios.DE_FABRICA:
        cid = CLIENTES.cliente_de(raiz_proyectos(), estilo_id=preset_id) or ""
        propia = PASOS_MODULOS.dominios.de_cliente(cid) if cid else None
        if not propia or propia["id"] != dominio:
            raise ErrorApi(400, "esa ficha del negocio no es la del proyecto de este estilo")
    with presets.lock_de(presets.FICHERO):
        ficha = _preset_o_400(lambda p: p.leer(preset_id))
        if ficha.get("tipo") != "canal":
            raise ErrorApi(400, "esto no es un preset de canal")
        contenido = copy.deepcopy(ficha.get("datos") or {})
        estilo = dict(contenido.get("estilo") or {})
        if dominio and not estilo.get("referencias"):
            raise ErrorApi(400, "este estilo todavía no tiene su estilo gráfico (las "
                                "láminas): genéralo antes de fijarle el negocio")
        if (estilo.get("dominio") or "") == dominio:
            return {"dominio": dominio, "cambiado": False}
        if dominio:
            estilo["dominio"] = dominio
        else:
            estilo.pop("dominio", None)
        if estilo:
            contenido["estilo"] = estilo
        else:
            contenido.pop("estilo", None)
        try:
            presets.guardar("canal", ficha.get("nombre") or "", contenido,
                            nota=ficha.get("nota") or "",
                            miniatura=ficha.get("miniatura") or "", pid=preset_id)
        except presets.ErrorPreset as fallo:
            raise ErrorApi(400, str(fallo))
    anotar_global("dominio_estilo", {"preset": preset_id, "dominio": dominio or "automatico"})
    return {"dominio": dominio, "cambiado": True}


@app.post("/api/reglas-estilo/afinar", status_code=202)
def afinar_regla_estilo(cuerpo: dict = Body(default=None)):
    """Claude reescribe una regla para el generador: {texto, nombre?, palabras?}.
    -> {id}; el resultado ({nombre, en, palabras, gravedad}) en GET. No guarda
    nada: lo propone y la persona lo acepta."""
    modulo = _reglas_estilo()
    datos = _cuerpo(cuerpo)
    texto = " ".join(str(datos.get("texto") or "").split())
    if not texto:
        raise ErrorApi(400, "escribe primero lo que exige la regla")
    palabras = datos.get("palabras") if isinstance(datos.get("palabras"), list) else []
    rid = uuid.uuid4().hex[:12]
    with _LOCK_AFINADOS:
        # DE UNA EN UNA: cada una es una llamada al CLI con su cupo, y nadie la
        # cancela; pulsar diez veces no puede lanzar diez
        if any(f.get("estado") == "pensando" for f in _AFINADOS.values()):
            raise ErrorApi(409, "Claude ya está afinando otra regla: espera a que termine")
        for viejo in list(_AFINADOS)[:-19]:
            _AFINADOS.pop(viejo, None)
        _AFINADOS[rid] = {"estado": "pensando"}

    def correr():
        try:
            propuesta = modulo.afinar(texto, nombre=str(datos.get("nombre") or ""),
                                      palabras=[str(p) for p in palabras],
                                      cwd=RAIZ_ESTUDIO)
            ficha = {"estado": "listo", "propuesta": propuesta}
        except Exception as fallo:                          # noqa: BLE001
            ficha = {"estado": "error", "error": str(fallo)[:600]}
        with _LOCK_AFINADOS:
            _AFINADOS[rid] = ficha

    try:
        threading.Thread(target=correr, daemon=True, name=f"afinar-{rid}").start()
    except RuntimeError as fallo:
        # sin hilo, la entrada no puede quedarse «pensando» para siempre: con
        # ella asi, el 409 de arriba bloquearia afinar hasta reiniciar
        with _LOCK_AFINADOS:
            _AFINADOS[rid] = {"estado": "error", "error": str(fallo)[:300]}
        raise ErrorApi(503, "no se ha podido arrancar: inténtalo otra vez")
    return {"id": rid, "estado": "pensando"}


@app.get("/api/reglas-estilo/afinar/{rid}")
def leer_afinado_regla(rid: str):
    """Como va «Afinar con Claude», y la propuesta al terminar."""
    with _LOCK_AFINADOS:
        ficha = _AFINADOS.get(rid)
    if not ficha:
        raise ErrorApi(404, "esa propuesta ya no está: vuelve a pedirla")
    return ficha


@app.delete("/api/presets-light/{preset_id}")
def borrar_preset_light(preset_id: str):
    """A la papelera de presets, y su taller con el.

    El taller no vale para nada sin su preset --son fotogramas de un estilo que
    ya no se puede aplicar-- y son cientos de megas. Va a la papelera de
    proyectos, que es donde se puede recuperar si el borrado fue un error.
    """
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    tid = ((ficha.get("datos") or {}).get("origen") or {}).get("taller")
    apartado = _preset_o_400(lambda p: p.apartar(preset_id))
    taller = ""
    if tid:
        try:
            apartar_proyecto(tid)
            taller = tid
        except ErrorApi:
            taller = ""             # ya no estaba: el preset se aparta igual
    return {"apartado": preset_id, "preset": apartado, "taller": taller}


# ==========================================================================
# EL VIDEO DEL MODO LIGHT: de un ESTILO a un MP4, en tres botones
#
# El modo light llegaba hasta el estilo (PENDIENTE 29). De aqui para abajo esta
# la segunda mitad: elegir un estilo y HACER UN VIDEO con el.
#
# LAS TRES TANDAS, y no cinco pestanas. En el modo editor cada pestana es una
# parada porque cada una tiene decisiones dentro. Aqui las decisiones son tres,
# y coinciden con las tres cosas que se pueden MIRAR antes de seguir:
#
#     guion            se lee y se corrige (a mano, por prompt, por bloque)
#     voz              se escucha, y editar un bloque regraba su seccion
#     video            se ve escena a escena, con su audio y su feedback
#     render           se monta, y se mira el MP4 entero
#
# HASTA EL 27-08 ERAN TRES: 'video' y 'render' iban juntas con el argumento de
# que entre las dos no habia ninguna decision. La hay, y es la mas cara de
# saltarse -- mirar los planos con su audio ANTES de montar --, asi que ahora
# son cuatro paradas y el MP4 es lo que se pide cuando ya has mirado.
#
# ESTO ES TAMBIEN PENDIENTE 28 (la tirada de punta a punta), que sale de
# standby: `POST /api/proyectos/{pid}/generar` acepta las pestanas que se le
# pidan, asi que las cinco de una tirada son un caso mas. Lo que no puede
# romper, y por eso esta escrito asi: el coste se dice ANTES (`GET .../generar`
# no lanza nada), y se puede interrumpir y retomar -- cancelar el trabajo corta
# donde este, y volver a lanzarlo en modo 'pendientes' se salta lo que ya salio.
# ==========================================================================

#: Marca en la config del proyecto: este video se hizo desde el modo light.
#: NO lo esconde de la lista (un video es un video, se haga por donde se haga);
#: lo que hace es decidir por el las tareas que en el modo editor se eligen a
#: mano. Hoy, una: la direccion de cada plano.
CONFIG_VIDEO_LIGHT = "video_light"

#: Y de que estilo salio, para poder decirlo y para poder volver a aplicarlo.
CONFIG_ESTILO_LIGHT = "estilo_light"

#: Las tandas del modo light, en orden, con las pestanas que recorre cada una.
TANDAS_LIGHT = [
    {"id": "guion", "nombre": "El guion", "pestanas": ["guion"],
     "porque": "lee el material y redacta el guion"},
    {"id": "voz", "nombre": "La voz", "pestanas": ["voz"],
     "porque": "adapta las siglas y las cifras, sintetiza y alinea"},
    # EL MP4 YA NO ENTRA AQUI. Esta tanda deja hecho todo lo que hace falta para
    # MIRAR el video sin montarlo --los planos, los subtitulos, las cartelas, la
    # musica y los efectos-- y se para. Lo que se mira despues es el
    # previsualizador escena a escena, y renderizar es lo que
    # se hace cuando ya has mirado.
    # LAS DIAPOSITIVAS SON LAS IMAGENES, Y NADA MAS.
    #
    # Llevaba tambien `callouts` --los subtitulos, las cartelas y el movimiento
    # de camara-- y eso ya no cuadra con lo que hace cada pantalla: en Imagenes
    # se mira el DIBUJO y nada mas (se quito de ahi todo lo que se monta
    # encima), asi que nada de callouts hace falta para esa revision.
    #
    # Donde si hace falta es al montar, y ahi es donde esta ahora. La cadena
    # queda en tres piezas con una frontera clara: guion y audio; las imagenes,
    # que solo dependen de esos dos; y el montaje, que es todo lo que se pone
    # encima --rotulos, transiciones, musica y efectos--.
    #
    # Efecto de lado, y es la mitad del motivo: rehacer un plano suelto dejaba
    # `callouts` obsoleto, y con callouts aqui dentro eso pintaba «Obsoleto» al
    # lado de las diapositivas, que estaban perfectamente al dia.
    {"id": "video", "nombre": "Las imágenes", "pestanas": ["video"],
     "sin": ["callouts"],
     "porque": "dibuja un plano por escena, listos para mirarlos uno a uno"},
    # MONTAR ES MONTAR LO QUE HAY, Y LO QUE HAY TIENE QUE ESTAR AL DIA.
    #
    # Esta tanda llevaba solo ["render"], asi que montaba con los rotulos de la
    # pasada anterior. Rehacer un plano suelto deja `callouts` obsoleto --su
    # movimiento y su capa son de ese dibujo-- y el render se plantaba con
    # «S007: el paso callouts no dejo movimiento», que no dice nada de lo que
    # de verdad pasa.
    #
    # Lleva la pestana entera y NO redibuja nada: el modo es «pendientes», y
    # ahi todo lo que ya esta al dia se salta (ver `_esta_al_dia`). Con assets
    # listo, lo unico que corre es lo que se quedo viejo.
    {"id": "render", "nombre": "El MP4", "pestanas": ["video", "render"],
     "porque": "pone al día los rótulos si hace falta y monta el vídeo"},
]
TANDAS_LIGHT_POR_ID = {t["id"]: t for t in TANDAS_LIGHT}


def _sin_de_la_tanda(datos):
    """Las tareas que esta tanda NO corre, aunque la receta las de por puestas.

    No se puede pedir por la receta: `recetas.resolver` fuerza las tareas no
    opcionales --y el render lo es-- justamente para que una receta guardada no
    se salte un paso obligado. Eso esta bien y no se toca; lo que una tanda dice
    es otra cosa: no que el paso sobre, sino que no toca AHORA.

    Hoy solo lo usa la tanda 'video' del modo light, que se para antes de montar
    el MP4 para que se pueda mirar escena a escena.
    """
    ficha = TANDAS_LIGHT_POR_ID.get(
        str((datos or {}).get("tanda") or "").strip().lower()) or {}
    return set(ficha.get("sin") or ())


# ------------------------------------------------- lo que lleva cada video
# «Que lleva este video»: voz, subtitulos, musica y efectos, elegidos al
# crearlo. Viven en la CONFIG del proyecto, que no entra en ninguna firma: se
# pueden guardar y leer sin dejar nada obsoleto. Lo que de verdad cambia el
# resultado se escribe en params SOLO cuando cambia de verdad:
#
#   subtitulos   el param `subtitulos: false` de callouts (rehace la capa de
#                subtitulos y el montaje; ni una imagen)
#   musica       la tanda se salta «La banda sonora»; y al APAGARLA en un video
#                que ya la tenia, `musica: {}` en render (solo el montaje)
#   efectos      lo mismo con «Los efectos de sonido» y `efectos: {}`
#   voz          todo el video se cronometra con la locucion: un video sin voz
#                necesita otro reloj, y llega en la fase 3. De momento SIEMPRE
#                lleva voz y apagarla se rechaza con su motivo.
CONFIG_LLEVA = "lleva"
LLEVA_POR_DEFECTO = {"voz": True, "subtitulos": True, "musica": True, "efectos": True}
# que tarea de la receta se salta cuando el video no lleva esa cosa
TAREA_DE_LLEVA = {"musica": "banda_sonora", "efectos": "efectos"}


def lleva_de(ctx):
    """Lo que lleva este video. Lo que no se eligio nunca, lo lleva (como antes)."""
    guardado = ctx.proyecto.config.get(CONFIG_LLEVA)
    salida = dict(LLEVA_POR_DEFECTO)
    if isinstance(guardado, dict):
        for clave in salida:
            if isinstance(guardado.get(clave), bool):
                salida[clave] = guardado[clave]
    return salida


def _normalizar_lleva(crudo):
    """Lo que manda la pantalla, validado. -> {clave: bool} solo con lo enviado."""
    if not isinstance(crudo, dict):
        raise ErrorApi(400, "«lleva» tiene que ser un objeto: "
                            "{voz, subtitulos, musica, efectos}")
    limpio = {}
    for clave, valor in crudo.items():
        if clave not in LLEVA_POR_DEFECTO:
            raise ErrorApi(400, f"«lleva» no sabe qué es «{clave}»: son "
                                + ", ".join(LLEVA_POR_DEFECTO))
        if not isinstance(valor, bool):
            raise ErrorApi(400, f"«lleva.{clave}» tiene que ser true o false")
        limpio[clave] = valor
    if limpio.get("voz") is False:
        raise ErrorApi(400, "un vídeo sin voz todavía no se puede hacer: todo el "
                            "montaje se cronometra con la locución. Llega en la "
                            "próxima actualización")
    return limpio


def _aplicar_lleva(ctx, pedido, al_crear=False):
    """Guarda lo que lleva el video y escribe en params lo que cambia de verdad.

    -> lo que lleva ahora. `al_crear`: en un video recien creado no hay nada
    hecho, asi que solo se escribe lo que se APAGA (el defecto es llevarlo).
    """
    antes = lleva_de(ctx)
    ahora = dict(antes)
    ahora.update(pedido)
    ctx.proyecto.config[CONFIG_LLEVA] = ahora
    ctx.proyecto.guardar_config()
    if ahora["subtitulos"] != antes["subtitulos"] or (al_crear and not ahora["subtitulos"]):
        ctx.estado.actualizar_params("callouts", {"subtitulos": ahora["subtitulos"]})
    render = ctx.estado.params("render") or {}
    vaciar = {}
    for clave in ("musica", "efectos"):
        # solo se vacia lo que habia: escribir `{}` donde no habia nada moveria
        # la firma del render sin cambiar el video
        if not ahora[clave] and antes[clave] and render.get(clave):
            vaciar[clave] = {}
    if vaciar:
        ctx.estado.actualizar_params("render", vaciar)
    if pedido:
        ctx.bitacora.anotar("lleva_cambiado", None, {"antes": antes, "ahora": ahora})
    return ahora


def _apagar_lo_que_no_lleva(ctx, receta):
    """Quita de la receta las tareas de lo que este video no lleva."""
    lleva = lleva_de(ctx)
    tareas = receta.setdefault("tareas", {}) if isinstance(receta, dict) else {}
    for clave, tarea in TAREA_DE_LLEVA.items():
        if not lleva[clave]:
            tareas[tarea] = False
    return receta


# ------------------------------------------ traer los cambios del estilo
#
# UN VIDEO SE QUEDA CON LA COPIA DEL ESTILO DEL DIA EN QUE SE CREO. Es a
# proposito: si cada retoque del estilo llegara solo a todos los videos, cambiar
# una imagen de referencia dejaria obsoletas las imagenes YA PAGADAS de todos
# los videos en curso. Esto es la puerta para traerlo cuando uno quiere, por
# partes y con lo que cuesta delante.
#
# Se aplica con `presets_canal.cambios_para`, el MISMO codigo que al crear el
# video, parte a parte. Y no se pisa lo que es DEL VIDEO: la duracion del
# encargo (va en el brief junto al tono), las llamadas a la accion, las
# indicaciones, lo que lleva y lo escrito a mano en el guion -- nada de eso
# viaja en un estilo.

#: parte de la pantalla -> bloque del preset de canal
PARTES_ESTILO = {"estilo": "estilo", "tono": "guion", "voz": "voz", "rotulos": "rotulos"}
NOMBRES_PARTE = {"estilo": "Estilo gráfico", "tono": "Tono del guion",
                 "voz": "Voz", "rotulos": "Rótulos y subtítulos"}
#: claves que el preset escribe pero que en un video ya creado son SUYAS
PROPIAS_DEL_VIDEO = {"brief": ("duracion_objetivo_s", "formato")}

#: Un corto nace en ritmo rapido aunque su estilo vaya mas lento
#: (`_montaje_al_crear`), y lo apunta en la config. Esas claves son entonces
#: del VIDEO: sin esto el estilo diria «tiene cambios» en cada corto nuevo y
#: «Traer» le devolveria el ritmo lento sin que nadie lo pidiera.
CONFIG_RITMO_DEL_VIDEO = "ritmo_del_video"
CLAVES_DEL_RITMO = {"assets": ("min_s", "max_s", "min_s_rotulos"),
                    "voz": ("hueco_minimo",)}


def _cambios_de_parte(ctx, ficha, parte):
    """{paso: {clave: valor}} con SOLO lo que de verdad cambiaria."""
    presets = _presets()
    bloque = (ficha.get("datos") or {}).get(PARTES_ESTILO[parte])
    if not bloque:
        return {}
    pasos = presets.TIPOS[PARTES_ESTILO[parte]]["pasos"]
    actuales = {paso: (ctx.estado.params(paso) or {}) for paso in pasos}
    crudos = presets.cambios_para({"tipo": PARTES_ESTILO[parte], "datos": bloque},
                                  actuales)
    cambios = {}
    for paso, valores in crudos.items():
        fuera = PROPIAS_DEL_VIDEO.get(paso, ())
        if ctx.proyecto.config.get(CONFIG_RITMO_DEL_VIDEO):
            fuera = tuple(fuera) + CLAVES_DEL_RITMO.get(paso, ())
        distintos = {k: v for k, v in valores.items()
                     if k not in fuera and (actuales.get(paso) or {}).get(k) != v}
        if distintos:
            cambios[paso] = distintos
    return cambios


def _que_rehace(ctx, parte, cambios):
    """Lo que habria que rehacer y lo que costaria, segun la etapa del video."""
    hechas = len([u for u in ctx.estado.unidades_producidas("assets")
                  if str(u).startswith("escena:")]) if ctx.estado.versiones("assets") else 0
    hojas = 0
    if hechas:
        # las hojas de reparto tambien son imagenes dibujadas en su calidad
        del_plan = (PASOS_MODULOS.p6_assets.plan_actual(
            ctx.proyecto, "assets", estado=ctx.estado) or {}).get("assets") or {}
        hojas = len([u for u in ctx.estado.unidades_producidas("assets")
                     if (del_plan.get(u) or {}).get("tipo") == "reparto"])
    tarifa = COSTE.tarifa_caracter() or 0.0
    caracteres = 0
    if ctx.estado.versiones("voz"):
        try:
            caracteres = sum(len(PASOS_MODULOS.marcas_tts.limpiar(b["texto"]))
                             for b in PASOS_MODULOS.p4_voz.cargar_guion(ctx.proyecto))
        except RuntimeError:
            caracteres = 0
    usd_voz = round(caracteres * tarifa, 3)
    calidad_antes = str((ctx.estado.params("assets") or {}).get("calidad") or "low")
    calidad = ((cambios.get("assets") or {}).get("calidad") or calidad_antes)
    estilo_nuevo = (cambios.get("assets") or {}).get("estilo") \
        or (ctx.estado.params("assets") or {}).get("estilo")
    usd_imagen = _light().usd_por_imagen(
        str(calidad), modo=PASOS_MODULOS.p6_assets.modo_de(estilo_nuevo))
    if parte == "rotulos":
        return {"rehace": "rehace solo el montaje del vídeo", "usd": 0.0}
    if parte == "voz":
        # SE MIRA SI HAY TOMA, no si se han podido contar los caracteres: con
        # el guion ilegible por lo que sea salia «aún no hay audio» en un video
        # con audio, y se traia la voz sin saber que habia que regrabarlo
        if not ctx.estado.versiones("voz"):
            return {"rehace": "no rehace nada: aún no hay audio", "usd": 0.0}
        ficha = {"rehace": "hay que regrabar el audio entero (las imágenes se "
                           "conservan) y volver a montar el vídeo",
                 "usd": usd_voz}
        if not tarifa or not caracteres:
            ficha["usd"] = None          # se sabe que cuesta, no cuanto
        return ficha
    if parte == "estilo":
        if not hechas:
            return {"rehace": "no rehace nada: aún no hay imágenes", "usd": 0.0}
        # LO QUE PASA DE VERDAD (D6, 15-10-2026). Decia «rehace las N imagenes»
        # con su precio, y «Poner al dia» las conservaba y las sellaba sin
        # redibujar ninguna: p6 no redibuja un plano que ya tiene su PNG si
        # nadie lo pide. Eso es lo que se queda (decision del dueño: que lo diga
        # y pregunte): se conservan, lo nuevo se aplica a lo que se haga o
        # rehaga, y si cambia la calidad la pantalla del video ofrece despues
        # rehacer las de la calidad vieja, con su precio delante.
        imagenes = f"{hechas} {'imagen' if hechas == 1 else 'imágenes'}"
        if hojas:
            imagenes += f" y {hojas} {'hoja' if hojas == 1 else 'hojas'} de reparto"
        nombres = {"low": "baja", "medium": "media", "high": "alta"}
        cambia_calidad = str(calidad) != calidad_antes
        lo_nuevo = (f"el estilo y la calidad {nombres.get(str(calidad), calidad)} se "
                    "aplican" if cambia_calidad else "el estilo se aplica")
        texto = (f"las {imagenes} que ya tiene se conservan como están"
                 + (f" (en calidad {nombres.get(calidad_antes, calidad_antes)})"
                    if cambia_calidad else "")
                 + f"; {lo_nuevo} a las que se hagan o rehagan, y se vuelve a montar "
                 "el vídeo")
        ficha = {"rehace": texto, "usd": 0.0, "imagenes": 0,
                 "conserva": hechas, "conserva_hojas": hojas,
                 "usd_rehacer_todas": round(hechas * usd_imagen, 2)}
        if cambia_calidad:
            ficha["calidad_antes"] = calidad_antes
            ficha["calidad"] = str(calidad)
            usd_texto = f"{ficha['usd_rehacer_todas']:.2f}".replace(".", ",")
            ficha["rehace"] += (". Después, el vídeo te ofrece rehacerlas en "
                                f"calidad {nombres.get(str(calidad), calidad)} "
                                f"(≈ {usd_texto} $)")
        return ficha
    # el tono: el guion se reescribe con la cuenta de Claude (sin coste de API),
    # y detras la voz y las imagenes de los planos cuyo texto cambie, que no se
    # sabe cuantas son hasta reescribirlo: se da el tope
    if not ctx.estado.versiones("guion"):
        return {"rehace": "no rehace nada: aún no hay guion", "usd": 0.0}
    tope = round(usd_voz + hechas * usd_imagen, 2)
    return {"rehace": "rehace el guion (con tu cuenta de Claude), la voz y las imágenes de "
                      "los planos cuyo texto cambie", "usd": usd_voz,
            "usd_hasta": tope, "imagenes_hasta": hechas}


def _partes_comparadas(ctx, ficha):
    """Cada parte del estilo `ficha` frente al video: si cambia y lo que cuesta."""
    presets = _presets()
    partes = []
    for parte in PARTES_ESTILO:
        try:
            cambios = _cambios_de_parte(ctx, ficha, parte)
        except presets.ErrorPreset as fallo:
            partes.append({"id": parte, "nombre": NOMBRES_PARTE[parte],
                           "cambia": False, "error": str(fallo)})
            continue
        ficha_parte = {"id": parte, "nombre": NOMBRES_PARTE[parte],
                       "cambia": bool(cambios),
                       "pasos": sorted(cambios),
                       "claves": sorted({k for v in cambios.values() for k in v})}
        if cambios:
            ficha_parte.update(_que_rehace(ctx, parte, cambios))
        partes.append(ficha_parte)
    return partes


def _cliente_al_cambiar_de_estilo(ctx, nuevo):
    """{antes, ahora} del proyecto (cliente) del video si pasa al estilo `nuevo`.

    El proyecto de un video se deduce de su estilo salvo que se le haya fijado
    uno (`/api/clientes/videos`). Al cambiar de estilo, un video que estaba en
    un proyecto SE QUEDA en el (se le fija); uno que no estaba en ninguno pasa
    al del estilo nuevo, si lo tiene. -> ({antes, ahora}, fijar)"""
    raiz = raiz_proyectos()
    asignaciones = CLIENTES._leer(raiz)
    actual = ctx.proyecto.config.get(CONFIG_ESTILO_LIGHT) or ""
    antes = CLIENTES.cliente_de(raiz, actual, ctx.id, datos=asignaciones)
    propio = (asignaciones.get("videos") or {}).get(ctx.id)
    del_nuevo = CLIENTES.cliente_de(raiz, nuevo, datos=asignaciones)
    fijar = bool(antes and not propio and del_nuevo != antes)
    return {"antes": antes, "ahora": antes if (fijar or propio) else del_nuevo}, fijar


@app.get("/api/proyectos/{pid}/estilo/cambios")
def cambios_del_estilo(pid: str, estilo: str = Query(default="")):
    """Que tiene el estilo del video que el video no tiene, por partes, y lo que
    costaria traerlo. Con `?estilo=<otro>`, lo mismo frente a OTRO estilo: la
    vista previa de «Cambiar de estilo…» (19-10-2026). No escribe nada."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    actual = ctx.proyecto.config.get(CONFIG_ESTILO_LIGHT) or ""
    otro = str(estilo or "").strip()
    preset_id = otro or actual
    if not preset_id:
        return {"estilo": None, "partes": [], "actual": "",
                "por_que_no": "este vídeo no se creó desde un estilo"}
    presets = _presets()
    # el motivo, para la persona (antes salia el de `leer` tal cual: «no hay
    # ningun preset con id '…'»)
    motivo = ("ese estilo ya no existe" if otro
              else "el estilo con el que se creó este vídeo ya no existe (se borró): "
                   "el vídeo sigue igual, y puedes pasarlo a otro estilo")
    try:
        ficha = presets.leer(preset_id)
    except presets.ErrorPreset:
        ficha = None
    if ficha and otro and ficha.get("tipo") != "canal":
        raise ErrorApi(400, "eso no es un estilo de vídeo")
    if ficha and otro and ficha.get("apartado") and otro != actual:
        ficha, motivo = None, "ese estilo está en la papelera: restáuralo antes"
    if not ficha:
        return {"estilo": {"id": preset_id}, "partes": [], "actual": actual,
                "por_que_no": motivo}
    salida = {"estilo": {"id": preset_id, "nombre": ficha.get("nombre") or preset_id,
                         # EN LA PAPELERA se sigue pudiendo comparar y traer
                         # (leer mira tambien ahi), pero la pantalla ofrece
                         # «Restaurarlo» y «Cambiar de estilo…»
                         "en_papelera": bool(ficha.get("apartado"))},
              "actual": actual,
              "partes": _partes_comparadas(ctx, ficha)}
    salida["al_dia"] = not any(p["cambia"] for p in salida["partes"])
    if otro and otro != actual:
        salida["cliente"], _fijar = _cliente_al_cambiar_de_estilo(ctx, otro)
    return salida


def _traer_partes(ctx, ficha, pedidas):
    """Aplica al video las partes `pedidas` del estilo `ficha`, con el MISMO
    codigo que al crearlo. Todo se calcula ANTES de escribir nada: una parte
    que no se puede aplicar (fotogramas que ya no estan) no deja el video a
    medias. Lanza ErrorApi(400) si alguna falla. -> {parte: [pasos cambiados]}"""
    presets = _presets()
    por_parte = {}
    for parte in pedidas:
        por_parte[parte] = _preset_o_400(lambda _p, parte=parte:
                                         _cambios_de_parte(ctx, ficha, parte))
    if any(p == "estilo" for p in pedidas):
        presets.restaurar_moodboard(ficha)
    cambiados = {}
    for parte, cambios in por_parte.items():
        for paso, valores in cambios.items():
            if ctx.estado.actualizar_params(paso, valores):
                cambiados.setdefault(parte, []).append(paso)
    return cambiados


def _calcular_partes(ctx, ficha, pedidas):
    """Comprueba (sin escribir) que todas las partes se pueden aplicar."""
    for parte in pedidas:
        _preset_o_400(lambda _p, parte=parte: _cambios_de_parte(ctx, ficha, parte))


def _respuesta_de_traer(ctx, cambiados):
    afectados = {paso for pasos in cambiados.values() for paso in pasos}
    return {"traidas": sorted(cambiados), "cambiados": cambiados,
            "obsoletos": sorted(p["id"] for p in PASOS
                                if ctx.estado.estado_de(p["id"]) == "obsoleto"),
            "aguas_abajo": sorted({h for paso in afectados
                                   for h in descendientes_de(paso)} - afectados),
            "pasos": [ficha_paso(ctx, p["id"]) for p in PASOS]}


def _partes_pedidas(datos, vacias=False):
    pedidas = [str(p).strip().lower() for p in (_lista_de_textos(datos, "partes") or [])]
    malas = [p for p in pedidas if p not in PARTES_ESTILO]
    if (not pedidas and not vacias) or malas:
        raise ErrorApi(400, "hace falta 'partes' con alguna de: "
                            + ", ".join(PARTES_ESTILO))
    return pedidas


@app.post("/api/proyectos/{pid}/estilo/traer")
def traer_cambios_del_estilo(pid: str, cuerpo: dict = Body(default=None)):
    """Trae al video las partes elegidas del estilo: {partes: [estilo, tono,
    voz, rotulos]}. No genera nada: deja obsoleto lo que toque."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    pedidas = _partes_pedidas(_cuerpo(cuerpo))
    if ctx.gestor.listar(activos=True):
        raise ErrorApi(409, "hay algo generándose en este vídeo: espera a que "
                            "termine para traer los cambios del estilo")
    preset_id = ctx.proyecto.config.get(CONFIG_ESTILO_LIGHT) or ""
    if not preset_id:
        raise ErrorApi(409, "este vídeo no se creó desde un estilo")
    ficha = _preset_o_400(lambda p: p.leer(preset_id))
    if not ficha:
        raise ErrorApi(404, "el estilo con el que se creó este vídeo ya no existe")
    cambiados = _traer_partes(ctx, ficha, pedidas)
    ctx.bitacora.anotar("estilo_traido", None, {
        "estilo": preset_id, "partes": pedidas,
        "cambiados": {k: sorted(v) for k, v in cambiados.items()}})
    return _respuesta_de_traer(ctx, cambiados)


@app.put("/api/proyectos/{pid}/estilo")
def cambiar_estilo_del_video(pid: str, cuerpo: dict = Body(default=None)):
    """PASA EL VIDEO A OTRO ESTILO: {estilo, partes: [...]} (19-10-2026).

    Un video cuyo estilo se borro (o llego de otra maquina) se quedaba
    huerfano: «Su estilo» no ofrecia nada y «Traer» daba 404. Esto escribe
    `config.estilo_light` (config: no mueve ninguna firma) y trae las partes
    elegidas por el mismo camino que «Traer»; sin partes, solo cambia el
    estilo apuntado y nada queda obsoleto. El video se queda en su proyecto
    (cliente) si tenia uno. 409 con algo en marcha o con el estilo en la
    papelera; 400 si no existe o una parte no se puede aplicar."""
    ctx = contexto(pid)
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    datos = _cuerpo(cuerpo)
    nuevo = str(datos.get("estilo") or "").strip()
    if not nuevo:
        raise ErrorApi(400, "hace falta 'estilo': el id del estilo nuevo")
    pedidas = _partes_pedidas(datos, vacias=True)
    ficha = _preset_o_400(lambda p: p.leer(nuevo))
    if ficha.get("tipo") != "canal":
        raise ErrorApi(400, "eso no es un estilo de vídeo")
    actual = ctx.proyecto.config.get(CONFIG_ESTILO_LIGHT) or ""
    if ficha.get("apartado") and nuevo != actual:
        raise ErrorApi(409, "ese estilo está en la papelera: restáuralo antes")
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo generándose en este vídeo: espera a que "
                                "termine para cambiarle el estilo")
        _calcular_partes(ctx, ficha, pedidas)
        cliente, fijar = _cliente_al_cambiar_de_estilo(ctx, nuevo)
        ctx.proyecto.config[CONFIG_ESTILO_LIGHT] = nuevo
        ctx.proyecto.guardar_config()
        if fijar:
            CLIENTES.asignar_video(raiz_proyectos(), ctx.id, cliente["antes"])
        cambiados = _traer_partes(ctx, ficha, pedidas)
    ctx.bitacora.anotar("estilo_cambiado", None, {
        "antes": actual, "ahora": nuevo, "partes": pedidas, "cliente": cliente,
        "cambiados": {k: sorted(v) for k, v in cambiados.items()}})
    return {"estilo": {"id": nuevo, "nombre": ficha.get("nombre") or nuevo},
            "antes": actual, "cliente": cliente, **_respuesta_de_traer(ctx, cambiados)}


@app.post("/api/proyectos/{pid}/imagenes/calidad", status_code=202)
def rehacer_en_la_calidad_del_video(pid: str, cuerpo: dict = Body(default=None)):
    """REHACE LAS IMAGENES QUE SIGUEN EN OTRA CALIDAD, y solo esas.

    Cambiar la calidad de un video con imagenes hechas no redibuja nada (p6
    conserva lo dibujado): la pantalla lo dice y lo pregunta con el precio
    delante («N imagenes siguen en low. ¿Rehacerlas en media?»). Esto es el
    «si». Los planos van como unidades PEDIDAS, por el camino normal del paso,
    en un solo trabajo y de uno en uno con el resto de tandas (regla 2: con
    algo en marcha en el video, 409).

    `imagenes` es cuantas ha visto quien confirma: si ya no son esas (otra
    tanda ha rehecho alguna, ha cambiado la calidad), no se lanza nada y se
    dice -- el precio que se confirmo ya no es el de lo que se haria."""
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    try:
        vistas = int(datos.get("imagenes"))
    except (TypeError, ValueError):
        raise ErrorApi(400, "hace falta 'imagenes': cuántas se confirmaron")
    with _cerrojo_de_cadena(ctx.id):
        if _trabajo_de_cadena(ctx) is not None or ctx.gestor.listar(activos=True):
            raise ErrorApi(409, "hay algo generándose en este vídeo: espera a que "
                                "termine y vuelve a mirarlo")
        with _COLA_LOCK:
            if _cola_dibujando(ctx):
                raise ErrorApi(409, "se están rehaciendo imágenes con tus notas: "
                                    "espera a que terminen")
            otra = imagenes_en_otra_calidad(ctx, _unidades_que_rehara(ctx))
            planos = sorted(otra["planos"])
            if not planos:
                raise ErrorApi(400, "no hay imágenes en otra calidad que rehacer")
            if len(planos) != vistas:
                raise ErrorApi(409, f"ahora son {len(planos)} imágenes, no {vistas}: "
                                    "vuelve a mirarlo antes de confirmar",
                               {"imagenes": len(planos)})
            # LA SEGUNDA MITAD DE UN PLANO LARGO (`sigue_a`) copia la primera:
            # no se cobra, pero si no se pide, p6 la conserva con la imagen de
            # antes y a mitad de toma se ve el salto de calidad (revision del
            # 15-10-2026). Va con su plano, gratis.
            planos = _con_sus_continuaciones(planos, PASOS_MODULOS.p6_assets.plan_actual(
                ctx.proyecto, "assets", estado=ctx.estado) or {})
            trabajo_id = lanzar_paso(ctx, "assets", planos,
                                     nombre="calidad_imagenes",
                                     evento="imagenes_recalidad",
                                     datos={"calidad": otra["calidad"],
                                            "de": otra["por_calidad"]})
    return {"trabajo_id": trabajo_id, "unidades": planos, "calidad": otra["calidad"],
            "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


@app.get("/api/proyectos/{pid}/lleva")
def leer_lleva(pid: str):
    """Lo que lleva este video: voz, subtitulos, musica y efectos."""
    ctx = contexto(pid)
    return {"lleva": lleva_de(ctx)}


@app.put("/api/proyectos/{pid}/lleva")
def cambiar_lleva(pid: str, cuerpo: dict = Body(default=None)):
    """Enciende o apaga lo que lleva el video. Rehace solo el montaje, nunca imagenes."""
    ctx = contexto(pid)
    pedido = _normalizar_lleva(_cuerpo(cuerpo).get("lleva", _cuerpo(cuerpo)))
    ahora = _aplicar_lleva(ctx, pedido)
    return {"lleva": ahora,
            "pasos": [ficha_paso(ctx, p["id"]) for p in PASOS]}


def _receta_de_video(ctx, pestana, datos=None):
    """La receta con la que corre una pestana de ESTE proyecto.

    Dos diferencias, y las dos son del proyecto y no del canal:

      1. En un video del modo light va encendida de fabrica la DIRECCION. Esta
         apagada de fabrica porque en un video ya generado encenderla cuesta
         imagenes --cambia el prompt de todos los planos-- y eso no se enciende
         solo (`recetas.de_fabrica`). Un video del modo light nace nuevo y se
         genera de una tirada, asi que ahi no repaga nada. Y por lo mismo va
         encendida en cualquier video que todavia no tenga planos, se haya
         creado por donde se haya creado.
      2. Y NO se toca lo que la tanda deja fuera: eso no se puede pedir aqui.
         `recetas.resolver` fuerza las tareas NO OPCIONALES --y el render lo
         es-- para que una receta guardada no pueda saltarse un paso obligado.
         La exclusion de una tanda es otra cosa y va en `_sin_de_la_tanda`.

    Aqui se encendia tambien la REVISION de los planos, que miraba los PNG con
    un modelo y rehacia los que contradecian el relato. Se retiro entera el
    27-08: quien mira los planos vuelve a ser una persona, con
    el previsualizador escena a escena.
    """
    recetas = _recetas()
    datos = datos or {}
    pedidas = dict((datos.get("tareas") or {}))
    # Y EN CUALQUIER VIDEO QUE NUNCA HAYA GENERADO SUS PLANOS, venga del modo
    # que venga (02-09): el modo editor recorre ahora las mismas
    # tandas que el light, y la razon de tenerla apagada --repagar las imagenes
    # de un video ya dibujado-- no existe donde todavia no hay ninguna. Un
    # proyecto con planos hechos se queda como estaba: ahi encenderla sigue
    # siendo un clic y una factura, y eso lo decide una persona.
    if ctx.proyecto.config.get(CONFIG_VIDEO_LIGHT) \
            or not ctx.proyecto.version_activa("assets"):
        pedidas.setdefault("direccion", True)
    return _apagar_lo_que_no_lleva(
        ctx, recetas.resolver(pestana, datos.get("receta"), pedidas))


def _planos_previstos(ctx):
    """Cuantos planos va a tener este video y cuantos pagan imagen.

    Con el plan ya cortado se CUENTAN; sin el se estiman con la misma cuenta que
    `POST /api/estimacion` -- la duracion entre el plano medio del ritmo --,
    porque el precio hay que decirlo antes de que exista ningun plan.
    """
    light = PASOS_MODULOS.presets_light
    # CON EL GUION VISUAL APROBADO SE CUENTAN SUS LINEAS (rama guion-visual-2):
    # cada linea es un plano, y la cuenta por duracion o el plan cortado por la
    # voz prometian otra cifra (prueba real del 23-10: «8 imágenes» y salieron 6)
    try:
        lineas, _origen = _guion_visual().efectivo(ctx.estado.params("assets") or {},
                                                   _bloques_del_guion(ctx))
    except Exception:                                       # noqa: BLE001
        lineas = None
    if lineas and not _guion_visual().fuera_de_la_voz(
            lineas, [b["id"] for b in _bloques_del_guion(ctx)]):
        return {"total": len(lineas), "con_imagen": len(lineas),
                "origen": "el guion visual aprobado"}
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = plan.get("escenas") or []
    if escenas:
        cartelas = PASOS_MODULOS.cartelas
        con_imagen = [e for e in escenas
                      if not cartelas.sin_imagen(e)
                      and not e.get("sigue_a")]
        return {"total": len(escenas), "con_imagen": len(con_imagen),
                "origen": "el plan de este video"}
    brief = PASOS_MODULOS.comun.leer_salida(ctx.proyecto, "brief", "brief.json",
                                            obligatorio=False) or {}
    segundos = float(brief.get("duracion_objetivo_s")
                     or (ctx.estado.params("brief") or {}).get("duracion_objetivo_s")
                     or 0)
    assets = ctx.estado.params("assets") or {}
    ficha = light.ritmo_parecido(assets.get("min_s"), assets.get("max_s"))
    media = max(0.5, float(ficha["media_s"]))
    total = max(1, int(round(segundos / media))) if segundos else 0
    return {"total": total, "con_imagen": total,
            "origen": "estimado por la duración y el ritmo"}


def _carpetas_de_assets(ctx):
    """Donde estan las imagenes de este video: la carpeta de trabajo mientras
    se genera y la version activa una vez sellada, en ese orden."""
    carpetas = [ctx.proyecto.ruta_trabajo("assets", crear=False)]
    version = ctx.proyecto.version_activa("assets")
    if version:
        carpetas.append(ctx.proyecto.ruta_paso("assets", version))
    return [c for c in carpetas if c and os.path.isdir(c)]


def _con_sus_continuaciones(planos, plan):
    """Los planos pedidos y, detras, la segunda mitad (`sigue_a`) de cada uno.
    -> [uid]. La continuacion copia la imagen de su plano: no se paga, pero si
    no se pide se queda con la de antes."""
    elegidos = set(planos)
    extra = sorted(f"escena:{e['id']}" for e in (plan.get("escenas") or [])
                   if e.get("sigue_a") and f"escena:{e['sigue_a']}" in elegidos
                   and f"escena:{e['id']}" not in elegidos)
    return list(planos) + extra


def _escenas_que_pagan(plan):
    """Los planos del plan que PAGAN imagen: ni cartelas (no dejan PNG) ni la
    segunda mitad de un plano largo (copia la primera)."""
    cartelas = PASOS_MODULOS.cartelas
    return [e for e in (plan.get("escenas") or [])
            if not cartelas.sin_imagen(e) and not e.get("sigue_a")]


def _unidades_que_rehara(ctx, modo="pendientes"):
    """Las unidades de `assets` que una tanda en ese modo VOLVERA A DIBUJAR
    aunque ya tengan su PNG. -> set, o None si son todas.

    Es la misma cuenta que hace la tanda (`_plan_de_ejecucion` con el cuerpo
    de `_un_paso`), y por eso vive aqui y no en una copia: con unas pocas
    unidades sucias --la nota de un plano, un texto que cambio-- la tanda se las
    pide a p6 una a una, y p6 las vuelve a dibujar (y a pagar) aunque su PNG
    exista. Con todas sucias, o ninguna, no pide ninguna y p6 conserva lo
    dibujado. En `todo`, se rehace todo."""
    if modo == "todo":
        return None
    try:
        unidades = _plan_de_ejecucion(ctx, "assets", {})
    except Exception:                                       # noqa: BLE001
        return set()
    return set(unidades or ())


def _imagenes_ya_generadas(ctx, planos, rehara=frozenset()):
    """Cuantos planos de los que PAGAN imagen la tienen ya y la tanda no la
    va a volver a dibujar.

    Es un HECHO, no una prediccion: p6 CONSERVA el PNG de un plano que ya lo
    tiene (`_generar_escenas`: «una imagen que ya existe se queda»), aunque su
    firma haya cambiado -- un cambio de estilo o de CALIDAD tampoco lo redibuja.
    Lo unico que hace que lo vuelva a dibujar, y a pagar, es que la tanda se lo
    PIDA: las unidades de `rehara` (`_unidades_que_rehara`), que se descuentan
    aqui. `rehara=None` es «todas» (modo `todo`): no queda nada hecho.

    Existe por un numero que asustaba con razon: una tanda cortada en el plano
    doscientos once de doscientos dieciseis volvia a ofrecerse como «216
    imagenes, 7,13 $». El precio era el del VIDEO ENTERO y no el de lo que
    faltaba, asi que retomar parecia costar lo mismo que empezar de cero -- y
    con esa cifra delante lo razonable es no pulsar.

    CON EL GUION VISUAL MANDANDO TAMBIEN SE CUENTA (26-10-2026). Desde
    guion-visual-2 `_planos_previstos` cuenta las lineas del guion visual
    (origen «el guion visual aprobado», tambien las de la Parrilla) y aqui solo
    se miraba el origen del plan cortado: lo hecho salia CERO, y «Montar el
    video» pedia dibujar las 6 imagenes de un video con las 6 al dia («6
    imagenes que han quedado viejas»). Redibujar no lo arreglaba --la cuenta
    volvia a dar cero--, asi que el aviso volvia en cada version. Lo que hay en
    disco es el mismo hecho venga de donde venga el numero de planos; el
    `min(hechas, imagenes)` de quien llama cubre un guion visual con menos
    lineas que el plan cortado.
    """
    if rehara is None or planos.get("origen") not in ("el plan de este video",
                                                      "el guion visual aprobado"):
        return 0
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    escenas = _escenas_que_pagan(plan)
    if planos.get("origen") == "el guion visual aprobado":
        # SOLO LOS PLANOS QUE VA A TENER EL GUION VISUAL (S001..SNNN, los ids
        # son por posicion): un plan cortado antes, mas largo y con un hueco
        # dentro, no puede tapar con sus PNG de sobra una imagen que p6 si
        # dibujara (revision independiente del 26-10)
        validos = {f"S{n:03d}" for n in range(1, int(planos.get("con_imagen") or 0) + 1)}
        escenas = [e for e in escenas if str(e.get("id") or "") in validos]
    # EN LA CARPETA DE TRABAJO MIENTRAS SE GENERA, Y EN LA VERSION UNA VEZ
    # SELLADA. Mirar solo la de trabajo daba CERO en cuanto el paso terminaba
    # --que es justo cuando hay 216 imagenes hechas-- y el boton volvia a pedir
    # los 7,13 $ enteros.
    carpetas = [os.path.join(c, "escenas") for c in _carpetas_de_assets(ctx)
                if os.path.isdir(os.path.join(c, "escenas"))]
    if not escenas or not carpetas:
        return 0
    return sum(1 for escena in escenas
               if f"escena:{escena['id']}" not in rehara
               and any(os.path.exists(os.path.join(c, f"{escena['id']}.png"))
                       for c in carpetas))


def imagenes_en_otra_calidad(ctx, rehara=frozenset()):
    """LAS IMAGENES DE ESTE VIDEO DIBUJADAS EN OTRA CALIDAD que la suya.

    -> {"calidad", "planos": [uid...], "por_calidad": {"low": n}, "hojas": n,
        "desconocidas": n}

    Pasa cuando cambia `assets.calidad` en un video con imagenes hechas (traer
    el estilo, cambiarla a mano): p6 conserva lo dibujado y la calidad nueva
    solo se aplica a lo que se haga o rehaga. Se dice y se pregunta; nada se
    redibuja solo.

    La calidad de cada imagen sale de su ficha (`p6_assets.calidad_de_ficha`):
    escrita en las nuevas, deducida de la firma en las viejas cuando la firma lo
    deja claro. Las que no se saben cuentan como `desconocidas` y NO se ofrecen:
    ofrecer rehacer una imagen que quiza ya esta en esa calidad es cobrarla dos
    veces. Las que la tanda va a rehacer de todos modos (`rehara`) tampoco: ya
    saldran en la calidad nueva. Las hojas de reparto se cuentan pero no se
    ofrecen: rehacer una hoja deja por rehacer todos los planos que la usan."""
    p6 = PASOS_MODULOS.p6_assets
    assets = ctx.estado.params("assets") or {}
    calidad = str(assets.get("calidad") or "low").lower()
    salida = {"calidad": calidad, "planos": [], "por_calidad": {}, "hojas": 0,
              "desconocidas": 0}
    if rehara is None:
        return salida
    plan = p6.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    carpetas = _carpetas_de_assets(ctx)
    if not carpetas:
        return salida
    try:
        tamano = PASOS_MODULOS.comun.ficha_formato(plan.get("formato"))["tamano_imagen"]
    except Exception:                                       # noqa: BLE001
        tamano = "apaisado"
    for escena in _escenas_que_pagan(plan):
        if escena.get("componente"):
            continue
        uid = f"escena:{escena['id']}"
        if uid in rehara:
            continue
        for carpeta in carpetas:
            png = os.path.join(carpeta, "escenas", f"{escena['id']}.png")
            if not os.path.exists(png):
                continue
            ruta = os.path.join(carpeta, "escenas", f"{escena['id']}.json")
            try:
                with open(ruta, encoding="utf-8") as fh:
                    ficha = json.load(fh)
            except (OSError, ValueError):
                ficha = {}
            suya = p6.calidad_de_ficha(ficha, tamano, ruta=ruta)
            if suya is None:
                salida["desconocidas"] += 1
            elif suya != calidad:
                salida["planos"].append(uid)
                salida["por_calidad"][suya] = salida["por_calidad"].get(suya, 0) + 1
            break
    for clave, ficha in (plan.get("assets") or {}).items():
        if not isinstance(ficha, dict) or ficha.get("tipo") != "reparto" or clave in rehara:
            continue
        nombre = str(ficha.get("nombre") or clave.split(":", 1)[-1])
        for carpeta in carpetas:
            if not os.path.exists(os.path.join(carpeta, "assets", "reparto", f"{nombre}.png")):
                continue
            hoja = PASOS_MODULOS.medios.leer_json(
                os.path.join(carpeta, "assets", "reparto", f"{nombre}.json"), {}) or {}
            if hoja.get("calidad") in AJUSTES.CALIDADES and hoja["calidad"] != calidad:
                salida["hojas"] += 1
            break
    return salida


def _coste_previsto(ctx, pestanas, modo="pendientes"):
    """Lo que va a costar esta tanda, en dolares y en imagenes.

    Se dice ANTES de pulsar, que es la unica forma de que sirva. Las dos partes
    caras del Estudio son las IMAGENES (una por plano) y el TTS (por caracter);
    todo lo que llama al CLI va por la suscripcion y no entra aqui.

    EL MODO CUENTA (D5, 16-10-2026). La voz no tiene cache: en modo 'todo' se
    vuelve a sintetizar ENTERA aunque estuviera al dia, y «Regenerar Audio» la
    prometia a 0 $ porque aqui solo se miraba si estaba al dia.
    """
    light = PASOS_MODULOS.presets_light
    planos = _planos_previstos(ctx)
    assets = ctx.estado.params("assets") or {}
    calidad = str(assets.get("calidad") or "low").lower()
    modo_imagen = PASOS_MODULOS.p6_assets.modo_de(assets.get("estilo"))
    usd_imagen = light.usd_por_imagen(calidad, modo=modo_imagen)
    tarifas = COSTE.tarifas()
    usd_caracter = float(((tarifas.get("tts") or {}).get("usd_por_caracter")) or 0.0)

    imagenes = planos["con_imagen"] if "video" in pestanas else 0
    caracteres = 0
    if "voz" in pestanas:
        brief = PASOS_MODULOS.comun.leer_salida(
            ctx.proyecto, "brief", "brief.json", obligatorio=False) or {}
        palabras = int(brief.get("presupuesto_palabras") or 0)
        # con el guion escrito se cuentan sus caracteres de verdad; sin el, el
        # presupuesto de palabras por los 6,1 caracteres de la media medida
        guion = PASOS_MODULOS.comun.leer_salida(
            ctx.proyecto, "guion", "guion.json", obligatorio=False) or {}
        bloques = guion.get("guion") or []
        if bloques:
            # lo que se ENVIA a la voz: el texto sin las marcas de pausa y
            # enfasis (es lo que cuenta el medidor, y lo que cobra Cartesia)
            limpiar = getattr(PASOS_MODULOS.marcas_tts, "limpiar", None)
            caracteres = sum(len(limpiar(str(b.get("texto") or "")) if limpiar
                                 else str(b.get("texto") or "")) for b in bloques)
        else:
            caracteres = int(round(palabras * 6.1))
    # LAS HOJAS DE PERSONAJES TAMBIEN SE PAGAN: una imagen por personaje del
    # reparto, antes de los planos. El cotizador solo contaba planos y se quedaba
    # corto en 1-3 imagenes por video con personajes (11-10-2026).
    rehara = _unidades_que_rehara(ctx, modo) if "video" in pestanas else frozenset()
    hojas, hojas_hechas = (_hojas_de_reparto(ctx, rehara) if "video" in pestanas
                           else (0, 0))
    imagenes += hojas
    usd_imagenes = round(imagenes * usd_imagen, 3)
    usd_tts = round(caracteres * usd_caracter, 4)
    # la voz ya grabada y al dia no se vuelve a pagar en una tanda «pendientes»;
    # en una 'todo' se graba otra vez entera, y se paga entera
    voz_al_dia = modo == "pendientes" and ctx.estado.estado_de("voz") == "listo"
    usd_tts_por_generar = 0.0 if voz_al_dia else usd_tts
    # LO QUE YA ESTA HECHO VIAJA AL LADO DEL TECHO, no en su lugar. El total
    # sigue siendo lo que cuesta el video entero --que es lo que hay que pagar
    # si algo aguas arriba cambia y la cache falla-- y `por_generar` es lo que
    # cuesta si nada cambia. Ensenar solo uno de los dos miente en un sentido o
    # en el otro: uno asusta al que retoma, el otro promete barato de mas.
    hechas = (_imagenes_ya_generadas(ctx, planos, rehara) + hojas_hechas) if imagenes else 0
    hechas = min(hechas, imagenes)
    por_generar = max(0, imagenes - hechas)
    precio = AJUSTES.precio_por_imagen(calidad, modo=modo_imagen)
    ficha = {"imagenes": imagenes, "calidad": calidad,
             "usd_por_imagen": usd_imagen, "usd_imagenes": usd_imagenes,
             "precio_de": precio.get("fuente"),
             "hojas_reparto": hojas,
             "imagenes_hechas": hechas, "imagenes_por_generar": por_generar,
             "usd_por_generar": round(por_generar * usd_imagen + usd_tts_por_generar, 3),
             "caracteres": caracteres, "usd_tts": usd_tts,
             "usd_tts_por_generar": round(usd_tts_por_generar, 4), "modo": modo,
             "usd_total": round(usd_imagenes + usd_tts, 3),
             "planos": planos}
    # LO QUE SIGUE EN OTRA CALIDAD: no entra en lo que cuesta esta tanda (no se
    # redibuja), viaja al lado para que la pantalla lo diga y lo pregunte
    if "video" in pestanas:
        try:
            otra = imagenes_en_otra_calidad(ctx, rehara)
        except Exception:                                   # noqa: BLE001
            otra = None
        # solo con PLANOS que ofrecer: las hojas se cuentan pero no se ofrecen
        # (ver `imagenes_en_otra_calidad`), y un aviso sin boton que no se
        # va nunca es ruido
        if otra and otra["planos"]:
            ficha["otra_calidad"] = {
                "calidad": calidad, "imagenes": len(otra["planos"]),
                "por_calidad": otra["por_calidad"], "hojas": otra["hojas"],
                "desconocidas": otra["desconocidas"],
                "usd": round(len(otra["planos"]) * usd_imagen, 3)}
    return ficha


def _hojas_de_reparto(ctx, rehara=frozenset()):
    """(personajes del reparto en el plan, cuantos ya tienen su hoja dibujada
    y la tanda no la va a volver a dibujar)."""
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    reparto = [(k, str(f.get("nombre") or k.split(":", 1)[-1]))
               for k, f in (plan.get("assets") or {}).items()
               if isinstance(f, dict) and f.get("tipo") == "reparto"]
    if not reparto:
        return 0, 0
    if rehara is None:
        return len(reparto), 0
    carpetas = _carpetas_de_assets(ctx)
    hechas = sum(1 for clave, nombre in reparto
                 if clave not in rehara
                 and any(os.path.exists(os.path.join(c, "assets", "reparto", f"{nombre}.png"))
                         for c in carpetas))
    return len(reparto), hechas


def _tamano_para(clave, planos, palabras):
    """Con que unidad se mide ese paso o esa fase, y cuanto vale hoy.

    Sale de `estadisticas.INICIALES`, que es donde cada uno declara su unidad:
    preguntarselo a una lista escrita aqui seria una segunda tabla que se
    desincroniza en cuanto alguien anade un paso.
    """
    unidad = str((ESTADISTICAS.INICIALES.get(str(clave)) or {}).get("unidad") or "")
    if "palabra" in unidad:
        return palabras
    if "segundo" in unidad:
        return 0
    return planos["total"]


def _fraccion_por_hacer(ctx, paso):
    """Que parte de un paso por unidades queda por rehacer. -> 0 < x <= 1

    LA ESTIMACION DEL HISTORIAL ES SIEMPRE DEL PASO ENTERO, y en una tanda
    «pendientes» eso miente por goleada. Montar el MP4 de un video con sus 302
    imagenes ya dibujadas prometia 282 minutos --lo que cuesta dibujarlas-- y
    duro veinte: `assets` no estaba «al dia» porque el feedback de UN plano le
    habia movido la firma, pero lo que quedaba por dibujar era ese plano y nada
    mas. Medido el 08-09-2026 en `video_referencia`, con la barra diciendo «quedan
    ~261m» a los veinte minutos de haber pulsado.

    Se mide con las unidades OBSOLETAS --que es exactamente lo que un modo
    «pendientes» va a rehacer-- contra las declaradas. Es la misma cuenta que
    ya hace el coste con `imagenes_por_generar`: lo que se dice del dinero y lo
    que se dice del reloj salen del mismo sitio.

    Suelo de una unidad: un paso que corre tarda algo, y un cero dejaria su
    tramo de la barra con ancho nulo -- que en pantalla es una tarea que no
    existe. Y NUNCA LEVANTA: no saber repartir el reloj no puede tumbar una
    tanda de cincuenta minutos.
    """
    try:
        if not (PASOS_POR_ID.get(paso) or {}).get("unidades"):
            return 1.0
        declaradas = len(ctx.estado.unidades_declaradas(paso))
        if not declaradas:
            return 1.0
        obsoletas = len(ctx.estado.unidades_obsoletas(paso))
        return min(1.0, max(1, obsoletas) / float(declaradas))
    except Exception:                                         # noqa: BLE001
        return 1.0


def _segundos_de_tarea(ctx, tarea, planos, palabras, reparto=None,
                       modo="todo"):
    """Lo que se espera que tarde una tarea, del historial real de esta maquina.

    UNA TAREA NO ES UN PASO. Aqui se estimaba el PASO de cada tarea, y la
    pestana Video tiene CINCO tareas del paso `assets`: la cuenta salia por
    cinco (medido: 20.742 s para una tanda de veinte minutos). Asi que:

      - una tarea con FASE propia (`catalogo_visual`, `guia_estilo`,
        `plan_cartelas`, `direccion`) se estima con su fase, que tiene su propio
        historial medido;
      - las que no la tienen SON el paso, y se reparten su tiempo entre ellas.

    Con eso el total de la tanda vuelve a ser el tiempo del paso, que es lo
    unico que la barra promete de verdad.
    """
    fase = tarea.get("fase")
    if fase:
        # UNA FASE NO SE ESCALA. Las tareas con fase propia --la guia de estilo,
        # el corte de cartelas, la direccion-- no rehacen las unidades del paso:
        # hacen lo suyo entero o no se hacen, y tienen su propio historial
        # medido. Lo que se escala mas abajo son las que SON el paso.
        ajuste = _ajuste_de_fase(_receta_de_video(ctx, tarea["pestana"]), fase)
        return float(ESTADISTICAS.estimar(
            fase, tamano=_tamano_para(fase, planos, palabras),
            ajuste={"modelo": ajuste["modelo"],
                    "esfuerzo": ajuste["esfuerzo"]})["segundos"])
    paso = tarea["paso"]
    entre = max(1, int((reparto or {}).get(paso, 1)))
    segundos = float(ESTADISTICAS.estimar(
        paso, tamano=_tamano_para(paso, planos, palabras))["segundos"]) / entre
    # SOLO EN «pendientes»: en modo 'todo' se rehace el paso entero y el
    # historial del paso entero es justo lo que va a tardar.
    if modo == "pendientes":
        segundos *= _fraccion_por_hacer(ctx, paso)
    return segundos


#: Lo que se promete para una tarea de render que solo vuelve a mezclar.
SEGUNDOS_SOLO_MEZCLA = 30.0


def _plan_de_generacion(ctx, pestanas, modo="pendientes", datos=None):
    """Que se va a hacer, cuanto va a tardar y cuanto va a costar. No lanza nada.

    LA BARRA VA POR TIEMPO MEDIDO, no por numero de tareas, y por la misma razon
    que en el modo light de los estilos: con las imagenes
    tardando seis minutos y el brief dos segundos, contar tareas da una barra
    que se planta y despues salta.
    """
    recetas = _recetas()
    planos = _planos_previstos(ctx)
    brief = PASOS_MODULOS.comun.leer_salida(
        ctx.proyecto, "brief", "brief.json", obligatorio=False) or {}
    palabras = int(brief.get("presupuesto_palabras") or 0)
    fases, total = [], 0.0
    for pestana in pestanas:
        receta = _receta_de_video(ctx, pestana, datos)
        sin = _sin_de_la_tanda(datos)
        puestas = [t for t in recetas.puestas_de(pestana, receta)
                   if t not in sin]
        orden = recetas.orden_de(pestana, puestas)
        # cuantas tareas de cada paso NO tienen fase propia: son las que SON el
        # paso, y se reparten su tiempo en vez de contarlo cada una entera
        reparto = {}
        for tarea in orden:
            if not tarea.get("fase"):
                reparto[tarea["paso"]] = reparto.get(tarea["paso"], 0) + 1
        tareas = []
        for tarea in orden:
            al_dia = _esta_al_dia(ctx, tarea)
            segundos = _segundos_de_tarea(ctx, tarea, planos, palabras,
                                          reparto, modo)
            # solo volver a mezclar: segundos, no el render (ver `_que_hace`)
            solo_mezcla = (tarea["id"] == "render" and not al_dia
                           and modo == "pendientes" and _solo_falta_mezclar(ctx))
            if solo_mezcla:
                segundos = min(segundos, SEGUNDOS_SOLO_MEZCLA)
            tareas.append({
                "id": tarea["id"], "nombre": tarea["nombre"],
                "publico": recetas.publico_de(tarea["id"]),
                "paso": tarea["paso"], "porque": tarea.get("porque", ""),
                "cuesta": bool(tarea["cuesta"]), "al_dia": al_dia,
                "se_hace": not (modo == "pendientes" and al_dia),
                "solo_mezcla": solo_mezcla,
                "segundos": round(segundos, 1)})
        pendientes = [t for t in tareas if t["se_hace"]]
        segundos = round(sum(t["segundos"] for t in pendientes), 1)
        fases.append({"pestana": pestana, "tareas": tareas,
                      "pendientes": [t["id"] for t in pendientes],
                      "segundos": segundos, "desde": round(total, 1),
                      "impedimentos": _impedimentos(
                          ctx, pestana,
                          [{"id": t["id"]} for t in pendientes])})
        total += segundos
    return {
        "pestanas": list(pestanas), "modo": modo,
        "fases": fases,
        "segundos": round(total, 1),
        "tareas": sum(len(f["pendientes"]) for f in fases),
        "coste": _coste_previsto(ctx, pestanas, modo),
        "impedimentos": [i for f in fases for i in f["impedimentos"]],
    }


#: Las tandas lanzadas de un video, con lo prometido y cuando empezaron y
#: acabaron: con eso se compara lo PROMETIDO antes de pulsar con lo GASTADO.
NOMBRE_TANDAS = "tandas_coste.jsonl"


def _apuntar_tanda(ctx, registro):
    try:
        with open(ctx.proyecto.ruta(NOMBRE_TANDAS), "a", encoding="utf-8") as fh:
            fh.write(json.dumps(registro, ensure_ascii=False) + "\n")
    except OSError:
        pass


def _cadena_con_cuenta(avisar, ctx, marca, *args):
    """`_correr_cadena` con su ventana de tiempo apuntada (ver NOMBRE_TANDAS)."""
    _apuntar_tanda(ctx, {"marca": marca, "inicio": ahora()})
    estado = "error"
    try:
        resultado = _correr_cadena(avisar, ctx, *args)
        estado = "listo"
        return resultado
    except BaseException as fallo:
        estado = "cancelado" if type(fallo).__name__ == "Cancelado" else "error"
        raise
    finally:
        _apuntar_tanda(ctx, {"marca": marca, "fin": ahora(), "estado": estado})


def _correr_cadena(avisar, ctx, pestanas, modo, datos, plan):
    """Recorre varias pestanas seguidas en UN trabajo. -> resumen.

    Cada pestana ocupa en la barra lo que se espera que tarde, y dentro de ella
    manda el progreso de `_correr_receta`, que ya reparte por tarea. Asi la
    barra de «Generar Vídeo» no se planta en el 50 % durante los seis minutos
    de las imagenes.

    SE INTERRUMPE Y SE RETOMA. Cancelar el trabajo corta en la siguiente llamada
    a `avisar` (nucleo/trabajos.py), y volver a lanzarlo en modo 'pendientes' se
    salta lo que ya salio bien: no hay estado que guardar aparte, porque lo que
    dice por donde iba es el propio proyecto.
    """
    recetas = _recetas()
    total = max(1.0, float(plan["segundos"]))
    salida = {"pestanas": [], "modo": modo, "tareas": [], "saltadas": [],
              "avisos": []}
    # EL CONTADOR PUBLICO ES DE LA TANDA ENTERA, no de cada pestana, y cuenta lo
    # que SE VA A HACER. Contaba todas las tareas del plan --tambien las que se
    # iban a saltar-- y montar el MP4 de un video ya dibujado decia «11 de 11»
    # con tres tareas por delante. Es la misma cuenta que hace `_correr_receta`
    # dentro de cada pestana, que es lo que impide un «9 de 8».
    total_publico = sum(len(f["pendientes"]) for f in plan["fases"])
    hechas_antes = 0
    for ficha in plan["fases"]:
        pestana = ficha["pestana"]
        desde = float(ficha["desde"]) / total
        trozo = max(0.001, float(ficha["segundos"]) / total)

        def avisar_fase(valor, mensaje="", publico="",
                        _d=desde, _t=trozo, _p=pestana):
            avisar(min(0.999, _d + _t * min(1.0, max(0.0, float(valor or 0)))),
                   f"{_p} · {mensaje}" if mensaje else _p,
                   # el nombre de la pestana NO va en el publico: es de casa
                   publico)
        # «Parar» llega en el acto también a través de este envoltorio
        avisar_fase.al_cancelar = getattr(avisar, "al_cancelar", None)

        receta = _receta_de_video(ctx, pestana, datos)
        sin = _sin_de_la_tanda(datos)
        puestas = [t for t in recetas.puestas_de(pestana, receta)
                   if t not in sin]
        if not recetas.orden_de(pestana, puestas):
            continue
        # LA MUSICA Y LOS EFECTOS SON PRESCINDIBLES AQUI: si no salen, el MP4
        # sale sin ellos y el aviso viaja en `avisos` (`_sonido_que_no_tumba`)
        hecho = _correr_receta(avisar_fase, ctx, pestana, receta, puestas, modo,
                               hechas_antes=hechas_antes,
                               total_global=total_publico,
                               sonido_prescindible=True)
        # LAS QUE DE VERDAD HAN CORRIDO, no las que el plan preveia: entre
        # planificar y correr una tarea puede haber dejado de estar al dia, y
        # entonces el contador de la pestana siguiente arrancaria por debajo.
        hechas_antes += len(hecho.get("tareas") or [])
        salida["pestanas"].append(pestana)
        salida["tareas"].extend(hecho.get("tareas") or [])
        salida["saltadas"].extend(hecho.get("saltadas") or [])
        salida["avisos"].extend(hecho.get("avisos") or [])
    salida["resumen"] = (f"{len(salida['tareas'])} tareas en "
                         f"{len(salida['pestanas'])} pestañas"
                         + (f", {len(salida['saltadas'])} ya estaban"
                            if salida["saltadas"] else ""))
    avisar(1.0, salida["resumen"], PUBLICO_LISTO)
    return salida


def _pestanas_pedidas(datos):
    """Las pestanas de una peticion de generacion, validadas y en orden.

    Acepta `tanda` (guion|voz|video, las tres del modo light) o `pestanas` (la
    lista cruda, que es lo que usa la tirada de punta a punta). Sin nada, las
    cinco: eso es PENDIENTE 28.
    """
    recetas = _recetas()
    tanda = str(datos.get("tanda") or "").strip().lower()
    if tanda:
        if tanda not in TANDAS_LIGHT_POR_ID:
            raise ErrorApi(400, f"tanda desconocida: {tanda!r}. Son "
                                + ", ".join(TANDAS_LIGHT_POR_ID))
        return list(TANDAS_LIGHT_POR_ID[tanda]["pestanas"])
    crudas = datos.get("pestanas")
    if crudas is None:
        return list(recetas.PESTANAS)
    if isinstance(crudas, str):
        crudas = [crudas]
    if not isinstance(crudas, list) or not crudas:
        raise ErrorApi(400, "'pestanas' tiene que ser una lista de pestañas")
    pedidas = [str(p).strip().lower() for p in crudas]
    for pestana in pedidas:
        if pestana not in recetas.PESTANAS:
            raise ErrorApi(404, f"pestaña desconocida: {pestana}. Son "
                                + ", ".join(recetas.PESTANAS))
    # EN EL ORDEN DEL PIPELINE, no en el que lleguen: pedir «render, video»
    # renderizaria clips de unos planos que todavia no existen.
    return [p for p in recetas.PESTANAS if p in pedidas]


def _con_origen(ctx, pestanas):
    """La tanda del guion se lleva el ORIGEN si a la ingesta le falta correr.

    En el modo light no hay una pestana «Origen»: hay MATERIAL, y el material
    vive en los params del paso `ingesta`. Pero un param no es una version:
    `brief` depende de `ingesta` y sigue BLOQUEADO hasta que la ingesta corre
    y deja la suya (`dependencias_que_faltan` pregunta por la version, y es lo
    unico que pregunta desde que el material tiene una sola via).

    Esto anadia el origen SOLO si habia una URL de YouTube que bajar --era la
    regla de cuando el material podia venir tambien del documentalista-- y con
    material pegado no anadia nada. Resultado: en un video nuevo la tanda del
    guion llegaba a `brief` con la ingesta sin correr y el servidor contestaba
    «no se puede generar todavia: falta ejecutar ingesta» (visto el 10-09 al
    pulsar «Generar el guion» desde el encargo). Ahora se mira lo que importa:
    si la ingesta NO esta al dia --nunca ha corrido, o el material ha cambiado--
    va delante. Si ya lo esta, no se anade y la tanda queda como antes: con
    modo 'pendientes' se saltaria igual, y con 'todo' no hay por que rehacer
    una entrada que no ha cambiado.
    """
    lista = list(pestanas)
    if "guion" not in lista or "origen" in lista:
        return lista
    if ctx.estado.al_dia("ingesta"):
        return lista
    return ["origen"] + lista


def _trabajo_de_cadena(ctx):
    for ficha in ctx.gestor.listar(activos=True):
        if str(ficha.get("nombre") or "").startswith("generar:"):
            return ficha
    return None


#: Un cerrojo por proyecto para MIRAR-Y-LANZAR una tanda sin que se cuelen dos.
#:
#: Entre la comprobacion de «ya se esta generando» y el `lanzar` hay varios
#: segundos: se calcula el plan entero, su coste y sus impedimentos. El 01-09 se
#: pulso «Montar el vídeo» dos veces con nueve segundos de diferencia y las dos
#: pasaron el 409 -- la primera todavia no habia registrado su trabajo --. Los
#: dos hilos escribieron en la misma carpeta de trabajo y el que llego segundo
#: se encontro con que el primero ya la habia versionado: FileNotFoundError
#: sobre su propio fichero temporal.
_CERROJOS_CADENA = {}
_CERROJO_CERROJOS = threading.Lock()


def _cerrojo_de_cadena(pid):
    with _CERROJO_CERROJOS:
        # REENTRANTE: `lanzar_paso` lo toma, y hay rutas que lo llaman con el
        # ya tomado (la recalidad de imagenes)
        return _CERROJOS_CADENA.setdefault(str(pid), threading.RLock())


@app.get("/api/proyectos/{pid}/generar")
def plan_de_generacion(pid: str, tanda: str = Query(default=""),
                       pestanas: str = Query(default=""),
                       modo: str = Query(default="pendientes")):
    """Lo que va a hacer, cuanto tarda y cuanto cuesta. NO lanza nada.

    Es lo que se lee al lado del boton antes de pulsarlo. Una cifra inventada en
    la pantalla y otra distinta durante la generacion serian dos mentiras, y la
    segunda tardaria diez minutos en descubrirse.
    """
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    ctx = contexto(pid)
    datos = {"tanda": tanda,
             "pestanas": [p for p in pestanas.split(",") if p.strip()] or None}
    if not tanda and not datos["pestanas"]:
        datos.pop("pestanas")
    modo = str(modo or "pendientes").strip().lower()
    if modo not in ("todo", "pendientes"):
        raise ErrorApi(400, f"modo desconocido: {modo!r}. Usa 'todo' o 'pendientes'")
    elegidas = _con_origen(ctx, _pestanas_pedidas(datos))
    # CON `datos` DELANTE, igual que el POST. Sin esto la tanda no llegaba hasta
    # aqui y el plan ENSENADO traia el render que la tanda de video no hace: el
    # boton prometia cuatro tareas y corrian tres. Una cifra en la pantalla y
    # otra durante la generacion son dos mentiras, que es justo lo que este
    # endpoint existe para evitar.
    plan = _plan_de_generacion(ctx, elegidas, modo, datos)
    plan["trabajo"] = _trabajo_de_cadena(ctx) or {}
    plan["tandas"] = TANDAS_LIGHT
    return plan


@app.post("/api/proyectos/{pid}/generar", status_code=202)
def generar_video(pid: str, cuerpo: dict = Body(default=None)):
    """Recorre varias pestanas seguidas, en orden, en UN trabajo.

    Es el boton que faltaba (PENDIENTE 28) y el motor de las tres tandas del
    modo light. `params` se guardan ANTES de planificar, por el mismo motivo que
    en `ejecutar_paso`: la pantalla manda lo que hay escrito al pulsar, y
    generar con los valores anteriores seria mentir.
    """
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    if datos.get("params") is not None and not isinstance(datos.get("params"), dict):
        raise ErrorApi(400, "'params' debe ser un objeto con los params de cada paso")
    nuevos_params = []
    for paso_id, valores in (datos.get("params") or {}).items():
        if paso_id not in PASOS_POR_ID:
            raise ErrorApi(400, f"'{paso_id}' no es un paso: no tiene params")
        if not isinstance(valores, dict):
            raise ErrorApi(400, f"los params de '{paso_id}' tienen que ser un objeto")
        # `_validar_params` VALIDA y no devuelve nada: lo que se guarda es lo
        # que llego. Encadenarlas escribiria None y no guardaria nada.
        _validar_params(paso_id, valores, ctx)
        nuevos_params.append((paso_id, valores))

    modo = str(datos.get("modo") or "pendientes").strip().lower()
    if modo not in ("todo", "pendientes"):
        raise ErrorApi(400, f"modo desconocido: {modo!r}. Usa 'todo' o 'pendientes'")
    elegidas = _con_origen(ctx, _pestanas_pedidas(datos))

    # MIRAR-Y-LANZAR, DENTRO DEL CERROJO. Comprobar fuera no vale: entre la
    # comprobacion y el `lanzar` se calcula el plan entero, y en esos segundos
    # cabe un segundo clic (ver `_cerrojo_de_cadena`).
    with _cerrojo_de_cadena(ctx.id):
        activo = _trabajo_de_cadena(ctx)
        if activo is not None:
            raise ErrorApi(409, "este vídeo ya se está generando",
                           {"trabajo_id": activo["id"], "progreso": activo["progreso"]})
        for pestana in elegidas:
            if _trabajo_de_receta(ctx, pestana) is not None:
                raise ErrorApi(409, f"la pestaña '{pestana}' ya se está generando")

        # LOS PARAMS SE GUARDAN AQUI, NO ANTES (R2 del analisis del 13-10-2026).
        # Escritos antes del cerrojo, un segundo clic que acaba en 409 cambiaba
        # igualmente los params del video que se estaba generando: la firma se
        # movia debajo del trabajo vivo. Se siguen guardando ANTES de planificar
        # (el plan cuenta con lo escrito en pantalla), pero solo si nada esta
        # corriendo en el video: NINGUN trabajo, no solo los de esos pasos. Lo
        # que corre la tanda (`producidos`) no se sabe hasta planificar, y
        # planificar necesita los params ya escritos; con un trabajo vivo de
        # cualquier paso, los mas adelante darian 409 con los params ya movidos
        # (revision de arreglos-v2h). Los 409 que quedan detras (impedimentos,
        # dependencias) no son de algo corriendo: dejar escrito lo de la
        # pantalla ahi es lo de siempre.
        if nuevos_params:
            otro = _trabajo_que_toca(ctx, [p["id"] for p in PASOS])
            if otro is not None:
                raise ErrorApi(409, f"«{otro.get('nombre')}» está corriendo en este "
                                    "vídeo: espera a que termine para generar",
                               {"trabajo_id": otro["id"], "progreso": otro["progreso"]})
            with _COLA_LOCK:
                if _cola_dibujando(ctx):
                    raise ErrorApi(409, "se están rehaciendo imágenes con tus "
                                        "notas: espera a que terminen (o páralas) "
                                        "y vuelve a generar")
                for paso_id, valores in nuevos_params:
                    ctx.estado.actualizar_params(paso_id, valores)

        plan = _plan_de_generacion(ctx, elegidas, modo, datos)
        if not plan["tareas"]:
            raise ErrorApi(400, "no queda nada por generar en "
                                + ", ".join(elegidas)
                                + ". Con modo 'todo' se rehace de todas formas")
        # LO QUE VA A PARAR LA TANDA, DICHO ANTES. Un 400 aqui es un mensaje; el
        # mismo fallo dentro del hilo es una barra que se pone roja a los seis
        # minutos con la mitad hecha.
        if plan["impedimentos"]:
            primero = plan["impedimentos"][0]
            raise ErrorApi(409, primero["que"], {"impedimentos": plan["impedimentos"]})
        recetas = _recetas()
        producidos = set()
        for ficha in plan["fases"]:
            for tarea in ficha["tareas"]:
                producidos.add(recetas.TAREAS_POR_ID[tarea["id"]]["paso"])
        for ficha in plan["fases"]:
            for tarea in ficha["tareas"]:
                paso = recetas.TAREAS_POR_ID[tarea["id"]]["paso"]
                if ctx.estado.estado_de(paso) != "bloqueado":
                    continue
                faltan = dependencias_que_faltan(ctx, paso, producidos)
                if faltan:
                    raise ErrorApi(409, "no se puede generar todavía: falta "
                                        "ejecutar " + ", ".join(faltan),
                                   {"faltan": faltan, "tarea": tarea["id"]})

        # NI A LA VEZ QUE LA COLA DE NOTAS. La cola espera a las tandas
        # (`_otros_trabajos`), pero al reves no se miraba: «Generar» con la cola
        # dibujando lanzaba dos trabajos de imagenes sobre la MISMA carpeta
        # `trabajo/` (regla 2), y se vio repagar planos ya hechos o sellar la
        # imagen vieja encima de la que la nota acababa de pagar (D1 del
        # analisis del 13-10-2026). Mirar y lanzar van con el cerrojo de la cola
        # tomado: es el mismo con el que la cola mira si hay otra cosa en marcha,
        # asi que ninguna de las dos puede colarse entre el mirar y el lanzar
        # de la otra.
        with _COLA_LOCK:
            if producidos & set(_PASOS_QUE_DIBUJA_O_MONTA) and _cola_dibujando(ctx):
                raise ErrorApi(409, "se están rehaciendo imágenes con tus notas: "
                                    "espera a que terminen (o páralas) y vuelve a "
                                    "generar")
            # nada que ya corra alguno de sus pasos (ver `_trabajo_que_toca`)
            otro = _trabajo_que_toca(ctx, producidos)
            if otro is not None:
                raise ErrorApi(409, f"«{otro.get('nombre')}» está corriendo uno de "
                                    "los pasos de esta tanda: espera a que termine",
                               {"trabajo_id": otro["id"], "progreso": otro["progreso"]})
            marca = uuid.uuid4().hex[:12]
            trabajo_id = ctx.gestor.lanzar("generar:" + "+".join(elegidas),
                                           _cadena_con_cuenta, ctx, marca, elegidas, modo, datos,
                                           plan, paso=plan["fases"][0]["tareas"][0]["paso"],
                                           toca=producidos)
        _apuntar_tanda(ctx, {"marca": marca, "trabajo": trabajo_id, "tandas": elegidas,
                             "modo": modo, "lanzada": ahora(),
                             "prometido_usd": (plan.get("coste") or {}).get("usd_por_generar"),
                             "prometido_imagenes": (plan.get("coste") or {}).get("imagenes_por_generar")})
    _registrar_trabajo(trabajo_id, ctx.id)
    ctx.bitacora.anotar("generacion_lanzada", None, {
        "pestanas": elegidas, "modo": modo, "tareas": plan["tareas"],
        "segundos_previstos": plan["segundos"],
        "usd_previstos": plan["coste"]["usd_total"]})
    return {"trabajo_id": trabajo_id, "pestanas": elegidas, "modo": modo,
            "plan": plan, "trabajo": ctx.gestor.estado(trabajo_id),
            "eventos": f"/api/trabajos/{trabajo_id}/eventos"}


#: LA CALIDAD MINIMA DE UN VIDEO FOTO. En foto, `low` es lo que da piel lisa y
#: aspecto de plastico -- la queja que abrio la Etapa Foto --, y subir a `medium`
#: cuesta 1,7 veces y no 6,8 (ver la tabla de CLAUDE.md: las referencias se
#: pagan igual en las dos). Por eso un video NUEVO con estilo foto no arranca por
#: debajo de esto aunque Configuracion diga `low`; con `high` puesto, se respeta.
CALIDAD_MINIMA_FOTO = "medium"


def calidad_de_video_nuevo(modo, calidad_del_estilo=None):
    """Con que calidad arranca un video nuevo. -> "low" | "medium" | "high"

    La del estilo si la trae; si no, la de Configuracion (`AJUSTES`). Y en foto,
    nunca por debajo de `CALIDAD_MINIMA_FOTO`. Solo para videos NUEVOS: `calidad`
    entra en la firma de cada imagen, asi que leer esto al generar dejaria
    obsoletas las de los videos que ya existen.
    """
    calidad = str(calidad_del_estilo or "").strip().lower()
    if calidad not in AJUSTES.CALIDADES:
        try:
            calidad = AJUSTES.calidad_imagen()
        except Exception:  # noqa: BLE001
            calidad = "low"
    if modo == "foto" and (AJUSTES.CALIDADES.index(calidad)
                           < AJUSTES.CALIDADES.index(CALIDAD_MINIMA_FOTO)):
        calidad = CALIDAD_MINIMA_FOTO
    return calidad


@app.post("/api/presets-light/{preset_id}/video", status_code=201)
def crear_video_light(preset_id: str, cuerpo: dict = Body(default=None)):
    """Un proyecto de video nuevo con ese estilo ya aplicado. -> la ficha.

    ES UN PROYECTO NORMAL Y SE VE EN LA LISTA. No es un taller: un taller es la
    carpeta donde se genero un estilo y no es de nadie; esto es un video, y un
    video se hace por donde se quiera pero es el mismo video. Se puede abrir en
    el modo editor y seguir ahi.

    Lo que se le escribe al nacer son las cuatro decisiones que la pantalla del
    modo light ya ha tomado: el estilo (aplicando el preset, con el MISMO codigo
    que el boton del modo editor), la duracion y el material.
    """
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    datos = _cuerpo(cuerpo)
    presets = _presets()
    # 404 y no 400: un estilo que no existe es una direccion equivocada, no una
    # peticion mal escrita. `_preset_o_400` traduce todo a 400 porque casi todo
    # lo que rechaza el almacen son datos malos; esto no.
    try:
        ficha_preset = presets.leer(preset_id)
    except presets.ErrorPreset as fallo:
        raise ErrorApi(404, str(fallo))
    if not ficha_preset:
        raise ErrorApi(404, f"no hay ningún estilo '{preset_id}'")
    if ficha_preset.get("tipo") != "canal":
        raise ErrorApi(400, f"el preset '{preset_id}' es de tipo "
                            f"'{ficha_preset.get('tipo')}': el modo light hace "
                            f"vídeos con estilos de canal")

    # LO QUE LLEVA, validado ANTES de crear nada: un «lleva» que no vale se
    # dice ahora, y no con el video ya creado a medias
    lleva = _normalizar_lleva(datos["lleva"]) if datos.get("lleva") is not None else {}
    # Y EL MONTAJE (movimiento, subtitulos de redes...), por lo mismo
    montaje_pedido = _montaje_pedido_al_crear(datos)
    # Y EL ESPACIO FIJO, por lo mismo (se guarda en `_opciones_al_crear`)
    _espacio_fijo_pedido(datos.get("opciones"))
    # y el tipo de relato (rama tipo-de-relato), por lo mismo
    _tipo_relato_pedido(datos.get("opciones"))

    nombre = str(datos.get("nombre") or "").strip()
    if not nombre:
        nombre = f"Vídeo de {ficha_preset.get('nombre') or preset_id}"
    if not identificador(nombre):
        raise ErrorApi(400, f"'{nombre}' no da un identificador válido")
    os.makedirs(raiz_proyectos(), exist_ok=True)
    base, intento = nombre[:60], 1
    while os.path.isdir(os.path.join(raiz_proyectos(), identificador(nombre))):
        intento += 1
        nombre = f"{base} {intento}"
    try:
        proyecto = Proyecto.crear(raiz_proyectos(), nombre)
    except OSError as fallo:
        raise ErrorApi(500, f"no se ha podido crear el vídeo: {fallo}")
    ctx = contexto(proyecto.id)
    ctx.proyecto.config[CONFIG_VIDEO_LIGHT] = True
    ctx.proyecto.config[CONFIG_ESTILO_LIGHT] = preset_id
    ctx.proyecto.guardar_config()

    # EL ESTILO, con el mismo codigo que el boton del modo editor. Un segundo
    # camino que copiara las claves a mano se quedaria viejo el dia que un
    # preset guarde una mas.
    aplicado = aplicar_preset_canal(proyecto.id, preset_id)
    # LA CALIDAD DE IMAGEN, al nacer, como hace `crear_proyecto`. Este camino no
    # la escribia, y es el UNICO por el que se crean videos desde la pantalla:
    # todos salian en `low` dijera lo que dijera Configuracion. Es un video
    # nuevo, asi que escribirla aqui no deja nada obsoleto.
    params_assets = ctx.estado.params("assets") or {}
    try:
        ctx.estado.actualizar_params("assets", {"calidad": calidad_de_video_nuevo(
            PASOS_MODULOS.p6_assets.modo_de(params_assets.get("estilo")),
            params_assets.get("calidad"))})
    except Exception:  # noqa: BLE001
        # una calidad que no se puede escribir no impide crear el video: se
        # queda con la del paso, que es lo que pasaba antes
        pass
    avisos = _sembrar_video_light(ctx, datos)
    if lleva:
        _aplicar_lleva(ctx, lleva, al_crear=True)
    avisos += _opciones_al_crear(ctx, preset_id, datos.get("opciones") or {})
    avisos += _montaje_al_crear(ctx, datos, montaje_pedido)
    ctx.bitacora.anotar("video_light_creado", None, {
        "preset": preset_id, "estilo": ficha_preset.get("nombre"),
        "nombre": nombre, "avisos": avisos})
    return {"proyecto": ficha_proyecto(ctx),
            "estilo": {"id": preset_id, "nombre": ficha_preset.get("nombre")},
            "aplicado": aplicado.get("pasos") or [],
            "avisos": avisos,
            "pasos": [ficha_paso(ctx, p["id"]) for p in PASOS]}


def _montaje_pedido_al_crear(datos):
    """El montaje y las transiciones que pide el encargo, validados. -> dict

    {"montaje": dict|None, "transiciones": [..]|None, "ritmo": "estilo"|None}.
    `montaje` None es «no ha dicho nada»: un video corto nace entonces con el
    de los cortos (`camara.MONTAJE_CORTOS`) y uno largo con el de siempre.
    """
    camara = PASOS_MODULOS.camara
    opciones = datos.get("opciones") if isinstance(datos.get("opciones"), dict) else {}
    salida = {"montaje": None, "transiciones": None, "ritmo": None}
    if opciones.get("montaje") is not None:
        try:
            salida["montaje"] = camara.normalizar_montaje(opciones["montaje"], estricto=True)
        except ValueError as fallo:
            raise ErrorApi(400, f"montaje: {fallo}")
    if opciones.get("transiciones") is not None:
        salida["transiciones"] = _transiciones_validas(opciones["transiciones"])
    ritmo = str(opciones.get("ritmo") or "").strip().lower()
    if ritmo and ritmo not in ("estilo", "rapido"):
        raise ErrorApi(400, "ritmo: «estilo» o «rapido»")
    salida["ritmo"] = ritmo or None
    return salida


def _transiciones_validas(lista):
    """Las transiciones pedidas, contra el catalogo. -> [ids] (vacia = las de fabrica)"""
    if not isinstance(lista, list):
        raise ErrorApi(400, "transiciones: una lista de nombres")
    catalogo = PASOS_MODULOS.transiciones.CATALOGO
    malas = [str(x) for x in lista if str(x) not in catalogo or str(x) == "corte"]
    if malas:
        raise ErrorApi(400, "transiciones que no existen: " + ", ".join(malas[:5]))
    vistas = []
    for nombre in lista:
        if str(nombre) not in vistas:
            vistas.append(str(nombre))
    return vistas


def _montaje_al_crear(ctx, datos, pedido):
    """El montaje de un video NUEVO, escrito al nacer. -> avisos

    Un video de hasta 2 minutos nace con el montaje de los cortos (movimiento
    vivo, subtitulos de redes, gancho, cifras y barra) y en ritmo rapido si su
    estilo va mas lento, salvo que el encargo diga otra cosa. Uno largo, con lo
    de siempre. Es un video nuevo: escribir aqui no deja nada obsoleto, y lo
    que es igual a lo de siempre NO se escribe (regla 1).
    """
    camara = PASOS_MODULOS.camara
    light = _light()
    avisos = []
    segundos = datos.get("duracion_objetivo_s")
    try:
        corto = 0 < float(segundos or 0) <= camara.DURACION_CORTA_S
    except (TypeError, ValueError):
        corto = False
    montaje = pedido.get("montaje")
    if montaje is None and corto:
        montaje = camara.normalizar_montaje(camara.MONTAJE_CORTOS)
    guardar = camara.para_guardar(montaje) if montaje is not None else None
    if guardar:
        ctx.estado.actualizar_params("callouts", {"montaje": guardar})
    if pedido.get("transiciones"):
        ctx.estado.actualizar_params("render", {"transiciones": pedido["transiciones"]})
    if corto and pedido.get("ritmo") != "estilo":
        assets = ctx.estado.params("assets") or {}
        ritmo = light.ritmo_para_video_nuevo(segundos, assets.get("max_s"))
        if ritmo:
            for paso, valores in light.params_de_ritmo(ritmo).items():
                ctx.estado.actualizar_params(paso, valores)
            ctx.proyecto.config[CONFIG_RITMO_DEL_VIDEO] = ritmo
            ctx.proyecto.guardar_config()
            ctx.bitacora.anotar("ritmo_de_corto", "assets", {"ritmo": ritmo})
    return avisos


def _espacio_fijo_pedido(opciones):
    """El `espacio_fijo` de las opciones del encargo, limpio. -> ({} | espacio, png|None)

    400 si llega mal formado. Se llama tambien ANTES de crear el video, para
    que un espacio que no vale se diga sin dejar un video creado a medias. La
    imagen llega como `imagen_nueva` (data URL o base64) y vuelve en PNG; una
    `imagen` ya guardada no vale aqui: el video todavia no existe.
    """
    if not isinstance(opciones, dict) or opciones.get("espacio_fijo") is None:
        return {}, None
    crudo = opciones["espacio_fijo"]
    if isinstance(crudo, dict):
        crudo = {k: v for k, v in crudo.items() if k not in ("imagen", "imagen_nueva")}
    try:
        espacio = _catalogo_visual().normalizar_espacio_fijo(crudo)
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    nueva = (opciones["espacio_fijo"] or {}).get("imagen_nueva") \
        if isinstance(opciones["espacio_fijo"], dict) else None
    png = _png_del_espacio(nueva) if (espacio and nueva) else None
    return espacio, png


#: Lo que se acepta de la imagen del espacio fijo. Se guarda en PNG y con el
#: lado mayor recortado: va adjunta a cada plano de su sitio y el motor la
#: reduce a 1024 de todos modos (`imagen.normalizar`).
MAX_BYTES_IMAGEN_ESPACIO = 12 * 1024 * 1024
LADO_IMAGEN_ESPACIO = 1536


def _png_del_espacio(crudo):
    """La imagen subida del espacio fijo (data URL o base64) -> bytes PNG. 400 si no vale."""
    import base64
    import binascii
    import io as _io
    if not isinstance(crudo, str) or not crudo.strip():
        raise ErrorApi(400, "espacio_fijo.imagen_nueva: hace falta la imagen")
    texto = crudo.strip()
    if texto.startswith("data:"):
        texto = texto.split(",", 1)[-1]
    if len(texto) > MAX_BYTES_IMAGEN_ESPACIO * 4 // 3 + 16:
        raise ErrorApi(400, f"la imagen del espacio fijo pasa de "
                            f"{MAX_BYTES_IMAGEN_ESPACIO // (1024 * 1024)} MB")
    try:
        datos = base64.b64decode(texto, validate=False)
    except (binascii.Error, ValueError):
        raise ErrorApi(400, "la imagen del espacio fijo no se puede leer")
    try:
        from PIL import Image                                # noqa: PLC0415
        imagen = Image.open(_io.BytesIO(datos))
        imagen.load()
        imagen = imagen.convert("RGB")
    except Exception:                                       # noqa: BLE001
        raise ErrorApi(400, "eso no es una imagen: sube un JPG o un PNG del sitio")
    if max(imagen.size) > LADO_IMAGEN_ESPACIO:
        escala = LADO_IMAGEN_ESPACIO / max(imagen.size)
        imagen = imagen.resize((max(1, int(imagen.width * escala)),
                                max(1, int(imagen.height * escala))))
    salida = _io.BytesIO()
    imagen.save(salida, format="PNG")
    return salida.getvalue()


def _guardar_png_del_espacio(ctx, png):
    """Guarda la imagen en <proyecto>/espacio_fijo/<huella>.png -> la ruta RELATIVA.

    Relativa y con el nombre del contenido: viaja con la carpeta del proyecto
    sin mudanza (CLAUDE.md, «copiar un proyecto»), y otra imagen es otro
    fichero, asi que la anterior sigue ahi para lo que ya se dibujo con ella."""
    nombre = hashlib.sha256(png).hexdigest()[:16] + ".png"
    destino = ctx.proyecto.ruta("espacio_fijo", nombre)
    os.makedirs(os.path.dirname(destino), exist_ok=True)
    if not os.path.exists(destino):
        temporal = destino + ".tmp"
        with open(temporal, "wb") as fh:
            fh.write(png)
        os.replace(temporal, destino)
    return f"espacio_fijo/{nombre}"


def _opciones_al_crear(ctx, preset_id, opciones):
    """Musica, subtitulos y logo elegidos en el encargo de un video NUEVO. -> avisos

    Lo mismo que se puede cambiar despues en el video, decidido antes de que
    exista. Solo se escribe lo que se eligio: lo que se deja en automatico no
    toca ningun param (regla 1). Y el logo del PROYECTO del estilo entra solo,
    salvo que el encargo diga «sin logo».
    """
    avisos = []
    sonido = _sonido()
    if not isinstance(opciones, dict):
        return avisos
    # EL ESPACIO FIJO (todo el video en un mismo sitio), a los params de assets,
    # que es lo que lee el catalogo. SOLO si viene con descripcion: sin el no se
    # escribe nada y el video nace como siempre (regla 1).
    espacio, png = _espacio_fijo_pedido(opciones)
    if espacio:
        if png:
            espacio["imagen"] = _guardar_png_del_espacio(ctx, png)
        ctx.estado.actualizar_params("assets", {"espacio_fijo": espacio})
    # EL TIPO DE RELATO elegido en el encargo (o leido de la Parrilla). Solo si
    # se eligio uno: sin el, manda el del estilo y no se escribe nada (regla 1)
    relato = _tipo_relato_pedido(opciones)
    if relato:
        ctx.estado.actualizar_params("assets", {"tipo_relato": relato})
    # QUE DIBUJAN LAS IMAGENES (rama guion-visual). Solo «guion» se escribe, y
    # con el las lineas «Visual:» de la Parrilla, si las hay, para casarlas con
    # el guion cuando exista. Sin elegir, nada (regla 1).
    gv = _guion_visual()
    crudo_img = opciones.get("imagenes")
    if crudo_img not in (None, "") and gv._llano(crudo_img).strip() == "voz":
        imagenes = "voz"       # «Imágenes: voz» explícito: manda sobre el estilo
    else:
        try:
            imagenes = gv.normalizar_modo(crudo_img)
        except ValueError as fallo:
            raise ErrorApi(400, str(fallo))
    visuales = gv.normalizar_visuales(opciones.get("visuales") or [])
    cambios = {}
    if imagenes:
        cambios["imagenes"] = imagenes
    if visuales:
        # las lineas «Visual:» del guion de la Parrilla se guardan siempre que
        # lleguen: si el estilo dice «guion», o se elige despues, no se pierden
        cambios["guion_visual"] = {"origen": "parrilla", "planos": [],
                                   "aprobado": False, "visuales": visuales}
    if cambios:
        ctx.estado.actualizar_params("assets", cambios)
    presencia = opciones.get("presencia")
    if presencia:
        if presencia not in sonido.PRESENCIAS:
            raise ErrorApi(400, "presencia: " + ", ".join(sonido.PRESENCIAS))
        if presencia != sonido.PRESENCIA_POR_DEFECTO:
            ctx.estado.actualizar_params("render", {"musica_presencia": presencia})
    # EL AJUSTE FINO DE LA MUSICA, elegido ya en el encargo del video nuevo
    # (19-10-2026). Mismo margen que `PUT /sonido`; 0 no se escribe (regla 1)
    if "musica_db" in opciones and opciones.get("musica_db") is not None:
        valor = opciones.get("musica_db")
        if isinstance(valor, bool) or not isinstance(valor, (int, float)) \
                or not math.isfinite(valor):
            raise ErrorApi(400, "musica_db: un número de decibelios, de -12 a +6")
        valor = round(max(-12.0, min(6.0, float(valor))), 1)
        if valor:
            ctx.estado.actualizar_params("render", {"musica_db": valor})
    tema = opciones.get("musica")
    if isinstance(tema, dict) and tema.get("id") and tema.get("descarga"):
        try:
            sonido.traer(tema, "musica")
            ctx.estado.actualizar_params("render", {"musica": tema})
        except Exception as fallo:                          # noqa: BLE001
            avisos.append(f"no se ha podido bajar el tema elegido ({fallo}): "
                          f"irá la música automática")
    if isinstance(opciones.get("subtitulos"), dict) and opciones["subtitulos"]:
        _aplicar_subtitulos(ctx, opciones["subtitulos"])
    logo = opciones.get("logo")
    if logo is False or opciones.get("sin_logo"):
        return avisos
    if not (isinstance(logo, dict) and logo.get("fichero")):
        del_proyecto = CLIENTES.de_estilo(raiz_proyectos(), preset_id) or {}
        logo = del_proyecto.get("logo")
    if isinstance(logo, dict) and logo.get("fichero"):
        try:
            _poner_logo_suelto(ctx, logo)
        except ErrorApi as fallo:
            avisos.append(f"el logo no se ha podido poner: {fallo.mensaje}")
    return avisos


def _sembrar_video_light(ctx, datos):
    """Las decisiones que la pantalla del modo light ya ha tomado. -> [avisos]

    Son params de siempre y de pasos de siempre: la duracion y el tema van al
    brief, y el material al paso «Origen». Nada de esto es una via nueva -- es
    rellenar los mismos cajones que rellena el modo editor a mano, que es la
    unica forma de que las dos pantallas no se separen.
    """
    avisos = []
    brief, guion = {}, {}
    if datos.get("duracion_objetivo_s") is not None:
        brief["duracion_objetivo_s"] = datos["duracion_objetivo_s"]
    # EL FORMATO, junto a la duracion: horizontal o vertical.
    # Es una decision del video y va al brief, de donde la leen los pasos.
    if datos.get("formato") is not None:
        brief["formato"] = PASOS_MODULOS.comun.normalizar_formato(datos["formato"])
    # LAS INSTRUCCIONES DEL BRIEF NO SE TOCAN, y es deliberado: ahi vive la GUIA
    # DE TONO del canal, que es lo que acaba de escribir el estilo al aplicarse.
    # En el modo light no hay un campo «de que va el video»: el material ES el
    # encargo y el nombre del proyecto es como lo llamo quien lo creo.
    # Machacarlas aqui borraria el tono del canal con una frase de este video.
    if datos.get("instrucciones") is not None:
        brief["instrucciones"] = str(datos["instrucciones"] or "")
    # EL MATERIAL, al paso «Origen»: es su param, con su version y su firma.
    # Aqui llega como un texto y no como una lista de fuentes -- ya no hay
    # varias, ni enlaces que resolver, ni nada que buscar fuera.
    ingesta = {}
    if datos.get("material") is not None:
        ingesta["texto"] = str(datos["material"] or "")
    if datos.get("titulo_material") is not None:
        ingesta["titulo"] = str(datos["titulo_material"] or "")
    # Y SI LO PEGADO YA ES EL GUION, la regla del redactor cambia: no se
    # reescribe, se respeta. Es del guion --es una regla de SU prompt-- y no del
    # material, que es el mismo texto en los dos casos.
    if datos.get("guion_propio") is not None:
        guion["guion_propio"] = bool(datos["guion_propio"])
    # LA PRESENTACION Y LAS LLAMADAS A LA ACCION. Se normalizan AQUI --y no al
    # redactar-- para que un producto que no existe se conteste al crear el
    # video, que es cuando hay alguien mirando la pantalla, y no veinte minutos
    # despues. El estilo ya las trae puestas (van en el preset de guion); esto
    # es lo que el encargo de ESTE video haya cambiado.
    if datos.get("cta") is not None:
        try:
            guion["cta"] = _cta().normalizar(datos["cta"], estricto=True)
        except ValueError as fallo:
            raise ErrorApi(400, f"cta: {fallo}")
    # LAS INDICACIONES DEL VIDEO, al cajon del guion que existe para eso
    # (`prompt_general`): «no fuerces una historia de personaje», «no incluyas
    # la entrevista». Van aparte del material a proposito -- el material son los
    # HECHOS y esto es COMO contarlos --, y no se pisa lo que ya hubiera escrito.
    if datos.get("indicaciones") is not None:
        guion["prompt_general"] = str(datos["indicaciones"] or "")
    if ingesta:
        _validar_params("ingesta", ingesta, ctx)
        ctx.estado.actualizar_params("ingesta", ingesta)
    if brief:
        _validar_params("brief", brief, ctx)
        ctx.estado.actualizar_params("brief", brief)
    if guion:
        _validar_params("guion", guion, ctx)
        ctx.estado.actualizar_params("guion", guion)
    return avisos


def _cta():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.cta


# ==========================================================================
# EL MATERIAL DEL VIDEO
#
# SI es un paso del grafo --«Origen», `pasos/p1_ingesta.py`-- y por eso aqui solo
# hay lectura. El texto vive en su param, con su version y su firma, asi que
# cambiarlo deja obsoletos el brief, el guion, la voz y todo lo que cuelga, que
# es exactamente lo que tiene que pasar.
#
# `pasos/fuentes.py` es quien lo LEE, y esta separado del paso que lo escribe a
# proposito: el porque esta en su cabecera.
# ==========================================================================

def _fuentes():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.fuentes


@app.get("/api/estadisticas")
def estadisticas_globales(paso: str = Query(default=""),
                          tamano: int = Query(default=0)):
    """Historico de tiempos reales, entre todos los proyectos.

    Sin 'paso' devuelve el panorama; con 'paso' devuelve la comparativa completa
    de combinaciones mas la recomendacion.
    """
    if not paso:
        return ESTADISTICAS.panorama()
    return {
        "paso": paso,
        "comparativa": ESTADISTICAS.comparativa(paso, tamano=tamano),
        "recomendacion": ESTADISTICAS.recomendacion(paso, tamano=tamano),
        "historial": ESTADISTICAS.historial(paso)[-40:],
    }


@app.post("/api/estadisticas/valoracion")
def valorar_ajuste(cuerpo: dict = Body(default=None)):
    """Anota si el resultado de un ajuste gusto o no.

    Es la unica senal de calidad que no es un proxy. Sin ella el recomendador
    solo sabria recomendar lo mas rapido, que es una tautologia, no un consejo.
    """
    datos = _cuerpo(cuerpo)
    paso = str(datos.get("paso") or "").strip()
    if not paso:
        raise ErrorApi(400, "hace falta decir de qué paso es la valoración")
    ajuste = _ajuste_cli(datos)
    try:
        anotada = ESTADISTICAS.valorar(
            paso, datos.get("valoracion"), ajuste=ajuste,
            proyecto=datos.get("proyecto"), nota=datos.get("nota"))
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    if anotada is None:
        raise ErrorApi(409, f"todavía no hay ninguna ejecución de '{paso}' con "
                            f"{ajuste['modelo']}/{ajuste['esfuerzo']} que valorar")
    return {"anotada": anotada,
            "recomendacion": ESTADISTICAS.recomendacion(paso)}


# ------------------------------------------------------------------- capturas
# La captura del fotograma la compone el navegador (en callouts rehaciendo la
# ventana de zoom con la misma matematica del render, en render dibujando el
# <video> en un canvas). Aqui llega ya como PNG y se guarda con su anotacion.

def almacen(ctx):
    """Almacen de capturas del proyecto."""
    return CAPTURAS.Almacen(ctx.proyecto)


def _p7():
    if PASOS_MODULOS is None:
        raise ErrorApi(503, f"los pasos no se han podido cargar: {ERROR_PASOS}")
    return PASOS_MODULOS.p7_callouts


def _ficha_captura(ctx, ficha):
    """Ficha de captura con la URL con la que la interfaz pinta el PNG."""
    salida = dict(ficha)
    salida["url"] = f"/a/{ctx.id}/" + str(ficha.get("imagen") or "")
    return salida


async def _cuerpo_captura(peticion):
    """Lee la captura venga como multipart o como JSON con la imagen en base64."""
    tipo = (peticion.headers.get("content-type") or "").lower()
    if tipo.startswith("multipart/"):
        try:
            formulario = await peticion.form()
        except Exception as fallo:  # noqa: BLE001
            raise ErrorApi(400, f"multipart ilegible: {fallo}")
        datos, imagen = {}, None
        for clave, valor in formulario.multi_items():
            if hasattr(valor, "read"):
                if clave in ("imagen", "png", "captura"):
                    imagen = await valor.read()
                continue
            datos[clave] = valor
        return datos, imagen
    try:
        datos = await peticion.json()
    except Exception:  # noqa: BLE001
        raise ErrorApi(400, "manda la captura como multipart (imagen + campos) "
                            "o como JSON con 'imagen_b64'")
    datos = datos if isinstance(datos, dict) else {}
    return datos, datos.get("imagen_b64") or datos.get("imagen")


@app.post("/api/proyectos/{pid}/capturas", status_code=201)
async def crear_captura(pid: str, peticion: Request):
    """Guarda una captura anotada de los pasos callouts o render.

    Acepta multipart (imagen + metadatos) y tambien JSON con 'imagen_b64', que
    es lo comodo para un cliente que ya tiene el dataURL del canvas.
    """
    ctx = await _en_hilo(contexto, pid)
    datos, imagen = await _cuerpo_captura(peticion)
    return await _en_hilo(_guardar_captura, ctx, datos, imagen)


def _guardar_captura(ctx, datos, imagen):
    """Lo de `crear_captura` que lee planos, mira el estado y escribe: en el pool."""
    if imagen is None:
        raise ErrorApi(400, "falta el PNG de la captura ('imagen' en multipart "
                            "o 'imagen_b64' en JSON)")
    paso = CAPTURAS.validar_paso(datos.get("paso"))
    escena = str(datos.get("escena") or "").strip() or None
    t_video = CAPTURAS.segundos(datos.get("t_video"), "t_video")
    t_escena = CAPTURAS.segundos(datos.get("t_escena"), "t_escena")
    if escena is None and t_video is None:
        raise ErrorApi(400, "hace falta 'escena' o 't_video' para situar la captura")

    temporal = _p7().contexto_temporal(ctx.proyecto, escena, t_video, t_escena)
    escena = temporal.get("escena") or escena
    if not escena:
        raise ErrorApi(400, f"no hay ningún plano en t_video={t_video}: "
                            f"manda 'escena' o ejecuta callouts antes")
    _comprobar_unidades(ctx, paso, [f"escena:{escena}"])

    ficha = almacen(ctx).crear(
        paso, escena, imagen,
        trazos=datos.get("trazos"),
        comentario=datos.get("comentario") or datos.get("texto") or "",
        t_video=temporal.get("t_video", t_video),
        t_escena=temporal.get("t_escena", t_escena),
        contexto=temporal)
    ctx.bitacora.anotar("captura_tomada", paso, {
        "captura": ficha["id"], "imagen": ficha["imagen"],
        "t_video": ficha["t_video"], "t_escena": ficha["t_escena"],
        "comentario": ficha["comentario"], "trazos": len(ficha["trazos"]),
        "instante": temporal.get("frase", "")}, unidad=ficha["unidad"])
    return {"captura": _ficha_captura(ctx, ficha), "contexto": temporal}


@app.get("/api/proyectos/{pid}/capturas")
def listar_capturas(pid: str, paso: str = Query(default=None),
                    escena: str = Query(default=None),
                    pendientes: int = Query(default=0)):
    """Capturas del proyecto, filtrables por paso y escena."""
    ctx = contexto(pid)
    fichas = almacen(ctx).listar(paso=paso, escena=escena,
                                 pendientes=True if pendientes else None)
    fichas = [_ficha_captura(ctx, f) for f in fichas]
    return {"proyecto": ctx.id, "capturas": fichas, "total": len(fichas),
            "pendientes": sum(1 for f in fichas if not f.get("aplicada"))}


@app.get("/api/proyectos/{pid}/capturas/contexto")
def contexto_captura(pid: str, paso: str = Query(default="callouts"),
                     escena: str = Query(default=None),
                     t_video: float = Query(default=None),
                     t_escena: float = Query(default=None)):
    """Donde cae un instante y con que material se compone ese fotograma.

    La interfaz necesita la ventana de zoom EXACTA de ese instante para pintar
    el fotograma igual que lo pinta el render; calcularla dos veces con dos
    formulas parecidas es justo lo que haria que la captura y el video no
    coincidiesen.
    """
    ctx = contexto(pid)
    paso = CAPTURAS.validar_paso(paso)
    p7 = _p7()
    ficha = p7.contexto_temporal(ctx.proyecto, escena, t_video, t_escena)
    ficha["paso"] = paso
    ficha["unidad"] = f"escena:{ficha['escena']}" if ficha.get("escena") else None
    ficha["escenas"] = [{"id": sid, **tramo} for sid, tramo in
                        sorted(p7.tiempos_de_escena(ctx.proyecto).items(),
                               key=lambda kv: kv[1]["t_in"])]

    if paso == "render":
        reproductor = PASOS_MODULOS.p8_render.reproductor(ctx.proyecto)
        ficha["mp4"] = url_de(ctx.id, reproductor["mp4"], ctx.proyecto.raiz)
        ficha["clip"] = url_de(ctx.id, reproductor["clips"].get(ficha.get("escena")),
                               ctx.proyecto.raiz)
        ficha["fps"] = reproductor["fps"]
        ficha["resolucion"] = reproductor["resolucion"]
        ficha["duracion_video"] = reproductor["duracion"]
        return ficha

    mov = p7.movimientos_de(ctx.proyecto).get(ficha.get("escena"))
    if not mov:
        raise ErrorApi(409, f"callouts todavía no ha producido el plano "
                            f"{ficha.get('escena')}: no hay fotograma que componer")
    base = os.path.dirname(p7.ruta_movimiento(ctx.proyecto))
    hyper = os.path.join(base, mov.get("hyperframe") or "")
    capa = os.path.join(base, mov.get("capa") or "")
    tamano = mov.get("hyperframe_px") or [3072, 2048]
    resolucion = PASOS_MODULOS.p8_render.PARAMS_POR_DEFECTO["resolucion"]
    aspecto = float(resolucion[0]) / float(resolucion[1])
    fraccion = ficha.get("fraccion") or 0.0
    ficha.update({
        "hyperframe": url_de(ctx.id, hyper, ctx.proyecto.raiz),
        "hyperframe_px": tamano,
        "capa": url_de(ctx.id, capa, ctx.proyecto.raiz),
        "resolucion": list(resolucion),
        "ventana": [round(v, 3) for v in
                    p7.ventana_en(mov, fraccion, tamano, aspecto)],
        "ventana_ini": mov.get("ventana_ini"),
        "ventana_fin": mov.get("ventana_fin"),
    })
    return ficha


@app.delete("/api/proyectos/{pid}/capturas/{cid}")
def borrar_captura(pid: str, cid: str):
    """Borra una captura y su PNG."""
    ctx = contexto(pid)
    borrada = almacen(ctx).borrar(cid)
    if borrada is None:
        raise ErrorApi(404, f"captura desconocida: {cid}")
    ctx.bitacora.anotar("captura_borrada", borrada.get("paso"),
                        {"captura": cid}, unidad=borrada.get("unidad"))
    return {"borrada": cid, "captura": borrada}


def _correr_capturas_agente(avisar, ctx, grupos, paso_id, unidades, ajuste=None):
    """Deja que el CLI decida que cambiar y despues rehace las unidades.

    El camino directo solo recoloca con lo que dicen los trazos; este sirve
    cuando el problema no es donde cae un rotulo sino como esta planteado el
    plano, que es algo que hay que mirar y decidir.

    El modelo y el esfuerzo llegan por invocacion y NO son params del paso: son
    la forma de resolver ESTA peticion, no una propiedad del plano. Guardarlos en
    los params cambiaria la firma del paso y dejaria obsoleto todo lo que cuelga
    de el cada vez que alguien mueve un desplegable.
    """
    ajuste = ajuste or {}
    recomendado = CLI_CLAUDE.por_defecto_de("capturas_agente")
    modelo = ajuste.get("modelo") or recomendado["modelo"]
    esfuerzo = ajuste.get("esfuerzo") or recomendado["esfuerzo"]
    instruccion = INSTRUCCION_CAPTURAS.format(
        proyecto=ctx.proyecto.raiz,
        paso=paso_id,
        unidades=", ".join(unidades or []),
        detalle="\n\n".join(g["instruccion"] for g in grupos))

    prevision = ESTADISTICAS.estimar(
        "capturas_agente", tamano=len(unidades or []),
        ajuste={"modelo": modelo, "esfuerzo": esfuerzo})
    avance = ESTADISTICAS.Avance(avisar, 0.05, 0.33, prevision,
                                 f"el agente esta mirando las capturas con "
                                 f"{modelo} (esfuerzo {esfuerzo})")
    avance.arrancar()
    arranque = time.time()
    try:
        # Aqui el agente SI usa herramientas: tiene que mirar los PNG y editar el
        # proyecto. Por eso no se le vetan, a diferencia del guion.
        texto, sobre = CLI_CLAUDE.ejecutar(
            instruccion, modelo=modelo, esfuerzo=esfuerzo,
            cwd=ctx.proyecto.raiz, tiempo_max_s=int(ajuste.get("tiempo_max_s") or 0),
            base_tiempo_s=1800, herramientas_vetadas=None,
            permisos="acceptEdits", avance=avance,
            para="el agente de capturas")
    except BaseException:
        avance.parar()
        ESTADISTICAS.anotar("capturas_agente", time.time() - arranque, ok=False,
                            ajuste={"modelo": modelo, "esfuerzo": esfuerzo},
                            proyecto=ctx.id, resultado="error")
        raise
    segundos = avance.parar()
    ESTADISTICAS.anotar("capturas_agente", segundos,
                        tamano=len(unidades or []),
                        ajuste={"modelo": modelo, "esfuerzo": esfuerzo},
                        proyecto=ctx.id, unidades=len(unidades or []),
                        detalle={"modelo": modelo, "esfuerzo": esfuerzo,
                                 "paso": paso_id,
                                 "tokens_salida": comun_tokens(sobre).get("salida")})
    with COSTE.contexto(ctx.proyecto, paso_id):
        COSTE.reportar_claude(sobre, operacion="capturas")
    ctx.bitacora.anotar("capturas_agente", paso_id,
                        {"resumen": str(texto or "")[:1200],
                         "modelo": modelo, "esfuerzo": esfuerzo,
                         "segundos": round(segundos, 1)})
    avisar(0.35, "rehaciendo lo que el agente ha tocado")
    resultado = _correr_paso(avisar, ctx, paso_id, unidades)
    resultado["agente"] = str(texto or "")[:2000]
    resultado["ajuste_cli"] = {"modelo": modelo, "esfuerzo": esfuerzo,
                               "segundos": round(segundos, 1)}
    return resultado


INSTRUCCION_CAPTURAS = """\
Eres el asistente de produccion de un video del Estudio.

El revisor ha marcado un problema sobre el reproductor del paso {paso} y ha
dejado estas capturas anotadas (las imagenes estan en capturas/ dentro del
proyecto, y los PNG se pueden mirar):

{detalle}

Trabajas en {proyecto}. Las unidades afectadas son: {unidades}.

Mira las capturas, decide que hay que cambiar de verdad (el texto del rotulo, su
colocacion, el movimiento de camara, el plano) y aplicalo donde corresponda
dentro del proyecto. NO toques otras escenas. En cuanto termines, el estudio
rehara por su cuenta esas unidades, asi que no lances renders tu.

Acaba con un resumen de una linea de lo que has cambiado.
"""


def _ajuste_cli(datos, defecto_modelo=None, defecto_esfuerzo=None):
    """Modelo y esfuerzo de una peticion, validados.

    Se valida aqui, al entrar, y no cuando ya se ha lanzado el CLI: un modelo mal
    escrito solo se detecta por returncode != 0, o sea despues de haber pagado el
    arranque y la espera entera.
    """
    datos = datos if isinstance(datos, dict) else {}
    crudo = datos.get("ajuste") if isinstance(datos.get("ajuste"), dict) else datos
    try:
        modelo = CLI_CLAUDE.normalizar_modelo(
            crudo.get("modelo"), defecto=defecto_modelo or CLI_CLAUDE.MODELO_POR_DEFECTO)
        esfuerzo = CLI_CLAUDE.normalizar_esfuerzo(
            crudo.get("esfuerzo"),
            defecto=defecto_esfuerzo or CLI_CLAUDE.ESFUERZO_POR_DEFECTO)
    except ValueError as fallo:
        raise ErrorApi(400, str(fallo))
    ajuste = {"modelo": modelo, "esfuerzo": esfuerzo}
    if crudo.get("tiempo_max_s"):
        try:
            ajuste["tiempo_max_s"] = int(crudo["tiempo_max_s"])
        except (TypeError, ValueError):
            raise ErrorApi(400, "tiempo_max_s tiene que ser un número entero")
    return ajuste


def _lanzar_capturas(ctx, paso_id, unidades, grupos, modo, ajuste=None):
    """Comprueba y lanza la regeneracion que piden las capturas aplicadas."""
    if ctx.estado.estado_de(paso_id) == "bloqueado":
        faltan = [d for d in PASOS_POR_ID[paso_id]["depende_de"]
                  if ctx.proyecto.version_activa(d) is None]
        raise ErrorApi(409, f"'{paso_id}' está bloqueado: falta ejecutar "
                            + ", ".join(faltan), {"faltan": faltan})
    if modo != "agente":
        return lanzar_paso(ctx, paso_id, unidades, nombre=f"capturas:{paso_id}",
                           evento="capturas_aplicadas",
                           datos={"modo": modo,
                                  "capturas": [c for g in grupos
                                               for c in g["capturas"]]})
    activo = _trabajo_activo(ctx, paso_id)
    if activo is not None:
        raise ErrorApi(409, f"'{paso_id}' ya se está ejecutando",
                       {"trabajo_id": activo["id"], "progreso": activo["progreso"]})
    modulo_de(paso_id)
    trabajo_id = ctx.gestor.lanzar(f"capturas:{paso_id}", _correr_capturas_agente,
                                   ctx, grupos, paso_id, unidades, ajuste,
                                   paso=paso_id)
    _registrar_trabajo(trabajo_id, ctx.id)
    ctx.bitacora.anotar("capturas_aplicadas", paso_id,
                        {"modo": modo, "trabajo": trabajo_id,
                         "unidades": unidades or "todas",
                         "ajuste": ajuste,
                         "capturas": [c for g in grupos for c in g["capturas"]]})
    return trabajo_id


@app.post("/api/proyectos/{pid}/capturas/aplicar", status_code=202)
def aplicar_capturas(pid: str, cuerpo: dict = Body(default=None)):
    """Traduce las capturas a instruccion y rehace SOLO las escenas tocadas.

    Varias capturas de la misma escena se juntan en una sola instruccion
    ordenada por instante. Si hay capturas de callouts y de render a la vez se
    lanza la de mas arriba del grafo: rehacer la capa ya deja obsoleta esa misma
    escena en el render, y lanzar los dos a la vez seria pisarse.
    """
    ctx = contexto(pid)
    datos = _cuerpo(cuerpo)
    modo = str(datos.get("modo") or "directo").strip().lower()
    if modo not in ("directo", "agente"):
        raise ErrorApi(400, f"modo desconocido: {modo!r}. Usa 'directo' o 'agente'")
    # Se valida siempre, aunque el modo sea 'directo': si alguien manda un ajuste
    # imposible conviene que lo sepa ahora y no la proxima vez que use el agente.
    ajuste = _ajuste_cli(datos)
    guardadas = almacen(ctx)
    pedidas = datos.get("capturas")
    if isinstance(pedidas, str):
        pedidas = [pedidas]
    else:
        pedidas = _lista_de_textos(datos, "capturas")
    if pedidas:
        fichas = guardadas.obtener_varias(pedidas)
    else:
        fichas = guardadas.listar(pendientes=True)
    if not fichas:
        raise ErrorApi(409, "no hay capturas pendientes que aplicar")

    p7 = _p7()
    zonas = {}
    for ficha in fichas:
        if ficha.get("paso") == "callouts":
            zonas[ficha["id"]] = p7.zonas_de_captura(ctx.proyecto, ficha)

    grupos = CAPTURAS.aplicar(ctx.estado, fichas, zonas=zonas, modo=modo)
    for grupo in grupos:
        ctx.bitacora.anotar("captura_aplicada", grupo["paso"], {
            "capturas": grupo["capturas"],
            "imagenes": grupo["nota"]["imagenes"],
            "instruccion": grupo["instruccion"],
            "zonas_evitadas": len(grupo["zonas"]),
            "modo": modo}, unidad=grupo["unidad"])

    por_paso = {}
    for grupo in grupos:
        por_paso.setdefault(grupo["paso"], []).append(grupo["unidad"])
    orden = [p["id"] for p in PASOS if p["id"] in por_paso]
    primero = orden[0]
    trabajo_id = _lanzar_capturas(ctx, primero, sorted(set(por_paso[primero])),
                                  [g for g in grupos if g["paso"] == primero], modo,
                                  ajuste=ajuste)
    guardadas.marcar_aplicadas([c for g in grupos for c in g["capturas"]],
                               trabajo=trabajo_id)
    return {
        "trabajo_id": trabajo_id,
        "paso": primero,
        "modo": modo,
        "ajuste": ajuste if modo == "agente" else None,
        "unidades": sorted(set(por_paso[primero])),
        "grupos": grupos,
        "aplazados": {paso: sorted(set(uds)) for paso, uds in por_paso.items()
                      if paso != primero},
        "aguas_abajo": {hijo: ctx.estado.unidades_obsoletas(hijo)
                        for hijo in descendientes_de(primero)},
        "trabajo": ctx.gestor.estado(trabajo_id),
        "eventos": f"/api/trabajos/{trabajo_id}/eventos",
    }


# ---------------------------------------------------------------------- web
# La interfaz se sirve desde el MISMO origen que la API: app.js pide rutas
# absolutas (/api/..., /a/...) y desde file:// o desde otro puerto no habria
# forma de hablar con el servicio sin CORS. Estas dos rutas van las ultimas
# para no tapar ninguna de las de arriba.

@app.get("/")
def portada(peticion: Request):
    """La interfaz del Estudio."""
    return fichero_web("index.html", peticion)


#: Rutas que NO son ficheros: son el MODO con el que abrir la interfaz.
#:
#: `/light` y `/editor` sirven la misma pagina que `/`, y quien lee el modo es
#: el navegador (`modoDeLaUrl` en app.js), que ademas lo recuerda. Existen para
#: poder guardar un enlace directo --y para que el panel de control pueda abrir
#: el Estudio ya en el modo que toca-- sin tener que entrar y cambiarlo a mano.
#:
#: Van aqui y no en el fichero de Caddy porque son de esta aplicacion: el proxy
#: solo tiene que seguir mandando /estudio/* a este puerto, que es lo que ya
#: hace. Una regla por modo en el proxy seria repartir la misma decision entre
#: dos sitios que no se hablan.
#: Hubo dos modos y la ruta llevaba cual --/estudio/light, /estudio/editor--.
#: Ahora hay uno, asi que no hay nada que llevar; se siguen ACEPTANDO esos dos
#: nombres para que un enlace guardado no de 404 y abra la pantalla de siempre.
MODOS_EN_LA_URL = ("light", "editor")

#: Los assets del front que se sellan en la portada. Son los dos unicos ficheros
#: que index.html enlaza.
ASSETS_SELLADOS = ("estilo.css", "app.js")


def _sello_asset(nombre):
    """Sello corto del asset: cambia cuando cambia el fichero, y solo entonces."""
    marca = _sello_fichero(os.path.join(RAIZ_WEB, nombre))
    return _huella_corta(marca) if marca else "0"


def _huella_corta(valor):
    return hashlib.sha256(repr(valor).encode("utf-8")).hexdigest()[:10]


def _portada_sellada():
    """index.html con `?v=<sello>` en los dos assets que enlaza.

    El sello sale del propio fichero (mtime + tamano), asi que cambia SOLO
    cuando el asset cambia. Eso es lo que permite servir app.js y estilo.css con
    cache de un ano: la URL nueva es un recurso nuevo, y la vieja ya no la pide
    nadie. Sin sello no se puede cachear fuerte -- congelaria a los usuarios en
    un front viejo sin forma de invalidarlo desde el servidor --, y por eso hasta
    ahora los 957 KB de app.js se revalidaban en CADA carga de la pagina.

    La portada en si NO se cachea: es la que trae los sellos nuevos.
    """
    with open(os.path.join(RAIZ_WEB, "index.html"), encoding="utf-8") as fh:
        html = fh.read()
    for nombre in ASSETS_SELLADOS:
        sello = _sello_asset(nombre)
        # solo la referencia literal del enlace, y una vez: asi no se toca
        # ninguna otra aparicion del nombre dentro del documento
        html = html.replace(f'"{nombre}"', f'"{nombre}?v={sello}"', 1)
    return HTMLResponse(html, headers={"Cache-Control": "no-cache"})


@app.get("/{fichero}")
def fichero_web(fichero: str, peticion: Request):
    """Sirve un fichero suelto de web/ (app.js, estilo.css...)."""
    nombre = str(fichero or "")
    if nombre in MODOS_EN_LA_URL:
        nombre = "index.html"
    # web/ es plano: aceptar solo un nombre de fichero deja fuera cualquier
    # forma de subir de carpeta antes incluso de tocar el disco
    if not FICHERO_WEB.match(nombre) or nombre in (".", ".."):
        raise ErrorApi(404, f"no existe: {fichero}")
    destino = os.path.join(RAIZ_WEB, nombre)
    if not os.path.isfile(destino):
        raise ErrorApi(404, f"no existe: {fichero}")
    if nombre == "index.html":
        return _portada_sellada()
    # UN ASSET PEDIDO CON SU SELLO ES INMUTABLE. La portada solo pone el `?v=`
    # que corresponde al fichero que hay ahora, asi que si el navegador pide ESE
    # sello, lo que reciba no va a cambiar nunca: se puede guardar un ano y no
    # volver a preguntar. Sin esto, app.js (957 KB) se revalidaba en cada carga
    # -- un viaje de ida y vuelta entero, y con ~235 ms de latencia se nota.
    #
    # Se comprueba que el sello COINCIDA con el del fichero: un `?v=` viejo (una
    # pestana que lleva dias abierta, un enlace guardado) no puede llevarse la
    # cabecera de inmutable, o se quedaria con esa respuesta para siempre.
    if nombre in ASSETS_SELLADOS:
        pedido = peticion.query_params.get("v")
        if pedido and pedido == _sello_asset(nombre):
            return FileResponse(destino, media_type=_tipo_de(destino), headers={
                "Cache-Control": "public, max-age=31536000, immutable",
            })
    return servir_fichero(peticion, destino)


# =================================================================== PORTADAS
# Portadas disenadas (rama `portadas`, 19-10-2026): ver pasos/portadas.py y
# pasos/grafismo.py. El diseno vive en la carpeta de Publicar, fuera de toda
# firma, y la portada hecha entra por `publicar.guardar_imagen_portada`, igual
# que una imagen subida: Publicar no sabe si la subiste o la disenaste. Lo que
# se paga (el fondo o la portada hechos con IA) va como trabajo, con su turno
# de imagenes (regla 2) y su coste apuntado en el video.

_PROPUESTAS_PORTADA = {}
_LOCK_PORTADAS = threading.Lock()


def _portadas():
    return PASOS_MODULOS.portadas if hasattr(PASOS_MODULOS, "portadas") else __import__("portadas")


def _motor_grafismo():
    # NO `_grafismo`: ese nombre ya es el de la paleta y el set de un video
    # (mas arriba), y en Python el segundo pisa al primero sin avisar
    return PASOS_MODULOS.grafismo if hasattr(PASOS_MODULOS, "grafismo") else __import__("grafismo")


def _raiz_publicar():
    return _publicar().carpeta(raiz_proyectos())


def _planos_para_portada(ctx):
    """[{sid, texto, ruta}] de los planos del video con imagen hecha."""
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    rutas = _imagenes_de_planos(ctx, plan)
    salida = []
    for escena in plan.get("escenas") or []:
        sid = str(escena.get("id") or "")
        ruta = rutas.get(sid)
        if ruta and os.path.isfile(ruta):
            salida.append({"sid": sid, "ruta": ruta,
                           "texto": " ".join(str(escena.get("narracion") or "").split())[:140]})
    return salida


def _rutas_fondo_portada(ctx, info, diseno):
    """Los ficheros del fondo del diseno (1 o 2), sacandolos si hace falta."""
    P = _portadas()
    fondo = (diseno or {}).get("fondo") or {}
    tipo = fondo.get("tipo")
    dos = fondo.get("disposicion") in ("diagonal", "vertical", "horizontal")
    rutas = []
    if tipo in ("subida", "ia"):
        for clave in ("imagen", "imagen2"):
            # SOLO los de este video: el nombre de otro no se pinta aqui
            if fondo.get(clave) and P.es_fondo_de(ctx.id, fondo[clave]):
                ruta = P.ruta_fondo(_raiz_publicar(), fondo[clave])
                if os.path.isfile(ruta):
                    rutas.append(ruta)
    elif tipo == "plano":
        planos = {p["sid"]: p["ruta"] for p in _planos_para_portada(ctx)}
        elegidos = [s for s in fondo.get("planos") or [] if s in planos] or list(planos)[:2]
        rutas = [planos[s] for s in elegidos]
    if not rutas and info.get("mp4"):
        # el fotograma (o dos, para las plantillas partidas). La cache va POR
        # MP4 (su huella): al volver a montar el video, los fotogramas viejos
        # no se cuelan en la portada; y se quedan los ultimos 40 por video.
        cache = os.path.join(_raiz_publicar(), "portadas", "fotogramas", P.prefijo_fondo(ctx.id))
        huella = re.sub(r"[^a-z0-9]", "", str(info.get("mp4_huella") or "x").lower())[:10] or "x"
        momentos = [int(fondo.get("ms") or 0)]
        if dos:
            dur = int(float(info.get("duracion_s") or 0) * 1000)
            momentos.append(int(fondo.get("ms2") or (dur // 2 if dur else 0)))
        try:
            hay = sorted((os.path.join(cache, n) for n in os.listdir(cache)), key=os.path.getmtime)
            de_otro_mp4 = [r for r in hay if not os.path.basename(r).startswith(huella + "_")]
            de_este = [r for r in hay if r not in de_otro_mp4]
            for ruta in de_otro_mp4 + de_este[:-40]:
                os.remove(ruta)
        except OSError:
            pass
        for ms in momentos:
            destino = os.path.join(cache, f"{huella}_{ms}.jpg")
            if not os.path.isfile(destino):
                try:
                    _publicar().fotograma(info["mp4"], ms, destino, ancho=1280)
                except Exception:                           # noqa: BLE001
                    continue
            rutas.append(destino)
    if not rutas:
        planos = _planos_para_portada(ctx)
        rutas = [p["ruta"] for p in planos[:2]]
    return rutas[:2] if dos else rutas[:1]


def _diseno_de_cuerpo(cuerpo):
    d = _cuerpo(cuerpo).get("diseno")
    if not isinstance(d, dict):
        raise ErrorApi(400, "manda {diseno}")
    return _portadas().normalizar(d)


def _diseno_inicial(ctx, info):
    P = _portadas()
    datos = _publicar()._leer_video(raiz_proyectos(), ctx.id)
    titulo = ""
    for red in ("youtube", "facebook", "instagram", "tiktok"):
        t = (datos.get("textos") or {}).get(red) or {}
        titulo = str(t.get("titulo") or "").strip() or titulo
        if titulo:
            break
    titulo = titulo or info.get("titulo") or info.get("nombre") or ""
    # 3-4 palabras: una portada no es el titulo del post
    corto = " ".join(str(titulo).split()[:4])
    # EL FONDO DE PARTIDA ES LA IMAGEN DE UN PLANO, tal cual (portadas-2,
    # 21-10): el fotograma sale del vídeo montado y trae subtítulos y rótulos.
    planos = _planos_para_portada(ctx)
    fondo = {"tipo": "plano", "planos": [planos[0]["sid"]]} if planos else None
    return P.de_plantilla("titular", {"titulo": corto}, "gamer", "anton",
                          P.formato_de_video(info.get("formato")), fondo=fondo)


@app.get("/api/portadas/catalogo")
def portadas_catalogo():
    """Plantillas, paletas, fuentes, elementos y formatos de las portadas."""
    # las fuentes de miniatura se bajan una vez, sin esperar (grafismo.py)
    _motor_grafismo().asegurar_fuentes_en_segundo_plano()
    return _portadas().catalogo()


@app.get("/api/publicar/videos/{pid}/portada/diseno")
def portada_diseno(pid: str, peticion: Request):
    """El diseno de portada de este video (el guardado o uno de partida, SIN
    guardarlo) y los planos que se pueden usar de fondo."""
    ctx = _ctx_publicable(pid, peticion)
    info = _info_para_publicar(ctx)
    guardado = _portadas().leer(_raiz_publicar(), ctx.id)
    return {"diseno": guardado or _diseno_inicial(ctx, info), "guardado": bool(guardado),
            "formato_video": _portadas().formato_de_video(info.get("formato")),
            "duracion_s": info.get("duracion_s") or 0, "montado": bool(info.get("mp4")),
            "planos": [{"sid": p["sid"], "texto": p["texto"]} for p in _planos_para_portada(ctx)],
            "fondos": _portadas().fondos_de(_raiz_publicar(), ctx.id)}


@app.put("/api/publicar/videos/{pid}/portada/diseno")
def portada_guardar_diseno(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """Guarda el diseno (para retocarlo otro dia). No cambia la portada."""
    ctx = _ctx_publicable(pid, peticion)
    return {"diseno": _portadas().guardar(_raiz_publicar(), ctx.id, _diseno_de_cuerpo(cuerpo))}


@app.post("/api/publicar/videos/{pid}/portada/plantilla")
def portada_desde_plantilla(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """Rehace el diseno con otra plantilla: {plantilla, paleta?, fuente?,
    formato?, textos?, diseno?}, conservando textos y fondo. Sin `plantilla`
    (solo paleta, letra o formato) cambia el estilo y deja los elementos como
    estaban. No guarda nada."""
    _ctx_publicable(pid, peticion)
    datos = _cuerpo(cuerpo)
    base = datos.get("diseno") if isinstance(datos.get("diseno"), dict) else None
    P = _portadas()
    actual = P.normalizar(base) if base else None
    if actual and not datos.get("plantilla"):
        # SOLO paleta, letra o formato: lo hecho a mano se queda (cambiar_estilo)
        return {"diseno": P.cambiar_estilo(actual, datos.get("paleta"), datos.get("fuente"),
                                           datos.get("formato"))}
    return {"diseno": P.de_plantilla(
        datos.get("plantilla") or (actual or {}).get("plantilla"),
        datos.get("textos") if isinstance(datos.get("textos"), dict) else None,
        datos.get("paleta") or (actual or {}).get("paleta") or "gamer",
        datos.get("fuente") or (actual or {}).get("fuente") or "anton",
        datos.get("formato") or (actual or {}).get("formato") or "9:16",
        base=actual)}


#: Cuantas vistas de portada se pintan a la vez (cada una abre un navegador):
#: arrastrar un deslizador no puede amontonar navegadores contra el render.
_VISTAS_PORTADA = threading.BoundedSemaphore(2)


@app.post("/api/publicar/videos/{pid}/portada/vista")
def portada_vista(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """La portada pintada en pequeno, para la pantalla: {diseno, ancho?,
    guias?} (con `guias`, las zonas que tapa cada red en rojo). PNG."""
    ctx = _ctx_publicable(pid, peticion)
    info = _info_para_publicar(ctx)
    diseno = _diseno_de_cuerpo(cuerpo)
    try:
        ancho = max(160, min(720, int(_cuerpo(cuerpo).get("ancho") or 360)))
    except (TypeError, ValueError):
        ancho = 360
    rutas = _rutas_fondo_portada(ctx, info, diseno)
    destino = os.path.join(_raiz_publicar(), "portadas", "vistas", f"{uuid.uuid4().hex[:12]}.png")
    if not _VISTAS_PORTADA.acquire(timeout=20):
        raise ErrorApi(503, "hay otras vistas pintándose: vuelve a intentarlo en un momento")
    try:
        _portadas().renderizar(diseno, rutas, destino, ancho_vista=ancho,
                               guias=bool(_cuerpo(cuerpo).get("guias")))
        with open(destino, "rb") as fh:
            contenido = fh.read()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(500, f"no he podido pintar la portada: {fallo}")
    finally:
        _VISTAS_PORTADA.release()
        try:
            os.remove(destino)
        except OSError:
            pass
    return Response(contenido, media_type="image/png", headers={"Cache-Control": "no-store"})


@app.post("/api/publicar/videos/{pid}/portada/usar")
def portada_usar(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """La pinta a tamano real y la deja como portada del video (como si la
    hubieras subido). Guarda tambien el diseno. -> la ficha de Publicar."""
    ctx = _ctx_publicable(pid, peticion)
    info = _info_para_publicar(ctx)
    diseno = _diseno_de_cuerpo(cuerpo)
    P = _portadas()
    rutas = _rutas_fondo_portada(ctx, info, diseno)
    destino = os.path.join(_raiz_publicar(), "portadas", "vistas", f"final_{uuid.uuid4().hex[:12]}.png")
    try:
        P.renderizar(diseno, rutas, destino)
        with open(destino, "rb") as fh:
            contenido = fh.read()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(500, f"no he podido pintar la portada: {fallo}")
    finally:
        try:
            os.remove(destino)
        except OSError:
            pass
    _por_publicar(_publicar().guardar_imagen_portada, raiz_proyectos(), ctx.id, contenido, ".png")
    P.guardar(_raiz_publicar(), ctx.id, diseno)
    ctx.bitacora.anotar("portada_disenada", "publicar", {"plantilla": diseno["plantilla"],
                                                         "formato": diseno["formato"]})
    return publicar_ficha(pid, peticion)


@app.get("/api/publicar/videos/{pid}/portada/planos/{sid}.jpg")
def portada_imagen_plano(pid: str, sid: str, peticion: Request):
    """La imagen de un plano, en pequeno, para elegir el fondo."""
    ctx = _ctx_publicable(pid, peticion)
    planos = {p["sid"]: p["ruta"] for p in _planos_para_portada(ctx)}
    if sid not in planos:
        raise ErrorApi(404, "ese plano no tiene imagen")
    try:
        from PIL import Image                               # noqa: PLC0415
        with Image.open(planos[sid]) as im:
            im = im.convert("RGB")
            im.thumbnail((360, 360))
            salida = io.BytesIO()
            im.save(salida, "JPEG", quality=82)
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(500, f"no he podido leer la imagen del plano: {fallo}")
    return Response(salida.getvalue(), media_type="image/jpeg", headers={"Cache-Control": "private, max-age=300"})


@app.get("/api/publicar/videos/{pid}/portada/fondos/{nombre}")
def portada_fondo(pid: str, nombre: str, peticion: Request):
    """Un fondo subido o hecho con IA."""
    _ctx_publicable(pid, peticion)
    try:
        ruta = _portadas().ruta_fondo(_raiz_publicar(), nombre)
    except ValueError:
        raise ErrorApi(404, "ese fondo no existe")
    if not os.path.isfile(ruta) or not _portadas().es_fondo_de(pid, nombre):
        raise ErrorApi(404, "ese fondo no existe")
    return FileResponse(ruta, headers={"Cache-Control": "private, max-age=3600"})


@app.post("/api/publicar/videos/{pid}/portada/fondo")
async def portada_subir_fondo(pid: str, peticion: Request):
    """Sube una imagen para el fondo (multipart, campo «imagen»). -> {nombre}"""
    ctx = await _en_hilo(_ctx_publicable, pid, peticion)
    try:
        formulario = await peticion.form()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(400, f"multipart ilegible: {fallo}")
    fichero = formulario.get("imagen")
    if not hasattr(fichero, "read"):
        raise ErrorApi(400, "manda la imagen en el campo «imagen»")
    contenido = await fichero.read(15 * 1024 * 1024 + 1)
    return await _en_hilo(_guardar_fondo_portada, ctx.id, contenido)


def _guardar_fondo_portada(pid, contenido):
    """La imagen, revisada por sus bytes y pasada a PNG de 2048 px como mucho."""
    if not contenido or len(contenido) > 15 * 1024 * 1024:
        raise ErrorApi(400, "el fondo tiene que pesar menos de 15 MB")
    if not (contenido[:8] == b"\x89PNG\r\n\x1a\n" or contenido[:3] == b"\xff\xd8\xff"
            or (contenido[:4] == b"RIFF" and contenido[8:12] == b"WEBP")):
        raise ErrorApi(400, "esa imagen no es un JPG, PNG o WebP de verdad")
    try:
        from PIL import Image                               # noqa: PLC0415
        with Image.open(io.BytesIO(contenido)) as im:
            # una imagen enorme (40 Mpx) se rechaza antes de abrirla en memoria
            if im.width * im.height > 40_000_000:
                raise ErrorApi(400, "esa imagen es demasiado grande (más de 40 megapíxeles)")
            im.draft("RGB", (2048, 2048))
            im.thumbnail((2048, 2048))
            im = im.convert("RGB")
            salida = io.BytesIO()
            im.save(salida, "PNG")
    except ErrorApi:
        raise
    except Exception:                                       # noqa: BLE001
        raise ErrorApi(400, "esa imagen no se puede leer")
    datos = salida.getvalue()
    P = _portadas()
    nombre = P.nombre_fondo(pid, datos)
    ruta = P.ruta_fondo(_raiz_publicar(), nombre)
    os.makedirs(os.path.dirname(ruta), exist_ok=True)
    temporal = f"{ruta}.{uuid.uuid4().hex[:6]}.tmp"
    with open(temporal, "wb") as fh:
        fh.write(datos)
    os.replace(temporal, ruta)
    return {"nombre": nombre}


def _resumen_para_portada(info):
    textos = [str(b.get("texto") or "") for b in info.get("guion") or [] if isinstance(b, dict)]
    return " ".join(" ".join(textos).split())[:1500] or str(info.get("material") or "")[:1500]


@app.post("/api/publicar/videos/{pid}/portada/proponer", status_code=202)
def portada_proponer(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """Claude propone tres portadas (suscripcion, sin coste aparte). -> {id};
    el resultado, en GET. No guarda nada."""
    ctx = _ctx_publicable(pid, peticion)
    info = _info_para_publicar(ctx)
    base = _cuerpo(cuerpo).get("diseno") if isinstance(_cuerpo(cuerpo).get("diseno"), dict) else None
    P = _portadas()
    formato = P.normalizar(base)["formato"] if base else P.formato_de_video(info.get("formato"))
    datos = _publicar()._leer_video(raiz_proyectos(), ctx.id)
    palabras = []
    for t in (datos.get("textos") or {}).values():
        palabras += [str(h) for h in (t or {}).get("hashtags") or []][:5]
    entrada = {"titulo": info.get("titulo") or info.get("nombre"), "palabras": palabras[:10],
               "resumen": _resumen_para_portada(info), "negocio": info.get("cliente_nombre") or ""}
    rid = uuid.uuid4().hex[:12]
    with _LOCK_PORTADAS:
        for viejo in list(_PROPUESTAS_PORTADA)[:-19]:
            _PROPUESTAS_PORTADA.pop(viejo, None)
        _PROPUESTAS_PORTADA[rid] = {"estado": "pensando", "proyecto": ctx.id}

    def correr():
        try:
            propuestas = P.proponer(entrada, formato, base=base, cwd=RAIZ_ESTUDIO)
            ficha = {"estado": "listo", "proyecto": ctx.id, "propuestas": propuestas}
        except Exception as fallo:                          # noqa: BLE001
            error = str(fallo)[:600]
            if CLI_CLAUDE.es_pasajero(fallo):
                error = ("La sesión de Claude se estaba renovando y no ha contestado. "
                         f"Vuelve a pedirlo en un minuto.\n\n{error}")
            ficha = {"estado": "error", "proyecto": ctx.id, "error": error}
        with _LOCK_PORTADAS:
            _PROPUESTAS_PORTADA[rid] = ficha

    threading.Thread(target=correr, daemon=True, name=f"portada-{rid}").start()
    return {"id": rid, "estado": "pensando"}


@app.get("/api/publicar/videos/{pid}/portada/proponer/{rid}")
def portada_propuestas(pid: str, rid: str, peticion: Request):
    """Como van las portadas propuestas, y cuales son al terminar."""
    ctx = _ctx_publicable(pid, peticion)
    with _LOCK_PORTADAS:
        ficha = _PROPUESTAS_PORTADA.get(rid)
    if not ficha or ficha.get("proyecto") != ctx.id:
        raise ErrorApi(404, "esa propuesta ya no está: vuelve a pedirla")
    return ficha


@_medido_en("publicar", "portada")
@_con_turno
def _correr_portada_ia(avisar, ctx, que, prompt, referencias, calidad, tamano):
    """Dibuja el fondo (o la portada entera) con la IA. Se paga."""
    avisar(0.05, "preparando la imagen")
    imagen = PASOS_MODULOS.medios.motor("imagen_openai/imagen.py")
    cache = os.path.join(_raiz_publicar(), "portadas", "refs")
    os.makedirs(cache, exist_ok=True)
    refs = [imagen.normalizar(r, cache) for r in referencias if r and os.path.isfile(r)][:2]
    if not refs:
        raise RuntimeError("no hay ninguna imagen del vídeo para tomar de referencia")
    avisar(0.15, "dibujando con la IA (se paga)")
    png, meta = imagen.generar(prompt, refs, quality=calidad, tamano=tamano)
    P = _portadas()
    nombre = P.nombre_fondo(ctx.id, png)
    ruta = P.ruta_fondo(_raiz_publicar(), nombre)
    os.makedirs(os.path.dirname(ruta), exist_ok=True)
    temporal = f"{ruta}.{uuid.uuid4().hex[:6]}.tmp"
    with open(temporal, "wb") as fh:
        fh.write(png)
    os.replace(temporal, ruta)
    # LO PAGADO SE APUNTA EN EL DISENO GUARDADO enseguida: si se cerro el
    # editor mientras se dibujaba, al volver a abrirlo sale (y en «Fondos ya
    # hechos» siempre esta)
    try:
        guardado = P.leer(_raiz_publicar(), ctx.id)
        if guardado:
            guardado["fondo"] = dict(guardado["fondo"], tipo="ia", imagen=nombre)
            if que == "portada":
                guardado["modo"] = "ia"
            P.guardar(_raiz_publicar(), ctx.id, guardado)
    except Exception:                                       # noqa: BLE001
        pass
    ctx.bitacora.anotar("portada_ia", "publicar", {"que": que, "calidad": calidad,
                                                   "coste_usd": meta.get("coste")})
    return {"nombre": nombre, "que": que, "coste_usd": meta.get("coste"), "prompt": prompt}


@app.post("/api/publicar/videos/{pid}/portada/ia", status_code=202)
def portada_ia(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """Dibuja con la IA de imagenes (SE PAGA): {diseno, que: "fondo"|"portada",
    calidad: low|medium|high, confirmado: true}. «fondo» hace solo la imagen de
    detras, sin texto (el texto sigue en capas); «portada» la hace entera, con
    el texto dentro. Sin `confirmado` devuelve el precio y no gasta nada."""
    ctx = _ctx_publicable(pid, peticion)
    info = _info_para_publicar(ctx)
    datos = _cuerpo(cuerpo)
    diseno = _diseno_de_cuerpo(cuerpo)
    que = "portada" if datos.get("que") == "portada" else "fondo"
    calidad = datos.get("calidad") if datos.get("calidad") in ("low", "medium", "high") else "low"
    precio = AJUSTES.precio_por_imagen(calidad)
    P = _portadas()
    entrada = {"titulo": info.get("titulo") or info.get("nombre"), "resumen": _resumen_para_portada(info)}
    # EL PROMPT SE VE Y SE PUEDE CAMBIAR (portadas-2, 21-10): sin `prompt` va
    # el de partida; con él, el de la pantalla. Las reglas del final (sin
    # letras en el fondo; los textos exactos en la portada) van SIEMPRE.
    propio = str(datos.get("prompt") or "").strip()
    de_partida = P.prompt_portada_ia(diseno, entrada) if que == "portada" else P.prompt_fondo_ia(diseno, entrada)
    prompt = P.prompt_final(que, propio or de_partida, diseno, entrada)
    if datos.get("confirmado") is not True:
        return {"precio": precio, "que": que, "calidad": calidad, "prompt": propio or de_partida,
                "prompt_final": prompt}
    referencias = _rutas_fondo_portada(ctx, info, diseno)
    trabajo_id = ctx.gestor.lanzar(f"portada_ia_{que}", _correr_portada_ia, ctx, que, prompt,
                                   referencias, calidad, P.TAMANO_IA[diseno["formato"]])
    _registrar_trabajo(trabajo_id, ctx.id)
    return {"trabajo_id": trabajo_id, "precio": precio}


def _guion_para_portada(info):
    """El guion entero (no solo el principio) para que Claude piense la imagen."""
    textos = [str(b.get("texto") or "") for b in info.get("guion") or [] if isinstance(b, dict)]
    return " ".join(" ".join(textos).split())[:6000] or str(info.get("material") or "")[:6000]


@app.post("/api/publicar/videos/{pid}/portada/ideas-ia", status_code=202)
def portada_ideas_ia(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """Claude lee el guion entero y propone tres ideas de imagen, cada una con
    su prompt editable (suscripción, sin coste aparte): {diseno}. -> {id}; el
    resultado, en GET. No dibuja ni guarda nada."""
    ctx = _ctx_publicable(pid, peticion)
    info = _info_para_publicar(ctx)
    diseno = _diseno_de_cuerpo(cuerpo)
    entrada = {"titulo": info.get("titulo") or info.get("nombre"), "guion": _guion_para_portada(info),
               "negocio": info.get("cliente_nombre") or ""}
    rid = uuid.uuid4().hex[:12]
    with _LOCK_PORTADAS:
        # UNA A LA VEZ POR VÍDEO: cerrar y abrir el editor lanzaba otra (cupo)
        for otro, ficha in _PROPUESTAS_PORTADA.items():
            if ficha.get("proyecto") == ctx.id and ficha.get("estado") == "pensando" and ficha.get("ideas_ia"):
                return {"id": otro, "estado": "pensando"}
        for viejo in list(_PROPUESTAS_PORTADA)[:-19]:
            _PROPUESTAS_PORTADA.pop(viejo, None)
        _PROPUESTAS_PORTADA[rid] = {"estado": "pensando", "proyecto": ctx.id, "ideas_ia": True}

    def correr():
        try:
            ficha = {"estado": "listo", "proyecto": ctx.id,
                     "ideas": _portadas().proponer_ideas_ia(entrada, diseno, cwd=RAIZ_ESTUDIO)}
        except Exception as fallo:                          # noqa: BLE001
            error = str(fallo)[:600]
            if CLI_CLAUDE.es_pasajero(fallo):
                error = ("La sesión de Claude se estaba renovando y no ha contestado. "
                         f"Vuelve a pedirlo en un minuto.\n\n{error}")
            ficha = {"estado": "error", "proyecto": ctx.id, "error": error}
        with _LOCK_PORTADAS:
            _PROPUESTAS_PORTADA[rid] = ficha

    threading.Thread(target=correr, daemon=True, name=f"ideas-portada-{rid}").start()
    return {"id": rid, "estado": "pensando"}


@app.get("/api/publicar/videos/{pid}/portada/ideas-ia/{rid}")
def portada_ideas_ia_estado(pid: str, rid: str, peticion: Request):
    """Cómo van las ideas de imagen, y cuáles son al terminar."""
    return portada_propuestas(pid, rid, peticion)


@app.post("/api/publicar/videos/{pid}/portada/descargar")
def portada_descargar(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """La portada a tamaño real, para guardarla (respaldo): {diseno}. PNG
    como adjunto. No guarda ni cambia nada."""
    ctx = _ctx_publicable(pid, peticion)
    info = _info_para_publicar(ctx)
    diseno = _diseno_de_cuerpo(cuerpo)
    rutas = _rutas_fondo_portada(ctx, info, diseno)
    destino = os.path.join(_raiz_publicar(), "portadas", "vistas", f"bajada_{uuid.uuid4().hex[:12]}.png")
    if not _VISTAS_PORTADA.acquire(timeout=20):
        raise ErrorApi(503, "hay otras portadas pintándose: vuelve a intentarlo en un momento")
    try:
        _portadas().renderizar(diseno, rutas, destino)
        with open(destino, "rb") as fh:
            contenido = fh.read()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(500, f"no he podido pintar la portada: {fallo}")
    finally:
        _VISTAS_PORTADA.release()
        try:
            os.remove(destino)
        except OSError:
            pass
    nombre = identificador(info.get("nombre") or ctx.id)[:60] or "portada"
    formato = diseno["formato"].replace(":", "x")
    return Response(contenido, media_type="image/png", headers={
        "Cache-Control": "no-store",
        "Content-Disposition": f'attachment; filename="{nombre}_portada_{formato}.png"'})


# ===================================================== DESCARGAS DE IMÁGENES
# Rama `imagenes-texto` (20-10-2026), pedido del dueño: bajarse las imágenes
# que se han creado. Una a una no hace falta ruta: la diapositiva enlaza el
# PNG con `/a/{pid}/...` (la misma que la pinta) y el atributo `download`.
# Aquí solo está «Descargar todas»: un .zip con las imágenes de PLANO de la
# versión ACTIVA de `assets`, en el orden del plan y numeradas.
#
# SOLO LEE. No toca el estado ni los params (regla 1) ni escribe nada dentro
# del proyecto: el .zip se arma en un temporal del sistema y se borra al
# terminar de mandarlo. Es una ruta normal (`def`), así que FastAPI la corre
# en su pool de hilos y comprimir 300 PNG no para el bucle de eventos. Los PNG
# van sin recomprimir (ZIP_STORED): ya vienen comprimidos y desinflarlos otra
# vez solo gasta CPU del servidor para ganar nada.

def _imagenes_de_plano(ctx):
    """[(nombre_en_el_zip, ruta)] de las imágenes de plano de la versión activa."""
    version = ctx.proyecto.version_activa("assets")
    if not version:
        return []
    carpeta = os.path.join(ctx.proyecto.ruta_paso("assets", version), "escenas")
    plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets", estado=ctx.estado) or {}
    salida = []
    for escena in plan.get("escenas") or []:
        sid = str(escena.get("id") or "")
        # el id viene del plan; aun así no se le deja salir de la carpeta
        if not sid or not re.fullmatch(r"[A-Za-z0-9_-]+", sid):
            continue
        ruta = os.path.join(carpeta, f"{sid}.png")
        if os.path.isfile(ruta):
            salida.append((f"{len(salida) + 1:03d}_{sid}.png", ruta))
    return salida


@app.get("/api/proyectos/{pid}/imagenes/zip")
def descargar_imagenes_zip(pid: str, peticion: Request, abiertos: str = Query(default="")):
    """Todas las imágenes de plano del vídeo en un .zip, en orden (solo lee)."""
    import tempfile  # noqa: PLC0415
    import zipfile  # noqa: PLC0415
    from starlette.background import BackgroundTask  # noqa: PLC0415

    ctx = contexto(pid)
    # UN PROYECTO CON CLAVE SIN ABRIR NO SE BAJA, como en Publicar
    # (`_ctx_publicable`). El pase llega en `X-Estudio-Abiertos` o, porque un
    # enlace `<a download>` no puede llevar cabeceras, en `?abiertos=`: es el
    # mismo pase firmado que la pantalla ya manda, no la clave.
    try:
        cerrados = CLIENTES.cerrados_para(
            raiz_proyectos(), abiertos or peticion.headers.get("x-estudio-abiertos"))
    except Exception:                                       # noqa: BLE001
        cerrados = set()
    if cerrados and _cliente_del_video(ctx.proyecto) in cerrados:
        raise ErrorApi(404, f"proyecto desconocido: {pid}")
    imagenes = _imagenes_de_plano(ctx)
    if not imagenes:
        raise ErrorApi(404, "este vídeo todavía no tiene imágenes que descargar")
    nombre = identificador(ctx.proyecto.config.get("nombre") or pid)[:60]
    descriptor, temporal = tempfile.mkstemp(prefix="imagenes_", suffix=".zip")
    os.close(descriptor)
    try:
        with zipfile.ZipFile(temporal, "w", zipfile.ZIP_STORED) as archivo:
            for dentro, ruta in imagenes:
                archivo.write(ruta, f"{nombre}_{dentro}")
    except Exception:
        os.remove(temporal)
        raise
    return FileResponse(temporal, media_type="application/zip",
                        filename=f"{nombre}_imagenes.zip",
                        background=BackgroundTask(os.remove, temporal))


# =================================================================== PUBLICAR
# Publicar en redes (rama `publicar-redes-1`, 16-10-2026). TODO lo de aqui es
# nuevo y vive en un bloque propio al final para no chocar con las ramas que
# cambian el resto del fichero: las rutas solo arman lo que sabe el video
# (encargo, guion, MP4) y llaman a `pasos/publicar.py`, que es quien decide.
# Ver la cabecera de ese modulo (donde vive cada cosa y lo que no se negocia).
#
# Van DETRAS de `/{fichero}` sin problema: esa ruta solo casa un nombre suelto
# y todas estas llevan varias barras.

try:
    import publicar as PUBLICAR  # noqa: E402  (pasos/ ya esta en sys.path)
    ERROR_PUBLICAR = ""
except Exception as _fallo_publicar:  # noqa: BLE001
    PUBLICAR = None
    ERROR_PUBLICAR = f"{type(_fallo_publicar).__name__}: {_fallo_publicar}"

_MEDIDAS_MP4 = {}
_MAX_MEDIDAS_MP4 = 500


def _publicar():
    if PUBLICAR is None:
        raise ErrorApi(503, f"el módulo de publicar no se ha podido cargar: {ERROR_PUBLICAR}")
    return PUBLICAR


def _por_publicar(fn, *args, **kwargs):
    """Llama a pasos/publicar.py y convierte su fallo en un ErrorApi."""
    try:
        return fn(*args, **kwargs)
    except PUBLICAR.ErrorPublicar as fallo:
        raise ErrorApi(fallo.codigo, str(fallo)) from None


def _mp4_del_video(proyecto):
    """(ruta absoluta, ruta para /a/) del MP4 activo, o ("", "")."""
    version = proyecto.version_activa("render")
    if not version:
        return "", ""
    ruta = os.path.join(proyecto.ruta_paso("render", version), "video.mp4")
    if not os.path.isfile(ruta):
        return "", ""
    return ruta, f"pasos/render/v{int(version)}/video.mp4"


def _nombres_de_clientes():
    try:
        return {c["id"]: c["nombre"] for c in CLIENTES.listar(raiz_proyectos())["clientes"]}
    except Exception:                                       # noqa: BLE001
        return {}


def _cliente_del_video(proyecto, datos_clientes=None):
    return CLIENTES.cliente_de(raiz_proyectos(),
                               (proyecto.config or {}).get(CONFIG_ESTILO_LIGHT) or "",
                               proyecto.id, datos=datos_clientes)


def _ctx_publicable(pid, peticion):
    """El contexto del video, o 404 si es de un proyecto con clave sin abrir."""
    ctx = contexto(pid)
    if (ctx.proyecto.config or {}).get(CONFIG_TALLER):
        raise ErrorApi(404, "eso no es un vídeo")
    cerrados = _cerrados(peticion)
    if cerrados and _cliente_del_video(ctx.proyecto) in cerrados:
        raise ErrorApi(404, f"proyecto desconocido: {pid}")
    return ctx


def _info_para_publicar(ctx):
    """Lo que publicar.py necesita saber de un video, leido de lo que ya hay."""
    P = _publicar()
    mp4, mp4_rel = _mp4_del_video(ctx.proyecto)
    huella = P.huella_mp4(mp4) if mp4 else ""
    medidas = {}
    if mp4:
        medidas = _MEDIDAS_MP4.get((mp4, huella))
        if medidas is None:
            medidas = P.medir_mp4(mp4)
            if len(_MEDIDAS_MP4) >= _MAX_MEDIDAS_MP4:
                _MEDIDAS_MP4.clear()
            _MEDIDAS_MP4[(mp4, huella)] = medidas
    plan, bloques = {}, []
    if PASOS_MODULOS is not None:
        try:
            plan = PASOS_MODULOS.p6_assets.plan_actual(ctx.proyecto, "assets",
                                                       estado=ctx.estado) or {}
        except Exception:                                   # noqa: BLE001
            plan = {}
        try:
            bloques = _bloques_del_guion(ctx)
        except Exception:                                   # noqa: BLE001
            bloques = []
    if medidas.get("ancho") and medidas.get("alto"):
        formato = "vertical" if medidas["alto"] > medidas["ancho"] else "horizontal"
    else:
        formato = str(plan.get("formato") or "horizontal")
        formato = "vertical" if formato == "vertical" else "horizontal"
    duracion = float(medidas.get("duracion") or plan.get("duracion_total") or 0.0)
    cid = _cliente_del_video(ctx.proyecto)
    ingesta = ctx.estado.params("ingesta") or {}
    return {
        "pid": ctx.id, "nombre": (ctx.proyecto.config or {}).get("nombre") or ctx.id,
        "cliente": cid, "cliente_nombre": _nombres_de_clientes().get(cid, ""),
        "montado": bool(mp4), "mp4": mp4, "mp4_rel": mp4_rel, "mp4_huella": huella,
        "formato": formato, "duracion_s": round(duracion, 1),
        "titulo": str(ingesta.get("titulo") or ""),
        "material": str(ingesta.get("texto") or ""),
        "instrucciones": str((ctx.estado.params("brief") or {}).get("instrucciones") or ""),
        "cta": (ctx.estado.params("guion") or {}).get("cta") or {},
        "guion": bloques,
        "capitulos_base": P.capitulos_base(plan.get("escenas") or [], duracion),
    }


def _videos_para_publicar(peticion):
    """Los videos que quien pregunta puede ver, sin abrir el estado de ninguno."""
    cerrados = _cerrados(peticion)
    asignaciones = CLIENTES._leer(raiz_proyectos())
    nombres = _nombres_de_clientes()
    # el nombre de cada estilo, para filtrar la cola por estilo
    try:
        estilos = {f.get("id"): f.get("nombre") or f.get("id") for f in
                   ((_presets().listar().get("presets") or {}).get("canal") or [])}
    except Exception:                                       # noqa: BLE001
        estilos = {}
    salida = []
    for ficha in _listar_proyectos():
        if ficha.get(CONFIG_TALLER):
            continue
        cid = CLIENTES.cliente_de(raiz_proyectos(), ficha.get(CONFIG_ESTILO_LIGHT) or "",
                                  ficha.get("id"), datos=asignaciones)
        if cerrados and cid in cerrados:
            continue
        try:
            mp4, _rel = _mp4_del_video(Proyecto(ficha["raiz"]))
        except Exception:                                   # noqa: BLE001
            mp4 = ""
        salida.append({"pid": ficha.get("id"), "nombre": ficha.get("nombre") or ficha.get("id"),
                       "cliente": cid, "cliente_nombre": nombres.get(cid, ""),
                       "estilo": ficha.get(CONFIG_ESTILO_LIGHT) or "",
                       "estilo_nombre": estilos.get(ficha.get(CONFIG_ESTILO_LIGHT) or "", "")
                       or (ficha.get(CONFIG_ESTILO_LIGHT) or ""),
                       "montado": bool(mp4), "actualizado": ficha.get("actualizado") or ""})
    return salida


