@app.post("/api/publicar/videos/{pid}/portada")
async def publicar_subir_portada(pid: str, peticion: Request):
    """Sube una imagen de portada (multipart, campo «portada»)."""
    ctx = await _en_hilo(_ctx_publicable, pid, peticion)
    try:
        formulario = await peticion.form()
    except Exception as fallo:                              # noqa: BLE001
        raise ErrorApi(400, f"multipart ilegible: {fallo}")
    fichero = formulario.get("portada")
    if not hasattr(fichero, "read"):
        raise ErrorApi(400, "manda la imagen en el campo «portada»")
    extension = os.path.splitext(str(getattr(fichero, "filename", "") or ""))[1].lower()
    P = _publicar()
    tam = getattr(fichero, "size", None)
    if isinstance(tam, int) and tam > P.MAX_BYTES_PORTADA:
        raise ErrorApi(400, "la portada tiene que pesar menos de 15 MB")
    contenido = await fichero.read(P.MAX_BYTES_PORTADA + 1)
    await _en_hilo(_por_publicar, P.guardar_imagen_portada, raiz_proyectos(),
                   ctx.id, contenido, extension)
    return await _en_hilo(publicar_ficha, pid, peticion)


@app.post("/api/publicar/videos/{pid}/textos", status_code=202)
def publicar_escribir_textos(pid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """Claude escribe los textos de las redes pedidas: {redes}. Se sigue
    preguntando por la ficha (`escribiendo`)."""
    ctx = _ctx_publicable(pid, peticion)
    info = _info_para_publicar(ctx)
    ajustes = _publicar().ajustes_de(raiz_proyectos(), info["cliente"])
    redes = _cuerpo(cuerpo).get("redes")
    P = _publicar()
    # lo que mejor funcionó en el proyecto y los hashtags de sus últimos vídeos,
    # para que Claude aprenda y no repita bloque (publicar-seo)
    del_proyecto = [v for v in _videos_para_publicar(peticion) if v["cliente"] == info["cliente"]]
    cid_res = "" if info["cliente"] in ("", P.SIN_PROYECTO) else info["cliente"]
    _por_publicar(P.lanzar_textos, raiz_proyectos(), info, redes, ajustes,
                  proyecto=ctx.proyecto, cwd=ctx.proyecto.raiz,
                  aprendido=P.aprendido_de_resultados(raiz_proyectos(), del_proyecto, cid_res),
                  recientes=P.hashtags_recientes(raiz_proyectos(), [v["pid"] for v in del_proyecto],
                                                 sin_pid=ctx.id))
    anotar_global("publicar_textos", {"proyecto": ctx.id, "redes": redes})
    return {"escribiendo": True}


