# ------------------------------------- PARRILLA: analizar una cuenta ajena
# (rama `analizar-cuentas`, 18-10-2026). Quien decide la vía y el gasto es
# `pasos/cuentas_ajenas.py`; las cuentas leídas son datos públicos y se
# guardan para todo el Studio (no son de ningún proyecto). Lo único de un
# proyecto son los guiones que se escriben con ellas (`desde-cuenta`).

try:
    import cuentas_ajenas as CUENTAS  # noqa: E402  (pasos/ ya esta en sys.path)
    ERROR_CUENTAS = ""
except Exception as _fallo_cuentas:  # noqa: BLE001
    CUENTAS = None
    ERROR_CUENTAS = f"{type(_fallo_cuentas).__name__}: {_fallo_cuentas}"


def _cuentas():
    if CUENTAS is None:
        raise ErrorApi(503, f"«Analizar una cuenta» no se ha podido cargar: {ERROR_CUENTAS}")
    return CUENTAS


def _por_cuentas(fn, *args, **kwargs):
    C = _cuentas()
    try:
        return fn(*args, **kwargs)
    except C.ErrorCuentas as fallo:
        raise ErrorApi(fallo.codigo, str(fallo)) from None


def _cuenta_pedida(red, usuario):
    """(red, usuario) de la URL, comprobados con el mismo criterio que lo escrito."""
    return _por_cuentas(_cuentas().entender, usuario, red)


@app.get("/api/parrilla/cuentas")
def parrilla_cuentas():
    """Las cuentas ya leídas, las conexiones (sin claves) y el gasto del mes."""
    C = _cuentas()
    return {"cuentas": C.cuentas(raiz_proyectos()), "conexiones": C.claves_publicas(),
            "gasto_mes": C.gasto_del_mes(raiz_proyectos()), "redes": list(C.REDES),
            "fuentes": C.FUENTES}


