@app.post("/api/parrilla/proyectos/{cid}/desde-cuenta", status_code=202)
def parrilla_desde_cuenta(cid: str, peticion: Request, cuerpo: dict = Body(default=None)):
    """Guiones para ESTE proyecto con lo que le funciona a una cuenta ajena:
    {red, usuario, cuantos, modo, peticion?, matriz?, nombre?}."""
    cid = _proyecto_parrilla(cid, peticion)
    C = _cuentas()
    d = _cuerpo(cuerpo)
    red, usuario = _por_cuentas(C.entender, d.get("usuario"), d.get("red") or "")
    datos = _por_cuentas(C.cuenta, raiz_proyectos(), red, usuario)
    posts = C.posts_de_cuenta(datos, 15)
    if not posts:
        raise ErrorApi(409, "esa cuenta no tiene vídeos con los que trabajar")
    ajena = f"@{datos.get('usuario')} en {C.NOMBRE_RED.get(red, red)}"
    trabajo_ = _por_parrilla(_parrilla().lanzar, raiz_proyectos(), cid, "resultados", {
        "posts": posts, "cuantos": d.get("cuantos"), "modo": d.get("modo"),
        "peticion": str(d.get("peticion") or "")[:3000], "matriz": str(d.get("matriz") or ""),
        "nombre": d.get("nombre") or f"Como {ajena}", "ajena": ajena,
        "analisis": datos.get("analisis") or "", "contexto": _contexto_parrilla(cid, d)})
    anotar_global("parrilla_desde_cuenta", {"proyecto": cid, "red": red, "usuario": usuario})
    return trabajo_


# ------------------------------------------------------------------------ main

def main():
    parser = argparse.ArgumentParser(description="Servicio HTTP del Estudio de Video")
    parser.add_argument("--puerto", type=int, default=8020)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--proyectos", default=None,
                        help="carpeta base de proyectos "
                             f"(por defecto {RAIZ_POR_DEFECTO})")
    argumentos = parser.parse_args()
    fijar_raiz_proyectos(argumentos.proyectos or raiz_proyectos())
    # Donde escucha esta API, para las herramientas del asistente
    # (pasos/mcp_estudio.py): el CLI arranca ese servidor como proceso hijo y
    # el hijo vuelve a hablar con este mismo proceso por HTTP.
    os.environ.setdefault("ESTUDIO_API", f"http://127.0.0.1:{argumentos.puerto}")

    import uvicorn
    # las cifras automaticas de Publicar (apagadas de fabrica: el hilo solo mira)
    if PUBLICAR is not None:
        try:
            import publicar_auto  # noqa: E402
            publicar_auto.arrancar(raiz_proyectos)
        except Exception as fallo:                          # noqa: BLE001
            print(f"AVISO: las cifras automáticas no arrancan -> {fallo}")
    print(f"Estudio de Video en http://{argumentos.host}:{argumentos.puerto}")
    print(f"proyectos en {raiz_proyectos()}")
    if ERROR_PASOS:
        print(f"AVISO: los pasos no se han cargado -> {ERROR_PASOS}")
    try:
        uvicorn.run(app, host=argumentos.host, port=argumentos.puerto,
                    log_level="warning")
    finally:
        # un `claude auth login` a medias deja un node esperando un codigo por
        # una tuberia que ya no tiene quien escriba
        if PASOS_MODULOS is not None:
            PASOS_MODULOS.login_cli.olvidar_todos()
            # y una charla a medias deja otro node contestando a nadie
            PASOS_MODULOS.asistente.olvidar_todas()
        # y las conversaciones de la Parrilla (parrilla-2)
        if GUIONISTA is not None:
            GUIONISTA.olvidar_todos()


if __name__ == "__main__":
    main()
